        public ActionResult craateabzar(personalabzar pn)
        {
            personalabzar pb = new personalabzar();
            pb.Year = pn.Year;
            pb.Month = pn.Month;
            pb.FK_PYM = pn.FK_PYM;
            pb.FK_usr = pn.FK_usr;
            pb.FK_Equgroup = pn.FK_Equgroup;
            pb.value = pn.value;
            db.personalabzar.Add(pb);
            db.SaveChanges();
            return Content("True");
        }
