        public ActionResult sabtkasriabz(int fk, int month, int year, int number_sorat)
        {
            var t = db.personalabzar.Where(p => p.FK_PYM == fk && p.Year == year && p.Month == month).ToList();
            double vv = 0;
            //var mashin = db.tbReffrenceSave.Where(p => p.FK_PeymanID == fk && p.IsFor == 3).FirstOrDefault();
            //var mashin2 = db.tbReffrenceSaveLevel.Where(p => p.FK_RRSave == mashin.ID).OrderByDescending(s => s.ID).FirstOrDefault();
            //var mashin3 = db.tbEquipmentMoalefeValueReffrenceSave.Where(p => p.FK_Baste == mashin2.ID && p.Final_Accept == true && p.tbEquipmentMoalefeValue.Any(s => s.Month == month && s.Year == year)).FirstOrDefault();
            //var mashin4 = db.tbEquipmentMoalefeValue.Where(p => p.FK_tbEquipmentMoalefeValueReffrenceSave == mashin3.ID).ToList();
            var yy = db.personalabzar.Where(p => p.FK_PYM == fk && p.Year == year && p.Month == month).ToList();
            foreach (var item in yy)
            {
                if (item.value != 0)
                {
                    var rx = db.tbEquipments.Where(p => p.FK_Bunch == item.FK_Equgroup && p.FK_Peyman == fk).FirstOrDefault();
                    if (rx != null)
                    {
                        vv += (long)(item.value * Math.Round((double)(rx.EachValue ?? 0) * 12 / 365, 2));
                    }
                }


            }
            tbkasriabzar pb = new tbkasriabzar();
            pb.number_sorat = number_sorat;
            pb.Value = vv;
            pb.FK_pymn = fk;
            db.tbkasriabzar.Add(pb);
            db.SaveChanges();
            return Content("True");
        }

