        public ActionResult viewkasrimoshin(int fk, int number_sorat, int month, int year)
        {
            var yy = db.tbPeymanContracts.Where(p => p.pec_ID == fk).FirstOrDefault();
            long mashincol = 0;
            long soght = 0;
            long Abzarncol = 0;
            var Abzar = db.tbReffrenceSave.Where(p => p.FK_PeymanID == yy.pec_ID && p.IsFor == 4).FirstOrDefault();
            var Abzar2 = db.tbReffrenceSaveLevel.Where(p => p.FK_RRSave == Abzar.ID && p.Deleted != true).OrderByDescending(s => s.ID).FirstOrDefault();
            var Abzar3 = db.tbEquipmentMoalefeValueReffrenceSave.Where(p => p.FK_Baste == Abzar2.ID && p.tbEquipmentMoalefeValue.Any(s => s.Month == month && s.Year == year)).FirstOrDefault();
            var Abzar4 = db.tbEquipmentMoalefeValue.Where(p => p.FK_tbEquipmentMoalefeValueReffrenceSave == Abzar3.ID && p.CountDays != 0 && p.Fk_pymn != null).ToList();
            foreach (var item10 in Abzar4)
            {
                var rx = db.tbEquipments.Where(p => p.ID == item10.FK_Equipment && p.FK_Peyman == yy.pec_ID).FirstOrDefault();
                if (rx != null)
                {
                    //var abb = db.tbEquipmentBunch.Where(p => p.Eqpbnch_ID == rx.FK_Bunch).Select(s => s.Eqpbnch_Name).FirstOrDefault();
                    Abzarncol += (long)(item10.CountDays * Math.Round((double)(rx.EachValue ?? 0) * 12 / 365, 2));
                    //var ttt = (long)(item10.CountDays * Math.Round((double)(rx.EachValue ?? 0) * 12 / 365, 2));
                    //var c55c = Math.Round((double)(rx.EachValue ?? 0) * 12 / 365, 2);
                    //var abz = item10.CountDays * c55c;
                }
            }
            long egareh = 0;

            var mashin = db.tbReffrenceSave.Where(p => p.FK_PeymanID == yy.pec_ID && p.IsFor == 3).FirstOrDefault();
            var mashin2 = db.tbReffrenceSaveLevel.Where(p => p.FK_RRSave == mashin.ID && p.Deleted != true).OrderByDescending(s => s.ID).FirstOrDefault();
            var mashin3 = db.tbEquipmentMoalefeValueReffrenceSave.Where(p => p.FK_Baste == mashin2.ID && p.tbEquipmentMoalefeValue.Any(s => s.Month == month && s.Year == year)).FirstOrDefault();
            if (mashin3 != null)
            {
                var mashin4 = db.tbEquipmentMoalefeValue.Where(p => p.FK_tbEquipmentMoalefeValueReffrenceSave == mashin3.ID && p.CountDays != 0).ToList();
                foreach (var item6 in mashin4)
                {
                    var rx = db.tbEquipments.Where(p => p.ID == item6.FK_Equipment && p.FK_Peyman == yy.pec_ID).FirstOrDefault();
                    if (item6.CountDays != 0)
                    {
                        if (rx != null)
                        {
                            mashincol += (long)(item6.CountDays * (rx.EachValue * 12 / 365));
                            var tt = (long)(item6.CountDays * (rx.Soght * 12 / 365));
                            var t = (rx.egareh * 12 / 365);
                            var y = (rx.Soght * 12 / 365);
                            var ttt = (long)(item6.CountDays * (rx.egareh * 12 / 365));
                            soght += (long)(item6.CountDays * (rx.Soght * 12 / 365));
                            egareh += (long)(item6.CountDays * (rx.egareh * 12 / 365));

                            var c55c = rx.EachValue * 12 / 365;
                        }
                    }

                }
                //var kasr2 = db.KasriMashin.Where(p => p.Fk_pymn == yy.pec_ID && p.number_sorat == number_sorat).FirstOrDefault();
                //if (kasr2 != null && kasr2.Value != null)
                //{
                //    mashincol -= (long)kasr2.Value;
                //}
            }




            //var kasr = db.tbkasriabzar.Where(p => p.FK_pymn == yy.pec_ID && p.number_sorat == number_sorat).FirstOrDefault();
            //if (kasr != null && kasr.Value != null)
            //{
            //    Abzarncol -= (long)kasr.Value;
            //}
            tbdetaol pb = new tbdetaol();
            pb.year = year;
            pb.month = month;
            pb.Fk_Pymn = fk;
            pb.abzarkol = Abzarncol;
            pb.mashinkol = mashincol;
            pb.number_sorat = (int)soght;
            db.tbdetaol.Add(pb);
            db.SaveChanges();
            return Content("True");
        }
