        public JsonResult AddNode(string name, int? relationId)
        {
            // در صورتی که نود ریشه باشد (relationId == null)
            int newNumber = 1;
            int radif = 1;
            string number = "01"; // مقدار پیش‌فرض برای نود ریشه

            if (relationId == null)
            {
                // پیدا کردن آخرین نود ریشه و مقدار `NUMberstring` آن
                var lastNode = db.dbLInkmagmo
                    .Where(p => p.reltaiontable == null)
                    .OrderByDescending(n => n.NUMberstring)
                    .FirstOrDefault();

                if (lastNode != null && !string.IsNullOrEmpty(lastNode.NUMberstring))
                {
                    // استخراج مقدار آخرین رشته و افزایش آن با قالب‌بندی به دو رقم
                    string lastNumberStr = lastNode.NUMberstring;

                    // افزایش مقدار رشته به عنوان یک عدد و تبدیل به دو رقمی با `PadLeft`
                    number = (int.Parse(lastNumberStr) + 1).ToString().PadLeft(lastNumberStr.Length, '0');
                }
            }
            else
            {
                // اگر نود فرزند باشد، مقدار NUMber همان مقدار پدر می‌شود و radif را پیدا و یک واحد اضافه می‌کنیم
                var parentNode = db.dbLInkmagmo.FirstOrDefault(n => n.reltaiontable == relationId);
                var parentNode2 = db.dbLInkmagmo.FirstOrDefault(n => n.ID == relationId);

                if (parentNode != null)
                {
                    var lastNode2 = db.dbLInkmagmo
                    .Where(p => p.reltaiontable == relationId)
                    .OrderByDescending(n => n.NUMberstring)
                    .FirstOrDefault();
                    newNumber = (int)parentNode.NUMber;
                    string lastNumberStr = lastNode2.NUMberstring;

                    BigInteger lastNumber = BigInteger.Parse(lastNumberStr);
                    number = (lastNumber + 1).ToString().PadLeft(lastNumberStr.Length, '0');
                    // پیدا کردن آخرین radif در زیرمجموعه‌ها و اضافه کردن یک واحد به آن
                    var lastChild = db.dbLInkmagmo
                        .Where(n => n.reltaiontable == relationId)
                        .OrderByDescending(n => n.radif)
                        .FirstOrDefault();

                    if (lastChild != null)
                    {
                        radif = (int)(lastChild.radif + 1);
                    }
                }
                else
                {
                    if (parentNode2 != null)
                    {
                        //var lastNode2 = db.dbLInkmagmo
                        //.Where(p => p.reltaiontable == relationId)
                        //.OrderByDescending(n => n.NUMberstring)
                        //.FirstOrDefault();
                        //newNumber = (int)parentNode.NUMber;
                        string lastNumberStr = parentNode2.NUMberstring;

                        number = lastNumberStr + "01";

                        // پیدا کردن آخرین radif در زیرمجموعه‌ها و اضافه کردن یک واحد به آن

                    }
                }

            }

            // ایجاد نود جدید با مقادیر به‌روز شده
            var newNode = new dbLInkmagmo
            {
                nameaval = name,
                reltaiontable = relationId,
                NUMber = newNumber,
                radif = radif,
                NUMberstring = number
            };

            db.dbLInkmagmo.Add(newNode);
            db.SaveChanges();

            // بازگشت اطلاعات نود جدید
            return Json(new { ID = newNode.ID, NameAval = newNode.nameaval + " " + newNode.NUMberstring });
        }

