        public JsonResult DeleteNode(int id)
        {
            // پیدا کردن نود با ID مشخص
            var nodeToDelete = db.dbLInkmagmo.Find(id); // فرض می‌کنیم که موجودیت شما با نام "Node" است

            if (nodeToDelete == null)
            {
                return Json(new { success = false, message = "Node not found." });
            }

            // بررسی اینکه آیا نود دارای فرزندان است
            var hasChildren = db.dbLInkmagmo.Any(n => n.reltaiontable == id);
            if (hasChildren)
            {
                return Json(new { success = false, message = "نمیتوان حذف کرد چون دارای ریشه است " });
            }

            // حذف نود از دیتابیس
            db.dbLInkmagmo.Remove(nodeToDelete);

            // ذخیره تغییرات
            db.SaveChanges();

            return Json(new { success = true });
        }
