        public ActionResult creat(List<int> userId = null, List<string> Date = null, string time = "", string titl = "", DateTime? DataDocument = null, DateTime? DataDocument2 = null)
        {
            // چک کردن تاریخ‌های ورودی
            if (DataDocument == null || DataDocument2 == null || userId == null || Date == null)
            {
                return Json(new { success = false, message = "لطفاً اطلاعات کامل را وارد کنید" });
            }

            // بازه تاریخ را محاسبه می‌کنیم
            var startDate = DataDocument.Value;
            var endDate = DataDocument2.Value;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            int personal = 0;

            if (cookie_user != null)
            {
                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                personal = user.usr_ID;
            }
            // ایجاد یک شیء کانتکست دیتابیس
            using (SaabEntities db = new SaabEntities())
            {
                // برای هر کاربر در بازه‌ی زمانی داده‌شده، روزهای هفته را چک می‌کنیم
                foreach (var user in userId)
                {
                    // پیمایش بین بازه‌ی تاریخی
                    for (var date = startDate; date <= endDate; date = date.AddDays(1))
                    {
                        // محاسبه‌ی روز هفته (شنبه = 1 تا جمعه = 7)
                        int dayOfWeek;

                        switch (date.DayOfWeek)
                        {
                            case DayOfWeek.Saturday:
                                dayOfWeek = 1;
                                break;
                            case DayOfWeek.Sunday:
                                dayOfWeek = 2;
                                break;
                            case DayOfWeek.Monday:
                                dayOfWeek = 3;
                                break;
                            case DayOfWeek.Tuesday:
                                dayOfWeek = 4;
                                break;
                            case DayOfWeek.Wednesday:
                                dayOfWeek = 5;
                                break;
                            case DayOfWeek.Thursday:
                                dayOfWeek = 6;
                                break;
                            case DayOfWeek.Friday:
                                dayOfWeek = 7;
                                break;
                            default:
                                dayOfWeek = 0; // مقدار پیش‌فرض، در صورتی که لازم باشد
                                break;
                        }
                        //var dayOfWeek = (int)date.DayOfWeek == 0 ? 7 : (int)date.DayOfWeek;

                        // چک می‌کنیم که آیا روز هفته در لیست ورودی وجود دارد
                        if (Date.Contains(dayOfWeek.ToString()))
                        {
                            //int fi = 0;
                            //var find = db.tbperson.Where(p => p.FK_usr == personal).FirstOrDefault();
                            //if (find != null)
                            //{
                            //    var find2 = db.dbRelatinafrad.Where(p => p.FK_person == find.ID && p.FK_usr == user).FirstOrDefault();
                            //    if (find2 != null)
                            //    {
                            //        fi = find2.ID;
                            //    }
                            //}
                            var findusr = db.dbrelatinperson.Where(p => p.ID == user).FirstOrDefault();


                            // ذخیره داده‌ها در دیتابیس
                            var newRecord = new dbmovazafisabt
                            {
                                FK_usr = findusr.FK_usr,
                                fromdata = startDate,
                                todata = endDate,
                                time = TimeSpan.Parse(time),
                                days = dayOfWeek,
                                timdata = date
                            };
                            db.dbmovazafisabt.Add(newRecord);

                            var newRecord20 = new tbcreatfaal
                            {
                                Title = titl,
                                sharhasli = titl,
                                DataDocument = startDate,
                                imporatant = 2,
                            };
                            db.tbcreatfaal.Add(newRecord20);
                            db.SaveChanges();  // ذخیره موقت برای مقداردهی ID در newRecord20

                            var newRecord2 = new dbRelatinafrad
                            {
                                FK_usr = findusr.FK_usr,
                                Title = titl,
                                DataDocument2 = startDate,
                                //clocktime = endDate,
                                clocktime = TimeSpan.Parse(time),
                                //days = dayOfWeek,
                                DataDocument = date,
                                FK_tbcreatfaal = newRecord20.ID,
                                FK_Relationperson = user,
                                canornotcan = "بلی"
                            };
                            db.dbRelatinafrad.Add(newRecord2);
                            db.SaveChanges();

                        }
                    }
                }

                // تغییرات را ذخیره می‌کنیم
            }

            return Json(new { success = true, message = "اطلاعات با موفقیت ذخیره شد" });
        }


        public JsonResult SaveUserSchedule(
            List<int> userId = null,
            List<string> days = null,
            List<string> morningStarts = null,
            List<string> morningEnds = null,
            List<string> afternoonStarts = null,
            List<string> afternoonEnds = null,
            List<string> nightStarts = null,
            List<string> nightEnds = null)
        {
            try
            {
                for (int i = 0; i < days.Count; i++)
                {
                    // تبدیل نام روز به عدد
                    int dayOfWeek = GetDayOfWeek(days[i]);
                    int currentUserId = userId[i]; // ذخیره id کاربر در یک متغیر محلی

                    // ذخیره یا آپدیت شیفت صبح
                    if (!string.IsNullOrEmpty(morningStarts[i]) && !string.IsNullOrEmpty(morningEnds[i]))
                    {
                        var morningShift = db.dbtarifmovazaf.FirstOrDefault(
                            x => x.FK_usr == currentUserId && x.day == dayOfWeek && x.parttime == 1); // بررسی وجود شیفت صبح

                        if (morningShift != null)
                        {
                            // اگر شیفت موجود است، آن را آپدیت کنید
                            morningShift.start_clock = TimeSpan.Parse(morningStarts[i]);
                            morningShift.end_clock = TimeSpan.Parse(morningEnds[i]);
                        }
                        else
                        {
                            // اگر شیفت موجود نیست، یک شیفت جدید اضافه کنید
                            db.dbtarifmovazaf.Add(new dbtarifmovazaf
                            {
                                FK_usr = currentUserId,
                                day = dayOfWeek,
                                parttime = 1, // صبح
                                start_clock = TimeSpan.Parse(morningStarts[i]),
                                end_clock = TimeSpan.Parse(morningEnds[i])
                            });
                        }
                    }

                    // ذخیره یا آپدیت شیفت عصر
                    if (!string.IsNullOrEmpty(afternoonStarts[i]) && !string.IsNullOrEmpty(afternoonEnds[i]))
                    {
                        var afternoonShift = db.dbtarifmovazaf.FirstOrDefault(
                            x => x.FK_usr == currentUserId && x.day == dayOfWeek && x.parttime == 2); // بررسی وجود شیفت عصر

                        if (afternoonShift != null)
                        {
                            // اگر شیفت موجود است، آن را آپدیت کنید
                            afternoonShift.start_clock = TimeSpan.Parse(afternoonStarts[i]);
                            afternoonShift.end_clock = TimeSpan.Parse(afternoonEnds[i]);
                        }
                        else
                        {
                            // اگر شیفت موجود نیست، یک شیفت جدید اضافه کنید
                            db.dbtarifmovazaf.Add(new dbtarifmovazaf
                            {
                                FK_usr = currentUserId,
                                day = dayOfWeek,
                                parttime = 2, // عصر
                                start_clock = TimeSpan.Parse(afternoonStarts[i]),
                                end_clock = TimeSpan.Parse(afternoonEnds[i])
                            });
                        }
                    }

                    // ذخیره یا آپدیت شیفت شب
                    if (!string.IsNullOrEmpty(nightStarts[i]) && !string.IsNullOrEmpty(nightEnds[i]))
                    {
                        var nightShift = db.dbtarifmovazaf.FirstOrDefault(
                            x => x.FK_usr == currentUserId && x.day == dayOfWeek && x.parttime == 3); // بررسی وجود شیفت شب

                        if (nightShift != null)
                        {
                            // اگر شیفت موجود است، آن را آپدیت کنید
                            nightShift.start_clock = TimeSpan.Parse(nightStarts[i]);
                            nightShift.end_clock = TimeSpan.Parse(nightEnds[i]);
                        }
                        else
                        {
                            // اگر شیفت موجود نیست، یک شیفت جدید اضافه کنید
                            db.dbtarifmovazaf.Add(new dbtarifmovazaf
                            {
                                FK_usr = currentUserId,
                                day = dayOfWeek,
                                parttime = 3, // شب
                                start_clock = TimeSpan.Parse(nightStarts[i]),
                                end_clock = TimeSpan.Parse(nightEnds[i])
                            });
                        }
                    }
                }

                // ذخیره تغییرات در پایگاه داده
                db.SaveChanges();

                return Json(new { success = true });
            }
            catch (Exception ex)
            {
                // در صورت بروز خطا
                return Json(new { success = false, message = ex.Message });
            }
        }



        // System.NotSupportedException: 'LINQ to Entities does not recognize the method 'Int32 get_Item(Int32)' method, and this method cannot be translated into a store expression.'تابعی برای تبدیل نام روز به عدد
        private int GetDayOfWeek(string dayName)
        {
            switch (dayName)
            {
                case "شنبه":
                    return 1;
                case "یکشنبه":
                    return 2;
                case "دوشنبه":
                    return 3;
                case "سه شنبه":
                    return 4;
                case "چهارشنبه":
                    return 5;
                case "پنجشنبه":
                    return 6;
                case "جمعه":
                    return 7;
