        public ActionResult result(List<int> Fkpym = null, int usr = 0)
        {
            tbperson tbperson = new tbperson();
            List<dbrelatinperson> dbrelatinperson2 = new List<dbrelatinperson>();
            var findd = db.tbperson.Where(p => p.FK_usr == usr).FirstOrDefault();
            if (findd != null)
            {
                tbperson = findd;
            }
            else
            {
                tbperson.FK_usr = usr;
                db.tbperson.Add(tbperson);
                db.SaveChanges();

            }

            foreach (var it in Fkpym)
            {
                if (it == 0)
                {
                    Fkpym = db.tbUsers.Select(s => s.usr_ID).ToList();

                }
                else if (it == -1)
                {
                    Fkpym = db.tbUsers.Select(s => s.usr_ID).ToList();
                    break;
                }
            }

            foreach (var it in Fkpym)
            {
                dbrelatinperson dbrelatinperson = new dbrelatinperson();
                dbrelatinperson.FK_usr = it;
                dbrelatinperson.FK_person = tbperson.ID;
                dbrelatinperson2.Add(dbrelatinperson);

            }
            db.dbrelatinperson.AddRange(dbrelatinperson2);
            db.SaveChanges();
            return Content("True");
        }



