        public ActionResult viewlist()
        {
            List<tbHoshdar> tbHoshdar = new List<tbHoshdar>();
            var findIDID = db.tbHoshdar.GroupBy(s => s.ID_ID).ToList();
            foreach (var it in findIDID)
            { var find = db.tbHoshdar.Where(s => s.ID_ID == it.Key && s.Active != false).FirstOrDefault();
                if (find != null)
                {
                    tbHoshdar.Add(find);

                }
            }
            return View(tbHoshdar);
        }
        public string notActive(int id = 0)
        {
            var find = db.tbHoshdar.Where(s => s.ID_ID == id && s.Active != false).ToList();
            foreach (var it in find)
            {
                it.Active = false;
            }
            db.SaveChanges();
            return "True";
        }


