        public string GetDataFromExcel_shenasehshomareh2(HttpPostedFileBase MyExcelStream) // برای نیروهای امانی
        {
            var workbook = Telerik.Web.Spreadsheet.Workbook.Load(MyExcelStream.InputStream, Path.GetExtension(MyExcelStream.FileName));

            if (workbook.Sheets.Count == 0)
            {
                return "هیچ شیتی در این اکسل وجود ندارد";
            }

            var sheet = workbook.Sheets[0];
            var rows = sheet.Rows;
            int rowCount = rows.Count;

            if (rowCount <= 1)
            {
                return "فایل اکسل فاقد اطلاعات یا فقط دارای سطر هدر می‌باشد";
            }

            // خواندن هدر برای بررسی تعداد سلول‌ها
            int headerCellCount = rows[0].Cells.Count;

            using (DbContextTransaction transaction = db.Database.BeginTransaction())
            {
                try
                {
                    // ۱. پاکسازی جدول قبلی با بهینه‌ترین حالت
                    // اگر از EF 6 یا Core استفاده می‌کنید، استفاده از دستور مستقیم SQL یا Bulk Delete بسیار سریع‌تر از RemoveRange است.
                    // اگر TRUNCATE به دلیل کلید خارجی خطا داد، از دستور زیر استفاده کنید:
                    // db.Database.ExecuteSqlCommand("DELETE FROM tbJaremehandpadash");

                    // ۲. بهینه‌سازی جستجو با استفاده از Dictionary در حافظه (RAM)
                    // واکشی فیلدهای مورد نیاز و تبدیل به دیکشنری بر اساس کلید یکتا جهت جستجوی O(1)
                    var usDictionary = db.ValuunicPriorityResult
                                         .Where(x => x.valuunic != null)
                                         .ToList() // واکشی به حافظه
                                         .GroupBy(x => x.valuunic)
                                         .ToDictionary(g => g.Key, g => g.First());

                    // ۳. پیمایش سطرها از ایندکس ۱ (رد کردن هدر)
                    for (int i = 1; i < rowCount; i++)
                    {
                        var row = rows[i];

                        // بررسی صحت ساختار ستون‌ها در سطر جاری
                        if (row.Cells.Count != headerCellCount)
                        {
                            return $"خطای ارزیابی در سطر {i + 1} رخ داده است. یکی از سلول‌ها فاقد اطلاعات یا خارج از محدوده جدول است.";
                        }

                        var nameCell = row.Cells[2];
                        var codeCell = row.Cells[1];

                        string nammm2 = nameCell.Value?.ToString();
                        string nammm = codeCell.Value?.ToString();

                        if (!string.IsNullOrEmpty(nammm2))
                        {
                            // جستجوی فوق‌سریع در Dictionary بدون نیاز به کوئری مجدد دیتابیس
                            if (usDictionary.TryGetValue(nammm2, out var priorityResult))
                            {
                                priorityResult.eshterak = nammm;
                            }
                        }
                    }

                    // ۴. ذخیره تغییرات به صورت یکجا (تنها یک بار رفت‌وبرگشت به دیتابیس)
                    db.SaveChanges();
                    transaction.Commit();

                    return "با موفقیت انجام شد";
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    return "خطا در پردازش اطلاعات: " + ex.Message;
                }
            }
        }


        public string GetDataFromExcel_MoalefeValueFish(HttpPostedFileBase MyExcelStream)
        {

            int ValueUser = 0;
            int month = 0;
            int year = 0;

            List<tbMoalefeValueFish> MoalefeValueFish = new List<tbMoalefeValueFish>();

            var workbook = Telerik.Web.Spreadsheet.Workbook.Load(MyExcelStream.InputStream, Path.GetExtension(MyExcelStream.FileName));
            using (DbContextTransaction transaction = db.Database.BeginTransaction())
            {
                try
                {
                    var Count_Sheets = workbook.Sheets.Count;
                    if (Count_Sheets >= 1)
                    {
                        var sheet = workbook.Sheets[0];
                        var Rows = sheet.Rows;
                        if (Rows.Count >= 1)
                        {
                            foreach (var item in Rows)
                            {
                                if (item.Cells.Count != sheet.Rows[0].Cells.Count)
                                {
                                    return " خطای ارزیابی در سطر " + (item.Index + 1).ToString() + " رخ داده است. یکی از سلول های این ستون فاقد اطلاعات می باشد ";
                                    ;
                                }
                                var title2 = workbook.Sheets[0].Rows[0].Cells;
                                var count = workbook.Sheets[0].Rows.Count();
                                List<int> ID = new List<int>();
                                for (int i = 3; i < title2.Count; i++)
                                {
                                    ID.Add(int.Parse(title2[i].Value.ToString()));
                                }
                                if (count == 1)
                                {
                                    return "فایل اکسل فاقد اطلاعات می باشد";
                                }
                                for (int i = 1; i < count; i++)
                                {
                                    var row = workbook.Sheets[0].Rows[i];
                                    var User = row.Cells[0];
                                    if (User.Value != null)
                                    {
                                        ValueUser = int.Parse(User.Value.ToString());

                                    }
                                    else
                                    {
                                        return " لطفا ستون نام  سطر " + " ( " + i + " ) " + "را پر کنید ";
                                    }
                                    var monthexcel = row.Cells[1];
                                    if (monthexcel.Value != null)
                                    {
                                        month = int.Parse(monthexcel.Value.ToString());

                                    }
                                    else
                                    {
                                        return " لطفا ستون نام  سطر " + " ( " + i + " ) " + "را پر کنید ";
                                    }
                                    var yearexcel = row.Cells[2];
                                    if (yearexcel.Value != null)
                                    {
                                        year = int.Parse(yearexcel.Value.ToString());

                                    }
                                    else
                                    {
                                        return " لطفا ستون نام  سطر " + " ( " + i + " ) " + "را پر کنید ";
                                    }


                                    int shomarande = 3;

                                    if (shomarande < row.Cells.Count)
                                    {

                                        var finduser = db.tbUsers.Where(s => s.usr_Personal_ID == ValueUser).FirstOrDefault();
                                        foreach (var it in ID)

                                        {
                                            var Value = row.Cells[shomarande];

                                            var find = db.tbMoalefeValueFish.Where(b => b.mlfvlfsh_Month == month && b.FK_EXCel == null && b.mlfvlfsh_Year == year && b.FK_User == finduser.usr_ID && b.FK_Moalefe == it).FirstOrDefault();
                                            if (Value.Value != null && find != null)
                                            {
                                                int valuecheack = int.Parse(Value.Value.ToString());
                                                if (find.mlfvlfsh_Value != (int)valuecheack)
                                                {
                                                    tbMoalefeValueFish tbMoalefeValueFish1 = new tbMoalefeValueFish();
                                                    find.mlfvlfsh_Value = int.Parse(Value.Value.ToString());
                                                    db.SaveChanges();
                                                }

                                            }
                                            else
                                            {
                                                tbMoalefeValueFish tbMoalefeValueFish1 = new tbMoalefeValueFish();
                                                tbMoalefeValueFish1.mlfvlfsh_Month = month;
                                                tbMoalefeValueFish1.mlfvlfsh_Year = year;
                                                tbMoalefeValueFish1.FK_Moalefe = it;
                                                tbMoalefeValueFish1.FK_User = finduser.usr_ID;
                                                tbMoalefeValueFish1.FK_EXCel = null;
                                                tbMoalefeValueFish1.mlfvlfsh_Value = int.Parse(Value.Value.ToString());
                                                MoalefeValueFish.Add(tbMoalefeValueFish1);

                                            }
                                            shomarande++;
                                        }
                                    }
                                    else
                                    {
                                        return "ایندکس خارج از محدوده در سطر " + (i + 1);
                                    }
                                }

                                db.tbMoalefeValueFish.AddRange(MoalefeValueFish);
                                db.SaveChanges();
                                break;
                            }
                        }
                        else
                        {
                            return "این شیت فاقد سطر می باشد";
                        }
                    }
                    else
                    {
                        return "هیچ شیتی در این اکسل وجود ندارد";
                    }
                    transaction.Commit();
                    return "با موفقیت انجام شد";
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    return ex.Message;

                }
            }
        }



