        [HttpPost]
        public ActionResult SaveOrUpdate(long select_peyman, long select_peyman22, string string_name, int select_peyman1, int name)
        {
            try
            {
                using (var db = new SaabEntities())
                {
                    // بررسی وجود رکورد
                    var existingRecord = db.dbergapishghan
                        .FirstOrDefault(x => x.name == name

                                          && x.vaziat == select_peyman1);

                    if (existingRecord != null)
                    {
                        // آپدیت رکورد موجود
                        existingRecord.FK_link = select_peyman22;
                        existingRecord.FK_gozaresh = select_peyman;
                        existingRecord.string_name = string_name;

                        existingRecord.timesabt = DateTime.Now;
                        db.SaveChanges();
                    }
                    else
                    {
                        // درج رکورد جدید
                        var newRecord = new dbergapishghan
                        {
                            FK_link = select_peyman22,
                            FK_gozaresh = select_peyman,
                            vaziat = select_peyman1,
                            name = name,
                            string_name = string_name,

                            timesabt = DateTime.Now
                        };

                        db.dbergapishghan.Add(newRecord);
                        db.SaveChanges();
                    }
                }

                return Json(new { success = true, message = "عملیات با موفقیت انجام شد" });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }


