        public ActionResult arzyabiedit(int id)
        {
            var arzyabi = db.arzyzbi1.FirstOrDefault(x => x.ID == id);
            if (arzyabi == null)
                return HttpNotFound();

            var soalha = db.arzyzbi2_soal
                .Where(s => s.FK_arzyzbi1 == id && s.Active != false)
                .ToList();

            var model = new EditEvaluationViewModel
            {
                ID = arzyabi.ID,
                typegozarwsh = (int)arzyabi.typegozaresh,
                Title = arzyabi.name,
                Questions = soalha.Select(s => new EditQuestionViewModel
                {
                    ID = s.ID,
                    Text = s.soal,
                    Description = s.sharh,
                    Options = db.arzyzbi3_gozeneh
                        .Where(o => o.FK_arzyabisoal == s.ID && o.Active != false)
                        .Select(o => new EditOptionViewModel
                        {
                            ID = o.ID,
                            Text = o.gozineh,
                            Weight = (int?)o.vazn
                        }).ToList()
                }).ToList()
            };

            return PartialView("~/Areas/Setting/Views/Orders/arzyabiedit.cshtml", model);
        }
