        public ActionResult SubmitEditedEvaluation(string EvaluationData)
        {
            try
            {
                var eval = JsonConvert.DeserializeObject<FunctionModel.EditEvaluationViewModel>(EvaluationData);
                if (eval == null)
                    return Json(new { success = false, message = "ارزیابی خالی است" });

                var dbEval = db.arzyzbi1.FirstOrDefault(e => e.ID == eval.ID);
                if (dbEval == null)
                    return Json(new { success = false, message = "ارزیابی یافت نشد" });

                dbEval.name = eval.Title;
                dbEval.typegozaresh = (int)eval.typegozarwsh;

                db.SaveChanges();
                var findarzyab2 = db.arzyzbi2_soal.Where(s => s.Active != false && s.FK_arzyzbi1 == eval.ID).ToList();
                var inputQuestionIDs = eval.Questions.Where(q => q.ID.HasValue).Select(q => q.ID.Value).ToList();

                // غیرفعال کردن سوالاتی که دیگه توی ورودی نیستند
                foreach (var oldQuestion in findarzyab2)
                {
                    if (!inputQuestionIDs.Contains(oldQuestion.ID))
                    {
                        oldQuestion.Active = false;
                        db.SaveChanges();
                    }
                }
                foreach (var q in eval.Questions)
                {
                    arzyzbi2_soal soal;
                    if (q.ID.HasValue)
                    {
                        soal = db.arzyzbi2_soal.Find(q.ID.Value);
                        if (soal != null)
                        {
                            soal.soal = q.Text;
                            soal.sharh = q.Description;
                            soal.datatime = DateTime.Now;

                            db.SaveChanges();
                        }
                    }
                    else
                    {
                        soal = new arzyzbi2_soal
                        {
                            FK_arzyzbi1 = dbEval.ID,
                            soal = q.Text,
                            sharh = q.Description,
                            datatime = DateTime.Now
                        };
                        db.arzyzbi2_soal.Add(soal);
                        db.SaveChanges();
                    }

                    var fidndarzyab3 = db.arzyzbi3_gozeneh.Where(s => s.Active != false && s.FK_arzyabisoal == soal.ID).ToList();
                    // لیست آیدی گزینه‌های ورودی
                    var inputOptionIDs = q.Options.Where(o => o.ID.HasValue).Select(o => o.ID.Value).ToList();

                    // غیرفعال کردن گزینه‌هایی که حذف شده‌اند
                    foreach (var oldOpt in fidndarzyab3)
                    {
                        if (!inputOptionIDs.Contains(oldOpt.ID))
                        {
                            oldOpt.Active = false;
                            db.SaveChanges();
                        }
                    }
                    for (int i = 1; i < q.Options.Count; i++)
                    {
                        var opt = q.Options[i];
                        if (opt.ID.HasValue)
                        {
                            var oldOpt = db.arzyzbi3_gozeneh.Find(opt.ID.Value);
                            if (oldOpt != null)
                            {
                                oldOpt.gozineh = opt.Text;
                                oldOpt.vazn = opt.Weight ?? 0;
                                oldOpt.datatime = DateTime.Now;

                                db.SaveChanges();
                            }
                        }
                        else
                        {
                            db.arzyzbi3_gozeneh.Add(new arzyzbi3_gozeneh
                            {
                                FK_arzyabisoal = soal.ID,
                                gozineh = opt.Text,
                                vazn = opt.Weight ?? 0,
                                datatime = DateTime.Now
                            });
                            db.SaveChanges();
                        }
                    }
                }
                return PartialView("~/Areas/Setting/Views/Orders/arzyabi.cshtml");

                //return Content("<script>alert('✅ ذخیره با موفقیت انجام شد'); window.location.reload();</script>", "text/html");
            }
            catch (Exception ex)
            {
                return Content("<script>alert('❌ خطا در ثبت اطلاعات: " + ex.Message + "');</script>", "text/html");
            }
        }


        #region استعداد 
        public async Task<string> GetDataFromExcel_Khodro2(HttpPostedFileBase MyExcelStream)
        {
            try
            {
                if (MyExcelStream == null || MyExcelStream.ContentLength == 0)
                    return "❌ فایل اکسل ارسال نشده است.";

                using (DbContextTransaction transaction = db.Database.BeginTransaction())
                {
                    try
                    {
                        var workbook = Telerik.Web.Spreadsheet.Workbook.Load(MyExcelStream.InputStream, Path.GetExtension(MyExcelStream.FileName));
                        var sheet = workbook.Sheets.FirstOrDefault();

                        if (sheet == null)
                            return "❌ Sheet در فایل یافت نشد.";

                        // 🔹 استخراج نام ستون‌ها از ردیف اول
                        var headerRow = sheet.Rows.FirstOrDefault();
                        if (headerRow == null)
                            return "❌ فایل فاقد ردیف عنوان ستون‌ها است.";

                        var headers = headerRow.Cells
                            .Select((c, i) => new { Index = i, Name = c?.Value?.ToString()?.Trim() })
                            .Where(h => !string.IsNullOrEmpty(h.Name))
                            .ToDictionary(h => h.Name, h => h.Index);

                        int inserted = 0;
                        int updated = 0;

                        // 🔹 پردازش ردیف‌های داده
                        for (int i = 1; i < sheet.Rows.Count; i++)
                        {
                            var row = sheet.Rows[i];
                            if (row == null || row.Cells.All(c => c == null || string.IsNullOrWhiteSpace(c.Value?.ToString())))
                                continue;

                            // 🔹 تابع کمکی برای خواندن مقدار هر ستون
                            string GetValue(string columnLetter)
                            {
                                // تبدیل حرف ستون به اندیس عددی (A=0, B=1, ...)
                                int index = 0;
                                foreach (char c in columnLetter.ToUpper())
                                {
                                    index *= 26;
                                    index += (c - 'A' + 1);
                                }
                                index--; // چون ایندکس از صفر شروع می‌شود

                                // اگر ردیف مقدار نداشت → null بده
                                if (row == null || row.Cells == null)
                                    return null;

                                // ✅ پیدا کردن سلول واقعی بر اساس Index
                                var cell = row.Cells.FirstOrDefault(c => c != null && c.Index == index);

                                // اگر سلول اصلاً وجود ندارد → null بده
                                if (cell == null || cell.Value == null)
                                    return null;

                                string value = cell.Value.ToString().Trim();

                                return string.IsNullOrWhiteSpace(value) ? null : value;
                            }




                            // 🔹 حالا با نام ستون‌ها می‌خونیم:
                            string Pelakvaziyat = GetValue("A");  // وضعیت پلاک
                            string Pelak = GetValue("B");         // شماره پلاک
                            string Model = GetValue("C");         // مدل خودرو
                            string Rang = GetValue("D");          // رنگ خودرو
                            string Noe = GetValue("E");           // نوع خودرو
                            string Uniform = GetValue("F");       // یونیفرم
                            string SaleSakht = GetValue("G");     // سال ساخت
                            string Karkard = GetValue("H");       // کارکرد کیلومتر
                            string Fk_UserMalek = GetValue("I");  // مالک خودرو(همکار اداره)
                            string NamKharejMalek = GetValue("J");  // نام و نام خانوادگی خارج اداره مالک خودرو
                            string CodeMeliKharejMalek = GetValue("K");  // کد ملی خارج اداره مالک خودرو
                            string TavalodKharejMalek = GetValue("L");   // تاریخ تولد خارج اداره مالک خودرو
                            string Fk_UserRanande1 = GetValue("M");  // راننده خودرو(همکار اداره 1)
                            string Fk_UserRanande2 = GetValue("N");  // راننده خودرو(همکار اداره 2)
                            string Fk_UserRanande3 = GetValue("O");  // راننده خودرو(همکار اداره 3)
                            string NamKharejRanande1 = GetValue("P");  // نام و نام خانوادگی خارج اداره راننده خودرو1
                            string NamKharejRanande2 = GetValue("Q");  // نام و نام خانوادگی خارج اداره راننده خودرو2
                            string NamKharejRanande3 = GetValue("R");  // نام و نام خانوادگی خارج اداره راننده خودرو3
                            string CodeMeliRanande1 = GetValue("S");  // شماره ملی. خارج اداره راننده خودرو1
                            string CodeMeliRanande2 = GetValue("T");  // شماره ملی. خارج اداره راننده خودرو2
                            string CodeMeliRanande3 = GetValue("U");  // شماره ملی. خارج اداره راننده خودرو3
                            string TavalodRanande1 = GetValue("V");   // تاریخ تولد. خارج اداره راننده خودرو1
                            string TavalodRanande2 = GetValue("W");   // تاریخ تولد. خارج اداره راننده خودرو2
                            string TavalodRanande3 = GetValue("X");   // تاریخ تولد. خارج اداره راننده خودرو3
                            string ShomareTamas1 = GetValue("Y");     // شماره تماس. خارج اداره راننده خودرو1
                            string ShomareTamas2 = GetValue("Z");     // شماره تماس. خارج اداره راننده خودرو2
                            string ShomareTamas3 = GetValue("AA");    // شماره تماس. خارج اداره راننده خودرو3
                            string CodePost1 = GetValue("AB");        // کد پستی خارج اداره راننده خودرو1
                            string CodePost2 = GetValue("AC");        // کد پستی خارج اداره راننده خودرو2
                            string CodePost3 = GetValue("AD");        // کد پستی خارج اداره راننده خودرو3
                            string Adres1 = GetValue("AE");           // آدرس خارج اداره راننده خودرو1
                            string Adres2 = GetValue("AF");           // آدرس خارج اداره راننده خودرو2
                            string Adres3 = GetValue("AG");           // آدرس خارج اداره راننده خودرو3
                            string VaziatSalamat = GetValue("AH");    // وضعیت سلامت خودرو
                            string DalayelPishfarz = GetValue("AI");  // دلایل پیش فرض
                            string Sharh = GetValue("AJ");            // شرح
                            string TarikhKhateme = GetValue("AK");    // تاریخ خاتمه اعتبار
                            string SherkatBimegar = GetValue("AL");   // شرکت بیمه گر
                            string VaziatBime = GetValue("AM");       // وضعیت بیمه شخص ثالث
                            string VaziatMoayene = GetValue("AN");    // وضعیت معاینه فنی


                            // 🔹 درج یا بروزرسانی
                            Table_Khodro existing = null;

                            if (Pelakvaziyat == "0")
                                existing = db.Table_Khodro.FirstOrDefault(x => x.PelakDakhel == Pelak);
                            else if (Pelakvaziyat == "1")
                                existing = db.Table_Khodro.FirstOrDefault(x => x.PelakKharej == Pelak);
                            DateTime? miladiDate2;
                            if (!string.IsNullOrWhiteSpace(TarikhKhateme))
                            {
                                // تبدیل تاریخ شمسی به میلادی
                                DateTime? miladiDate = ConvertPersianToGregorian(TarikhKhateme);

                                if (miladiDate != null)
                                    miladiDate2 = miladiDate.Value;
                                else
                                    miladiDate2 = null; // اگر تاریخ اشتباه بود
                            }
                            else
                            {
                                miladiDate2 = null;
                            }
                            DateTime? ConvertPersianToGregorian(string persianDate)
                            {
                                try
                                {
                                    if (string.IsNullOrWhiteSpace(persianDate))
                                        return null;

                                    persianDate = persianDate.Trim()
                                                             .Replace("-", "/")
                                                             .Replace(".", "/");

                                    var parts = persianDate.Split('/');
                                    if (parts.Length != 3)
                                        return null;

                                    int year = int.Parse(parts[0]);
                                    int month = int.Parse(parts[1]);
                                    int day = int.Parse(parts[2]);

                                    var pc = new System.Globalization.PersianCalendar();
                                    DateTime miladi = pc.ToDateTime(year, month, day, 0, 0, 0, 0);
                                    return miladi;
                                }
                                catch
                                {
                                    return null; // اگر فرمت اشتباه بود
                                }
                            }
                            if (existing != null)
                            {
                                existing.Model = ParseLong(Model);
                                existing.Rang = ParseLong(Rang);
                                existing.Noe = ParseLong(Noe);
                                existing.Uniform = ParseBool(Uniform);
                                existing.SaleSakht = ParseInt(SaleSakht);
                                existing.KarkardKilometr = ParseLong(Karkard);
                                existing.Fk_UserMalekHamkarEdare = ParseInt(Fk_UserMalek);
                                existing.NamKharejMalek = NamKharejMalek;
                                existing.CodeMeliKharejMalek = CodeMeliKharejMalek;
                                existing.TavalodKharejMalek = ParseDate(TavalodKharejMalek);
                                existing.Fk_UserRanandeHamkarEdare1 = ParseInt(Fk_UserRanande1);
                                existing.Fk_UserRanandeHamkarEdare2 = ParseInt(Fk_UserRanande2);
                                existing.Fk_UserRanandeHamkarEdare3 = ParseInt(Fk_UserRanande3);
                                existing.NamKharejRanande1 = NamKharejRanande1;
                                existing.NamKharejRanande2 = NamKharejRanande2;
                                existing.NamKharejRanande3 = NamKharejRanande3;
                                existing.CodeMeliKharejRanande1 = CodeMeliRanande1;
                                existing.CodeMeliKharejRanande2 = CodeMeliRanande2;
                                existing.CodeMeliKharejRanande3 = CodeMeliRanande3;
                                existing.TavalodKharejRanande1 = ParseDate(TavalodRanande1);
                                existing.TavalodKharejRanande2 = ParseDate(TavalodRanande2);
                                existing.TavalodKharejRanande3 = ParseDate(TavalodRanande3);
                                existing.ShomareTamasKharejRanande1 = ShomareTamas1;
                                existing.ShomareTamasKharejRanande2 = ShomareTamas2;
                                existing.ShomareTamasKharejRanande3 = ShomareTamas3;
                                existing.CodePostKharejRanande1 = CodePost1;
                                existing.CodePostKharejRanande2 = CodePost2;
                                existing.CodePostKharejRanande3 = CodePost3;
                                existing.AdresKharejRanande1 = Adres1;
                                existing.AdresKharejRanande2 = Adres2;
                                existing.AdresKharejRanande3 = Adres3;
                                existing.VaziatSalamatKhodro = ParseInt(VaziatSalamat);
                                existing.DalayelPishfarz = ParseLong(DalayelPishfarz);
                                existing.Sharh = Sharh;
                                existing.TarikhKhatemeEtebar = miladiDate2;

                                existing.SherkatBimegar = SherkatBimegar;
                                existing.VaziatBimeShakhsSales = ParseInt(VaziatBime);
                                existing.VaziatMoayeneFani = ParseInt(VaziatMoayene);

                                updated++;
                            }

                            else
                            {
                                var newItem = new Table_Khodro
                                {
                                    PelakKharej = (Pelakvaziyat == "1") ? Pelak : null,
                                    PelakDakhel = (Pelakvaziyat == "0") ? Pelak : null,
                                    Model = ParseLong(Model),
                                    Rang = ParseLong(Rang),
                                    Noe = ParseLong(Noe),
                                    Uniform = ParseBool(Uniform),
                                    SaleSakht = ParseInt(SaleSakht),
                                    KarkardKilometr = ParseLong(Karkard),
                                    Fk_UserMalekHamkarEdare = ParseInt(Fk_UserMalek),
                                    NamKharejMalek = NamKharejMalek,
                                    CodeMeliKharejMalek = CodeMeliKharejMalek,
                                    TavalodKharejMalek = ParseDate(TavalodKharejMalek),
                                    Fk_UserRanandeHamkarEdare1 = ParseInt(Fk_UserRanande1),
                                    Fk_UserRanandeHamkarEdare2 = ParseInt(Fk_UserRanande2),
                                    Fk_UserRanandeHamkarEdare3 = ParseInt(Fk_UserRanande3),
                                    NamKharejRanande1 = NamKharejRanande1,
                                    NamKharejRanande2 = NamKharejRanande2,
                                    NamKharejRanande3 = NamKharejRanande3,
                                    CodeMeliKharejRanande1 = CodeMeliRanande1,
                                    CodeMeliKharejRanande2 = CodeMeliRanande2,
                                    CodeMeliKharejRanande3 = CodeMeliRanande3,
                                    TavalodKharejRanande1 = ParseDate(TavalodRanande1),
                                    TavalodKharejRanande2 = ParseDate(TavalodRanande2),
                                    TavalodKharejRanande3 = ParseDate(TavalodRanande3),
                                    ShomareTamasKharejRanande1 = ShomareTamas1,
                                    ShomareTamasKharejRanande2 = ShomareTamas2,
                                    ShomareTamasKharejRanande3 = ShomareTamas3,
                                    CodePostKharejRanande1 = CodePost1,
                                    CodePostKharejRanande2 = CodePost2,
                                    CodePostKharejRanande3 = CodePost3,
                                    AdresKharejRanande1 = Adres1,
                                    AdresKharejRanande2 = Adres2,
                                    AdresKharejRanande3 = Adres3,
                                    VaziatSalamatKhodro = ParseInt(VaziatSalamat),
                                    DalayelPishfarz = ParseLong(DalayelPishfarz),
                                    Sharh = Sharh,
                                    TarikhKhatemeEtebar = miladiDate2,
                                    SherkatBimegar = SherkatBimegar,
                                    VaziatBimeShakhsSales = ParseInt(VaziatBime),
                                    VaziatMoayeneFani = ParseInt(VaziatMoayene)
                                };

                                db.Table_Khodro.Add(newItem);
                                inserted++;
                            }
                        }

                        await db.SaveChangesAsync();
                        transaction.Commit();

                        return "✅ عملیات انجام شد. {inserted} رکورد جدید درج و {updated} رکورد بروزرسانی شد.";
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();
                        return "❌ خطا در پردازش فایل: " + ex.Message;
                    }
                }
            }
            catch (Exception ex)
            {
                return "❌ خطای کلی: " + ex.Message;
            }
        }
        public ActionResult SaveEstedadKhodro(List<tbSabtEstedadKhodro> items)
        {
            try
            {
                using (var db = new SaabEntities())
                {
                    var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                    if (cookie_user == null)
                        return Json(new { success = false, message = "کوکی یافت نشد." });

                    var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                    var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                    if (user == null)
                        return Json(new { success = false, message = "کاربر یافت نشد." });

                    int personal = user.usr_ID;

                    foreach (var item in items)
                    {
                        var existing = db.tbSabtEstedadKhodro
                            .FirstOrDefault(x => x.FK_ == item.FK_ &&
                                                 DbFunctions.TruncateTime(x.TarikhSabt) ==
                                                 DbFunctions.TruncateTime(item.TarikhSabt));

                        if (existing != null)
                        {
                            existing.VaziatHozor = item.VaziatHozor;
                            existing.Kilometr = item.Kilometr;
                            existing.NoeAmaliat = item.NoeAmaliat;
                            existing.VaziatKhodro = item.VaziatKhodro;
                            existing.NoeEyb = item.NoeEyb;
                            existing.Sharh = item.Sharh;
                            existing.SaatShoro = item.SaatShoro;
                            existing.SaatKhateme = item.SaatKhateme;
                            existing.SaatShoro1 = TimeHelper.ConvertToDateTime(item.SaatShoro);
                            existing.SaatKhateme1 = TimeHelper.ConvertToDateTime(item.SaatKhateme);
                            existing.UserSabt = personal;
                            existing.TarikhSabt = item.TarikhSabt;
                        }
                        else
                        {
                            item.FK_ = item.FK_;
                            item.VaziatHozor = item.VaziatHozor;
                            item.Kilometr = item.Kilometr;
                            item.NoeAmaliat = item.NoeAmaliat;
                            item.VaziatKhodro = item.VaziatKhodro;
                            item.NoeEyb = item.NoeEyb;
                            item.Sharh = item.Sharh;
                            item.SaatShoro = item.SaatShoro;
                            item.SaatKhateme = item.SaatKhateme;
                            item.SaatShoro1 = TimeHelper.ConvertToDateTime(item.SaatShoro);
                            item.SaatKhateme1 = TimeHelper.ConvertToDateTime(item.SaatKhateme);
                            item.UserSabt = personal;
                            db.tbSabtEstedadKhodro.Add(item);
                        }
                    }

                    db.SaveChanges();
                }

                return Json(new { success = true, message = "ثبت با موفقیت انجام شد." });
            }
            catch (Exception ex)
            {

                System.Diagnostics.Debug.WriteLine("خطا در SaveEstedadKhodro: " + ex.Message);

                return Json(new
                {
                    success = false,
                    message = "در هنگام ثبت خطایی رخ داد: " + ex.Message
                });
            }
        }


        public ActionResult BargashEstedadKhodroByDate(DateTime date)
        {
            try
            {
                // 🔹 دریافت کاربر لاگین‌شده
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return Json(new { success = false, message = "کوکی یافت نشد" });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return Json(new { success = false, message = "کاربر یافت نشد" });

                long personalId = user.usr_ID;

                // 🔹 همه کاربرانی که باید نمایش داده شوند (مثلاً راننده‌ها یا مرتبط‌ها)
                // اگر همه کاربران مدنظرند:
                var allUsers = db.Table_Khodro

                    .ToList();

                // 🔹 داده‌های ثبت‌شده برای آن تاریخ
                var existingData = db.tbSabtEstedadKhodro
                    .Where(x => DbFunctions.TruncateTime(x.TarikhSabt) == date.Date)
                    .ToList();

                // 🔹 ادغام داده‌های موجود با لیست کاربران (پر یا خالی)
                var model = allUsers.Select(u =>
                {
                    var data = existingData.FirstOrDefault(e => e.FK_ == u.ID);
                    return new tbSabtEstedadKhodro
                    {
                        FK_ = u.ID,
                        VaziatHozor = data?.VaziatHozor,
                        Kilometr = data?.Kilometr,
                        NoeAmaliat = data?.NoeAmaliat,
                        VaziatKhodro = data?.VaziatKhodro,
                        NoeEyb = data?.NoeEyb,
                        Sharh = data?.Sharh,
                        SaatShoro = data?.SaatShoro,
                        SaatKhateme = data?.SaatKhateme,
                        TarikhSabt = date,
                        Table_Khodro = u
                    };
                }).ToList();

                var model2 = new FunctionModel
                {
                    madarek_sabtdoreh_4 = db.madarek_sabtdoreh_4.ToList(),
                    tbSabtEstedadKhodro = model,
                    Table_Khodro = db.Table_Khodro.ToList(),
                    SelectedDate = date
                };

                return PartialView("~/Areas/Setting/Views/Orders/BargashEstedadKhodroByDate.cshtml", model2);
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = "خطا: " + ex.Message });
            }
        }

        public static class TimeHelper
        {
            public static DateTime? ConvertToDateTime(string time)
            {
                try
                {
                    if (string.IsNullOrWhiteSpace(time))
                        return null; // ⛔ اگر خالی بود، نال برگردون

                    // حذف فاصله‌ها و اطمینان از وجود دو رقم در ساعت و دقیقه
                    time = time.Trim();
                    if (time.Length == 4 && time[1] == ':')
                        time = "0" + time; // مثلا "8:30" → "08:30"

                    string[] formats = { "HH:mm", "H:mm", "HH:mm:ss", "H:mm:ss" };
                    if (DateTime.TryParseExact(time, formats, CultureInfo.InvariantCulture,
                        DateTimeStyles.None, out DateTime result))
                    {
                        return result;
                    }

                    return null; // ❌ اگر فرمت نادرست بود، خطا نده
                }
                catch
                {
                    return null; // ⚠️ به‌جای خطا، مقدار خنثی برگردون
                }
            }
        }

