                        if (item.Vaziat == 0)
                        {
                            tb.SaatVorod = item.SaatVorod;
                            tb.SaatKhorog = item.SaatKhorog;
                            tb.SaatVorod1 = TimeHelper.ConvertToDateTime(item.SaatVorod);
                            tb.SaatKhorog1 = TimeHelper.ConvertToDateTime(item.SaatKhorog);
                            tb.Sharh = item.Sharh;
                            //tb.SaatShoro = null;
                            //tb.SaatKhateme = null;
                            //tb.SaatShoro1 = null;
                            //tb.SaatKhateme1 = null;
                            //tb.SaatShoro = item.SaatShoro;
                            //tb.SaatKhateme = item.SaatKhateme;
                            //tb.SaatShoro1 = TimeHelper.ConvertToDateTime(item.SaatShoro); 
                            //tb.SaatKhateme1 = TimeHelper.ConvertToDateTime(item.SaatKhateme);
                        }
                        else
                        {
                            tb.SaatShoro = item.SaatShoro;
                            tb.SaatKhateme = item.SaatKhateme;
                            tb.SaatShoro1 = TimeHelper.ConvertToDateTime(item.SaatShoro);
                            tb.SaatKhateme1 = TimeHelper.ConvertToDateTime(item.SaatKhateme);
                            //tb.SaatVorod = null;
                            //tb.SaatKhorog = null;
                            //tb.SaatVorod1 = null;
                            //tb.SaatKhorog1 = null;
                            tb.SaatVorod = item.SaatVorod;
                            tb.SaatKhorog = item.SaatKhorog;
                            tb.SaatVorod1 = TimeHelper.ConvertToDateTime(item.SaatVorod);
                            tb.SaatKhorog1 = TimeHelper.ConvertToDateTime(item.SaatKhorog);
                            tb.Sharh = item.Sharh;
                        }
                    }

                    db.SaveChanges();
                    return Json(new { success = true, message = "✅ ثبت یا بروزرسانی اطلاعات با موفقیت انجام شد." });
                }

                return Json(new { success = false, message = "اطلاعات ارسالی معتبر نیست." });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = "❌ خطا در ثبت اطلاعات: " + ex.Message });
            }
        }
