        public ActionResult BargashEstedadNiroEnsaniByDate(DateTime date)
        {
            try
            {
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return Json(new { success = false, message = "کوکی یافت نشد" });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return Json(new { success = false, message = "کاربر یافت نشد" });

                var personal = user.usr_ID;

                // 🔹 زیرمجموعه‌ها
                //var subUsers = db.tbAdamAdam
                //    .Where(a => a.Name == personal && a.Value == 1)
                //    .Join(db.tbUsers,
                //          a => a.nam,        // ستون nam یعنی زیرمجموعه‌ها
                //          u => u.usr_ID,
                //          (a, u) => u)
                //    .ToList();
                var subUsers = (from a in db.tbAdamAdam
                                join u in db.tbUsers on a.nam equals u.usr_ID
                                join c in db.closed_time_estedad on u.usr_ID equals c.FK_usr
                                where a.Name == personal
                                      && a.Value == 1
                                      && DbFunctions.TruncateTime(date) >= DbFunctions.TruncateTime(c.time)
                                      && DbFunctions.TruncateTime(date) <= DbFunctions.TruncateTime(c.timeend)
                                select u).ToList();
                // 🔹 داده‌های استعداد ثبت‌شده برای تاریخ انتخابی
                var estedadData = db.EstedadNiroEnsani
                    .Where(x => DbFunctions.TruncateTime(x.Timesabt) == date.Date)
                    .ToList();

                // 🔹 ادغام داده‌ها: زیرمجموعه‌ها + اطلاعات ثبت‌شده (اگر وجود داشته باشد)
                var mergedList = subUsers.Select(u => new UserEstedadViewModel
                {
                    usr_ID = u.usr_ID,
                    FullName = u.FullName,
                    usr_Personal_ID = u.usr_Personal_ID,
                    SaatShoro = estedadData.FirstOrDefault(e => e.Fk_User == u.usr_ID)?.SaatShoro,
                    SaatKhateme = estedadData.FirstOrDefault(e => e.Fk_User == u.usr_ID)?.SaatKhateme,
                    SaatVorod = estedadData.FirstOrDefault(e => e.Fk_User == u.usr_ID)?.SaatVorod,
                    SaatKhorog = estedadData.FirstOrDefault(e => e.Fk_User == u.usr_ID)?.SaatKhorog,
                    Vaziat = estedadData.FirstOrDefault(e => e.Fk_User == u.usr_ID)?.Vaziat,
                    Sharh = estedadData.FirstOrDefault(e => e.Fk_User == u.usr_ID)?.Sharh
                }).ToList();

                // 🔹 مدل نهایی برای ارسال به PartialView
                var model = new FunctionModel
                {
                    SubUsersData = mergedList,
                    SelectedDate = date
                };

                return PartialView("~/Areas/Setting/Views/Orders/BargashEstedadNiroEnsaniByDate.cshtml", model);
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = "خطا: " + ex.Message });
            }
        }















