        [HttpPost]
        public JsonResult SaveAbzarEstedad(List<AbzarEstedadDto> data)
        {
            try
            {


                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return Json(new { success = false, message = "کوکی یافت نشد" });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return Json(new { success = false, message = "کاربر یافت نشد" });

                int personal = user.usr_ID;


                foreach (var item in data)
                {

                    //var existing = db.tbTarifAbzarKar2Estedad
                    //    .FirstOrDefault(x => x.Fk_tarifabzarkar == item.Fk_tarifabzarkar);
                    var existing = db.tbTarifAbzarKar2Estedad
                                                           .FirstOrDefault(x => x.Fk_tarifabzarkar == item.Fk_tarifabzarkar
                                        && x.TimeSabt == item.TimeSabt);


                    if (existing != null)
                    {

                        existing.SalemZakhire = item.SalemZakhire;
                        existing.SalemMamor = item.SalemMamor;
                        existing.NiyazmandTamir = item.NiyazmandTamir;
                        existing.GomShode = item.GomShode;
                        existing.jam = item.jam;
                        existing.Sharh = item.Sharh;
                        existing.TimeSabt = item.TimeSabt;
                    }
                    else
                    {

                        var entity = new tbTarifAbzarKar2Estedad
                        {
                            Fk_tarifabzarkar = item.Fk_tarifabzarkar,
                            SalemZakhire = item.SalemZakhire,
                            SalemMamor = item.SalemMamor,
                            NiyazmandTamir = item.NiyazmandTamir,
                            GomShode = item.GomShode,
                            jam = item.jam,
                            Sharh = item.Sharh,
                            TimeSabt = item.TimeSabt,
                            UserSabt = personal

                        };

                        db.tbTarifAbzarKar2Estedad.Add(entity);
                    }
                }

                db.SaveChanges();

                return Json(new { success = true });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, error = ex.Message });
            }
        }

