        [HttpPost]
        public JsonResult SaveKalaEstedad(List<KalaEstedadDto> data)
        {
            try
            {
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return Json(new { success = false, message = "کوکی یافت نشد" });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return Json(new { success = false, message = "کاربر یافت نشد" });

                int personal = user.usr_ID;


                foreach (var item in data)
                {
                    var exist = db.tbTarifKalayeAsasi2Estedad
   .FirstOrDefault(x => x.Fk_TarifKalayeAsasi == item.Fk_TarifKalayeAsasi
                     && DbFunctions.TruncateTime(x.TimeSabt) == DbFunctions.TruncateTime(item.TimeSabt));

                    if (exist != null)
                    {
                        // آپدیت
                        exist.DarAnbar = item.DarAnbar;
                        exist.nazdMamor = item.NazdMamor;
                        exist.Jam = item.Jam;
                        exist.Sharh = item.Sharh;
                        exist.TimeSabt = item.TimeSabt;
                    }
                    else
                    {
                        // اینسرت
                        var tb = new tbTarifKalayeAsasi2Estedad
                        {
                            Fk_TarifKalayeAsasi = item.Fk_TarifKalayeAsasi,
                            DarAnbar = item.DarAnbar,
                            nazdMamor = item.NazdMamor,
                            Jam = item.Jam,
                            Sharh = item.Sharh,
                            TimeSabt = item.TimeSabt,
                            UserSabt = personal

                        };
                        db.tbTarifKalayeAsasi2Estedad.Add(tb);
                    }
                }


                db.SaveChanges();

                return Json(new { success = true, message = "✅ با موفقیت ذخیره شد" });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = "❌ خطا: " + ex.Message });
            }
        }






