        public ActionResult SubmitEvaluation()
        {
            try
            {
                Request.InputStream.Position = 0;
                var reader = new StreamReader(Request.InputStream);
                string json = reader.ReadToEnd();

                // مرحله ۱: تبدیل JSON به مدل C# ناشناس
                var data = JsonConvert.DeserializeObject<DynamicEvaluationModel>(json);

                // مرحله ۲: ذخیره ارزیابی در arzyzbi1
                var evaluation = new arzyzbi1
                {
                    name = data.title,
                    typegozaresh = data.typegozarwsh,
                    datatime = DateTime.Now
                    // usrsabt = 123; // در صورت نیاز
                };
                db.arzyzbi1.Add(evaluation);
                db.SaveChanges();

                foreach (var q in data.questions)
                {
                    var soal = new arzyzbi2_soal
                    {
                        FK_arzyzbi1 = evaluation.ID,
                        soal = q.text,
                        sharh = q.description,
                        datatime = DateTime.Now
                    };
                    db.arzyzbi2_soal.Add(soal);
                    db.SaveChanges();

                    foreach (var opt in q.options)
                    {
                        var gozineh = new arzyzbi3_gozeneh
                        {
                            FK_arzyabisoal = soal.ID,
                            gozineh = opt.text,
                            vazn = opt.weight ?? 0,
                            datatime = DateTime.Now
                        };
                        db.arzyzbi3_gozeneh.Add(gozineh);
                    }
                    db.SaveChanges();
                }

                return Json(new { success = true });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }
        public class DynamicEvaluationModel
        {
            public string title { get; set; }
            public int typegozarwsh { get; set; }

            public List<QuestionModel> questions { get; set; }
        }

        public class QuestionModel
        {
            public string text { get; set; }
            public string description { get; set; }
            public List<OptionModel> options { get; set; }
        }

        public class OptionModel
        {
            public string text { get; set; }
            public int? weight { get; set; }
        }
