        public async Task<string> Linkarzyab(List<arzyzbi4_link> modelList)
        {
            var find34 = await db.arzyzbi4_link.ToListAsync();

            foreach (var it in modelList)
            {
                var find = find34.Where(p => p.FK_usr == it.FK_usr && p.FK_arzyzbi1 == it.FK_arzyzbi1).FirstOrDefault();
                if (find != null)
                {
                    if (find.vaziat != it.vaziat)
                    {
                        find.vaziat = it.vaziat;
                    }


                }
                else
                {
                    db.arzyzbi4_link.Add(it);
                }
            }
            await db.SaveChangesAsync();
            return "true";
        }
