        public async Task<ActionResult> arzyabivaluekarbaremtehan()
        {
            var model = new FunctionModel
            {
                tbAdamAdam2 = new List<tbAdamAdam2>(),

                tbAdamAdam = new List<tbAdamAdam>(),
                arzyzbi5_time = new List<arzyzbi5_time>()
            };

            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;

            var findurlist = db.arzyzbi4_link
                .Where(s => s.FK_usr == personal && s.vaziat == true && s.arzyzbi1.Active != false)
                .ToList();

            //var findurlistusr = await db.tbAdamAdam
            //    .Where(s => s.Name == personal && s.Value == 1)
            //    .ToListAsync();

            //model.tbAdamAdam.AddRange(findurlistusr);
            var findurlistusr1 = await db.tbAdamAdam
    .Where(s => s.Name == personal && s.Value == 1)
    .ToListAsync();

            foreach (var adam in findurlistusr1)
            {
                var user1 = db.tbUsers.FirstOrDefault(u => u.usr_ID == adam.nam);
                if (user1 != null)
                {
                    var tbAdamAdam22 = new tbAdamAdam2();
                    tbAdamAdam22.ID = user1.usr_ID;
                    tbAdamAdam22.fullname = user1.FullName;
                    model.tbAdamAdam2.Add(tbAdamAdam22);

                }

                //adam.ExtraFullname = user.fullname; // این پراپرتی باید به صورت دستی به tbAdamAdam اضافه بشه (ViewModel یا Partial Class)
            }
            foreach (var it in findurlist)
            {
                var times = await db.arzyzbi5_time
                    .Where(s => s.FK_arzyzbi1 == it.FK_arzyzbi1 && s.arzyzbi1.typegozaresh == 3
                               )
                    .ToListAsync();

                foreach (var time in times)
                {
                    // فقط اگر namedoreh هنوز داخل مدل وجود نداشت، اضافه کن
                    if (!model.arzyzbi5_time.Any(x => x.namedoreh == time.namedoreh && x.FK_arzyzbi1 == time.FK_arzyzbi1))
                    {
                        model.arzyzbi5_time.Add(time);
                    }
                }
            }

            return PartialView("~/Areas/Setting/Views/Orders/arzyabivaluekarbaremtehan.cshtml", model);
        }
