        public JsonResult GetPeyman2Search(string term, int month, int year)
        {
            var query = db.Create_linkrelation2job_3
                          .Where(s => s.Create_linkjob_2.month == month &&
                                      s.Create_linkjob_2.year == year &&
                                      s.unic.Contains(term))  // فقط رکوردهای مرتبط با term
                          .OrderBy(s => s.ID)
                          .Take(50)  // حداکثر ۵۰ رکورد برگردان
                          .Select(s => new { id = s.ID, text = s.unic })
                          .ToList();

            return Json(query, JsonRequestBehavior.AllowGet);
        }
        public async Task<JsonResult> GetLinkAutocomplete(string term, int month = 5, int year = 1404)
        {
            try
            {
                var results = await db.Create_linkrelation2job_3
                    .AsNoTracking()
                    .Where(s => s.Create_linkjob_2.month == month && s.Create_linkjob_2.year == year)
                    .Where(x => x.unic.Contains(term)) // جستجوی سمت سرور
                    .OrderBy(x => x.unic)
                    .Select(x => new
                    {
                        label = x.unic,
                        value = x.ID
                    })
                    .Take(20) // محدود کردن نتایج
                    .ToListAsync();

                return Json(results, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                return Json(new { error = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }

