        public async Task<string> GetDataFromExcel_filetaeed(HttpPostedFileBase MyExcelStream, long IDgozareh = 0)
        {
            // گرفتن همه رکوردهای مرتبط
            //var fidnds = db.dbergharel_4
            //    .Where(s => s.FK_namegozarwsh == ID)
            //    .ToList();

            //if (fidnds == null || fidnds.Count == 0)
            //    return "هیچ رکوردی برای این گزارش یافت نشد";

            int totalInserted = 0;

            try
            {
                List<Create_linkrelation2job_3> Create_linkrelation2job_3 = new List<Create_linkrelation2job_3>();

                // تنظیمات ExcelDataReader
                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration()
                    {
                        ConfigureDataTable = _ => new ExcelDataTableConfiguration()
                        {
                            UseHeaderRow = false // ما خودمون مدیریت هدر رو می‌کنیم
                        }
                    });

                    int countsheet = 0;
                    //string unic = fidnd.unic;

                    if (countsheet >= dataSet.Tables.Count)
                        return $"تعداد شیت‌های اکسل کمتر از مقدار تعیین شده در دیتابیس است (مقدار: {countsheet})";

                    var sheet = dataSet.Tables[countsheet];
                    if (sheet.Rows.Count <= 1)
                        return "این شیت فاقد اطلاعات است";



                    // گرفتن کاربر از کوکی
                    int personal = 0;
                    var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                    if (cookie_user != null)
                    {
                        var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                        var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                        if (user != null)
                            personal = user.usr_ID;
                    }

                    // تابع کمکی برای گرفتن مقدار سلول با حرف ستون
                    string GetCellValueByLetter(DataRow row, string columnLetter)
                    {
                        if (string.IsNullOrEmpty(columnLetter))
                            return null;

                        int columnIndex = ColumnLetterToIndex(columnLetter); // تبدیل A=0, B=1, ...
                        if (columnIndex < 0 || columnIndex >= sheet.Columns.Count)
                            return null;

                        return row[columnIndex]?.ToString();
                    }

                    // پیمایش سطرها (از ردیف دوم به بعد چون اولی هدر است)
                    for (int i = 1; i < sheet.Rows.Count; i++)
                    {
                        var dataRow = sheet.Rows[i];
                        //string unicValue = GetCellValueByLetter(dataRow, unic);

                        string valueFK = GetCellValueByLetter(dataRow, "A");

                        Create_linkrelation2job_3.Add(new Create_linkrelation2job_3
                        {
                            FK_linkjob = IDgozareh,
                            unic = valueFK,

                        });

                    }

                    totalInserted += sheet.Rows.Count - 1;
                }

                // ایجاد DataTable و BulkInsert
                var dataTable = CreateDataTable_dbergharelimsertfk1_Create_linkrelation2job_3(Create_linkrelation2job_3);
                int insertedCount = await BulkInsert_dbergharelimsertfk1_Create_linkrelation2job_33(dataTable);

                return $"با موفقیت {insertedCount} رکورد درج شد (از {totalInserted} ردیف خوانده‌شده)";
            }
            catch (Exception ex)
            {
                return "خطا: " + ex.Message;
            }
        }




        public class ExcelPreviewVM
        {
            public string unic { get; set; }
            public int? FK_usr { get; set; }
            public int month { get; set; }
            public int year { get; set; }
            public Dictionary<string, string> ExtraColumns { get; set; } = new Dictionary<string, string>();
            public string ValueE { get; set; }

            // فقط برای پیش‌نمایش
            public string FullName { get; set; }
            public string Job { get; set; }
        }

        public ActionResult PreviewExcel(HttpPostedFileBase MyExcelStream, int year, int month, long job)
        {
            try
            {
                List<ExcelPreviewVM> records = new List<ExcelPreviewVM>();
                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration()
                    {
                        ConfigureDataTable = _ => new ExcelDataTableConfiguration()
                        {
                            UseHeaderRow = false
                        }
                    });

                    var sheet = dataSet.Tables[0];
                    if (sheet.Rows.Count <= 1)
                        return Json(new { success = false, message = "این شیت فاقد اطلاعات است" }, JsonRequestBehavior.AllowGet);

                    // گرفتن نام ستون‌ها از ردیف 0
                    List<string> extraColumns = new List<string>();
                    for (int c = 5; c < sheet.Columns.Count; c++) // ستون F = index 5
                    {
                        extraColumns.Add(sheet.Rows[0][c]?.ToString() ?? $"Column{c + 1}");
                    }

                    for (int i = 1; i < sheet.Rows.Count && i <= 5000; i++) // فقط 5000 ردیف
                    {
                        var row = sheet.Rows[i];
                        string valueFK = row[0]?.ToString();
                        string job22 = row[1]?.ToString();
                        int.TryParse(row[2]?.ToString(), out int codprselly);
                        string fullname = row[3]?.ToString();

                        // ستون E (index 4) نباید خالی باشد
                        string valueE = row[4]?.ToString();
                        if (string.IsNullOrWhiteSpace(valueE))
                        {
                            valueE = ""; // مقدار placeholder
                        }

                        // جمع‌آوری مقادیر ستون‌های اضافی
                        Dictionary<string, string> extraValues = new Dictionary<string, string>();
                        for (int c = 5; c < sheet.Columns.Count; c++)
                        {
                            string colName = extraColumns[c - 5];
                            string colValue = row[c]?.ToString() ?? "";
                            extraValues[colName] = colValue;
                        }

                        records.Add(new ExcelPreviewVM
                        {
                            unic = valueFK,
                            FK_usr = codprselly,
                            FullName = fullname,
                            Job = job22,
                            ValueE = valueE, // اضافه شد
                            ExtraColumns = extraValues
                        });
                    }
                }

                return Json(new { success = true, preview = records }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }



