        public async Task<string> GetDataFromExcel_filetaeedlinkmamor(HttpPostedFileBase MyExcelStream, int year, int month)
        {
            int totalInserted = 0;

            try
            {
                List<Create_linkmamorjob_4> Create_linkrelation2job_3 = new List<Create_linkmamorjob_4>();

                // 📌 تنظیمات ExcelDataReader
                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration()
                    {
                        ConfigureDataTable = _ => new ExcelDataTableConfiguration()
                        {
                            UseHeaderRow = false
                        }
                    });

                    int countsheet = 0;
                    if (countsheet >= dataSet.Tables.Count)
                        return $"تعداد شیت‌های اکسل کمتر از مقدار تعیین شده است (مقدار: {countsheet})";

                    var sheet = dataSet.Tables[countsheet];
                    if (sheet.Rows.Count <= 1)
                        return "این شیت فاقد اطلاعات است";

                    // 📌 همه لینک‌ها و یوزرها
                    var allLinks = db.Create_linkrelation2job_3
                                     .Select(x => new { x.ID, x.unic })
                                     .AsNoTracking()
                                     .ToList();

                    var allUsers = db.tbUsers
                                     .Where(u => u.usr_Personal_ID != null)
                                     .Select(u => new { u.usr_ID, u.usr_Personal_ID })
                                     .AsNoTracking()
                                     .ToList();

                    var linkDict = allLinks
                        .GroupBy(x => x.unic)
                        .ToDictionary(g => g.Key, g => (long?)g.First().ID);

                    var userDict = allUsers
                        .GroupBy(x => x.usr_Personal_ID.Value)
                        .ToDictionary(g => g.Key, g => (int?)g.First().usr_ID);
                    var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];

                    int personal = 0;
                    string fullnamesabt = "";
                    int person = 0;
                    int cityyy = 0;
                    string cityname = "";
                    if (cookie_user != null)
                    {
                        var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                        var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                        personal = user.usr_ID;
                        fullnamesabt = user.FullName;
                        person = (int)user.usr_Personal_ID;
                        if (user.usr_City_Dutysystem != null)
                        {
                            cityyy = (int)user.usr_City_Dutysystem;
                            var findcit = db.tbCities.Where(s => s.ID == cityyy).FirstOrDefault();
                            if (findcit != null)
                            {
                                cityname = findcit.Name;
                            }
                        }
                    }
                    // 📌 تابع کمکی برای گرفتن مقدار سلول
                    string GetCellValueByLetter(DataRow row, string columnLetter)
                    {
                        if (string.IsNullOrEmpty(columnLetter))
                            return null;

                        int columnIndex = ColumnLetterToIndex(columnLetter);
                        if (columnIndex < 0 || columnIndex >= sheet.Columns.Count)
                            return null;

                        return row[columnIndex]?.ToString();
                    }

                    // 📌 پیمایش سطرها
                    for (int i = 1; i < sheet.Rows.Count; i++)
                    {
                        var dataRow = sheet.Rows[i];
                        string valueFK = GetCellValueByLetter(dataRow, "A");

                        string codStr = GetCellValueByLetter(dataRow, "C");
                        int.TryParse(codStr, out int codprselly);
                        string valuname = GetCellValueByLetter(dataRow, "E");


                        int monthlly = month;
                        int yearlly = year;
                        long? fkLink = null;
                        if (!string.IsNullOrEmpty(valueFK) && linkDict.ContainsKey(valueFK))
                            fkLink = linkDict[valueFK];

                        int? fkUsr = null;
                        if (userDict.ContainsKey(codprselly))
                            fkUsr = userDict[codprselly];
                        PersianCalendar pc = new PersianCalendar();

                        DateTime now = DateTime.Now;

                        string persianDateTime =
                            $"{pc.GetDayOfMonth(now)}/{pc.GetMonth(now)}/{pc.GetYear(now)}" +
                            $"_{pc.GetHour(now):00}:{pc.GetMinute(now):00}:{pc.GetSecond(now):00}";
                        Create_linkrelation2job_3.Add(new Create_linkmamorjob_4
                        {
                            FK_link = fkLink,
                            FK_usr = fkUsr,
                            unic = valueFK,
                            month = monthlly,
                            year = yearlly,
                            valueamal = valuname,
                            timesabtsahmsi = persianDateTime,
                            Fullnamesabt = fullnamesabt,
                            personalIDsabt = person,
                            cityname = cityname,
                            fk_city = cityyy,
                            FK_usrsabt = personal,
                            TIMESABT = DateTime.Now


                        });
                    }

                    totalInserted += sheet.Rows.Count - 1;
                }

                // 📌 تبدیل به DataTable و BulkUpsert
                var dataTable = CreateDataTable_dbergharelimsertfk1_Create_linkmamorjob_4(Create_linkrelation2job_3);
                //var (insertedCount, updatedCount) = await BulkUpsertByKeyAsync(dataTable);
                int insertedOrUpdatedCount = await BulkInsert_dbergharelimsertfk1_7122(dataTable);

                // 📌 آخرین رکوردها
                var last30 = db.Create_linkmamorjob_4
                               .OrderByDescending(x => x.ID)
                               .Take(insertedOrUpdatedCount)
                               .AsEnumerable()
                               .Select(x => new
                               {
                                   x.unic,
                                   PersonalID = x.tbUsers?.usr_Personal_ID,
                                   FullName = x.tbUsers?.FullName,
                                   x.month,
                                   x.year
                               })
                               .ToList();

                return JsonConvert.SerializeObject(new
                {
                    success = true,
                    message = $"با موفقیت {insertedOrUpdatedCount} رکورد درج و {insertedOrUpdatedCount} رکورد آپدیت شد (از {totalInserted} ردیف خوانده‌شده)",
                    lastRecords = last30
                });
            }
            catch (Exception ex)
            {
                var last30 = db.Create_linkmamorjob_4
                               .OrderByDescending(x => x.ID)
                               .Take(30)
                               .AsEnumerable()
                               .Select(x => new
                               {
                                   x.unic,
                                   PersonalID = x.tbUsers?.usr_Personal_ID,
                                   FullName = x.tbUsers?.FullName,
                                   x.month,
                                   x.year
                               })
                               .ToList();

                return JsonConvert.SerializeObject(new
                {
                    success = false,
                    message = $"خطا: {ex.Message}",
                    lastRecords = last30
                });
            }
        }

        private async Task<(int InsertedCount, int UpdatedCount)> BulkUpsertByKeyAsync(System.Data.DataTable dataTable)
        {
            if (dataTable == null || dataTable.Rows.Count == 0)
                return (0, 0);

            string connectionString = GetSqlConnectionString();
            int inserted = 0, updated = 0;

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();

                string tempTableName = "#Temp_Create_linkmamorjob_4";

                string createTempSql = $@"
            IF OBJECT_ID('tempdb..{tempTableName}') IS NOT NULL DROP TABLE {tempTableName};
            CREATE TABLE {tempTableName} (
                SrcRowId BIGINT IDENTITY(1,1) PRIMARY KEY,
                FK_link BIGINT NOT NULL,
                unic NVARCHAR(255) COLLATE Persian_100_BIN NULL,
                FK_usr INT NULL,
                month INT NOT NULL,
                year INT NOT NULL
            );";
                using (var cmd = new SqlCommand(createTempSql, connection))
                    await cmd.ExecuteNonQueryAsync();

                using (SqlBulkCopy bulkCopy = new SqlBulkCopy(connection,
                    SqlBulkCopyOptions.TableLock | SqlBulkCopyOptions.CheckConstraints, null))
                {
                    bulkCopy.DestinationTableName = tempTableName;
                    bulkCopy.BatchSize = 50000;
                    bulkCopy.BulkCopyTimeout = 0;

                    bulkCopy.ColumnMappings.Add("FK_link", "FK_link");
                    bulkCopy.ColumnMappings.Add("unic", "unic");
                    bulkCopy.ColumnMappings.Add("FK_usr", "FK_usr");
                    bulkCopy.ColumnMappings.Add("month", "month");
                    bulkCopy.ColumnMappings.Add("year", "year");

                    await bulkCopy.WriteToServerAsync(dataTable);
                }

                string mergeSql = $@"
            SET NOCOUNT ON;
            DECLARE @MergeResults TABLE (Action NVARCHAR(10));

            ;WITH SourceDedup AS (
                SELECT FK_link, unic, FK_usr, month, year,
                       ROW_NUMBER() OVER (
                           PARTITION BY FK_link, month, year 
                           ORDER BY SrcRowId DESC
                       ) AS rn
                FROM {tempTableName}
            )
            , SourceFinal AS (
                SELECT FK_link, unic, FK_usr, month, year
                FROM SourceDedup
                WHERE rn = 1
            )
            MERGE dbo.Create_linkmamorjob_4 AS Target
            USING SourceFinal AS Source
            ON Target.FK_link = Source.FK_link
               AND Target.month = Source.month
               AND Target.year = Source.year
            WHEN MATCHED THEN
                UPDATE SET Target.FK_usr = Source.FK_usr
            WHEN NOT MATCHED BY TARGET THEN
                INSERT (FK_link, unic, FK_usr, month, year)
                VALUES (Source.FK_link, Source.unic, Source.FK_usr, Source.month, Source.year)
            OUTPUT $action INTO @MergeResults;

            SELECT 
                SUM(CASE WHEN Action = 'INSERT' THEN 1 ELSE 0 END) AS InsertedCount,
                SUM(CASE WHEN Action = 'UPDATE' THEN 1 ELSE 0 END) AS UpdatedCount
            FROM @MergeResults;";

                using (var cmd = new SqlCommand(mergeSql, connection))
                using (var reader = await cmd.ExecuteReaderAsync())
                {
                    if (await reader.ReadAsync())
                    {
                        inserted = reader.IsDBNull(0) ? 0 : reader.GetInt32(0);
                        updated = reader.IsDBNull(1) ? 0 : reader.GetInt32(1);
                    }
                }

                using (var dropCmd = new SqlCommand($"DROP TABLE IF EXISTS {tempTableName};", connection))
                    await dropCmd.ExecuteNonQueryAsync();
            }

            return (inserted, updated);
        }

        private async Task<int> BulkUpsertByKeyAsyn2c(System.Data.DataTable dataTable)
        {
            int rowsAffected = 0;
            string connectionString = GetSqlConnectionString();

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();

                string tempTableName = "#Temp_Create_linkmamorjob_4";

                // 1) ایجاد جدول موقت
                using (SqlCommand createTempCmd = new SqlCommand($@"
            IF OBJECT_ID('tempdb..{tempTableName}') IS NOT NULL DROP TABLE {tempTableName};
            CREATE TABLE {tempTableName} (
                FK_link BIGINT NOT NULL,
                unic NVARCHAR(255) COLLATE Persian_100_BIN NULL,
                FK_usr INT NULL,
                month INT NOT NULL,
                year INT NOT NULL
            );", connection))
                {
                    await createTempCmd.ExecuteNonQueryAsync();
                }

                // 2) BulkCopy دیتای اکسل → جدول موقت
                using (SqlBulkCopy bulkCopy = new SqlBulkCopy(connection,
                    SqlBulkCopyOptions.TableLock | SqlBulkCopyOptions.CheckConstraints, null))
                {
                    bulkCopy.DestinationTableName = tempTableName;
                    bulkCopy.BatchSize = 50000;
                    bulkCopy.BulkCopyTimeout = 0;

                    bulkCopy.ColumnMappings.Add("FK_link", "FK_link");
                    bulkCopy.ColumnMappings.Add("unic", "unic");
                    bulkCopy.ColumnMappings.Add("FK_usr", "FK_usr");
                    bulkCopy.ColumnMappings.Add("month", "month");
                    bulkCopy.ColumnMappings.Add("year", "year");

                    await bulkCopy.WriteToServerAsync(dataTable);
                }

                // 3) MERGE → آپدیت فقط آخرین رکورد یا اینسرت
                string mergeSql = $@"
            ;WITH LatestTarget AS (
                SELECT t.*
                FROM dbo.Create_linkmamorjob_4 t
                INNER JOIN (
                    SELECT FK_link, month, year, MAX(ID) AS MaxID
                    FROM dbo.Create_linkmamorjob_4
                    GROUP BY FK_link, month, year
                ) g ON t.FK_link = g.FK_link 
                   AND t.month = g.month 
                   AND t.year = g.year 
                   AND t.ID = g.MaxID
            )
            MERGE LatestTarget AS Target
            USING {tempTableName} AS Source
            ON Target.FK_link = Source.FK_link
               AND Target.month = Source.month
               AND Target.year = Source.year
            WHEN MATCHED THEN
                UPDATE SET Target.FK_usr = Source.FK_usr
            WHEN NOT MATCHED BY TARGET THEN
                INSERT (FK_link, unic, FK_usr, month, year)
                VALUES (Source.FK_link, Source.unic, Source.FK_usr, Source.month, Source.year);";

                using (SqlCommand mergeCmd = new SqlCommand(mergeSql, connection))
                {
                    mergeCmd.CommandTimeout = 0;
                    rowsAffected = await mergeCmd.ExecuteNonQueryAsync();
                }

                // 4) پاکسازی جدول موقت
                using (SqlCommand dropCmd = new SqlCommand($"DROP TABLE IF EXISTS {tempTableName};", connection))
                {
                    await dropCmd.ExecuteNonQueryAsync();
                }
            }

            return rowsAffected;
        }


