                    exist.kontorKharabAst = model.KontorKharabAst ? 1 : 0;
                    exist.barghGheyrMojazAzShabakeh = model.BarghGheyrMojazAzShabakeh ? 1 : 0;
                    exist.azGhalamOftadeh = model.AzGhalamOftadeh ? 1 : 0;
                    exist.eslahShomareHamrah = model.EslahShomareHamrah;
                    exist.timesabt = DateTime.Now;

                    db.Entry(exist).State = EntityState.Modified;
                }
                else
                {
                    // ✅ درج رکورد جدید
                    var entity = new dbergharelicreatejob13
                    {
                        FK_usr = personal,
                        taghsitBedehi = model.TaghsitBedehi,
                        miladi_date1 = model.Miladi_date1,
                        pardakhtShod = model.PardakhtShod ? 1 : 0,
                        darbBasteh = model.DarbBasteh ? 1 : 0,
                        mamanetAzAnjamKar = model.MamanetAzAnjamKar ? 1 : 0,
                        ensheabGhatMovaghat = model.EnsheabGhatMovaghat ? 1 : 0,
                        ensheabJamAvaryShodeh = model.EnsheabJamAvaryShodeh ? 1 : 0,
                        moghayratFazBaAmper = model.MoghayratFazBaAmper ? 1 : 0,
                        dastkariDarKontor = model.DastkariDarKontor ? 1 : 0,
                        kontorKharabAst = model.KontorKharabAst ? 1 : 0,
                        barghGheyrMojazAzShabakeh = model.BarghGheyrMojazAzShabakeh ? 1 : 0,
                        azGhalamOftadeh = model.AzGhalamOftadeh ? 1 : 0,
                        eslahShomareHamrah = model.EslahShomareHamrah,
                        FK_tb12 = model.fkdb12,
                        timesabt = DateTime.Now
                    };

                    db.dbergharelicreatejob13.Add(entity);
                }

                db.SaveChanges();
                var finddb13 = db.dbergharelicratgrouprel11.Where(s => s.ID == model.fkdb12).FirstOrDefault();
                if (finddb13 != null)
                {
                    finddb13.vaziat = 1;
                    db.SaveChanges();

                }

                return Json(new { success = true, message = exist != null ? "با موفقیت ویرایش شد" : "با موفقیت ثبت شد" });


            }
            catch (Exception ex)
