        // POST: ذخیره گروه و کاربران
        [HttpPost]
        public JsonResult SaveGroup(GroupViewModel model)
        {
            using (var transaction = db.Database.BeginTransaction())
            {
                try
                {
                    if (model == null)
                        throw new Exception("اطلاعات گروه خالی است!");

                    // ذخیره گروه اصلی
                    var group = new dbergharelicratgroup_8
                    {
                        name = model.Name,
                        code = model.Code,
                        timesabt = DateTime.Now
                    };

                    db.dbergharelicratgroup_8.Add(group);
                    db.SaveChanges();

                    // ذخیره کاربران گروه
                    if (model.Users != null && model.Users.Any())
                    {
                        foreach (var user in model.Users)
                        {
                            var rel = new dbergharelicratgrouprel8_9
                            {
                                FK_dbergharelicratgroup_8 = group.ID,
                                FK_usr = user.FK_usr,
                                raes = user.Role == "raes",
                                ranndeh = user.Role == "ranndeh",
                                janshin = user.Role == "janshin",
                                Kartabl = user.Kartabl
                            };
                            db.dbergharelicratgrouprel8_9.Add(rel);
                        }
                        db.SaveChanges();
                    }

                    transaction.Commit();
                    return Json(new { success = true, message = "گروه با موفقیت ثبت شد!" });
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    return Json(new { success = false, message = ex.Message });
                }
            }
        }


