        public async Task<ActionResult> DeleteRelatedRecords(long FK_ID)
        {
            try
            {
                // اتصال به دیتابیس
                using (SqlConnection conn = new SqlConnection("YourConnectionString"))
                {
                    await conn.OpenAsync();

                    // حذف رکوردها بر اساس FK
                    string sql = @"
                DELETE FROM [sistan1meh1404].[dbo].[dbergharelimsertfk1_7]
                WHERE FK_dbergharelinsert_6 = @FK_ID;
            ";

                    using (SqlCommand cmd = new SqlCommand(sql, conn))
                    {
                        cmd.Parameters.AddWithValue("@FK_ID", FK_ID);

                        // اجرای حذف
                        int rowsAffected = await cmd.ExecuteNonQueryAsync();
                        return Content($"Deleted {rowsAffected} records successfully.");
                    }
