                int unicColIndex = ColumnLetterToIndex(unic);
                List<dbergharelimsertfk1_7DTO> bulkData = new List<dbergharelimsertfk1_7DTO>();

                // تابع کمکی برای خواندن ایمن سلول
                string GetCellValue(Telerik.Web.Spreadsheet.Row row, int columnIndex)
                {
                    if (row.Cells.Count <= columnIndex || row.Cells[columnIndex] == null)
                        return null;
                    return row.Cells[columnIndex].Value?.ToString();
                }

                // پیمایش سطرها
                for (int i = 1; i < Rows.Count; i++)
                {
                    var row = sheet.Rows[i];

                    string unicValue = GetCellValue(row, unicColIndex);

