        SELECT
            -- جدول اول
            (SELECT COUNT(DISTINCT valuunic)
             FROM dbo.dbergharelimsertfk1_7_1218
             WHERE valuunic IS NOT NULL) AS totalValuunic1,

            (SELECT SUM(
                    CASE 
                        WHEN FK_db2 = 182 
                        THEN ISNULL(TRY_CONVERT(DECIMAL(38,4), valueFK_db2),0)
                        ELSE 0
                    END)
             FROM dbo.dbergharelimsertfk1_7_1218
             WHERE valuunic IS NOT NULL) AS totalSum1,

            -- Reason = 1
            COUNT(DISTINCT CASE WHEN Reason='1' THEN valuunic END) AS totalValuunic2,
            SUM(CASE WHEN Reason='1' THEN ISNULL(TRY_CONVERT(DECIMAL(38,4),TotalVosol),0) ELSE 0 END) AS totalSum2,

            -- Reason = 3
            COUNT(DISTINCT CASE WHEN Reason='3' THEN valuunic END) AS totalValuunic4,
            SUM(CASE WHEN Reason='3' THEN ISNULL(TRY_CONVERT(DECIMAL(38,4),TotalVosol),0) ELSE 0 END) AS totalSum4,

            -- Reason = 4
            COUNT(DISTINCT CASE WHEN Reason='4' THEN valuunic END) AS totalValuunic5,
            SUM(CASE WHEN Reason='4' THEN ISNULL(TRY_CONVERT(DECIMAL(38,4),TotalVosol),0) ELSE 0 END) AS totalSum5

        FROM dbo.Result1218_Rejected
        WHERE valuunic IS NOT NULL
        ";

                using (SqlCommand cmd = new SqlCommand(queryMain, con))
                {
                    cmd.CommandTimeout = 900;

                    using (SqlDataReader dr = cmd.ExecuteReader())
