        public ActionResult view_see_1218_vaz_modal_telphon4()
        {
            FunctionModel model = new FunctionModel();

            try
            {
                using (SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["DefaultConnection"].ConnectionString))
                {
                    con.Open();

                    string query = @"
DECLARE @sumCount INT;

SELECT @sumCount = ISNULL(SUM([Count]),0)
FROM dbo.countnero_1218_5
WHERE [Count] IS NOT NULL 
AND [Count] <> 0
AND name = N'تلفنی';

WITH cte AS
(
    SELECT 
        valuunic,
        P5,
        ROW_NUMBER() OVER (ORDER BY ID) AS rn
    FROM dbo.ValuunicPriorityResult2
)

SELECT 
    SUM(CASE WHEN rn <= @sumCount AND valuunic IS NOT NULL THEN 1 ELSE 0 END) AS countTake,
    SUM(CASE WHEN rn >  @sumCount AND valuunic IS NOT NULL THEN 1 ELSE 0 END) AS countRemain,
    SUM(CASE WHEN rn <= @sumCount THEN P5 ELSE 0 END) AS sumTake,
    SUM(CASE WHEN rn >  @sumCount THEN P5 ELSE 0 END) AS sumRemain
FROM cte
";

                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.CommandTimeout = 900;

                        using (SqlDataReader dr = cmd.ExecuteReader())
                        {
                            if (dr.Read())
                            {
                                model.countmablaghtabletelephon = System.Convert.ToInt64(dr["countTake"]);
                                model.countbletelephonnot = System.Convert.ToInt64(dr["countRemain"]);

                                model.mablaghtabletelephon = dr["sumTake"] == DBNull.Value ? 0 : System. Convert.ToDecimal(dr["sumTake"]);
                                model.mablaghtabletelephonnot = dr["sumRemain"] == DBNull.Value ? 0 : System.Convert.ToDecimal(dr["sumRemain"]);
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                // در صورت خطا
                model.countmablaghtabletelephon = 0;
                model.countbletelephonnot = 0;
                model.mablaghtabletelephon = 0;
                model.mablaghtabletelephonnot = 0;

                // اگر بخواهی می‌توانی لاگ هم بگیری
                // System.IO.File.AppendAllText(Server.MapPath("~/errorlog.txt"), ex.ToString());
            }

            return View(model);
        }

        
