        public async Task<string> GetDataFromExcel_FishtAEADeditedittop(
            HttpPostedFileBase MyExcelStream,
            long ID,
            long IDgozareh = 0)
        {
            var fidnds = db.dbergharel_4
                .Where(s => s.FK_namegozarwsh == ID)
                .ToList();

            if (fidnds == null || fidnds.Count == 0)
                return "هیچ رکوردی برای این گزارش یافت نشد";

            long gozar = 0;
            var findd1 = db.dbergharelinsert_6.FirstOrDefault(s => s.ID == IDgozareh);
            if (findd1 != null)
                gozar = (long)findd1.dbergharel_4.FK_namegozarwsh;

            // گرفتن کاربر فقط یک‌بار
            int personal = 0;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user != null)
            {
                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user != null)
                    personal = user.usr_ID;
            }

            DateTime batchTime = DateTime.Now;
            int batchSize = 120000;
            int totalInserted = 0;

            System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

            using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
            {
                foreach (var fidnd in fidnds)
                {
                    int targetSheetIndex = (int)fidnd.start;
                    int startRow = (int)fidnd.radifstart;
                    string unicColumn = fidnd.unic;

                    // mapping فقط یک‌بار
                    var mappings = await db.dbergharel4_5
                        .Where(m => m.FK_dbergharel4 == fidnd.ID && m.del != true)
                        .ToListAsync();

                    if (mappings.Count == 0)
                        return "هیچ مپینگی برای این گزارش ثبت نشده است";

                    int currentSheet = -1;

                    do
                    {
                        currentSheet++;

                        if (currentSheet != targetSheetIndex)
                            continue;

                        var batchTable = CreateEmptyDataTableByGozar(gozar);

                        int rowIndex = -1;

                        while (reader.Read())
                        {
                            rowIndex++;
                            if (rowIndex < startRow)
                                continue;

                            string unicValue = GetCell(reader, unicColumn);

                            foreach (var map in mappings)
                            {
                                string valueFK = GetCell(reader, map.onvan);

                                batchTable.Rows.Add(
                                    IDgozareh,
                                    unicValue ?? (object)DBNull.Value,
                                    map.FK_dbergharel2,
                                    valueFK ?? (object)DBNull.Value,
                                    batchTime,
                                    personal
                                );
                            }

                            if (batchTable.Rows.Count >= batchSize)
                            {
                                totalInserted += await BulkInsertByGozar1(gozar, batchTable);
                                batchTable.Clear();
                            }
                        }

                        if (batchTable.Rows.Count > 0)
                        {
                            totalInserted += await BulkInsertByGozar1(gozar, batchTable);
                            batchTable.Clear();
                        }

                        break;

                    } while (reader.NextResult());
                }
            }

            return $"با موفقیت {totalInserted} رکورد درج شد و duplicate های آخر بررسی شدند.";
        }
