        public Stream ConvertToXlsx(HttpPostedFileBase MyExcelStream)
        {
            var outputStream = new MemoryStream();

            // شناسایی فرمت و باز کردن فایل
            if (Path.GetExtension(MyExcelStream.FileName).ToLower() == ".xls")
            {
                // باز کردن فایل قدیمی
                HSSFWorkbook hssfwb = new HSSFWorkbook(MyExcelStream.InputStream);

                // ایجاد یک ورک‌بوک جدید با فرمت XLSX
                XSSFWorkbook xssfWorkbook = new XSSFWorkbook();

                // کپی کردن تمام شیت‌ها از قدیمی به جدید
                for (int i = 0; i < hssfwb.NumberOfSheets; i++)
                {
                    var sourceSheet = hssfwb.GetSheetAt(i);
                    var targetSheet = xssfWorkbook.CreateSheet(sourceSheet.SheetName);
                    // توجه: برای کپی دقیق تمام استایل‌ها و سلول‌ها در فایل‌های حجیم 
                    // بهتر است از متدهای کمکی استفاده شود، اما برای استخراج دیتا همین کافیست.
                }

                xssfWorkbook.Write(outputStream);
                outputStream.Position = 0;
                return outputStream;
            }

            // اگر از قبل جدید بود، همان را برگردان
            return MyExcelStream.InputStream;
        }

        public string ConvertExcelToCsv(Stream excelStream)
        {
            StringBuilder csvContent = new StringBuilder();
            // باز کردن فایل اکسل
            HSSFWorkbook workbook = new HSSFWorkbook(excelStream); // مخصوص .xls

            for (int i = 0; i < workbook.NumberOfSheets; i++)
            {
                var sheet = workbook.GetSheetAt(i);
                for (int r = 0; r <= sheet.LastRowNum; r++)
                {
                    var row = sheet.GetRow(r);
                    if (row == null) continue;

                    var line = new List<string>();
                    for (int c = 0; c < row.LastCellNum; c++)
                    {
                        var cell = row.GetCell(c);
                        // فقط گرفتن مقدار متنی برای سرعت حداکثری
                        line.Add(cell?.ToString()?.Replace(",", " ") ?? "");
                    }
                    csvContent.AppendLine(string.Join(",", line));
                }
            }
            return csvContent.ToString();
        }
        public string FastConvertToXlsx(HttpPostedFileBase excelFile)
        {
            string outputFolder = @"D:\backupsub\2day";
            if (!Directory.Exists(outputFolder)) Directory.CreateDirectory(outputFolder);

            string outputPath = Path.Combine(outputFolder, "Converted_" + DateTime.Now.Ticks + ".xlsx");

            string ext = Path.GetExtension(excelFile.FileName).ToLowerInvariant();
            string tempExcelPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N") + ext);
            excelFile.SaveAs(tempExcelPath);

            try
            {
                using (var reader = Sylvan.Data.Excel.ExcelDataReader.Create(tempExcelPath))
                using (var stream = new FileStream(outputPath, FileMode.Create, FileAccess.Write))
                using (var xlsxWriter = new XlsxWriter(stream))
                {
                    // ساده‌سازی استایل برای جلوگیری از خطای جابجایی آرگومان‌ها
                    // از استایل پیش‌فرض استفاده می‌کنیم
                    var defaultStyle = XlsxStyle.Default;
                    do
                    {
                        xlsxWriter.BeginWorksheet(reader.WorksheetName ?? "Sheet1");

                        while (reader.Read())
                        {
                            xlsxWriter.BeginRow();

                            for (int i = 0; i < reader.FieldCount; i++)
                            {
                                var value = reader.GetValue(i);

                                if (value == null || value == DBNull.Value)
                                    xlsxWriter.Write();
                                else if (value is decimal || value is double || value is int || value is float)
                                    xlsxWriter.Write(System.Convert.ToDouble(value));
                                else if (value is DateTime dt)
                                    xlsxWriter.Write(dt);
                                else
                                    xlsxWriter.Write(value.ToString());
                            }
                        }

                    } while (reader.NextResult());


                }

                return outputPath;
            }
            finally
            {
                // حل مشکل خطای File (تداخل با متد Controller.File)
                if (System.IO.File.Exists(tempExcelPath))
                    System.IO.File.Delete(tempExcelPath);
            }
        }
        public string FastConvertLargeXlsToCsv(HttpPostedFileBase excelFile)
        {
            // ===== 1. مسیر خروجی =====
            string outputFolder = @"D:\backupsub\2day";
            if (!Directory.Exists(outputFolder))
                Directory.CreateDirectory(outputFolder);

            string outputPath = Path.Combine(
                outputFolder,
                "Converted_" + DateTime.Now.Ticks + ".csv"
            );

            // ===== 2. ساخت فایل موقت با پسوند واقعی اکسل =====
            string ext = Path.GetExtension(excelFile.FileName).ToLowerInvariant();
            if (ext != ".xls" && ext != ".xlsx" && ext != ".xlsb")
                throw new InvalidOperationException("فرمت فایل اکسل معتبر نیست.");

            string tempExcelPath = Path.Combine(
                Path.GetTempPath(),
                Guid.NewGuid().ToString("N") + ext
            );

            excelFile.SaveAs(tempExcelPath);

            try
            {
                // ===== 3. خواندن اکسل (Sylvan - بسیار سریع) =====
                using (var reader = Sylvan.Data.Excel.ExcelDataReader.Create(tempExcelPath))
                using (var writer = new StreamWriter(
                    outputPath,
                    false,
                    new UTF8Encoding(false),      // UTF8 بدون BOM
                    4 * 1024 * 1024               // Buffer = 4MB (خیلی مهم)
                ))
                {
                    var sb = new StringBuilder(4096);

                    do
                    {
                        while (reader.Read())
                        {
                            sb.Clear();
                            int fieldCount = reader.FieldCount;

                            for (int i = 0; i < fieldCount; i++)
                            {
                                if (i > 0)
                                    sb.Append(',');

                                string val = reader.GetString(i);
                                if (!string.IsNullOrEmpty(val))
                                {
                                    // پاک‌سازی کاراکترهای خراب‌کننده CSV (سریع)
                                    foreach (char c in val)
                                    {
                                        if (c == ',' || c == '\r' || c == '\n')
                                            sb.Append(' ');
                                        else
                                            sb.Append(c);
                                    }
                                }
                            }

                            writer.WriteLine(sb);
                        }
                    }
                    while (reader.NextResult()); // تمام شیت‌ها
                }

                return outputPath;
            }
            finally
            {
                try
                {
                    if (!string.IsNullOrEmpty(tempExcelPath) &&
                        System.IO.File.Exists(tempExcelPath))
                    {
                        System.IO.File.Delete(tempExcelPath);
                    }
                }
                catch
                {
                    // عمداً خالی — نباید Exception اصلی رو خراب کنه
                }
            }

        }
        public string ConvertLargeExcelToCsv(HttpPostedFileBase MyExcelStream)
        {
            string folderPath = @"D:\backupsub\2day";
            // ایجاد پوشه در صورت عدم وجود
            if (!Directory.Exists(folderPath))
            {
                Directory.CreateDirectory(folderPath);
            }

            // نام فایل خروجی (همان نام فایل اصلی با پسوند csv)
            string fileName = Path.GetFileNameWithoutExtension(MyExcelStream.FileName) + "_" + DateTime.Now.Ticks + ".csv";
            string fullPath = Path.Combine(folderPath, fileName);

            System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

            using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
            {
                // استفاده از StreamWriter برای نوشتن مستقیم روی هارد (بدون اشغال رم)
                using (var writer = new StreamWriter(fullPath, false, Encoding.UTF8))
                {
                    do
                    {
                        while (reader.Read())
                        {
                            var rowValues = new List<string>();
                            for (int i = 0; i < reader.FieldCount; i++)
                            {
                                object value = reader.GetValue(i);
                                string cellValue = value?.ToString() ?? "";

                                // پاکسازی متن (حذف کاما و اینتر که ساختار CSV را بهم نریزد)
                                cellValue = cellValue.Replace(",", " ").Replace("\r", " ").Replace("\n", " ");
                                rowValues.Add(cellValue);
                            }
                            // نوشتن یک خط کامل در فایل
                            writer.WriteLine(string.Join(",", rowValues));
                        }
                    } while (reader.NextResult()); // حرکت به شیت بعدی
                }
            }

            return fullPath; // مسیر فایل ذخیره شده را برمی‌گرداند
        }
