        {
            public int StartRow { get; set; }
            public int UnicIdx { get; set; }
            public List<ColumnMap> Columns { get; set; }
        }

        class ColumnMap
        {
            public long FK_dbergharel2 { get; set; }
            public int ValIdx { get; set; }
        }
        public async Task<string> GetDataFromExcel_FishtAEADeditedittop2(HttpPostedFileBase MyExcelStream, long ID, long IDgozareh = 0)
        {
            // ۱. اعتبارسنجی اولیه
            var fidnds = db.dbergharel_4.Where(s => s.FK_namegozarwsh == ID).ToList();
            if (!fidnds.Any()) return "هیچ رکوردی یافت نشد";

            var findd1 = db.dbergharelinsert_6.FirstOrDefault(s => s.ID == IDgozareh);
            long gozar = findd1 != null ? (long)findd1.dbergharel_4.FK_namegozarwsh : 0;
            string targetTable = GetTableNameByGozar(gozar);

            int personal = GetUserIdFromCookie();
            DateTime batchTime = DateTime.Now;
            const int batchSize = 100000;
            int totalInserted = 0;

            // ۲. ذخیره فایل موقت
            string ext = Path.GetExtension(MyExcelStream.FileName).ToLowerInvariant();
            string tempExcelPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N") + ext);
            MyExcelStream.SaveAs(tempExcelPath);

            await ManageIndexes(targetTable, "DISABLE");

            try
            {
                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                // ✅ رفع خطا: در Sylvan برای نادیده گرفتن هدر، از تنظیمات Schema استفاده می‌شود 
                // یا به سادگی بدون Options ریدر را می‌سازیم و با rowIndex مدیریت می‌کنیم.
                using (var reader = Sylvan.Data.Excel.ExcelDataReader.Create(tempExcelPath))
                {
                    int currentSheet = -1;
                    do
                    {
                        currentSheet++;

                        // شیت‌ها در دیتابیس شما احتمالا 1-based هستند
                        var fidndsForSheet = fidnds.Where(f => f.start == currentSheet + 1).ToList();
                        if (!fidndsForSheet.Any()) continue;

                        // ۳. ساخت مپینگ شیت
                        var sheetMappings = new List<FidndMapping>();
                        foreach (var f in fidndsForSheet)
                        {
                            var dbMaps = await db.dbergharel4_5
                                .Where(m => m.FK_dbergharel4 == f.ID && (m.del ?? false) == false)
                                .Select(m => new { m.FK_dbergharel2, m.onvan })
                                .ToListAsync();

                            if (!dbMaps.Any()) continue;

                            var columnMaps = dbMaps.Select(m => new ColumnMap
                            {
                                FK_dbergharel2 = (long)(m.FK_dbergharel2 ?? 0),
                                ValIdx = ColumnLetterToIndex(m.onvan)
                            }).Where(c => c.ValIdx >= 0).ToList();

                            sheetMappings.Add(new FidndMapping
                            {
                                StartRow = (int)f.radifstart,
                                UnicIdx = ColumnLetterToIndex(f.unic),
                                Columns = columnMaps
                            });
                        }

                        if (!sheetMappings.Any()) continue;

                        // ۴. پردازش ردیف‌ها
                        int rowIndex = -1;
                        var batchTable = CreateEmptyDataTable();

                        while (reader.Read())
                        {
                            rowIndex++; // از 0 شروع می‌شود (ردیف 1 اکسل)
                            int actualFieldCount = reader.FieldCount;

                            foreach (var fidndMap in sheetMappings)
                            {
                                // مطابق تصویر شما: اگر ردیف شروع 6 باشد، rowIndex باید حداقل 5 باشد
                                if (rowIndex + 1 < fidndMap.StartRow) continue;

                                object unicValue = (fidndMap.UnicIdx >= 0 && fidndMap.UnicIdx < actualFieldCount)
                                                   ? reader.GetValue(fidndMap.UnicIdx) : DBNull.Value;

                                foreach (var col in fidndMap.Columns)
                                {
                                    if (col.ValIdx < 0 || col.ValIdx >= actualFieldCount) continue;

                                    object val = reader.GetValue(col.ValIdx);

                                    if (val == null || val == DBNull.Value || string.IsNullOrWhiteSpace(val.ToString()))
                                        continue;

                                    batchTable.Rows.Add(IDgozareh, unicValue, col.FK_dbergharel2, val, batchTime, personal);
                                }
                            }

                            if (batchTable.Rows.Count >= batchSize)
                            {
                                await BulkInsert_Final(batchTable, targetTable);
                                totalInserted += batchTable.Rows.Count;
                                batchTable.Clear();
                            }
                        }

                        if (batchTable.Rows.Count > 0)
                        {
                            await BulkInsert_Final(batchTable, targetTable);
                            totalInserted += batchTable.Rows.Count;
                            batchTable.Clear();
                        }

                    } while (reader.NextResult());
                }
            }
            finally
            {
                await ManageIndexes(targetTable, "REBUILD");
                if (System.IO.File.Exists(tempExcelPath)) System.IO.File.Delete(tempExcelPath);
            }

            return $"موفقیت‌آمیز: {totalInserted} رکورد درج شد.";
        }
