        public async Task<string> GetDataFromExcel_FishtAEADeditedittop212(
    HttpPostedFileBase MyExcelStream, long ID, long IDgozareh = 0)
        {
            var fidnds = db.dbergharel_4
                .Where(s => s.FK_namegozarwsh == ID)
                .ToList();

            if (!fidnds.Any())
                return "هیچ رکوردی برای این گزارش یافت نشد";

            var findd1 = db.dbergharelinsert_6.FirstOrDefault(s => s.ID == IDgozareh);
            long gozar = findd1 != null ? (long)findd1.dbergharel_4.FK_namegozarwsh : 0;
            string targetTable = GetTableNameByGozar(gozar);

            int personal = GetUserIdFromCookie();
            DateTime batchTime = DateTime.Now;

            const int batchSize = 120_000;
            int totalInserted = 0;

            System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

            using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
            {
                int currentSheet = -1;

                do
                {
                    currentSheet++;

                    var fidndsForSheet = fidnds
                        .Where(f => f.start == currentSheet)
                        .ToList();

                    if (!fidndsForSheet.Any())
                        continue;

                    foreach (var fidnd in fidndsForSheet)
                    {
                        int startRow = (int)fidnd.radifstart;
                        int unicIdx = ColumnLetterToIndex(fidnd.unic);

                        var mappings = await db.dbergharel4_5
                            .Where(m => m.FK_dbergharel4 == fidnd.ID && (m.del ?? false) == false)
                            .ToListAsync();

                        var mappingIndexes = mappings
                            .Select(m => new
                            {
                                m.FK_dbergharel2,
                                Idx = ColumnLetterToIndex(m.onvan)
                            })
                            .ToList();

                        int rowIndex = -1;
                        var batchTable = CreateEmptyDataTable();

                        while (reader.Read())
                        {
                            rowIndex++;
                            if (rowIndex < startRow)
                                continue;

                            // unic
                            object unicValue =
                                unicIdx >= 0 && unicIdx < reader.FieldCount
                                    ? reader.GetValue(unicIdx)
                                    : DBNull.Value;

                            foreach (var map in mappingIndexes)
                            {
                                object val =
                                    map.Idx >= 0 && map.Idx < reader.FieldCount
                                        ? reader.GetValue(map.Idx)
                                        : DBNull.Value;

                                batchTable.Rows.Add(
                                    IDgozareh,
                                    unicValue,
                                    map.FK_dbergharel2,
                                    val,
                                    batchTime,
                                    personal
                                );
                            }

                            if (batchTable.Rows.Count >= batchSize)
                            {
                                await BulkInsert_Final(batchTable, targetTable);
                                totalInserted += batchTable.Rows.Count;
                                batchTable.Clear();
                            }
                        }

                        if (batchTable.Rows.Count > 0)
                        {
                            await BulkInsert_Final(batchTable, targetTable);
                            totalInserted += batchTable.Rows.Count;
                            batchTable.Clear();
                        }
                    }

                } while (reader.NextResult());
            }

            return $"موفقیت‌آمیز: {totalInserted} رکورد درج شد.";
        }


