        private async Task ManageIndexes(string tableName, string action)
        {
            // اسم جدول بدون dbo. برای کوئری سیستم
            string pureTableName = tableName.Replace("dbo.", "");

            string sql = $@"
        DECLARE @sql NVARCHAR(MAX) = '';
        SELECT @sql += 'ALTER INDEX ' + QUOTENAME(name) + ' ON ' + QUOTENAME(OBJECT_SCHEMA_NAME(object_id)) + '.' + QUOTENAME(OBJECT_NAME(object_id)) + ' {action};'
        FROM sys.indexes
        WHERE object_id = OBJECT_ID('{tableName}') 
        AND is_primary_key = 0 AND type > 0;
        EXEC sp_executesql @sql;";

            using (SqlConnection conn = new SqlConnection(GetSqlConnectionString()))
            {
                await conn.OpenAsync();
                using (SqlCommand cmd = new SqlCommand(sql, conn))
                {
                    cmd.CommandTimeout = 0; // بازسازی ایندکس زمان‌بر است
                    await cmd.ExecuteNonQueryAsync();
                }
            }
        }
        private async Task BulkInsert_Final(System.Data.DataTable dataTable, string tableName)
        {
            using (SqlConnection connection = new SqlConnection(GetSqlConnectionString()))
            {
                await connection.OpenAsync();
                using (SqlBulkCopy bulkCopy = new SqlBulkCopy(connection,
                       SqlBulkCopyOptions.TableLock | SqlBulkCopyOptions.UseInternalTransaction, null))
                {
                    bulkCopy.DestinationTableName = tableName;
                    bulkCopy.BatchSize = 120000;
                    bulkCopy.BulkCopyTimeout = 0;

                    bulkCopy.ColumnMappings.Add("FK_6", "FK_dbergharelinsert_6");
                    bulkCopy.ColumnMappings.Add("unic", "valuunic");
                    bulkCopy.ColumnMappings.Add("FK_db2", "FK_db2");
                    bulkCopy.ColumnMappings.Add("val_db2", "valueFK_db2");
                    bulkCopy.ColumnMappings.Add("time", "timesabt");
                    bulkCopy.ColumnMappings.Add("user", "FK_usrsabt");

                    await bulkCopy.WriteToServerAsync(dataTable);
                }
            }
        }
        private string GetCell(IExcelDataReader reader, string columnLetter)
        {
            if (string.IsNullOrEmpty(columnLetter))
                return null;

            int index = ColumnLetterToIndex(columnLetter);
            if (index < 0 || index >= reader.FieldCount)
                return null;

            return reader.GetValue(index)?.ToString();
        }
        private System.Data.DataTable CreateEmptyDataTableByGozar(long gozar)
        {
            if (gozar == 5)
                return CreateDataTable_dbergharelimsertfk1_7_1218(new List<dbergharelimsertfk1_7DTO>());
            if (gozar == 21)
                return CreateDataTable_dbergharelimsertfk1_7_1218_bace(new List<dbergharelimsertfk1_7DTO>());
            if (gozar == 23)
                return CreateDataTable_dbergharelimsertfk1_7_GIS(new List<dbergharelimsertfk1_7DTO>());

            return CreateDataTable_dbergharelimsertfk1_7(new List<dbergharelimsertfk1_7DTO>());
        }
        private async Task<int> BulkInsertByGozar1(long gozar, System.Data.DataTable table)
        {
            if (table.Rows.Count == 0)
                return 0;

            if (gozar == 5)
                return await BulkInsert_dbergharelimsertfk1_71_1218(table);
            else if (gozar == 21)
                return await BulkInsert_dbergharelimsertfk1_71_1218_bace(table);
            else if (gozar == 23)
                return await BulkInsert_dbergharelimsertfk1_7_GIS(table);
            else
                return await BulkInsert_dbergharelimsertfk1_71(table);
        }

