        private System.Data.DataTable CreateEmptyDataTable_1218()
        {
            System.Data.DataTable dt = new System.Data.DataTable();

            dt.Columns.Add("FK_dbergharelinsert_6", typeof(long));
            dt.Columns.Add("valuunic", typeof(string));
            dt.Columns.Add("FK_db2", typeof(long));
            dt.Columns.Add("valueFK_db2", typeof(string));
            dt.Columns.Add("timesabt", typeof(DateTime));
            dt.Columns.Add("FK_usrsabt", typeof(int));

            return dt;
        }
        private string GetCellValueByLetter(IExcelDataReader reader, string columnLetter)
        {
            if (string.IsNullOrEmpty(columnLetter))
                return null;

            int index = ColumnLetterToIndex(columnLetter);

            if (index < 0 || index >= reader.FieldCount)
                return null;

            return reader.GetValue(index)?.ToString();
        }
        public async Task<string> GetDataFromExcel_Fast(
       HttpPostedFileBase MyExcelStream,
       long ID,
       long IDgozareh = 0)
        {
            try
            {
                var fidnds = db.dbergharel_4
                    .Where(s => s.FK_namegozarwsh == ID)
                    .ToList();

                if (fidnds == null || fidnds.Count == 0)
                    return "هیچ رکوردی برای این گزارش یافت نشد";

                long gozar = 0;
                var findd1 = db.dbergharelinsert_6.FirstOrDefault(s => s.ID == IDgozareh);
                if (findd1 != null)
                    gozar = (long)findd1.dbergharel_4.FK_namegozarwsh;

                int personal = 0;
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user != null)
                {
                    var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                    var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                    if (user != null)
                        personal = user.usr_ID;
                }

                DateTime batchTime = DateTime.Now;

                System.Text.Encoding.RegisterProvider(
                    System.Text.CodePagesEncodingProvider.Instance);

                const int CHUNK_SIZE = 10000;

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    int sheetIndex = 0;

                    do
                    {
                        var fidnd = fidnds.FirstOrDefault(f => f.start == sheetIndex);
                        if (fidnd == null)
                        {
                            sheetIndex++;
                            continue;
                        }

                        var mappings = await db.dbergharel4_5
                            .Where(m => m.FK_dbergharel4 == fidnd.ID && m.del != true)
                            .ToListAsync();

                        if (mappings.Count == 0)
                            return "هیچ مپینگی برای این گزارش ثبت نشده است";

                        System.Data.DataTable dt = CreateEmptyDataTable_1218();
                        int rowIndex = 0;

                        while (reader.Read())
                        {
                            rowIndex++;
                            if (rowIndex < fidnd.radifstart)
                                continue;

                            string unicValue = GetCellValueByLetter(reader, fidnd.unic);

                            foreach (var map in mappings)
                            {
                                string valueFK = GetCellValueByLetter(reader, map.onvan);

                                dt.Rows.Add(
                                    IDgozareh,
                                    unicValue ?? (object)DBNull.Value,
                                    map.FK_dbergharel2,
                                    valueFK ?? (object)DBNull.Value,
                                    batchTime,
                                    personal
                                );
                            }

                            if (dt.Rows.Count >= CHUNK_SIZE)
                            {
                                await BulkInsertByGozar(gozar, dt);
                                dt.Clear();
                            }
                        }

                        if (dt.Rows.Count > 0)
                        {
                            await BulkInsertByGozar(gozar, dt);
                            dt.Clear();
                        }

                        sheetIndex++;

                    } while (reader.NextResult());
                }

                return "عملیات با موفقیت انجام شد (Fast & Safe Import)";
            }
            catch (Exception ex)
            {
                return "خطا: " + ex.Message;
            }
        }

        private async Task BulkInsertByGozar(long gozar, System.Data.DataTable dt)
        {
            if (gozar == 5)
                await BulkInsert_dbergharelimsertfk1_71_1218(dt);
            else if (gozar == 21)
                await BulkInsert_dbergharelimsertfk1_71_1218_bace(dt);
            else if (gozar == 23)
                await BulkInsert_dbergharelimsertfk1_7_GIS(dt);
            else
                await BulkInsert_dbergharelimsertfk1_71(dt);
        }

