        // مسیر: Models/FishEstandardViewModel.cs
        public class FishEstandardViewModel
        {
            public int StepNumber { get; set; }        // شماره پله => count
            public long StartAmount { get; set; }      // شماره شروع مبلغ => startvalue
            public long EndAmount { get; set; }        // پایان مبلغ => endvalue
            public long Standard { get; set; }         // استاندارد => estandard
            public int Type { get; set; }              // نوع => type_int
        }


        public JsonResult AddAjax(FishEstandardViewModel model)
        {
            if (!ModelState.IsValid)
                return Json(new { success = false, message = "اطلاعات فرم معتبر نیست." });

            bool exists = db.tbgozaresh_1275_Fish_estandard
                .Any(x => x.count == model.StepNumber && x.type_int == model.Type);

            if (exists)
                return Json(new { success = false, message = "این رکورد قبلاً ثبت شده است!" });

            var item = new tbgozaresh_1275_Fish_estandard
            {
                count = model.StepNumber,
                startvalue = model.StartAmount,
                endvalue = model.EndAmount,
                estandard = model.Standard,
                type_int = model.Type,
                active = 1,
                type = (model.Type == 1 ? "دیماندی" : "عادی"),
                name = ""
            };

            db.tbgozaresh_1275_Fish_estandard.Add(item);
            db.SaveChanges();

            // برگرداندن اطلاعات رکورد جدید برای جدول
            return Json(new
            {
                success = true,
                data = new
                {
                    id = item.ID,
                    count = item.count,
                    startvalue = item.startvalue,
                    endvalue = item.endvalue,
                    estandard = item.estandard,
                    type = item.type
                }
            });
        }

        // حذف رکورد
        [HttpPost]
        public JsonResult DeleteAjax(long id)
        {
            var item = db.tbgozaresh_1275_Fish_estandard.Find(id);
            if (item != null)
            {
                db.tbgozaresh_1275_Fish_estandard.Remove(item);
                db.SaveChanges();
                return Json(new { success = true });
            }
            return Json(new { success = false, message = "رکورد یافت نشد!" });
        }
        #endregion

