        public async Task<string> GetDataFromExcel_asnalpersonaldel(HttpPostedFileBase MyExcelStream)
        {
            using (var transaction = db.Database.BeginTransaction())
            {
                try
                {
                    var workbook = Telerik.Web.Spreadsheet.Workbook.Load(
                        MyExcelStream.InputStream,
                        System.IO.Path.GetExtension(MyExcelStream.FileName)
                    );

                    if (workbook.Sheets.Count < 1)
                        return "هیچ شیتی در این اکسل وجود ندارد";

                    var sheet = workbook.Sheets[0];
                    var rows = sheet.Rows;

                    if (rows.Count < 2)
                        return "فایل اکسل فاقد اطلاعات می باشد";

                    for (int i = 1; i < rows.Count; i++)
                    {
                        var row = rows[i];

                        // ستون 1 = usr_Personal_ID
                        if (!int.TryParse(row.Cells[0]?.Value?.ToString(), out int personalId))
                            return $"کد پرسنلی در ردیف {i} صحیح نیست";

                        var user = await db.tbUsers
                                           .FirstOrDefaultAsync(u => u.usr_Personal_ID == personalId);
                        if (user == null)
                            return $"کاربری با کد پرسنلی {personalId} در ردیف {i} یافت نشد";

                        int userId = user.usr_ID;

                        // ستون 5 = ماه
                        if (!int.TryParse(row.Cells[4]?.Value?.ToString(), out int month))
                            return $"ماه در ردیف {i} صحیح نیست";

                        // ستون 6 = سال
                        if (!int.TryParse(row.Cells[5]?.Value?.ToString(), out int year))
                            return $"سال در ردیف {i} صحیح نیست";

                        // ستون 2 و 3 و 4 = مقادیر
                        double col2 = 0, col3 = 0;
                        int col4 = 0;
                        double.TryParse(row.Cells[1]?.Value?.ToString(), out col2);
                        double.TryParse(row.Cells[2]?.Value?.ToString(), out col3);
                        int.TryParse(row.Cells[3]?.Value?.ToString(), out col4);
                        var moalefeIds = new List<int> { 1979, 1978, 1977 };
                        if (col4 > 0)
                            moalefeIds.Add(col4);

                        // گرفتن رکوردهای موجود فقط برای همین آی‌دی‌ها
                        var records = await db.tbMoalefeValueFish
                                              .Where(r => r.FK_User == userId &&
                                                          r.mlfvlfsh_Year == year &&
                                                          r.mlfvlfsh_Month == month &&
                                                          r.FK_EXCel == null &&
                                                          moalefeIds.Contains((int)r.FK_Moalefe))
                                              .ToListAsync();


                        // ویرایش رکوردهای موجود
                        foreach (var rec in records)
                        {
                            double currentValue = ((double?)rec.mlfvlfsh_Value ?? 0);

                            if (rec.FK_Moalefe == 1979)
                            {
                                rec.mlfvlfsh_Value = (double?)(currentValue - col2 + col3);
                            }
                            else if (rec.FK_Moalefe == 1978)
                            {
                                rec.mlfvlfsh_Value = (double?)(currentValue + col2);
                            }
                            else if (rec.FK_Moalefe == 1977)
                            {
                                rec.mlfvlfsh_Value = (double?)(currentValue + col3);
                            }
                        }

                        // اگر col4 > 0 → رکورد مربوط به col4 تغییر یا درج شود
                        if (col4 > 0)
                        {
                            var recCol4 = records.FirstOrDefault(r => r.FK_Moalefe == col4);

                            if (recCol4 != null)
                            {
                                // آپدیت مقدار
                                recCol4.mlfvlfsh_Value = (col2 != 0 ? col2 : col3);
                            }
                            else
                            {
                                db.tbMoalefeValueFish.Add(new tbMoalefeValueFish
                                {
                                    FK_User = userId,
                                    mlfvlfsh_Year = year,
                                    mlfvlfsh_Month = month,
                                    FK_Moalefe = col4,
                                    mlfvlfsh_Value = (col2 != 0 ? col2 : col3),
                                    Datatmie = DateTime.Now
                                });
                            }
                        }
                    }

                    await db.SaveChangesAsync();
                    transaction.Commit();

                    return "True";
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    return ex.Message;
                }
            }
        }

