                    var rows = sheet.Rows;

                    if (rows.Count < 2)
                        return "فایل اکسل فاقد اطلاعات می باشد";

                    // گرفتن همه userId هایی که در اکسل هست
                    var personalIds = rows.Skip(1)
                                          .Select(r => r.Cells[1]?.Value?.ToString())
                                          .Where(v => !string.IsNullOrEmpty(v) && int.TryParse(v, out _))
                                          .Select(int.Parse)
                                          .Distinct()
                                          .ToList();

                    // رفع مشکل Duplicate Key با GroupBy
                    var users = db.tbUsers
                                  .Where(u => personalIds.Contains((int)u.usr_Personal_ID))
                                  .GroupBy(u => u.usr_Personal_ID)
                                  .Select(g => g.FirstOrDefault())
                                  .ToDictionary(u => u.usr_Personal_ID, u => u.usr_ID);

                    // گرفتن سال‌ها و ماه‌ها برای رکوردهای موجود
                    var years = rows.Skip(1)
                                    .Select(r => r.Cells[4]?.Value?.ToString())
                                    .Where(v => !string.IsNullOrEmpty(v) && int.TryParse(v, out _))
                                    .Select(int.Parse)
                                    .Distinct()
                                    .ToList();

                    var months = rows.Skip(1)
                                     .Select(r => r.Cells[3]?.Value?.ToString())
                                     .Where(v => !string.IsNullOrEmpty(v) && int.TryParse(v, out _))
                                     .Select(int.Parse)
                                     .Distinct()
                                     .ToList();

                    // گرفتن همه رکوردهای موجود مرتبط یکجا
                    var existingRecords = db.tbDetailFish
                                            .Where(f => years.Contains((int)f.year) && months.Contains((int)f.month))
                                            .ToList();

                    List<tbDetailFish> newRecords = new List<tbDetailFish>();

                    for (int i = 1; i < rows.Count; i++)
                    {
                        var row = rows[i];
                        var personalIdStr = row.Cells[1]?.Value?.ToString();

                        if (string.IsNullOrEmpty(personalIdStr) || !int.TryParse(personalIdStr, out int personalId))
                            return $"مقدار ستون نام در سطر ( {i} ) عددی نمی باشد";

                        if (!users.TryGetValue(personalId, out int userId))
                            return $"کاربر با کد پرسنلی در سطر ( {i} ) یافت نشد";

                        if (!int.TryParse(row.Cells[3]?.Value?.ToString(), out int month))
                            return $"لطفا ستون ماه در سطر ( {i} ) را پر کنید";

                        if (!int.TryParse(row.Cells[4]?.Value?.ToString(), out int year))
                            return $"لطفا ستون سال در سطر ( {i} ) را پر کنید";

                        var sharh = row.Cells[2]?.Value?.ToString();
                        if (string.IsNullOrEmpty(sharh))
                            return $"لطفا ستون شرح در سطر ( {i} ) را پر کنید";

                        // چک کردن وجود رکورد در حافظه
                        var exist = existingRecords
                                    .FirstOrDefault(x => x.FK_usr == userId &&
                                                         x.month == month &&
                                                         x.year == year);

                        if (exist != null)
                        {
                            // آپدیت شرح
                            exist.sharh = sharh;
                        }
                        else
                        {
                            // رکورد جدید
                            newRecords.Add(new tbDetailFish
                            {
                                FK_usr = userId,
                                month = month,
                                year = year,
                                sharh = sharh
                            });
                        }
                    }

                    if (newRecords.Any())
                        db.tbDetailFish.AddRange(newRecords);

                    db.SaveChanges();
                    transaction.Commit();

                    return "True";
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    return ex.Message;
                }
            }
        }
