        [HttpPost]
        public JsonResult GetReportData(int Month, int Year, int Day)
        {
            int userid = 0;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user != null)
            {
                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var User = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode.ToString() == nationalcode);
                if (User != null)
                    userid = User.usr_ID;
            }

            // لیست estandard
            var estandardList = db.tbgozaresh_1275_Fish_estandard
                                  .Where(e => e.active == 1)
                                  .ToList();

            // داده‌های روز مشخص از tbgozaresh_1275_Fish
            var fishData = db.tbgozaresh_1275_Fish
                             .Where(f => f.FK_usr == userid
                                        && f.month == Month
                                        && f.year == Year
                                        && f.day == Day
                                        && f.active == 1)
                             .ToList();

            var reportData = estandardList.Select(e =>
            {
                // پیدا کردن ردیف مرتبط در Fish
                var fish = fishData.FirstOrDefault(f => f.moadelasli == e.type_int && f.active_fal == e.estandard);

                return new
                {
                    startvalue = e.startvalue,
                    endvalue = e.endvalue,
                    type = e.type,
                    estandard = e.estandard,
                    count = fish != null ? fish.count_darsad : 0,
                    sum_vosol = fish != null ? fish.sum_vosol : 0,
                    vosol_equivalent = (fish != null && e.estandard != 0) ? fish.sum_vosol / (e.estandard * 5) : 0
                };
            }).ToList();

            return Json(reportData, JsonRequestBehavior.AllowGet);
        }




