        private async Task RemoveDuplicatesLastBatchOptimized(string connectionString, DateTime batchTime)
        {
            string sql = @"
DELETE t
FROM dbo.dbergharelimsertfk1_7 t
INNER JOIN (
    SELECT t.ID AS newID, p.valueFK_db2 AS prevValue, t.valueFK_db2 AS newValue
    FROM dbo.dbergharelimsertfk1_7 t
    CROSS APPLY (
        SELECT TOP 1 *
        FROM dbo.dbergharelimsertfk1_7 p
        WHERE p.valuunic = t.valuunic
          AND p.FK_db2 = t.FK_db2
          AND p.timesabt < t.timesabt
        ORDER BY p.timesabt DESC
    ) p
    WHERE t.timesabt = @batchTime
) pr ON t.ID = pr.newID
WHERE ISNULL(pr.newValue,'') = ISNULL(pr.prevValue,'');"
;

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();
                using (SqlCommand command = new SqlCommand(sql, connection))
                {
                    command.Parameters.AddWithValue("@batchTime", batchTime);
                    command.CommandTimeout = 0;
                    await command.ExecuteNonQueryAsync();
                }
            }
        }

