        [HttpPost]
        public JsonResult SaveErjaOmomiEdit(
    string Nam,
    int? Model,
    int Type,
    long? Fk_Shooghl,
    int IsRequired,
    List<string> Options,
    string DependenciesJson
)
        {
            try
            {
                using (SaabEntities db = new SaabEntities())
                {
                    var item = new erja_omomi_edit
                    {
                        Nam = Nam,
                        Model = Type == 1 ? Model : null,
                        Type = Type,
                        Fk_Shooghl = Fk_Shooghl,
                        vaziat = 1,
                        asli = IsRequired
                    };

                    db.erja_omomi_edit.Add(item);
                    db.SaveChanges();

                    long newId = item.ID;

                    if ((Type == 3 || Type == 4) && Options != null)
                    {
                        int counter = 1;

                        foreach (var op in Options)
                        {
                            db.erja_omomi_edit_link.Add(new erja_omomi_edit_link
                            {
                                FK_erja_omomi_edit = newId,
                                value = op,
                                vaziat = 1,
                                numeber = counter
                            });

                            counter++;
                        }

                        db.SaveChanges();
                    }

                    // ⬅⬅ تبدیل JSON به لیست
                    var Dependencies = new List<DependencyModel>();
                    if (!string.IsNullOrEmpty(DependenciesJson))
                    {
                        Dependencies = Newtonsoft.Json.JsonConvert
                             .DeserializeObject<List<DependencyModel>>(DependenciesJson);
                    }

                    if (Dependencies != null && Dependencies.Any())
                    {
                        foreach (var dep in Dependencies)
                        {
                            db.erja_omomi_edit_link_link.Add(new erja_omomi_edit_link_link
                            {
                                FK_erja_omomi_edit = newId,
                                FK_erja_omomi_edit_2 = dep.field,
                                number = dep.value,
                                active = 1
                            });
                        }

                        db.SaveChanges();
                    }

                    return Json(new { success = true, message = "با موفقیت ذخیره شد" });
                }
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }


