        public async Task<ActionResult> UserContract_Details1022(List<string> Fkpym, DateTime az, DateTime ta)
        {
            try
            {
                // فقط مقادیر عددی معتبر
                var userIds = Fkpym
                    .Where(x => int.TryParse(x, out _))
                    .Select(int.Parse)
                    .ToList();

                if (userIds == null || userIds.Count == 0)
                    return Content("No valid user IDs provided");

                List<int> finalUserIds;

                // اگر فقط یک آیتم هست و مقدارش -1 است، یعنی برای همه‌ی کاربران
                if (userIds.Count == 1 && userIds[0] == -1)
                {
                    finalUserIds = await db.tbUsers
                                           .Select(u => u.usr_ID)
                                           .ToListAsync();
                }
                else
                {
                    finalUserIds = userIds;
                }

                // گرفتن رکوردهای موجود برای همین کاربران
                var existingRecords = await db.closed_time_estedad
                                              .Where(c => finalUserIds.Contains((int)c.FK_usr))
                                              .ToListAsync();

                List<closed_time_estedad> newRecords = new List<closed_time_estedad>();

                foreach (var uid in finalUserIds)
                {
                    var record = existingRecords.FirstOrDefault(r => r.FK_usr == uid);
                    if (record != null)
                    {
                        // اگر وجود دارد → آپدیت کن
                        record.time = az;
                        record.timeend = ta;
                        db.Entry(record).State = EntityState.Modified;
                    }
                    else
                    {
                        // اگر وجود ندارد → درج کن
                        newRecords.Add(new closed_time_estedad
                        {
                            FK_usr = uid,
                            time = az,
                            timeend = ta
                        });
                    }
                }

                if (newRecords.Count > 0)
                    db.closed_time_estedad.AddRange(newRecords);

                await db.SaveChangesAsync();

                return Content("True");
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }
        [HttpPost]
        public async Task<ActionResult> ImportErjaLikeExcel(HttpPostedFileBase MyExcelStream, int jobId)
        {
            try
            {
                var result = await ImportErjaLikeAndLinks(MyExcelStream, jobId);
                return Content(result);
            }
            catch (Exception ex)
            {
                return Content("❌ خطا: " + ex.Message);
            }
        }

        public async Task<string> ImportErjaLikeAndLinks(HttpPostedFileBase MyExcelStream, int jobId)
        {
            int totalInserted = 0;
            try
            {
                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration()
                    {
                        ConfigureDataTable = _ => new ExcelDataTableConfiguration() { UseHeaderRow = false }
                    });

                    var sheet = dataSet.Tables[0];
                    if (sheet.Rows.Count < 3)
                        return "📂 فایل اکسل باید حداقل سه ردیف (ID، عنوان، داده‌ها) داشته باشد.";

                    //--------------------------------------------------------
                    // ۱️⃣ خواندن ID های erja_omomi از ردیف اول
                    //--------------------------------------------------------
                    List<long?> omomiIds = new List<long?>();
                    for (int c = 3; c < sheet.Columns.Count; c++)
                    {
                        if (long.TryParse(sheet.Rows[0][c]?.ToString(), out long id))
                            omomiIds.Add(id);
                        else
                            omomiIds.Add(null);
                    }

                    //--------------------------------------------------------
                    // ۲️⃣ آماده‌سازی لیست‌ها
                    //--------------------------------------------------------
                    List<erja_like> likes = new List<erja_like>();
                    List<erja_like_link> likeLinks = new List<erja_like_link>();

                    //--------------------------------------------------------
                    // 📌 اطلاعات کاربر ثبت‌کننده
                    //--------------------------------------------------------
                    var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                    int fk_usr_sabt = 0;
                    if (cookie_user != null)
                    {
                        var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                        var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                        if (user != null)
                            fk_usr_sabt = user.usr_ID;
                    }

                    //--------------------------------------------------------
                    // ۳️⃣ پیمایش ردیف‌ها از ردیف سوم به بعد
                    //--------------------------------------------------------
                    for (int r = 2; r < sheet.Rows.Count; r++)
                    {
                        var row = sheet.Rows[r];
                        if (row == null) continue;

                        // ستون دوم (B): کد کاربر
                        string usrCodeStr = row[1]?.ToString();
                        int.TryParse(usrCodeStr, out int fkUsr);

                        // ستون سوم (C): کار درخواستی
                        string unic = row[2]?.ToString();

                        erja_like like = new erja_like
                        {
                            FK_usr = fkUsr,
                            unic = unic,
                            vaziat = 0,
                            FK_job = jobId,
                            del = null,
                        };

                        likes.Add(like);
                    }

                    //--------------------------------------------------------
                    // 📦 Bulk Insert برای erja_like
                    //--------------------------------------------------------
                    var dtLike = CreateDataTable_ErjaLike(likes);
                    int insertedLikes = await BulkInsertAsync(dtLike, "dbo.erja_like");

                    // گرفتن ID های درج‌شده
                    var lastLikes = db.erja_like
                                .OrderByDescending(x => x.ID)
                                .Where(s => s.del != 1)
                                .Take(likes.Count)
                                .OrderBy(x => x.ID) // دوباره مرتب سازی برای مطابقت با اکسل
                                .ToList(); totalInserted = lastLikes.Count;

                    //--------------------------------------------------------
                    // ۴️⃣ ایجاد داده‌های erja_like_link
                    //--------------------------------------------------------
                    int index = 0;
                    foreach (var like in lastLikes)
                    {
                        var row = sheet.Rows[index + 2]; // از ردیف سوم شروع می‌شود
                        for (int c = 3; c < sheet.Columns.Count; c++)
                        {
                            var val = row[c]?.ToString();
                            long? fk_omomi = omomiIds[c - 3];
                            if (fk_omomi == null || string.IsNullOrEmpty(val))
                                continue;

                            likeLinks.Add(new erja_like_link
                            {
                                FK_erja_like = like.ID,
                                FK_omomi = fk_omomi,
                                value = val,
                                timesabt = DateTime.Now,
                                vaziat = 0
                            });
                        }
                        index++;
                    }

                    //--------------------------------------------------------
                    // 📦 Bulk Insert برای erja_like_link
                    //--------------------------------------------------------
                    var dtLikeLink = CreateDataTable_ErjaLikeLink(likeLinks);
                    int insertedLinks = await BulkInsertAsync(dtLikeLink, "dbo.erja_like_link");
                    return "True";

                    //--------------------------------------------------------
                    //return $"✅ {insertedLikes} رکورد در erja_like و {insertedLinks} رکورد در erja_like_link درج شد.";
                }
            }
            catch (Exception ex)
            {
                return "❌ خطا در پردازش: " + ex.Message;
            }
        }

        private System.Data.DataTable CreateDataTable_ErjaLike(List<erja_like> list)
        {
            var dt = new System.Data.DataTable();
            dt.Columns.Add("FK_usr", typeof(int));
            dt.Columns.Add("unic", typeof(string));
            dt.Columns.Add("vaziat", typeof(int));
            dt.Columns.Add("del", typeof(long));
            dt.Columns.Add("FK_job", typeof(long));

            foreach (var item in list)
                dt.Rows.Add(item.FK_usr ?? (object)DBNull.Value,
                            item.unic ?? (object)DBNull.Value,
                            item.vaziat ?? (object)DBNull.Value,
                            item.del ?? (object)DBNull.Value,
                            item.FK_job ?? (object)DBNull.Value);

            return dt;
        }

        private System.Data.DataTable CreateDataTable_ErjaLikeLink(List<erja_like_link> list)
        {
            var dt = new System.Data.DataTable();
            dt.Columns.Add("FK_erja_like", typeof(long));
            dt.Columns.Add("FK_omomi", typeof(long));
            dt.Columns.Add("value", typeof(string));
            dt.Columns.Add("timesabt", typeof(DateTime));
            dt.Columns.Add("vaziat", typeof(int));

            foreach (var item in list)
                dt.Rows.Add(item.FK_erja_like ?? (object)DBNull.Value,
                            item.FK_omomi ?? (object)DBNull.Value,
                            item.value ?? (object)DBNull.Value,
                            item.timesabt ?? (object)DBNull.Value,
                            item.vaziat ?? (object)DBNull.Value);

            return dt;
        }

        private async Task<int> BulkInsertAsync(System.Data.DataTable dt, string tableName)
        {
            int inserted = 0;
            string connectionString = GetSqlConnectionString();

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();

                using (SqlBulkCopy bulk = new SqlBulkCopy(connection,
                    SqlBulkCopyOptions.TableLock | SqlBulkCopyOptions.CheckConstraints, null))
                {
                    bulk.DestinationTableName = tableName;
                    bulk.BatchSize = 5000;
                    bulk.BulkCopyTimeout = 0;

                    foreach (DataColumn col in dt.Columns)
                        bulk.ColumnMappings.Add(col.ColumnName, col.ColumnName);

                    await bulk.WriteToServerAsync(dt);
                    inserted = dt.Rows.Count;
                }
            }
            return inserted;
        }
