        // 🔹 تبدیل مقدار به long (در صورت خالی بودن مقدار، null برمی‌گرداند)
        private long? ParseLong(string value)
        {
            if (long.TryParse(value, out long result))
                return result;
            return null;
        }

        // 🔹 تبدیل مقدار به int
        private int? ParseInt(string value)
        {
            if (int.TryParse(value, out int result))
                return result;
            return null;
        }

        // 🔹 تبدیل مقدار به bool
        private bool? ParseBool(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
                return null;

            value = value.Trim();

            // پشتیبانی از چند حالت متداول (True/False, 1/0, بله/خیر)
            if (value == "1" || value.Equals("true", StringComparison.OrdinalIgnoreCase) || value == "بله")
                return true;
            if (value == "0" || value.Equals("false", StringComparison.OrdinalIgnoreCase) || value == "خیر")
                return false;

            return null;
        }

        // 🔹 تبدیل مقدار به DateTime
        private DateTime? ParseDate(string value)
        {
            if (DateTime.TryParse(value, out DateTime date))
                return date;
            return null;
        }

