        public async Task<string> GetDataFromExcel_Khodro(HttpPostedFileBase MyExcelStream)
        {
            if (MyExcelStream == null || MyExcelStream.ContentLength == 0)
                return "❌ فایل اکسل ارسال نشده است.";

            using (DbContextTransaction transaction = db.Database.BeginTransaction())
            {
                try
                {
                    // بارگذاری فایل اکسل با Telerik.Web.Spreadsheet
                    var workbook = Telerik.Web.Spreadsheet.Workbook.Load(MyExcelStream.InputStream, Path.GetExtension(MyExcelStream.FileName));
                    var sheet = workbook.Sheets.FirstOrDefault();
                    if (sheet == null)
                        return "❌ Sheet در فایل یافت نشد.";

                    int inserted = 0;
                    int updated = 0;

                    // تعداد ستون‌های مورد انتظار در فایل (براساس مثال شما ~40). در صورت لزوم تغییر بده.
                    int expectedColumns = 40;

                    // Helper برای خواندن ایمن مقدار یک سلول (در صورت отсутств بودن، رشته خالی برمی‌گرداند)
                    Func<Telerik.Web.Spreadsheet.Row, int, string> GetCellValue = (r, idx) =>
                    {
                        try
                        {
                            if (r == null) return string.Empty;
                            if (r.Cells == null) return string.Empty;
                            if (idx < 0 || idx >= r.Cells.Count) return string.Empty;
                            var cell = r.Cells[idx];
                            if (cell == null) return string.Empty;
                            var v = cell.Value;
                            return v == null ? string.Empty : v.ToString().Trim();
                        }
                        catch
                        {
                            return string.Empty;
                        }
                    };

                    // شروع از سطر 1 (فرض اینکه سطر 0 هدر است)
                    for (int i = 1; i < sheet.Rows.Count; i++)
                    {
                        var row = sheet.Rows[i];

                        // بررسی اینکه آیا ردیف کاملاً خالی است (بررسی تا expectedColumns)
                        bool rowHasAnyValue = false;
                        for (int c = 0; c < expectedColumns; c++)
                        {
                            if (!string.IsNullOrWhiteSpace(GetCellValue(row, c)))
                            {
                                rowHasAnyValue = true;
                                break;
                            }
                        }

                        if (!rowHasAnyValue)
                        {
                            // ردیف کاملاً خالی است؛ ادامه بده (نخوانده و حساب نمیشه)
                            continue;
                        }

                        // خواندن مقدار Pelakvaziyat به صورت ایمن
