        public async Task<ActionResult> InsertErjaSabtUsr(List<erja_sabt_usr> model)
        {
            try
            {
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");
                var findlik = await db.erja_like.Where(s => s.del != 1).ToListAsync();
                int personal = user.usr_ID;
                long FK_erja_like = 0;
                List<erja_sabt_usr> erja_sabt_usr = new List<erja_sabt_usr>();
                int vazit2 = 0;
                foreach (var item in model)
                {
                    vazit2 = (int)item.vaziat;
                    FK_erja_like = (long)item.FK_omomi;
                    var entity = new erja_sabt_usr
                    {
                        FK_usr = personal,
                        FK_omomi = item.FK_omomi,
                        unic = item.unic,
                        FK_erja_omomi_edit = item.FK_erja_omomi_edit,
                        value_str = item.value_str,
                        value_int = item.value_int,
                        value_time = item.value_time,
                        value_cheek = item.value_cheek,
                        timesabt_vaz0 = DateTime.Now,
                        del = false,
                        vaziat = item.vaziat
                    };

                    erja_sabt_usr.Add(entity);
                }
                db.erja_sabt_usr.AddRange(erja_sabt_usr);

                await db.SaveChangesAsync();
                var find = db.erja_like.Where(s => s.ID == FK_erja_like && s.del != 1).FirstOrDefault();
                if (find != null)
                {

                    if (vazit2 == 1)
                    {
                        var findusr_lonk = db.erja_like_link.Where(s => s.FK_erja_like == find.ID).FirstOrDefault();
                        var findust = db.dbGIS_USR_after.Where(s => s.FK_usr == personal).FirstOrDefault();
                        if (findust != null && findusr_lonk != null)
                        {
                            var find_x = db.dbergharelimsertfk1_7_GIS.Where(s => s.valuunic == findusr_lonk.value && s.FK_db2 == 450).FirstOrDefault();
                            var find_y = db.dbergharelimsertfk1_7_GIS.Where(s => s.valuunic == findusr_lonk.value && s.FK_db2 == 451).FirstOrDefault();


                            if (find_x != null)
                                findust.mogtasat_x = double.TryParse(find_x.valueFK_db2, out double xVal2) ? xVal2 : (double?)null;

                            if (find_y != null)
                                findust.mogtasat_y = double.TryParse(find_y.valueFK_db2, out double yVal2) ? yVal2 : (double?)null;

                            findust.FK_erja = find.ID;
                            findust.cod_car = find.unic;
                            findust.unic = findusr_lonk.value;
                            await db.SaveChangesAsync();

                        }
                        else if (findusr_lonk != null)
                        {
                            dbGIS_USR_after dbGIS_USR_after = new dbGIS_USR_after();
                            var find_x = db.dbergharelimsertfk1_7_GIS.Where(s => s.valuunic == findusr_lonk.value && s.FK_db2 == 450).FirstOrDefault();
                            var find_y = db.dbergharelimsertfk1_7_GIS.Where(s => s.valuunic == findusr_lonk.value && s.FK_db2 == 451).FirstOrDefault();

                            dbGIS_USR_after.FK_usr = personal;
                            if (find_x != null)
                                dbGIS_USR_after.mogtasat_x = double.TryParse(find_x.valueFK_db2, out double xVal2) ? xVal2 : (double?)null;

                            if (find_y != null)
                                dbGIS_USR_after.mogtasat_y = double.TryParse(find_y.valueFK_db2, out double yVal2) ? yVal2 : (double?)null;

                            dbGIS_USR_after.FK_erja = find.ID;
                            dbGIS_USR_after.cod_car = find.unic;
                            dbGIS_USR_after.unic = findusr_lonk.value;
                            db.dbGIS_USR_after.Add(dbGIS_USR_after);
                            await db.SaveChangesAsync();
                        }
                    }
                    find.vaziat = vazit2;
                    await db.SaveChangesAsync();
                }

                return Json(new { success = true });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, error = ex.Message });
            }
        }
        [HttpPost]
        public async Task<JsonResult> SaveCheckedItems(List<long> ids)
        {
            try
            {
                // اگر چیزی ارسال نشده بود
                if (ids == null || ids.Count == 0)
                {
                    return Json(new { success = false, message = "هیچ موردی ارسال نشده است." });
                }
                foreach (var it in ids)
                {
                    var find = db.erja_like.Where(s => s.ID == it && s.vaziat == 1 && s.del != 1).FirstOrDefault();
                    if (find != null)
                    {
                        find.vaziat = 2;

                    }
                    var findlist = db.erja_sabt_usr.Where(s => s.FK_omomi == it && s.vaziat == 1).ToList();
                    foreach (var t in findlist)
                    {
                        t.vaziat = 2;

                    }
                }
                await db.SaveChangesAsync();

                // اینجا می‌تونی عملیات دلخواه رو انجام بدی
                // مثلاً ذخیره در دیتابیس:
