        public ActionResult ImportExcel_dashbord_voslo(HttpPostedFileBase MyExcelStream, DateTime fromDate, DateTime toDate)
        {
            if (MyExcelStream == null)
                return Json(new { success = false, message = "فایل بطور صحیح بارگذاری نشده است" });

            try
            {
                var del_dbdashbord1 = db.dbdashbord1.ToList();
                db.dbdashbord1.RemoveRange(del_dbdashbord1);
                db.SaveChanges();
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return Json(new { success = false, message = "دسترسی غیر مجاز" });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);

                using (var db = new SaabEntities())
                {
                    var user = db.tbUsers.AsNoTracking()
                                 .FirstOrDefault(p => p.usr_NationalCode == nationalcode);

                    if (user == null)
                        return Json(new { success = false, message = "کاربر یافت نشد" });

                    int personal = user.usr_ID;

                    ExcelPackage.LicenseContext = OfficeOpenXml.LicenseContext.NonCommercial;

                    using (var package = new ExcelPackage(MyExcelStream.InputStream))
                    {
                        var sheet = package.Workbook.Worksheets.FirstOrDefault();
                        if (sheet == null || sheet.Dimension == null)
                            return Json(new { success = false, message = "فایل اکسل خالی است" });

                        var dimension = sheet.Dimension;
                        int lastRow = dimension.End.Row;
                        int lastCol = dimension.End.Column;

                        var now = DateTime.Now;

                        // ساخت DataTable مطابق جدول SQL
                        var table = new System.Data.DataTable();

                        table.Columns.Add("FK_usr", typeof(int));
                        table.Columns.Add("astargh_shams", typeof(string));
                        table.Columns.Add("tatarigh_shams", typeof(string));
                        table.Columns.Add("tatarigh", typeof(DateTime));
                        table.Columns.Add("astarigh", typeof(DateTime));
                        table.Columns.Add("time_sabt", typeof(DateTime));
                        table.Columns.Add("name_city", typeof(string));
                        table.Columns.Add("vorodi1", typeof(string));
                        table.Columns.Add("vorodi2", typeof(string));
                        table.Columns.Add("vorodi3", typeof(string));
                        table.Columns.Add("vahd", typeof(string));
                        table.Columns.Add("margah", typeof(string));
                        table.Columns.Add("sumkol", typeof(long));
                        table.Columns.Add("avrage", typeof(double));
                        table.Columns.Add("valu_big", typeof(long));
                        table.Columns.Add("value_nv", typeof(string));
                        table.Columns.Add("active", typeof(bool));

                        for (int row = 2; row <= lastRow; row++)
                        {
                            var name_city = sheet.Cells[row, 2].Text?.Trim();
                            var vorodi1 = sheet.Cells[row, 3].Text?.Trim();
                            var vorodi2 = sheet.Cells[row, 4].Text?.Trim();
                            var vorodi3 = sheet.Cells[row, 5].Text?.Trim();
                            var vahd = sheet.Cells[row, 6].Text?.Trim();
                            var margah = sheet.Cells[row, 7].Text?.Trim();
                            var value_nv = sheet.Cells[row, 10].Text?.Trim();

                            long? valu_big = null;
                            long vg;
                            if (long.TryParse(sheet.Cells[row, 11].Value?.ToString(), out vg))
                                valu_big = vg;

                            for (int col = 12; col <= lastCol; col++)
                            {
                                var shamsiHeader = sheet.Cells[1, col].Text?.Trim();
                                if (string.IsNullOrEmpty(shamsiHeader))
                                    continue;

                                var cellValue = sheet.Cells[row, col].Value;
                                if (cellValue == null)
                                    continue;

                                double cellDouble;
                                if (!double.TryParse(cellValue.ToString(), out cellDouble))
                                    continue;

                                DateTime? miladiDate = null;
                                try
                                {
                                    miladiDate = ConvertShamsiToMiladi11(shamsiHeader);
                                }
                                catch
                                {
                                    continue;
                                }

                                var roundedTwoDecimal =
                                    Math.Round(cellDouble, 2, MidpointRounding.AwayFromZero);

                                table.Rows.Add(
                                    personal,
                                    roundedTwoDecimal.ToString("0.##"),
                                    shamsiHeader,
                                    miladiDate.HasValue ? (object)miladiDate.Value : DBNull.Value,
                                    miladiDate.HasValue ? (object)miladiDate.Value : DBNull.Value,
                                    toDate,
                                    name_city,
                                    vorodi1,
                                    vorodi2,
                                    vorodi3,
                                    vahd,
                                    margah,
                                    (long)Math.Round(cellDouble, 0, MidpointRounding.AwayFromZero),
                                    roundedTwoDecimal,
                                    valu_big.HasValue ? (object)valu_big.Value : DBNull.Value,
                                    value_nv,
                                    DBNull.Value
                                );
                            }
                        }

                        // Bulk Insert حرفه‌ای (بدون وابستگی به ترتیب)
                        var connection = (SqlConnection)db.Database.Connection;
                        if (connection.State != ConnectionState.Open)
                            connection.Open();

                        using (var bulkCopy = new SqlBulkCopy(connection))
                        {
                            bulkCopy.DestinationTableName = "dbo.dbdashbord1";
                            bulkCopy.BatchSize = 5000;
                            bulkCopy.BulkCopyTimeout = 0;

                            foreach (System.Data.DataColumn column in table.Columns)
                                bulkCopy.ColumnMappings.Add(column.ColumnName, column.ColumnName);

                            bulkCopy.WriteToServer(table);
                        }
                    }
                }

                return Json(new { success = true, message = "True" });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = "خطا: " + ex.Message });
            }
        }


