        public ActionResult SaveOrUpdate_data(string select_peyman, long select_peyman22, string string_name, long select_peyman1, long name)
        {
            try
            {
                using (var db = new SaabEntities())
                {
                    // بررسی وجود رکورد
                    var existingRecord = db.dbdashbord1_link
                        .FirstOrDefault(x => x.FK_li == name

                                          && x.nobat == select_peyman1);

                    if (existingRecord != null)
                    {
                        // آپدیت رکورد موجود
                        existingRecord.FK_li = name;
                        existingRecord.name = string_name;
                        existingRecord.name_1 = select_peyman;
                        existingRecord.name = string_name;
                        existingRecord.vaziat = select_peyman22;

                        existingRecord.time_sabt = DateTime.Now;
                        db.SaveChanges();
                    }
                    else
                    {
                        // درج رکورد جدید
                        var newRecord = new dbdashbord1_link
                        {
                            FK_li = name,
                            name = string_name,
                            nobat = select_peyman1,
                            name_1 = select_peyman,
                            vaziat = select_peyman22,

                            time_sabt = DateTime.Now
                        };

                        db.dbdashbord1_link.Add(newRecord);
                        db.SaveChanges();
                    }
                }

                return Json(new { success = true, message = "عملیات با موفقیت انجام شد" });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }
