        public async Task<ActionResult> viewIcon()
        {
            try {
                var model = new FunctionModel
                {
                    ID = 1,
                    valueokala1 = new List<valueokala1>()
                };

                // ===== Cookie =====
                var cookie = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

                var nationalcode = Utility.Base64.Base64Decode(cookie.Value);

                // ===== User =====
                var personal = await db.tbUsers
                    .Where(u => u.usr_NationalCode == nationalcode)
                    .Select(u => u.usr_ID)
                    .FirstOrDefaultAsync();

                if (personal == 0)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

                // ===== FAST SQL QUERY =====
                var result = await db.Database.SqlQuery<NearPointDto1>(@"
;WITH LastPerUnic AS
(
    SELECT *,
           ROW_NUMBER() OVER (PARTITION BY unic ORDER BY ID DESC) AS rn
    FROM erja_like
    WHERE FK_usr = @uid
      AND (del IS NULL OR del <> 1)
      AND FK_job IS NOT NULL
)
SELECT
    CAST(FK_job AS BIGINT) AS ID,  -- <--- مهم
    CAST(SUM(CASE WHEN vaziat = 0 THEN 1 ELSE 0 END) AS BIGINT) AS countentezar,
    CAST(SUM(CASE WHEN vaziat = 1 THEN 1 ELSE 0 END) AS BIGINT) AS countersal,
    CAST(SUM(CASE WHEN vaziat = 2 THEN 1 ELSE 0 END) AS BIGINT) AS countersaltaeed
FROM LastPerUnic
WHERE rn = 1
GROUP BY FK_job

",
                new SqlParameter("@uid", personal)
                ).ToListAsync();

                // ===== Fill Model =====
                model.valueokala1 = result.Select(x => new valueokala1
                {
                    ID = x.ID,
                    countentezar = x.countentezar,
                    countersal = x.countersal,
                    countersaltaeed = x.countersaltaeed
                }).ToList();

                model.sumentezar = result.Sum(x => x.countentezar);
                model.sumersal = result.Sum(x => x.countersal);
                model.sumtaeed = result.Sum(x => x.countersaltaeed);

                return View("~/Areas/Setting/Views/Orders/viewIcon.cshtml", model);
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }
        public class NearPointDto1
        {
            public long ID { get; set; }
            public long count { get; set; }              // اگر لازم داشتی
            public long countentezar { get; set; }
            public long countersal { get; set; }
            public long countersaltaeed { get; set; }
        }

        public async Task<ActionResult> viewIcon1()
        {
            // ایجاد یک مدل FunctionModel
            var model = new FunctionModel
            {
                ID = 1,
                valueokala = new List<valueokala>()
            };
            int count = 0;
            int countersal = 0;
            int countentezar = 0;
            int countersaltaeed = 0;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");
            int personal = user.usr_ID;
            var findlik = await db.erja_like.Where(s => s.FK_usr == personal && s.del != 1).ToListAsync();

            var findunicgroup = findlik.Where(s => s.del != 1).GroupBy(t => t.unic).ToList();
            List<erja_like> erja_like = new List<erja_like>();
            foreach (var it in findunicgroup)
            {
                var findusr = findlik.Where(s => s.unic == it.Key).OrderByDescending(t => t.ID).FirstOrDefault();
                if (findusr.FK_usr == personal)
                {
                    erja_like.Add(findusr);
                }
            }
            long sumentezar = 0;
            long sumersal = 0;
            long sumtaeed = 0;

            foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job).ToList())
            {
                model.valueokala.Add(new valueokala
                {
                    ID = (int)it.Key,
                    count = count,
                    countentezar = erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 0).Count(),
                    countersal = erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 1).Count(),
                    countersaltaeed = erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 2).Count(),
                });
                sumentezar += erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 0).Count();
                sumersal += erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 1).Count();
                sumtaeed += erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 2).Count();

            }
            model.sumtaeed = sumtaeed;
            model.sumentezar = sumentezar;
            model.sumersal = sumersal;

            // ساخت چندین آیتم valueokala با حلقه

            return View("~/Areas/Setting/Views/Orders/viewIcon.cshtml", model);

        }
        public async Task<ActionResult> viewnearEntezar(int jobId, int takeCount = 10)
        {
            var model = new FunctionModel
            {
                ID = 1,
                valueokala = new List<valueokala>(),
                detailjob = new List<detailjob>(),
                detailjob1 = new List<detailjob1>()
            };

            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;

            // لیست erja_like برای کاربر
            var findlik = await db.erja_like.Where(s => s.del != 1).ToListAsync();
            var findunicgroup = findlik.Where(s => s.del != 1).GroupBy(t => t.unic).ToList();
            List<erja_like> erja_like = new List<erja_like>();
            foreach (var it in findunicgroup)
            {
                var findusr = findlik.Where(s => s.unic == it.Key).OrderByDescending(t => t.ID).FirstOrDefault();
                if (findusr.FK_usr == personal)
                    erja_like.Add(findusr);
            }

            // جمع آمار
            foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job))
            {
                model.valueokala.Add(new valueokala
                {
                    ID = (int)it.Key,
                    countentezar = it.Count(x => x.vaziat == 0),
                    countersal = it.Count(x => x.vaziat == 1),
                    countersaltaeed = it.Count(x => x.vaziat == 2)
                });
            }

            model.sumentezar = erja_like.Count(x => x.vaziat == 0);
            model.sumersal = erja_like.Count(x => x.vaziat == 1);
            model.sumtaeed = erja_like.Count(x => x.vaziat == 2);

            // نقطه مرجع برای محاسبه فاصله
            double baseLat = 29.4988;
            double baseLng = 60.8689;
            double maxDistance = 500000; // کیلومتر

            // گرفتن نزدیک‌ترین نقاط از SQL
            var nearPoints = db.Database.SqlQuery<NearPointDto>(@"
        ;WITH Points AS
(
    SELECT 
        lat.valuunic AS Unic,
        CAST(lat.valueFK_db2 AS FLOAT) AS Lat,
        CAST(lng.valueFK_db2 AS FLOAT) AS Lng
    FROM dbergharelimsertfk1_7_GIS lat
    JOIN dbergharelimsertfk1_7_GIS lng 
        ON lat.valuunic = lng.valuunic
    WHERE lat.FK_db2 = 450
      AND lng.FK_db2 = 451
),
DistCalc AS
(
    SELECT *,
        6371 * 2 * ASIN(
            SQRT(
                POWER(SIN((RADIANS(Lat - @lat0)) / 2), 2) +
                COS(RADIANS(@lat0)) * COS(RADIANS(Lat)) *
                POWER(SIN((RADIANS(Lng - @lng0)) / 2), 2)
            )
        ) AS DistanceKm
    FROM Points
)
SELECT TOP (@take) *
FROM DistCalc
WHERE DistanceKm <= @maxd
ORDER BY DistanceKm ASC
",
            new SqlParameter("@lat0", baseLat),
            new SqlParameter("@lng0", baseLng),
            new SqlParameter("@maxd", maxDistance),
            new SqlParameter("@take", takeCount)
            ).ToList();

            // لیست IDs erja_like
            var erjaIds = erja_like.Select(e => e.ID).ToList();

            // اضافه کردن نزدیک‌ترین نقاط به detailjob با نام و جزئیات درست
            foreach (var p in nearPoints)
            {
                // پیدا کردن لینک مرتبط با erja_like و Unic
                var link = db.erja_like_link
                    .Where(l => l.value == p.Unic && l.FK_erja_like.HasValue && erjaIds.Contains(l.FK_erja_like.Value))
                    .OrderByDescending(l => l.ID)
                    .FirstOrDefault();

                if (link != null)
                {
                    string name = "";
                    string detal = "";

                    // نام را از erja_omomi بگیریم
                    var omomi = db.erja_omomi.FirstOrDefault(o => o.ID == link.FK_omomi);
                    if (omomi != null)
                    {
                        name = omomi.title;

                        if (omomi.vaziat == 1)
                        {
                            detal = link.value;
                        }
                        else if (omomi.vaziat == 0)
                        {
                            // اگر unic=true بود
                            var findvalue = db.dbergharelimsertfk1_7
                                .Where(s => s.valuunic == link.value && s.FK_db2 == omomi.FK_link)
                                .OrderByDescending(t => t.ID)
                                .FirstOrDefault();
                            if (findvalue != null)
                                detal = findvalue.valueFK_db2;
                        }
                    }

                    model.detailjob.Add(new detailjob
                    {
                        IDst = link.erja_like.unic,
                        name = name,
                        detal = detal
                    });

                    model.detailjob1.Add(new detailjob1
                    {
                        IDst = link.erja_like.unic,
                        ID = link.FK_erja_like.Value,
                        FK_usr = personal,
                        vaziat = 1
                    });
                }
            }

            return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
        }


        public ActionResult ViewNearest1(int jobId, int takeCount)
        {
            try
            {
                double baseLat = 29.457259;
                double baseLng = 60.76013;
                double maxDistance = 5000000;

                var model = new List<detailjob1>();

                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest);

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest);

                int personal = user.usr_ID;

                var erja_like = db.erja_like
                    .Where(s => s.del != 1 && s.FK_usr == personal && s.FK_job == jobId && s.vaziat == 0)
                    .ToList();

                var nearPoints = db.Database.SqlQuery<NearPointDto>(@"
;WITH Points AS
(
    SELECT 
        lat.valuunic AS Unic,
        CAST(lat.valueFK_db2 AS FLOAT) AS Lat,
        CAST(lng.valueFK_db2 AS FLOAT) AS Lng
    FROM dbergharelimsertfk1_7_GIS lat
    JOIN dbergharelimsertfk1_7_GIS lng 
        ON lat.valuunic = lng.valuunic
    WHERE lat.FK_db2 = 450
      AND lng.FK_db2 = 451
),
DistCalc AS
(
    SELECT *,
        6371 * ACOS(
            COS(RADIANS(@lat0)) * COS(RADIANS(Lat)) *
            COS(RADIANS(Lng) - RADIANS(@lng0)) +
            SIN(RADIANS(@lat0)) * SIN(RADIANS(Lat))
        ) AS DistanceKm
    FROM Points
)
SELECT TOP (@take) *
FROM DistCalc
WHERE DistanceKm <= @maxd
ORDER BY DistanceKm ASC
",
                new SqlParameter("@lat0", baseLat),
                new SqlParameter("@lng0", baseLng),
                new SqlParameter("@maxd", maxDistance),
                new SqlParameter("@take", takeCount)
                ).ToList();

                foreach (var p in nearPoints)
                {
                    var it = erja_like.FirstOrDefault(x => x.unic == p.Unic);
                    if (it == null) continue;

                    model.Add(new detailjob1
                    {
                        IDst = it.unic,
                        ID = it.ID,
                        FK_usr = personal,
                        vaziat = 1
                    });
                }

                return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }
        public class NearPointDto
        {
            public string Unic { get; set; }
            public double Lat { get; set; }
            public double Lng { get; set; }
            public double DistanceKm { get; set; }
        }


        public async Task<ActionResult> viewEntezar2(int jobId, int takeCount)
        {
            var model = new FunctionModel
            {
                ID = 1,
                valueokala = new List<valueokala>(),
                detailjob = new List<detailjob>(),
                detailjob1 = new List<detailjob1>()
            };

            //int takeCount = takeCount; // 🔴 تعداد نزدیک‌هایی که می‌خوای نمایش بدی
            double maxDistanceKm = 10000; // 🔴 حداکثر فاصله

            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;

            // ================== نقطه مرجع ==================
            double baseLat = 0;
            double baseLng = 0;

            var groBase = await db.erja_like_link
                .OrderByDescending(s => s.ID)
                .FirstOrDefaultAsync();

            if (groBase != null)
            {
                var find = db.dbergharelimsertfk1_7
                    .FirstOrDefault(s => s.valuunic == groBase.value && s.FK_db2 == 143);

                if (find != null)
                {
                    var latObj = db.dbergharelimsertfk1_7_GIS
                        .Where(s => s.valuunic == find.valueFK_db2 && s.FK_db2 == 450)
                        .OrderByDescending(s => s.ID)
                        .FirstOrDefault();

                    var lngObj = db.dbergharelimsertfk1_7_GIS
                        .Where(s => s.valuunic == find.valueFK_db2 && s.FK_db2 == 451)
                        .OrderByDescending(s => s.ID)
                        .FirstOrDefault();

                    if (latObj != null && lngObj != null)
                    {
                        baseLat = System.Convert.ToDouble(latObj.valueFK_db2);
                        baseLng = System.Convert.ToDouble(lngObj.valueFK_db2);
                    }
                }
            }

            // ================== لیست ارجاعات کاربر ==================
            var findlik = await db.erja_like.Where(s => s.del != 1).ToListAsync();

            var findunicgroup = findlik.GroupBy(t => t.unic).ToList();
            List<erja_like> erja_like = new List<erja_like>();

            foreach (var it in findunicgroup)
            {
                var findusr = findlik
                    .Where(s => s.unic == it.Key)
                    .OrderByDescending(t => t.ID)
                    .FirstOrDefault();

                if (findusr.FK_usr == personal)
                {
                    erja_like.Add(findusr);
                }
            }

            // ================== آمار بالا ==================
            long sumentezar = 0;
            long sumersal = 0;
            long sumtaeed = 0;

            foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job).ToList())
            {
                int entezar = erja_like.Count(s => s.FK_job == it.Key && s.vaziat == 0);
                int ersal = erja_like.Count(s => s.FK_job == it.Key && s.vaziat == 1);
                int taeed = erja_like.Count(s => s.FK_job == it.Key && s.vaziat == 2);

                model.valueokala.Add(new valueokala
                {
                    ID = (int)it.Key,
                    countentezar = entezar,
                    countersal = ersal,
                    countersaltaeed = taeed,
                });

                sumentezar += entezar;
                sumersal += ersal;
                sumtaeed += taeed;
            }

            model.sumtaeed = sumtaeed;
            model.sumentezar = sumentezar;
            model.sumersal = sumersal;

            // ================== فقط job جاری ==================
            var gro = erja_like.Where(t => t.FK_job == jobId && t.vaziat == 0).ToList();

            var allGis = db.dbergharelimsertfk1_7_GIS.ToList();

            // ================== محاسبه فاصله ==================
            List<(erja_like item, double dist)> tempList = new List<(erja_like, double)>();

            foreach (var it in gro)
            {
                var latObj = allGis
                    .Where(s => s.valuunic == it.unic && s.FK_db2 == 450)
                    .OrderByDescending(s => s.ID)
                    .FirstOrDefault();

                var lngObj = allGis
                    .Where(s => s.valuunic == it.unic && s.FK_db2 == 451)
                    .OrderByDescending(s => s.ID)
                    .FirstOrDefault();

                if (latObj == null || lngObj == null)
                    continue;

                double lat = System.Convert.ToDouble(latObj.valueFK_db2);
                double lng = System.Convert.ToDouble(lngObj.valueFK_db2);

                double dist = CalcDistance(baseLat, baseLng, lat, lng);

                if (dist <= maxDistanceKm)
                {
                    tempList.Add((it, dist));
                }
            }

            // ================== مرتب + انتخاب N تا ==================
            var nearestItems = tempList
                .OrderBy(s => s.dist)
                .Take(takeCount)
                .ToList();

            foreach (var n in nearestItems)
            {
                model.detailjob1.Add(new detailjob1
                {
                    IDst = n.item.unic,
                    ID = n.item.ID,
                    FK_usr = personal,
                    vaziat = 1
                });
            }

            return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
        }
        private double CalcDistance(double lat1, double lon1, double lat2, double lon2)
        {
            double R = 6371;
            var dLat = ToRad(lat2 - lat1);
            var dLon = ToRad(lon2 - lon1);

            var a = Math.Sin(dLat / 2) * Math.Sin(dLat / 2) +
                    Math.Cos(ToRad(lat1)) * Math.Cos(ToRad(lat2)) *
                    Math.Sin(dLon / 2) * Math.Sin(dLon / 2);

            var c = 2 * Math.Atan2(Math.Sqrt(a), Math.Sqrt(1 - a));
            return R * c;
        }

        private double ToRad(double val)
        {
            return val * Math.PI / 180;
        }
        public async Task<ActionResult> viewEntezar_NEAR1(int jobId, int takeCount = 10)
        {
            var model = new FunctionModel
            {
                ID = 1,
                valueokala = new List<valueokala>(),
                detailjob = new List<detailjob>(),
                detailjob1 = new List<detailjob1>()
            };

            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;

            // -------------------- گرفتن erja_like های کاربر --------------------
            var findlik = await db.erja_like.Where(s => s.del != 1).ToListAsync();

            var findunicgroup = findlik.GroupBy(t => t.unic).ToList();
            List<erja_like> erja_like = new List<erja_like>();

            foreach (var it in findunicgroup)
            {
                var findusr = findlik.Where(s => s.unic == it.Key)
                                     .OrderByDescending(t => t.ID)
                                     .FirstOrDefault();
                if (findusr.FK_usr == personal)
                    erja_like.Add(findusr);
            }

            // -------------------- آمار کلی --------------------
            foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job))
            {
                model.valueokala.Add(new valueokala
                {
                    ID = (int)it.Key,
                    countentezar = it.Count(x => x.vaziat == 0),
                    countersal = it.Count(x => x.vaziat == 1),
                    countersaltaeed = it.Count(x => x.vaziat == 2)
                });
            }

            model.sumentezar = erja_like.Count(x => x.vaziat == 0);
            model.sumersal = erja_like.Count(x => x.vaziat == 1);
            model.sumtaeed = erja_like.Count(x => x.vaziat == 2);

            // -------------------- محاسبه فاصله (SQL) --------------------
            double baseLat = 29.4988;
            double baseLng = 60.8689;
            double maxDistance = 500000; // km

            var nearPoints = db.Database.SqlQuery<NearPointDto>(@"
;WITH Points AS
(
    SELECT 
        lat.valuunic AS Unic,
        CAST(lat.valueFK_db2 AS FLOAT) AS Lat,
        CAST(lng.valueFK_db2 AS FLOAT) AS Lng
    FROM dbergharelimsertfk1_7_GIS lat
    JOIN dbergharelimsertfk1_7_GIS lng 
        ON lat.valuunic = lng.valuunic
    WHERE lat.FK_db2 = 450
      AND lng.FK_db2 = 451
),
DistCalc AS
(
    SELECT *,
        6371 * 2 * ASIN(
            SQRT(
                POWER(SIN((RADIANS(Lat - @lat0)) / 2), 2) +
                COS(RADIANS(@lat0)) * COS(RADIANS(Lat)) *
                POWER(SIN((RADIANS(Lng - @lng0)) / 2), 2)
            )
        ) AS DistanceKm
    FROM Points
)
SELECT TOP (@take) *
FROM DistCalc
WHERE DistanceKm <= @maxd
ORDER BY DistanceKm ASC
",
            new SqlParameter("@lat0", baseLat),
            new SqlParameter("@lng0", baseLng),
            new SqlParameter("@maxd", maxDistance),
            new SqlParameter("@take", takeCount)
            ).ToList();

            // فقط یونیک‌های نزدیک به ترتیب فاصله
            var orderedNearUnics = nearPoints.Select(x => x.Unic).ToList();

            // -------------------- gro با ترتیب فاصله --------------------
            var gro = orderedNearUnics
                .Select(unic =>
                    erja_like.FirstOrDefault(e =>
                        e.unic == unic &&
                        e.FK_job == jobId &&
                        e.vaziat == 0))
                .Where(e => e != null)
                .ToList();

            // -------------------- پر کردن مدل --------------------
            foreach (var it in gro)
            {
                var fooo = db.erja_omomi
                    .Where(s => s.FK_job == it.FK_job && s.dargeshavad == 1)
                    .ToList();

                foreach (var it1 in fooo)
                {
                    string name = it1.title;
                    string detailname = "";

                    if (it1.vaziat == 1)
                    {
                        var fidname = db.erja_like_link
                            .Where(s => s.FK_omomi == it1.ID && s.FK_erja_like == it.ID)
                            .OrderByDescending(t => t.ID)
                            .FirstOrDefault();

                        if (fidname != null)
                            detailname = fidname.value;
                    }
                    else if (it1.vaziat == 0)
                    {
                        var findunic = db.erja_omomi
                            .Where(s => s.unic == true && s.FK_gozaresh == it1.FK_gozaresh && s.FK_job == jobId)
                            .OrderByDescending(t => t.ID)
                            .FirstOrDefault();

                        if (findunic != null)
                        {
                            var fidname = db.erja_like_link
                                .Where(s => s.FK_omomi == findunic.ID && s.FK_erja_like == it.ID)
                                .OrderByDescending(t => t.ID)
                                .FirstOrDefault();

                            if (fidname != null)
                            {
                                var findvalue = db.dbergharelimsertfk1_7
                                    .Where(s => s.valuunic == fidname.value && s.FK_db2 == it1.FK_link)
                                    .OrderByDescending(t => t.ID)
                                    .FirstOrDefault();

                                if (findvalue != null)
                                    detailname = findvalue.valueFK_db2;
                            }
                        }
                    }

                    model.detailjob.Add(new detailjob
                    {
                        IDst = it.unic,
                        name = name,
                        detal = detailname
                    });
                }

                model.detailjob1.Add(new detailjob1
                {
                    IDst = it.unic,
                    ID = it.ID,
                    FK_usr = personal,
                    vaziat = 1
                });
            }

            return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
        }
        public async Task<ActionResult> viewEntezar_NEAR2(int jobId, int takeCount = 10)
        {
            var model = new FunctionModel
            {
                ID = 1,
                valueokala = new List<valueokala>(),
                detailjob = new List<detailjob>(),
                detailjob1 = new List<detailjob1>()
            };

            // ---------- User ----------
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;

            // ---------- erja_like کاربر ----------
            var allLikes = await db.erja_like
                .Where(s => s.del != 1)
                .ToListAsync();

            var erja_like = allLikes
                .GroupBy(t => t.unic)
                .Select(g => g.OrderByDescending(x => x.ID).First())
                .Where(x => x.FK_usr == personal)
                .ToList();

            // ---------- آمار ----------
            foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job))
            {
                model.valueokala.Add(new valueokala
                {
                    ID = (int)it.Key,
                    countentezar = it.Count(x => x.vaziat == 0),
                    countersal = it.Count(x => x.vaziat == 1),
                    countersaltaeed = it.Count(x => x.vaziat == 2)
                });
            }

            model.sumentezar = erja_like.Count(x => x.vaziat == 0);
            model.sumersal = erja_like.Count(x => x.vaziat == 1);
            model.sumtaeed = erja_like.Count(x => x.vaziat == 2);

            // ---------- فاصله GIS ----------
            double baseLat = 29.4988;
            double baseLng = 60.8689;
            double maxDistance = 500000;

            var nearPoints = db.Database.SqlQuery<NearPointDto>(@"
;WITH MaxBatch AS
(
    SELECT MAX(FK_dbergharelinsert_6) AS MaxFK
    FROM dbergharelimsertfk1_7_GIS
),
Points AS
(
    SELECT 
        lat.valuunic AS Unic,
        CAST(lat.valueFK_db2 AS FLOAT) AS Lat,
        CAST(lng.valueFK_db2 AS FLOAT) AS Lng
    FROM dbergharelimsertfk1_7_GIS lat
    JOIN dbergharelimsertfk1_7_GIS lng
        ON lat.valuunic = lng.valuunic
    CROSS JOIN MaxBatch mb
    WHERE lat.FK_dbergharelinsert_6 = mb.MaxFK
      AND lng.FK_dbergharelinsert_6 = mb.MaxFK
      AND lat.FK_db2 = 450
      AND lng.FK_db2 = 451
),
DistCalc AS
(
    SELECT *,
        6371 * 2 * ASIN(
            SQRT(
                POWER(SIN((RADIANS(Lat - @lat0)) / 2), 2) +
                COS(RADIANS(@lat0)) * COS(RADIANS(Lat)) *
                POWER(SIN((RADIANS(Lng - @lng0)) / 2), 2)
            )
        ) AS DistanceKm
    FROM Points
)
SELECT TOP (@take) *
FROM DistCalc
WHERE DistanceKm <= @maxd
ORDER BY DistanceKm ASC
",
     new SqlParameter("@lat0", baseLat),
     new SqlParameter("@lng0", baseLng),
     new SqlParameter("@maxd", maxDistance),
     new SqlParameter("@take", takeCount)
     ).ToList();


            var orderedNearUnics = nearPoints.Select(x => x.Unic).ToList();

            // ---------- gro به ترتیب فاصله ----------
            var gro = orderedNearUnics
                .Select(unic => erja_like.FirstOrDefault(e =>
                    e.erja_like_link.Any(s => s.value == unic) &&
                    e.FK_job == jobId &&
                    e.vaziat == 0))
                .Where(e => e != null)
                .ToList();

            if (!gro.Any())
                return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);

            var groIds = gro.Select(x => x.ID).ToList();

            // ---------- همه omomi های لازم ----------
            var omomis = await db.erja_omomi
                .Where(s => s.FK_job == jobId && s.dargeshavad == 1)
                .ToListAsync();

            var omomiIds = omomis.Select(x => x.ID).ToList();
            var orderedUnics = nearPoints.Select(x => x.Unic).ToList();

            // ---------- همه link ها ----------
            var links = await db.erja_like_link
        .Where(l => orderedUnics.Contains(l.value) && l.FK_erja_like.HasValue)
        .OrderByDescending(l => l.ID)
        .ToListAsync();



            // ---------- همه مقادیر dbergharelimsertfk1_7 ----------
            var unics = links.Select(l => l.value).Distinct().ToList();

            var dbValues = await db.dbergharelimsertfk1_7
                .Where(s => unics.Contains(s.valuunic))
                .OrderByDescending(s => s.ID)
                .ToListAsync();

            // ---------- ساخت مدل ----------
            foreach (var it in gro)
            {
                foreach (var it1 in omomis)
                {
                    string detailname = "";

                    if (it1.vaziat == 1)
                    {
                        var link = links.FirstOrDefault(l =>
                            l.FK_omomi == it1.ID && l.FK_erja_like == it.ID);

                        if (link != null)
                            detailname = link.value;
                    }
                    else
                    {
                        var findunicOmomi = omomis
                            .FirstOrDefault(o => o.unic == true &&
                                                 o.FK_gozaresh == it1.FK_gozaresh);

                        if (findunicOmomi != null)
                        {
                            var link = links.FirstOrDefault(l =>
                                l.FK_omomi == findunicOmomi.ID &&
                                l.FK_erja_like == it.ID);

                            if (link != null)
                            {
                                var val = dbValues.FirstOrDefault(v =>
                                    v.valuunic == link.value &&
                                    v.FK_db2 == it1.FK_link);

                                if (val != null)
                                    detailname = val.valueFK_db2;
                            }
                        }
                    }

                    model.detailjob.Add(new detailjob
                    {
                        IDst = it.unic,
                        name = it1.title,
                        detal = detailname
                    });
                }

                model.detailjob1.Add(new detailjob1
                {
                    IDst = it.unic,
                    ID = it.ID,
                    FK_usr = personal,
                    vaziat = 1
                });
            }

            return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
        }
