        public ActionResult hesabreyali(int Month = 11, int Year = 1404, int day = 30, int kasri = 3)
        {
            try
            {
                var FINDFISH = db.tbMoalefeValueFish.Where(s => s.mlfvlfsh_Month == Month && s.mlfvlfsh_Year == Year && s.Finalaccept == true).ToList();
                var find20 = db.tbkarkard_notsystem.Where(s => s.moadel_kol != null && s.month == Month && s.year == Year).ToList();

                var findusr = db.tbMoadelPadashJarimeAyab.Where(s => s.Moadel != null && s.Year == Year && s.Month == Month).ToList();
                foreach (var fin in findusr)
                {
                    double xx = 0;
                    var find2 = find20.Where(s => s.FK_usr == fin.UserID && s.month == Month && s.year == Year).OrderByDescending(s => s.ID).FirstOrDefault();
                    if (find2 != null)
                    {
                        xx = (double)find2.moadel_kol;

                    }
                    else
                    {
                        xx = (double)fin.Moadel;

                    }
                    if (xx > 1)
                    {
                        int kar = 0;
                        int kar2 = 0;
                        double kar5 = 0;
                        double kar6 = 0;

                        var find1964 = FINDFISH.Where(s => s.FK_User == fin.UserID && s.FK_Moalefe == 1964).FirstOrDefault();
                        var findkaraneh = FINDFISH.Where(s => s.FK_User == fin.UserID && s.FK_Moalefe== 4589).FirstOrDefault();

                        var find = FINDFISH.Where(s => s.FK_User == fin.UserID && s.FK_Moalefe == 1965).FirstOrDefault();
                        var find1961 = FINDFISH.Where(s => s.FK_User == fin.UserID && s.FK_Moalefe == 1961).FirstOrDefault();
                        if (find != null && find.mlfvlfsh_Value != null)
                        {
                            kar = (int)(day - find.mlfvlfsh_Value);

                        }
                        else
                        {
                            kar = day;
                        }
                        if (find1964 != null && find1964.mlfvlfsh_Value != null)
                        {

                            kar2 = (int)(kar - find1964.mlfvlfsh_Value);



                        }
                        else
                        {
                            kar2 = kar;
                        }
                        kar5 = xx - 1;
                        kar6 = Math.Ceiling(kar5 * 7.3333 * kar2);
                        if (kar6 > 80)
                        {
                            kar6 = 80;
                        }
                        if (findkaraneh != null) {
                            kar6 += findkaraneh.mlfvlfsh_Value ?? 0;

                        }
                        if (find1961 != null)
                        {
                            find1961.mlfvlfsh_Value = kar6;

                        }
                    }
                    else
                    {
                        double kar6 = 0;
                        var find1964 = FINDFISH.Where(s => s.FK_User == fin.UserID && s.FK_Moalefe == 1964).FirstOrDefault();
                        var findkaraneh = FINDFISH.Where(s => s.FK_User == fin.UserID && s.FK_Moalefe == 4589).FirstOrDefault();

                        var find = FINDFISH.Where(s => s.FK_User == fin.UserID && s.FK_Moalefe == 1965).FirstOrDefault();
                        var find1961 = FINDFISH.Where(s => s.FK_User == fin.UserID && s.FK_Moalefe == 1961).FirstOrDefault();
                        if (findkaraneh != null)
                        {
                            kar6 = findkaraneh.mlfvlfsh_Value ?? 0;
                        }
                        if (find1961 != null)
                        {
                            find1961.mlfvlfsh_Value = kar6;

                        }
                    }

                }
                db.SaveChanges();

                return Content("true");
            }
            catch (Exception ex)
            {
                return Content(ex.Message);


            }

        }
        public ActionResult hesabreyali_mohasebehh(int Month = 11, int Year = 1404, int day = 30, int kasri = 3)
        {
            try
            {
                string inputDate = "1/" + Month + "/" + Year;
                DateTime persianDate = PersianDateToDateTime(inputDate);

                var find20 = db.tbkarkard_notsystem
                    .Where(s => s.moadel_kol != null && s.month == Month && s.year == Year)
                    .ToList()
                    .GroupBy(x => x.FK_usr)
                    .ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.ID).First());

                var findusr = db.tbMoadelPadashJarimeAyab
                    .Where(s => s.Moadel != null && s.Year == Year && s.Month == Month)
                    .ToList();

                var fin5 = db.tbfkfinancial
                    .FirstOrDefault(p => p.DataDocument == persianDate && p.numbershomar == 10001);

                if (fin5 == null)
                {
                    fin5 = new tbfkfinancial
                    {
                        Title = "مساعده مدیر عامل",
                        DataDocument = persianDate,
                        numbershomar = 10001
                    };
                    db.tbfkfinancial.Add(fin5);
                    db.SaveChanges();
                }

                var financialDocs = db.FinancialDocuments
                    .Where(p => p.DataDocument == persianDate)
                    .ToList();

                foreach (var fin in findusr)
                {
                    double xx = 0;

                    if (find20.ContainsKey(fin.UserID))
                        xx = (double)find20[fin.UserID].moadel_kol;
                    else
                        xx = (double)fin.Moadel;

                    if (xx <= 0.7) continue;

                    float ayabzahab2;

                    if (xx > 1.7)
                        ayabzahab2 = 67000000;
                    else
                        ayabzahab2 = (float)((xx - 0.7) * 67000000);


                    if (ayabzahab2 < 67000000) { 
                    //{
                    //    if(ayabzahab2< 18720000)
                    //    {
                    //        ayabzahab2 = 18720000;
                    //    }
                        
                        ayabzahab2 = ayabzahab2 + 18720000;
                        if(ayabzahab2> 67000000)
                        {
                            ayabzahab2 = 67000000;

                        }

                    }

                    var doc = financialDocs
                        .FirstOrDefault(p => p.User_ID == fin.UserID && p.FK_final == fin5.ID);

                    if (doc != null)
                    {
                        doc.Creditor = ayabzahab2;
                    }
                    else
                    {
                        db.FinancialDocuments.Add(new FinancialDocuments
                        {
                            FK_final = fin5.ID,
                            Creditor = ayabzahab2,
                            User_ID = fin.UserID,
                            DataDocument = persianDate,
                            Debtore = 0,
                            Title = "مساعده مدیر عامل"
                        });
                    }
                }

                db.SaveChanges();

                return Content("true");
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }

