        public async Task<ActionResult> viewEntezar_near3(int jobId, int takeCount = 10)
        {
            var model = new FunctionModel
            {
                ID = 1,
                valueokala = new List<valueokala>(),
                detailjob = new List<detailjob>(),
                detailjob1 = new List<detailjob1>()
            };

            // ---------- User ----------
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;

            // ---------- erja_like های کاربر ----------
            var allLikes = await db.erja_like.Where(s => s.del != 1).ToListAsync();

            var erja_like = allLikes
                .GroupBy(t => t.unic)
                .Select(g => g.OrderByDescending(x => x.ID).First())
                .Where(x => x.FK_usr == personal)
                .ToList();

            // ---------- آمار ----------
            foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job))
            {
                model.valueokala.Add(new valueokala
                {
                    ID = (int)it.Key,
                    countentezar = it.Count(x => x.vaziat == 0),
                    countersal = it.Count(x => x.vaziat == 1),
                    countersaltaeed = it.Count(x => x.vaziat == 2)
                });
            }

            model.sumentezar = erja_like.Count(x => x.vaziat == 0);
            model.sumersal = erja_like.Count(x => x.vaziat == 1);
            model.sumtaeed = erja_like.Count(x => x.vaziat == 2);
            var erja_like_entezar = erja_like.Where(x => x.vaziat == 0 && x.FK_job == jobId).ToList();
            var erjaIds = erja_like_entezar.Select(x => x.ID).ToList();

            // ---------- GIS : فقط آخرین Batch ----------
            double baseLat = 27.2009;
            double baseLng = 60.6691;
            db.Database.CommandTimeout = 800;
            var points = db.Database.SqlQuery<NearPointDto>(@"
;WITH MaxBatch AS
(
    SELECT MAX(FK_dbergharelinsert_6) AS MaxFK
    FROM dbergharelimsertfk1_7_GIS
),
FilteredLinks AS
(
    SELECT value
    FROM erja_like_link
    WHERE FK_erja_like IN (" + string.Join(",", erjaIds) + @")
)
SELECT 
    lat.valuunic AS Unic,
    CAST(lat.valueFK_db2 AS FLOAT) AS Lat,
    CAST(lng.valueFK_db2 AS FLOAT) AS Lng
FROM dbergharelimsertfk1_7_GIS lat
JOIN dbergharelimsertfk1_7_GIS lng
    ON lat.valuunic = lng.valuunic
JOIN FilteredLinks fl
    ON lat.valuunic = fl.value
CROSS JOIN MaxBatch mb
WHERE lat.FK_dbergharelinsert_6 = mb.MaxFK
  AND lng.FK_dbergharelinsert_6 = mb.MaxFK
  AND lat.FK_db2 = 450
  AND lng.FK_db2 = 451
").ToList();

            //            var points = db.Database.SqlQuery<NearPointDto>(@"
            //;WITH MaxBatch AS
            //(
            //    SELECT MAX(FK_dbergharelinsert_6) AS MaxFK
            //    FROM dbergharelimsertfk1_7_GIS
            //)
            //SELECT 
            //    lat.valuunic AS Unic,
            //    CAST(lat.valueFK_db2 AS FLOAT) AS Lat,
            //    CAST(lng.valueFK_db2 AS FLOAT) AS Lng
            //FROM dbergharelimsertfk1_7_GIS lat
            //JOIN dbergharelimsertfk1_7_GIS lng
            //    ON lat.valuunic = lng.valuunic
            //CROSS JOIN MaxBatch mb
            //WHERE lat.FK_dbergharelinsert_6 = mb.MaxFK
            //  AND lng.FK_dbergharelinsert_6 = mb.MaxFK
            //  AND lat.FK_db2 = 450
            //  AND lng.FK_db2 = 451
            //").ToList();

            // ---------- مرتب‌سازی زنجیره‌ای (Nearest Neighbor) ----------
            List<NearPointDto> ordered = new List<NearPointDto>();
            var remaining = new List<NearPointDto>(points);
            double curLat = baseLat;
            double curLng = baseLng;

            while (remaining.Any() && ordered.Count < takeCount)
            {
                var nearest = remaining
                    .OrderBy(p => Haversine(curLat, curLng, p.Lat, p.Lng))
                    .First();

                ordered.Add(nearest);
                remaining.Remove(nearest);

                curLat = nearest.Lat;
                curLng = nearest.Lng;
            }

            var orderedUnics = ordered.Select(x => x.Unic).ToList();

            // ---------- link ها ----------
            var links = await db.erja_like_link
                .Where(l => orderedUnics.Contains(l.value) && l.FK_erja_like.HasValue && l.erja_like.FK_usr == personal && l.erja_like.vaziat == 0 && l.erja_like.FK_job == jobId)
                .OrderByDescending(l => l.ID)
                .ToListAsync();

            // ---------- erja_like به ترتیب فاصله ----------
            var likesDict = erja_like.ToDictionary(x => x.ID, x => x);

            var gro = orderedUnics
                .Select(unic =>
                {
                    var link = links.FirstOrDefault(l => l.value == unic && l.erja_like.FK_usr == personal && l.erja_like.vaziat == 0);
                    if (link == null) return null;

                    //if (!likesDict.TryGetValue(link.FK_erja_like.Value, out var like))
                    //    return null;

                    if (link.erja_like.FK_job != jobId || link.erja_like.vaziat != 0)
                        return null;

                    return link.erja_like;
                })
                .Where(x => x != null)
                .ToList();

            // ---------- omomi ----------
            var omomis = await db.erja_omomi
                .Where(s => s.FK_job == jobId && s.dargeshavad == 1)
                .ToListAsync();

            var groIds = gro.Select(x => x.ID).ToList();
            var relLinks = links
                .Where(l => l.FK_erja_like.HasValue && groIds.Contains(l.FK_erja_like.Value))
                .ToList();

            var unics = relLinks.Select(l => l.value).Distinct().ToList();

            var dbValues = await db.dbergharelimsertfk1_7
                .Where(s => unics.Contains(s.valuunic))
                .OrderByDescending(s => s.ID)
                .ToListAsync();

            // ---------- ساخت مدل ----------
            foreach (var it in gro)
            {
                foreach (var it1 in omomis)
                {
                    string detailname = "";

                    if (it1.vaziat == 1)
                    {
                        var link = relLinks.FirstOrDefault(l =>
                            l.FK_omomi == it1.ID && l.FK_erja_like == it.ID);

                        if (link != null)
                            detailname = link.value;
                    }
                    else
                    {
                        var findunicOmomi = omomis.FirstOrDefault(o =>
                            o.unic == true && o.FK_gozaresh == it1.FK_gozaresh);

                        if (findunicOmomi != null)
                        {
                            var link = relLinks.FirstOrDefault(l =>
                                l.FK_omomi == findunicOmomi.ID && l.FK_erja_like == it.ID);

                            if (link != null)
                            {
                                var val = dbValues.FirstOrDefault(v =>
                                    v.valuunic == link.value && v.FK_db2 == it1.FK_link);

                                if (val != null)
                                    detailname = val.valueFK_db2;
                            }
                        }
                    }

                    model.detailjob.Add(new detailjob
                    {
                        IDst = it.unic,
                        name = it1.title,
                        detal = detailname,


                    });

                }

                model.detailjob1.Add(new detailjob1
                {
                    IDst = it.unic,
                    ID = it.ID,
                    FK_usr = personal,
                    vaziat = 1
                });
            }

            return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
        }

        // ---------- تابع Haversine ----------
        private static double Haversine(double lat1, double lon1, double lat2, double lon2)
        {
            const double R = 6371; // km
            double dLat = (lat2 - lat1) * Math.PI / 180;
            double dLon = (lon2 - lon1) * Math.PI / 180;

            double a =
                Math.Sin(dLat / 2) * Math.Sin(dLat / 2) +
                Math.Cos(lat1 * Math.PI / 180) * Math.Cos(lat2 * Math.PI / 180) *
                Math.Sin(dLon / 2) * Math.Sin(dLon / 2);

            double c = 2 * Math.Asin(Math.Sqrt(a));
            return R * c;
        }



        public async Task<ActionResult> viewEntezar_near31(int jobId, int takeCount = 10, int type_gis = 1)
        {
            var model = new FunctionModel
            {
                ID = 1,
                valueokala = new List<valueokala>(),
                detailjob = new List<detailjob>(),
                detailjob1 = new List<detailjob1>()
            };

            // ---------- User ----------
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;

            // ---------- erja_like های کاربر ----------
            var allLikes = await db.erja_like.Where(s => s.del != 1).ToListAsync();

            var erja_like = allLikes
                .GroupBy(t => t.unic)
                .Select(g => g.OrderByDescending(x => x.ID).First())
                .Where(x => x.FK_usr == personal)
                .ToList();

            // ---------- آمار ----------
            foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job))
            {
                model.valueokala.Add(new valueokala
                {
                    ID = (int)it.Key,
                    countentezar = it.Count(x => x.vaziat == 0),
                    countersal = it.Count(x => x.vaziat == 1),
                    countersaltaeed = it.Count(x => x.vaziat == 2)
                });
            }

            model.sumentezar = erja_like.Count(x => x.vaziat == 0);
            model.sumersal = erja_like.Count(x => x.vaziat == 1);
            model.sumtaeed = erja_like.Count(x => x.vaziat == 2);

            var erja_like_entezar = erja_like.Where(x => x.vaziat == 0 && x.FK_job == jobId).ToList();
            if (!erja_like_entezar.Any())
                return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
            double baseLat = 27.2009;
            double baseLng = 60.6691;
            // ---------- GIS : آخرین Batch ----------
            if (type_gis == 1)
            {
                var findusr = db.dbGIS_USR.Where(s => s.FK_usr == personal).FirstOrDefault();
                if (findusr != null)
                {
                    baseLat = (double)findusr.x;
                    baseLng = (double)findusr.y;

                }
            }
            else
            {
                var findusr = db.dbGIS_USR_after.Where(s => s.FK_usr == personal).FirstOrDefault();
                if (findusr != null)
                {
                    baseLat = (double)findusr.mogtasat_x;
                    baseLng = (double)findusr.mogtasat_y;

                }
            }


            db.Database.CommandTimeout = 180; // 3 دقیقه
            var points = await db.Database.SqlQuery<NearPointDto>(@"
    ;WITH MaxBatch AS
    (
        SELECT MAX(FK_dbergharelinsert_6) AS MaxFK
        FROM dbergharelimsertfk1_7_GIS
    )
    SELECT 
        ell.value AS Unic,
        CAST(lat.valueFK_db2 AS FLOAT) AS Lat,
        CAST(lng.valueFK_db2 AS FLOAT) AS Lng
    FROM erja_like_link ell
    INNER JOIN erja_like el ON ell.FK_erja_like = el.ID
    INNER JOIN dbergharelimsertfk1_7_GIS lat
        ON lat.valuunic = ell.value AND lat.FK_db2 = 450
    INNER JOIN dbergharelimsertfk1_7_GIS lng
        ON lng.valuunic = ell.value AND lng.FK_db2 = 451
    CROSS JOIN MaxBatch mb
    WHERE el.FK_usr = @personal
      AND el.vaziat = 0
      AND el.FK_job = @jobId
      AND lat.FK_dbergharelinsert_6 = mb.MaxFK
      AND lng.FK_dbergharelinsert_6 = mb.MaxFK
    ", new SqlParameter("@personal", personal), new SqlParameter("@jobId", jobId)).ToListAsync();

            // ---------- مرتب‌سازی بر اساس نزدیک‌ترین نقطه ----------
            var ordered = points
                .Select(p => new { Point = p, Distance = Haversine1(baseLat, baseLng, p.Lat, p.Lng) })
                .OrderBy(x => x.Distance)
                .Take(takeCount)
                .Select(x => x.Point)
                .ToList();

            var orderedUnics = ordered.Select(x => x.Unic).ToList();

            // ---------- لینک‌ها ----------
            var links = await db.erja_like_link
                .Where(l => orderedUnics.Contains(l.value)
                            && l.FK_erja_like.HasValue
                            && l.erja_like.FK_usr == personal
                            && l.erja_like.vaziat == 0
                            && l.erja_like.FK_job == jobId)
                .OrderByDescending(l => l.ID)
                .ToListAsync();

            var likesDict = erja_like.ToDictionary(x => x.ID, x => x);

            var gro = orderedUnics
                .Select(unic =>
                {
                    var link = links.FirstOrDefault(l => l.value == unic && l.erja_like.FK_usr == personal && l.erja_like.vaziat == 0);
                    if (link == null) return null;
                    if (link.erja_like.FK_job != jobId || link.erja_like.vaziat != 0)
                        return null;
                    return link.erja_like;
                })
                .Where(x => x != null)
                .ToList();

            // ---------- omomi ----------
            var omomis = await db.erja_omomi
                .Where(s => s.FK_job == jobId && s.dargeshavad == 1)
                .ToListAsync();

            var groIds = gro.Select(x => x.ID).ToList();
            var relLinks = links.Where(l => l.FK_erja_like.HasValue && groIds.Contains(l.FK_erja_like.Value)).ToList();
            var unics = relLinks.Select(l => l.value).Distinct().ToList();
            var dbValues = await db.dbergharelimsertfk1_7
                .Where(s => unics.Contains(s.valuunic))
                .OrderByDescending(s => s.ID)
                .ToListAsync();

            // ---------- ساخت مدل ----------
            foreach (var it in gro)
            {
                foreach (var it1 in omomis)
                {
                    string detailname = "";

                    if (it1.vaziat == 1)
                    {
                        var link = relLinks.FirstOrDefault(l => l.FK_omomi == it1.ID && l.FK_erja_like == it.ID);
                        if (link != null)
                            detailname = link.value;
                    }
                    else
                    {
                        var findunicOmomi = omomis.FirstOrDefault(o => o.unic == true && o.FK_gozaresh == it1.FK_gozaresh);
                        if (findunicOmomi != null)
                        {
                            var link = relLinks.FirstOrDefault(l => l.FK_omomi == findunicOmomi.ID && l.FK_erja_like == it.ID);
                            if (link != null)
                            {
                                var val = dbValues.FirstOrDefault(v => v.valuunic == link.value && v.FK_db2 == it1.FK_link);
                                if (val != null)
                                    detailname = val.valueFK_db2;
                            }
                        }
                    }

                    model.detailjob.Add(new detailjob
                    {
                        IDst = it.unic,
                        name = it1.title,
                        detal = detailname
                    });
                }

                model.detailjob1.Add(new detailjob1
                {
                    IDst = it.unic,
                    ID = it.ID,
                    FK_usr = personal,
                    vaziat = 1
                });
            }

            return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
        }

        // ---------- تابع Haversine ----------
        private static double Haversine1(double lat1, double lon1, double lat2, double lon2)
        {
            const double R = 6371; // km
            double dLat = (lat2 - lat1) * Math.PI / 180;
            double dLon = (lon2 - lon1) * Math.PI / 180;

            double a =
                Math.Sin(dLat / 2) * Math.Sin(dLat / 2) +
                Math.Cos(lat1 * Math.PI / 180) * Math.Cos(lat2 * Math.PI / 180) *
                Math.Sin(dLon / 2) * Math.Sin(dLon / 2);

            double c = 2 * Math.Asin(Math.Sqrt(a));
            return R * c;
        }

