        public async Task<ActionResult> viewEntezar(int jobId)
        {
            try
            {
                var model = new FunctionModel
                {
                    ID = 1,
                    valueokala = new List<valueokala>(),
                    detailjob = new List<detailjob>(),
                    detailjob1 = new List<detailjob1>()
                };

                #region User

                var cookieUser = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookieUser == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

                var nationalCode = Utility.Base64.Base64Decode(cookieUser.Value);

                var userId = await db.tbUsers
                    .Where(p => p.usr_NationalCode == nationalCode)
                    .Select(p => (int?)p.usr_ID)
                    .FirstOrDefaultAsync();

                if (!userId.HasValue)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

                int personal = userId.Value;

                #endregion

                #region Latest erja_like per unic - exactly equivalent to old logic

                var latestLikeIds = await db.erja_like
                    .Where(s => s.FK_usr == personal && s.del != 1)
                    .GroupBy(t => t.unic)
                    .Select(g => g.Max(x => x.ID))
                    .ToListAsync();

                var erjaLike = await db.erja_like
                    .Where(x => latestLikeIds.Contains(x.ID))
                    .ToListAsync();

                #endregion

                #region Statistics

                var groupedStats = erjaLike
                    .Where(t => t.FK_job != null)
                    .GroupBy(s => s.FK_job)
                    .Select(it => new valueokala
                    {
                        ID = (int)it.Key,
                        countentezar = it.Count(x => x.vaziat == 0),
                        countersal = it.Count(x => x.vaziat == 1),
                        countersaltaeed = it.Count(x => x.vaziat == 2)
                    })
                    .ToList();

                model.valueokala.AddRange(groupedStats);

                model.sumentezar = erjaLike.Count(x => x.vaziat == 0);
                model.sumersal = erjaLike.Count(x => x.vaziat == 1);
                model.sumtaeed = erjaLike.Count(x => x.vaziat == 2);

                #endregion

                #region Filter waiting likes for selected job

                var erjaLikeEntezar = erjaLike
                    .Where(x => x.vaziat == 0 && x.FK_job == jobId)
                    .ToList();

                if (!erjaLikeEntezar.Any())
                    return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);

                var erjaLikeEntezarIds = erjaLikeEntezar.Select(x => x.ID).ToList();

                #endregion

                #region Links - equivalent to old logic but optimized

                var links = await db.erja_like_link
                    .Where(l =>
                        l.FK_erja_like.HasValue &&
                        erjaLikeEntezarIds.Contains(l.FK_erja_like.Value) &&
                        l.erja_like.FK_usr == personal &&
                        l.erja_like.vaziat == 0 &&
                        l.erja_like.FK_job == jobId)
                    .OrderByDescending(l => l.ID)
                    .ToListAsync();

                #endregion

                #region gro - exactly as old behavior, but based on IDs for reliability

                var groIds = links
                    .Where(l => l.erja_like != null)
                    .Select(l => l.erja_like.ID)
                    .Distinct()
                    .ToList();

                var gro = erjaLikeEntezar
                    .Where(x => groIds.Contains(x.ID))
                    .ToList();

                if (!gro.Any())
                    return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);

                #endregion

                #region Omomi

                var omomis = await db.erja_omomi
                    .Where(s => s.FK_job == jobId && s.dargeshavad == 1)
                    .ToListAsync();

                #endregion

                #region Related links and db values

                var relLinks = links
                    .Where(l => l.FK_erja_like.HasValue && groIds.Contains(l.FK_erja_like.Value))
                    .ToList();

                var unics = relLinks
                    .Select(l => l.value)
                    .Where(v => v != null)
                    .Distinct()
                    .ToList();

                var dbValues = await db.dbergharelimsertfk1_7
                    .Where(s => unics.Contains(s.valuunic))
                    .OrderByDescending(s => s.ID)
                    .ToListAsync();

                #endregion

                #region Lookups for high performance while preserving old behavior

                var relLinksLookup = relLinks
                    .ToLookup(l => Tuple.Create(l.FK_omomi, l.FK_erja_like));

                var unicOmomiLookup = omomis
                    .Where(o => o.unic == true && o.FK_gozaresh != null)
                    .GroupBy(o => o.FK_gozaresh)
                    .ToDictionary(g => g.Key, g => g.First());

                var dbValuesLookup = dbValues
                    .ToLookup(v => Tuple.Create(v.valuunic, v.FK_db2));

                #endregion

                #region Build model

                foreach (var it in gro)
                {
                    foreach (var it1 in omomis)
                    {
                        string detailname = "";

                        if (it1.vaziat == 1)
                        {
                            var link = relLinksLookup[Tuple.Create((long?)it1.ID, (long?)it.ID)].FirstOrDefault();
                            if (link != null)
                                detailname = link.value;
                        }
                        else
                        {
                            erja_omomi findunicOmomi = null;

                            if (it1.FK_gozaresh != null)
                                unicOmomiLookup.TryGetValue(it1.FK_gozaresh, out findunicOmomi);

                            if (findunicOmomi != null)
                            {
                                var link = relLinksLookup[Tuple.Create((long?)findunicOmomi.ID, (long?)it.ID)].FirstOrDefault();
                                if (link != null)
                                {
                                    var val = dbValuesLookup[Tuple.Create(link.value, it1.FK_link)].FirstOrDefault();
                                    if (val != null)
                                        detailname = val.valueFK_db2;
                                }
                            }
                        }

                        model.detailjob.Add(new detailjob
                        {
                            IDst = it.unic,
                            name = it1.title,
                            detal = detailname
                        });
                    }

                    model.detailjob1.Add(new detailjob1
                    {
                        IDst = it.unic,
                        ID = it.ID,
                        FK_usr = personal,
                        vaziat = 1
                    });
                }

                #endregion

                return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }

        public async Task<ActionResult> viewEntezar_ed(int jobId)
        {
            try
            {
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

                int personal = user.usr_ID;

                // افزایش زمان اجرای SQL
                db.Database.CommandTimeout = 6000;

                // SQL مستقیم برای دریافت داده‌ها
                string sql = @"
SELECT 
    e.ID AS erjaID,
    e.unic AS unicErja,
    e.vaziat,
    o.ID AS omomiID,
    o.title AS omomiTitle,
    l.value AS linkValue,
    d.valueFK_db2 AS dbValue
FROM erja_like e
LEFT JOIN erja_like_link l ON l.FK_erja_like = e.ID
LEFT JOIN erja_omomi o ON o.FK_job = e.FK_job AND o.dargeshavad = 1
LEFT JOIN dbergharelimsertfk1_7 d ON d.valuunic = l.value AND d.FK_db2 = o.FK_link
WHERE e.FK_usr = @personal AND e.FK_job = @jobId AND e.del != 1
ORDER BY e.ID DESC
";

                var results = await db.Database.SqlQuery<ErjaSqlResult>(
                    sql,
                    new SqlParameter("@personal", personal),
                    new SqlParameter("@jobId", jobId)
                ).ToListAsync();

                // ساخت مدل
                var model = new FunctionModel
                {
                    ID = 1,
                    valueokala = results.GroupBy(x => x.erjaID).Select(g => new valueokala
                    {
                        ID = g.Key,
                        countentezar = g.Count(x => x.vaziat == 0),
                        countersal = g.Count(x => x.vaziat == 1),
                        countersaltaeed = g.Count(x => x.vaziat == 2)
                    }).ToList(),

                    sumentezar = results.Count(x => x.vaziat == 0),
                    sumersal = results.Count(x => x.vaziat == 1),
                    sumtaeed = results.Count(x => x.vaziat == 2),

                    detailjob = results.Select(x => new detailjob
                    {
                        IDst = x.unicErja.ToString(), // این هم اصلاح شد
                        name = x.omomiTitle,
                        detal = x.dbValue ?? x.linkValue ?? ""
                    }).ToList(),

                    detailjob1 = results.Select(x => new detailjob1
                    {
                        IDst = x.unicErja.ToString(), // این هم اصلاح شد
                        ID = x.erjaID,
                        FK_usr = personal,
                        vaziat = 1
                    }).Distinct().ToList(),
                };

                return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
            }
            catch (Exception exx)
            {
                return Content(exx.Message);
            }
        }

