        // ---------- تابع Haversine ----------
        private static double Haversine3(double lat1, double lon1, double lat2, double lon2)
        {
            const double R = 6371; // km
            double dLat = (lat2 - lat1) * Math.PI / 180;
            double dLon = (lon2 - lon1) * Math.PI / 180;

            double a =
                Math.Sin(dLat / 2) * Math.Sin(dLat / 2) +
                Math.Cos(lat1 * Math.PI / 180) * Math.Cos(lat2 * Math.PI / 180) *
                Math.Sin(dLon / 2) * Math.Sin(dLon / 2);

            double c = 2 * Math.Asin(Math.Sqrt(a));
            return R * c;
        }
        private static double Haversine2(double lat1, double lon1, double lat2, double lon2)
        {
            const double R = 6371000.0; // m

            double dLat = (lat2 - lat1) * Math.PI / 180.0;
            double dLon = (lon2 - lon1) * Math.PI / 180.0;

            lat1 *= Math.PI / 180.0;
            lat2 *= Math.PI / 180.0;

            double a =
                Math.Pow(Math.Sin(dLat / 2), 2) +
                Math.Cos(lat1) * Math.Cos(lat2) *
                Math.Pow(Math.Sin(dLon / 2), 2);

            double c = 2 * Math.Atan2(Math.Sqrt(a), Math.Sqrt(1 - a));

            return R * c;
        }
        private static async Task<double> GetCurrentTemperatureAsync(double lat, double lng)
        {
            try
            {
                using (var client = new HttpClient())
                {
                    client.DefaultRequestHeaders.Add("User-Agent", "C# Weather Routing Service");

                    string url = $"https://api.open-meteo.com/v1/forecast?latitude={lat.ToString(CultureInfo.InvariantCulture)}&longitude={lng.ToString(CultureInfo.InvariantCulture)}&current_weather=true";
                    var response = await client.GetStringAsync(url);

                    using (JsonDocument doc = JsonDocument.Parse(response))
                    {
                        if (doc.RootElement.TryGetProperty("current_weather", out JsonElement currentWeather) &&
                            currentWeather.TryGetProperty("temperature", out JsonElement temperatureElement))
                        {
                            return temperatureElement.GetDouble();
                        }
                    }

                    return 22.0;
                }
            }
            catch (Exception ex1)
            {
                string ex2 = ex1.Message;
                return 22.0;
            }
        }

        // تابع محاسبه هزینه تلفیقی (ترکیب فاصله و دما بر اساس فصل جاری)
        private static double CalculateCost(double distanceInMeters, double temp, bool isColdSeason)
        {
            // تبدیل مسافت به کیلومتر برای هم‌مقیاس کردن با درجه دما
            double distanceCost = distanceInMeters / 1000.0;

            double tempCost = 0;
            if (isColdSeason)
            {
                // در فصل سرد: دمای پایین‌تر جریمه بیشتری دارد (حرکت به سمت جاهای گرم‌تر ترجیح داده می‌شود)
                tempCost = (40.0 - temp);
            }
            else
            {
                // در فصل گرم: دمای بالاتر جریمه بیشتری دارد (حرکت به سمت جاهای خنک‌تر ترجیح داده می‌شود)
                tempCost = temp;
            }

            // وزن تاثیر پارامتر دما (هرچه بزرگ‌تر باشد، آب‌وهوا اهمیت بیشتری نسبت به مسافت پیدا می‌کند)
            double weightTemp = 1.5;

            return distanceCost + (weightTemp * tempCost);
        }
        public async Task<ActionResult> viewEntezar_near3121(int jobId, int takeCount = 10, int type_gis = 1, double? lat = null, double? lng = null)
        {
            try
            {
                var model = new FunctionModel
                {
                    ID = 1,
                    valueokala = new List<valueokala>(),
                    detailjob = new List<detailjob>(),
                    detailjob1 = new List<detailjob1>()
                };

                // ---------- User ----------
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

                int personal = user.usr_ID;

                // ---------- erja_like های کاربر ----------
                var allLikes = await db.erja_like.Where(s => s.FK_usr == personal && s.del != 1).ToListAsync();

                var erja_like = allLikes
                    .GroupBy(t => t.unic)
                    .Select(g => g.OrderByDescending(x => x.ID).First())
                    .Where(x => x.FK_usr == personal)
                    .ToList();

                // ---------- آمار ----------
                foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job))
                {
                    model.valueokala.Add(new valueokala
                    {
                        ID = (int)it.Key,
                        countentezar = it.Count(x => x.vaziat == 0),
                        countersal = it.Count(x => x.vaziat == 1),
                        countersaltaeed = it.Count(x => x.vaziat == 2)
                    });
                }

                model.sumentezar = erja_like.Count(x => x.vaziat == 0);
                model.sumersal = erja_like.Count(x => x.vaziat == 1);
                model.sumtaeed = erja_like.Count(x => x.vaziat == 2);

                var erja_like_entezar = erja_like.Where(x => x.vaziat == 0 && x.FK_job == jobId).ToList();
                if (!erja_like_entezar.Any())
                    return View("~/Areas/Setting/Views/Orders/viewEntezar_near312.cshtml", model);

                // ---------- Base coordinates ----------
                double baseLat = 27.2009;
                double baseLng = 60.6691;

                if (type_gis == 1)
                {
                    var findusr = db.dbGIS_USR.FirstOrDefault(s => s.FK_usr == personal);
                    if (findusr != null)
                    {
                        baseLat = (double)findusr.x;
                        baseLng = (double)findusr.y;
                    }
                }
                else if (type_gis == 3 && lat.HasValue && lng.HasValue)
                {
                    baseLat = lat.Value;
                    baseLng = lng.Value;
                }
                else
                {
                    var findusr = db.dbGIS_USR_after.FirstOrDefault(s => s.FK_usr == personal);
                    if (findusr != null)
                    {
                        baseLat = (double)findusr.mogtasat_x;
                        baseLng = (double)findusr.mogtasat_y;
                    }
                }

                db.Database.CommandTimeout = 600;

                // ---------- دریافت نقاط ----------
                var points = await db.Database.SqlQuery<NearPointDto>(@"
;WITH MaxBatch AS
(
    SELECT MAX(FK_dbergharelinsert_6) AS MaxFK
    FROM dbergharelimsertfk1_7_GIS
)
SELECT 
    ell.value AS Unic,
    CAST(lat.valueFK_db2 AS FLOAT) AS Lat,
    CAST(lng.valueFK_db2 AS FLOAT) AS Lng
FROM erja_like_link ell
INNER JOIN erja_like el ON ell.FK_erja_like = el.ID
INNER JOIN dbergharelimsertfk1_7_GIS lat
    ON lat.valuunic = ell.value AND lat.FK_db2 = 450
INNER JOIN dbergharelimsertfk1_7_GIS lng
    ON lng.valuunic = ell.value AND lng.FK_db2 = 451
CROSS JOIN MaxBatch mb
WHERE el.FK_usr = @personal
  AND el.vaziat = 0
  AND el.FK_job = @jobId
  AND lat.FK_dbergharelinsert_6 = mb.MaxFK
  AND lng.FK_dbergharelinsert_6 = mb.MaxFK
", new SqlParameter("@personal", personal),
                   new SqlParameter("@jobId", jobId)).ToListAsync();

                // فیلتر کردن و یکتا سازی نقاط
                points = points
                    .Where(p => !string.IsNullOrEmpty(p.Unic))
                    .GroupBy(p => p.Unic)
                    .Select(g => g.First())
                    .ToList();

                // ---------- واکشی پویای دمای هوا به صورت موازی برای سرعت بیشتر ----------
                var tempTasks = points.Select(async p =>
                {
                    double temp = await GetCurrentTemperatureAsync(p.Lat, p.Lng);
                    return new { Point = p, Temperature = temp };
                });
                var pointsWithTemp = await Task.WhenAll(tempTasks);

                // تشخیص فصل جاری سیستم جهت اعمال استراتژی بهینه‌سازی
                int currentMonth = DateTime.Now.Month;
                // ماه‌های نوامبر تا آوریل (آبان تا فروردین) به عنوان فصل سرد در نظر گرفته می‌شوند
                bool isColdSeason = (currentMonth >= 11 || currentMonth <= 4);

                // ---------- Nearest Neighbor بر اساس هزینه ترکیبی (مکان + آب‌وهوا) ----------
                var remaining = pointsWithTemp.ToList();
                var tspOrdered = new List<NearPointDto>();
                double curLat = baseLat;
                double curLng = baseLng;

                while (remaining.Any())
                {
                    var nextBest = remaining
                        .Select(p => new
                        {
                            Item = p,
                            Cost = CalculateCost(Haversine2(curLat, curLng, p.Point.Lat, p.Point.Lng), p.Temperature, isColdSeason)
                        })
                        .OrderBy(x => x.Cost)
                        .First();

                    tspOrdered.Add(nextBest.Item.Point);
                    remaining.Remove(nextBest.Item);

                    curLat = nextBest.Item.Point.Lat;
                    curLng = nextBest.Item.Point.Lng;
                }

                tspOrdered = tspOrdered.Take(takeCount).ToList();
                var orderedUnics = tspOrdered.Select(x => x.Unic).ToList();

                // ---------- دیکشنری مختصات ----------
                var pointDict = tspOrdered.ToDictionary(x => x.Unic, x => x);
                var indexDict = tspOrdered
                    .Select((p, i) => new { p.Unic, Index = i })
                    .ToDictionary(x => x.Unic, x => x.Index);

                // ---------- لینک‌ها ----------
                var links = await db.erja_like_link
                    .Where(l => orderedUnics.Contains(l.value)
                                && l.FK_erja_like.HasValue
                                && l.erja_like.FK_usr == personal
                                && l.erja_like.vaziat == 0
                                && l.erja_like.FK_job == jobId)
                    .OrderByDescending(l => l.ID)
                    .ToListAsync();

                var gro = orderedUnics
                    .Select(unic =>
                    {
                        var link = links.FirstOrDefault(l => l.value == unic && l.erja_like.FK_usr == personal && l.erja_like.vaziat == 0);
                        if (link == null) return null;
                        if (link.erja_like.FK_job != jobId || link.erja_like.vaziat != 0)
                            return null;
                        return link.erja_like;
                    })
                    .Where(x => x != null)
                    .ToList();

                // ---------- omomi ----------
                var omomis = await db.erja_omomi
                    .Where(s => s.FK_job == jobId && s.dargeshavad == 1)
                    .ToListAsync();

                var groIds = gro.Select(x => x.ID).ToList();
                var relLinks = links.Where(l => l.FK_erja_like.HasValue && groIds.Contains(l.FK_erja_like.Value)).ToList();
                var unics = relLinks.Select(l => l.value).Distinct().ToList();

                var dbValues = await db.dbergharelimsertfk1_7
                    .Where(s => unics.Contains(s.valuunic))
                    .OrderByDescending(s => s.ID)
                    .ToListAsync();

                // ---------- ساخت مدل خروجی ----------
                foreach (var it in gro)
                {
                    var linkw = relLinks.FirstOrDefault(l => l.FK_erja_like == it.ID);
                    if (linkw == null) continue;

                    if (!pointDict.TryGetValue(linkw.value, out var curPoint))
                        continue;

                    int idx = indexDict[linkw.value];
                    NearPointDto prevPoint = idx > 0 ? tspOrdered[idx - 1] : null;

                    foreach (var it1 in omomis)
                    {
                        string detailname = "";

                        if (it1.vaziat == 1)
                        {
                            var link = relLinks.FirstOrDefault(l => l.FK_omomi == it1.ID && l.FK_erja_like == it.ID);
                            if (link != null)
                                detailname = link.value;
                        }
                        else
                        {
                            var findunicOmomi = omomis.FirstOrDefault(o => o.unic == true && o.FK_gozaresh == it1.FK_gozaresh);
                            if (findunicOmomi != null)
                            {
                                var link = relLinks.FirstOrDefault(l => l.FK_omomi == findunicOmomi.ID && l.FK_erja_like == it.ID);
                                if (link != null)
                                {
                                    var val = dbValues.FirstOrDefault(v => v.valuunic == link.value && v.FK_db2 == it1.FK_link);
                                    if (val != null)
                                        detailname = val.valueFK_db2;
                                }
                            }
                        }

                        model.detailjob.Add(new detailjob
                        {
                            IDst = it.unic,
                            name = it1.title,
                            detal = detailname,

                            Lat = curPoint.Lat,
                            Lng = curPoint.Lng,

                            PrevLat = prevPoint != null ? prevPoint.Lat : baseLat,
                            PrevLng = prevPoint != null ? prevPoint.Lng : baseLng
                        });
                    }

                    model.detailjob1.Add(new detailjob1
                    {
                        IDst = it.unic,
                        ID = it.ID,
                        FK_usr = personal,
                        vaziat = 1
                    });
                }

                return View("~/Areas/Setting/Views/Orders/viewEntezar_near312.cshtml", model);
            }
            catch (Exception exx)
            {
                return Content(exx.Message);
            }
        }
