            model.sumersal = erja_like.Count(x => x.vaziat == 1);
            model.sumtaeed = erja_like.Count(x => x.vaziat == 2);

            var erja_like_entezar = erja_like.Where(x => x.vaziat == 0 && x.FK_job == jobId).ToList();
            if (!erja_like_entezar.Any())
                return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);

            // ---------- Base coordinates ----------
            double baseLat = 27.2009;
            double baseLng = 60.6691;

            if (type_gis == 1)
            {
                var findusr = db.dbGIS_USR.Where(s => s.FK_usr == personal).FirstOrDefault();
                if (findusr != null)
                {
                    baseLat = (double)findusr.x;
                    baseLng = (double)findusr.y;
                }
            }
            else
            {
                var findusr = db.dbGIS_USR_after.Where(s => s.FK_usr == personal).FirstOrDefault();
                if (findusr != null)
                {
                    baseLat = (double)findusr.mogtasat_x;
                    baseLng = (double)findusr.mogtasat_y;
                }
            }

            db.Database.CommandTimeout = 600; // 3 دقیقه

            // ---------- دریافت نقاط ----------
            var points = await db.Database.SqlQuery<NearPointDto>(@"
    ;WITH MaxBatch AS
    (
        SELECT MAX(FK_dbergharelinsert_6) AS MaxFK
        FROM dbergharelimsertfk1_7_GIS
    )
    SELECT 
        ell.value AS Unic,
        CAST(lat.valueFK_db2 AS FLOAT) AS Lat,
        CAST(lng.valueFK_db2 AS FLOAT) AS Lng
    FROM erja_like_link ell
    INNER JOIN erja_like el ON ell.FK_erja_like = el.ID
    INNER JOIN dbergharelimsertfk1_7_GIS lat
        ON lat.valuunic = ell.value AND lat.FK_db2 = 450
    INNER JOIN dbergharelimsertfk1_7_GIS lng
        ON lng.valuunic = ell.value AND lng.FK_db2 = 451
    CROSS JOIN MaxBatch mb
    WHERE el.FK_usr = @personal
      AND el.vaziat = 0
      AND el.FK_job = @jobId
      AND lat.FK_dbergharelinsert_6 = mb.MaxFK
      AND lng.FK_dbergharelinsert_6 = mb.MaxFK
    ", new SqlParameter("@personal", personal), new SqlParameter("@jobId", jobId)).ToListAsync();

            // ---------- TSP greedy ----------
            var remaining = points.ToList();
            var tspOrdered = new List<NearPointDto>();
            double curLat = baseLat;
            double curLng = baseLng;

            while (remaining.Any())
            {
                var next = remaining
                    .Select(p => new { Point = p, Dist = Haversine1(curLat, curLng, p.Lat, p.Lng) })
                    .OrderBy(x => x.Dist)
                    .First().Point;

                tspOrdered.Add(next);
                remaining.Remove(next);

                curLat = next.Lat;
                curLng = next.Lng;
            }

            tspOrdered = tspOrdered.Take(takeCount).ToList();

            // ---------- 2-opt optimization ----------
            bool improved = true;
            while (improved)
            {
                improved = false;
                for (int i = 0; i < tspOrdered.Count - 1; i++)
                {
                    for (int j = i + 1; j < tspOrdered.Count; j++)
                    {
                        double oldDist = Haversine13(
                                            i == 0 ? baseLat : tspOrdered[i - 1].Lat,
                                            i == 0 ? baseLng : tspOrdered[i - 1].Lng,
                                            tspOrdered[i].Lat,
                                            tspOrdered[i].Lng)
                                        + Haversine13(
                                            tspOrdered[j].Lat,
                                            tspOrdered[j].Lng,
                                            j + 1 < tspOrdered.Count ? tspOrdered[j + 1].Lat : tspOrdered[j].Lat,
                                            j + 1 < tspOrdered.Count ? tspOrdered[j + 1].Lng : tspOrdered[j].Lng);

                        double newDist = Haversine13(
                                            i == 0 ? baseLat : tspOrdered[i - 1].Lat,
                                            i == 0 ? baseLng : tspOrdered[i - 1].Lng,
                                            tspOrdered[j].Lat,
                                            tspOrdered[j].Lng)
                                        + Haversine13(
                                            tspOrdered[i].Lat,
                                            tspOrdered[i].Lng,
                                            j + 1 < tspOrdered.Count ? tspOrdered[j + 1].Lat : tspOrdered[j].Lat,
                                            j + 1 < tspOrdered.Count ? tspOrdered[j + 1].Lng : tspOrdered[j].Lng);

                        if (newDist < oldDist)
                        {
                            tspOrdered.Reverse(i, j - i + 1);
                            improved = true;
                        }
                    }
                }
            }

            var orderedUnics = tspOrdered.Select(x => x.Unic).ToList();

