                int personal = user.usr_ID;

                // ---------- erja_like های کاربر ----------
                var allLikes = await db.erja_like.Where(s => s.del != 1).ToListAsync();
                var erja_like = allLikes
                    .GroupBy(t => t.unic)
                    .Select(g => g.OrderByDescending(x => x.ID).First())
                    .Where(x => x.FK_usr == personal)
                    .ToList();

                // ---------- آمار ----------
                foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job))
                {
                    model.valueokala.Add(new valueokala
                    {
                        ID = (int)it.Key,
                        countentezar = it.Count(x => x.vaziat == 0),
                        countersal = it.Count(x => x.vaziat == 1),
                        countersaltaeed = it.Count(x => x.vaziat == 2)
                    });
                }

                model.sumentezar = erja_like.Count(x => x.vaziat == 0);
                model.sumersal = erja_like.Count(x => x.vaziat == 1);
                model.sumtaeed = erja_like.Count(x => x.vaziat == 2);

                // ---------- GIS : آخرین Batch با Spatial ----------
                double baseLat = 29.4988;
                double baseLng = 60.8689;

                var nearPoints = db.Database.SqlQuery<NearPointDto>(@"
DECLARE @Start GEOGRAPHY = GEOGRAPHY::Point(@lat0, @lng0, 4326);
DECLARE @TakeCount INT = @take;

;WITH MaxBatch AS
(
    SELECT MAX(FK_dbergharelinsert_6) AS MaxFK
    FROM dbergharelimsertfk1_7_GIS
),
LastPoints AS
(
    SELECT *
    FROM dbergharelimsertfk1_7_GIS
    WHERE FK_dbergharelinsert_6 = (SELECT MaxFK FROM MaxBatch)
      AND FK_db2 IN (450,451)
)
SELECT TOP (@TakeCount)
    valuunic AS Unic,
    CAST(valueFK_db2 AS FLOAT) AS Lat,
    CAST(valueFK_db2 AS FLOAT) AS Lng,
    Geo.STDistance(@Start) AS DistanceM
FROM LastPoints
ORDER BY DistanceM ASC
",
                    new SqlParameter("@lat0", baseLat),
                    new SqlParameter("@lng0", baseLng),
                    new SqlParameter("@take", takeCount)
                ).ToList();

                var orderedUnics = nearPoints.Select(x => x.Unic).ToList();

                // ---------- erja_like_link ----------
                var links = await db.erja_like_link
                    .Where(l => orderedUnics.Contains(l.value) && l.FK_erja_like.HasValue)
                    .OrderByDescending(l => l.ID)
                    .ToListAsync();

                var likesDict = erja_like.ToDictionary(x => x.ID, x => x);

                // ---------- erja_like به ترتیب نزدیک‌ترین نقاط ----------
                var gro = orderedUnics
                    .Select(unic =>
                    {
                        var link = links.FirstOrDefault(l => l.value == unic);
                        if (link == null) return null;

                        if (!likesDict.TryGetValue(link.FK_erja_like.Value, out var like))
                            return null;

                        if (like.FK_job != jobId || like.vaziat != 0)
                            return null;

                        return like;
                    })
                    .Where(x => x != null)
                    .ToList();

                // ---------- omomi ----------
                var omomis = await db.erja_omomi
                    .Where(s => s.FK_job == jobId && s.dargeshavad == 1)
                    .ToListAsync();

                var groIds = gro.Select(x => x.ID).ToList();
                var relLinks = links
                    .Where(l => l.FK_erja_like.HasValue && groIds.Contains(l.FK_erja_like.Value))
                    .ToList();

                var unicsDb = relLinks.Select(l => l.value).Distinct().ToList();

                var dbValues = await db.dbergharelimsertfk1_7
                    .Where(s => unicsDb.Contains(s.valuunic))
                    .OrderByDescending(s => s.ID)
                    .ToListAsync();

                // ---------- ساخت مدل ----------
                foreach (var it in gro)
                {
                    foreach (var it1 in omomis)
                    {
                        string detailname = "";

                        if (it1.vaziat == 1)
                        {
                            var link = relLinks.FirstOrDefault(l =>
                                l.FK_omomi == it1.ID && l.FK_erja_like == it.ID);

                            if (link != null)
                                detailname = link.value;
                        }
                        else
                        {
                            var findunicOmomi = omomis.FirstOrDefault(o =>
                                o.unic == true && o.FK_gozaresh == it1.FK_gozaresh);

                            if (findunicOmomi != null)
                            {
                                var link = relLinks.FirstOrDefault(l =>
                                    l.FK_omomi == findunicOmomi.ID && l.FK_erja_like == it.ID);

                                if (link != null)
                                {
                                    var val = dbValues.FirstOrDefault(v =>
                                        v.valuunic == link.value && v.FK_db2 == it1.FK_link);

                                    if (val != null)
                                        detailname = val.valueFK_db2;
                                }
                            }
                        }

                        model.detailjob.Add(new detailjob
                        {
                            IDst = it.unic,
                            name = it1.title,
                            detal = detailname
                        });
                    }

                    model.detailjob1.Add(new detailjob1
                    {
                        IDst = it.unic,
                        ID = it.ID,
                        FK_usr = personal,
                        vaziat = 1
                    });
                }

                return View("~/Areas/Setting/Views/Orders/viewEntezar.cshtml", model);
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }
        public async Task<ActionResult> viewEntezar22(int jobId)
        {
            var model = new FunctionModel
            {
                ID = 1,
                valueokala1 = new List<valueokala1>(),
                detailjob = new List<detailjob>(),
                detailjob1 = new List<detailjob1>()
            };

            // ===== Cookie =====
            var cookie = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie.Value);

            // ===== User =====
            var user = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            var personal = user.usr_ID;

            // ===== FAST SQL QUERY for erja_like summary =====
            var summaryQuery = @"
;WITH LastPerUnic AS
(
    SELECT *,
           ROW_NUMBER() OVER (PARTITION BY unic ORDER BY ID DESC) AS rn
    FROM erja_like
    WHERE (del IS NULL OR del <> 1)
)
SELECT
    CAST(FK_job AS BIGINT) AS JobId,
   CAST(SUM(CASE WHEN vaziat = 0 THEN 1 ELSE 0 END) AS BIGINT) AS CountEntezar,
    CAST(SUM(CASE WHEN vaziat = 1 THEN 1 ELSE 0 END) AS BIGINT) AS CountErsal,
    CAST(SUM(CASE WHEN vaziat = 2 THEN 1 ELSE 0 END) AS BIGINT) AS CountTaee
FROM LastPerUnic
WHERE rn = 1
GROUP BY FK_job";

            var summaries = await db.Database.SqlQuery<ErjaLikeSummaryDto>(summaryQuery).ToListAsync();

            // Fill valueokala
            foreach (var s in summaries)
            {
                model.valueokala1.Add(new valueokala1
                {
                    ID = s.JobId,
                    countentezar = s.CountEntezar,
                    countersal = s.CountErsal,
                    countersaltaeed = s.CountTaeed
                });
            }

            model.sumentezar = summaries.Sum(x => x.CountEntezar);
            model.sumersal = summaries.Sum(x => x.CountErsal);
            model.sumtaeed = summaries.Sum(x => x.CountTaeed);

            // ===== Fetch detailjob and detailjob1 in ONE QUERY using JOIN =====
            var detailQuery = @"
SELECT l.unic AS IDst, o.title AS Name, l.ID AS LikeID, l.FK_usr, o.vaziat,
       ol.value AS DetailName, o.ID AS OmomiID
FROM erja_like l
INNER JOIN erja_omomi o ON o.FK_job = l.FK_job
LEFT JOIN erja_like_link ol ON ol.FK_erja_like = l.ID AND ol.FK_omomi = o.ID
WHERE l.FK_job = @jobId AND l.vaziat = 0 AND (l.del IS NULL OR l.del <> 1)";

            var details = await db.Database.SqlQuery<ErjaDetailDto>(
                detailQuery, new SqlParameter("@jobId", jobId)).ToListAsync();

            foreach (var d in details)
            {
                model.detailjob.Add(new detailjob
                {
                    IDst = d.IDst.ToString(),
                    name = d.Name,
                    detal = d.DetailName
                });

                model.detailjob1.Add(new detailjob1
                {
                    IDst = d.IDst.ToString(),
                    ID = d.LikeID,
                    FK_usr = d.FK_usr,
                    vaziat = d.vaziat
                });
            }

            return View("~/Areas/Setting/Views/Orders/viewEntezar22.cshtml", model);
        }

        // ===== DTOs for optimized query =====
        public class ErjaLikeSummaryDto
        {
            public long JobId { get; set; }
            public long CountEntezar { get; set; }
            public long CountErsal { get; set; }
            public long CountTaeed { get; set; }
        }

        public class ErjaDetailDto
        {
            public string IDst { get; set; }
            public string Name { get; set; }
            public long LikeID { get; set; }
            public int FK_usr { get; set; }
            public int vaziat { get; set; }
            public string DetailName { get; set; }
            public long OmomiID { get; set; }
        }
