        public async Task<ActionResult> viewEntezar_end(int jobId)
        {
            // ایجاد یک مدل FunctionModel
            // ایجاد یک مدل FunctionModel
            var model = new FunctionModel
            {
                ID = 1,
                valueokala = new List<valueokala>(),
                detailjob = new List<detailjob>(),
                detailjob1 = new List<detailjob1>()


            };
            int count = 0;
            int countersal = 0;
            int countentezar = 0;
            int countersaltaeed = 0;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");
            int personal = user.usr_ID;
            var findlik = await db.erja_like.Where(s => s.FK_usr == personal && s.del != 1).ToListAsync();

            var findunicgroup = findlik.Where(s => s.del != 1).GroupBy(t => t.unic).ToList();
            List<erja_like> erja_like = new List<erja_like>();
            foreach (var it in findunicgroup)
            {
                var findusr = findlik.Where(s => s.unic == it.Key).OrderByDescending(t => t.ID).FirstOrDefault();
                if (findusr.FK_usr == personal)
                {
                    erja_like.Add(findusr);
                }
            }
            long sumentezar = 0;
            long sumersal = 0;
            long sumtaeed = 0;

            foreach (var it in erja_like.Where(t => t.FK_job != null).GroupBy(s => s.FK_job).ToList())
            {
                model.valueokala.Add(new valueokala
                {
                    ID = (int)it.Key,
                    count = count,
                    countentezar = erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 0).Count(),
                    countersal = erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 1).Count(),
                    countersaltaeed = erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 2).Count(),
                });
                sumentezar += erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 0).Count();
                sumersal += erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 1).Count();
                sumtaeed += erja_like.Where(s => s.FK_job == it.Key && s.vaziat == 2).Count();

            }
            model.sumtaeed = sumtaeed;
            model.sumentezar = sumentezar;
            model.sumersal = sumersal;
            var gro = erja_like.Where(t => t.FK_job == jobId && t.vaziat == 0).ToList();
            foreach (var it in gro)
            {
                var fooo = db.erja_omomi.Where(s => s.FK_job == it.FK_job && s.dargeshavad == 1).ToList();
                foreach (var it1 in fooo)
                {
                    string name = it1.title;
                    string ID_ID = "";
                    string detailname = "";
                    if (it1.vaziat == 1)
                    {
                        var fidname = db.erja_like_link.Where(s => s.FK_omomi == it1.ID && s.FK_erja_like == it.ID).OrderByDescending(t => t.ID).FirstOrDefault();
                        if (fidname != null)
                        {

                            detailname = fidname.value;
                            ID_ID = fidname.erja_like.unic;
                        }

                    }
                    else if (it1.vaziat == 0)
                    {
                        string unic = "";
                        var findunic = db.erja_omomi.Where(s => s.unic == true && s.FK_gozaresh == it1.FK_gozaresh && s.FK_job == jobId).OrderByDescending(t => t.ID).FirstOrDefault();
                        if (findunic != null)
                        {
                            var fidname = db.erja_like_link.Where(s => s.FK_omomi == findunic.ID && s.FK_erja_like == it.ID).OrderByDescending(t => t.ID).FirstOrDefault();
                            if (fidname != null)
                            {
                                unic = fidname.value;
                                ID_ID = fidname.value;

                                var findvalue = db.dbergharelimsertfk1_7.Where(s => s.valuunic == unic && s.FK_db2 == it1.FK_link).OrderByDescending(t => t.ID).FirstOrDefault();
                                if (findvalue != null)
                                {
