        public ActionResult ImportExcel_safhesefr(HttpPostedFileBase MyExcelStream)
        {
            if (MyExcelStream != null)
            {

                string Message = GetDataFromExcel_safhesefr(MyExcelStream);

                return Content(Message);

            }
            else
            {
                return Content("فایل بطور صحیح بارگذاری نشده است");

            }

        }




        public string GetDataFromExcel_safhesefr(HttpPostedFileBase MyExcelStream)
        {
            try
            {
                using (var db = new SaabEntities())
                {
                    ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
                    using (var package = new ExcelPackage(MyExcelStream.InputStream))
                    {
                        var worksheet = package.Workbook.Worksheets[0];

                        int rowCount = worksheet.Dimension.End.Row;
                        int saved = 0;

                        for (int row = 2; row <= rowCount; row++)
                        {
                            string name = worksheet.Cells[row, 1].Text?.Trim();
                            string codStr = worksheet.Cells[row, 2].Text?.Trim();

                            if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(codStr))
                                continue;

                            long cod;
                            if (!long.TryParse(codStr, out cod))
                                continue;


                            var obj = new countnero_1218_0
                            {
                                name = name,
                                cod = cod,
                                active = 1
                            };

                            db.countnero_1218_0.Add(obj);
                            saved++;
                        }

                        db.SaveChanges();
                        return $"تعداد {saved} ردیف با موفقیت ثبت شد.";
                    }
                }
            }
            catch (Exception ex)
            {
                return "خطا در فرآیند ذخیره: " + ex.Message;
            }
        }

