                {
                    ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
                    var ws = package.Workbook.Worksheets.First();
                    int rows = ws.Dimension.End.Row;
                    int saved = 0;

                    for (int r = 2; r <= rows; r++)
                    {
                        string namcity = ws.Cells[r, 1].Text?.Trim();
                        string mantaghej = ws.Cells[r, 2].Text?.Trim();
                        string kodmantagehStr = ws.Cells[r, 3].Text?.Trim();
                        string kodsamanehStr = ws.Cells[r, 4].Text?.Trim();


                        if (string.IsNullOrWhiteSpace(namcity) ||
                            string.IsNullOrWhiteSpace(mantaghej) ||
                            string.IsNullOrWhiteSpace(kodmantagehStr) ||
                            string.IsNullOrWhiteSpace(kodsamanehStr))
                            continue;


                        if (!long.TryParse(kodmantagehStr, out long kodmantageh))
                            continue;

                        if (!long.TryParse(kodsamanehStr, out long kodsamaneh))
                            continue;


                        var row = new countnero_1218_1
                        {
                            namcity = namcity,
                            mantaghej = mantaghej,
                            kodmantageh = kodmantageh,
                            kodsamaneh = kodsamaneh,
                            vaziat = 1,
                            sharh = null,
                            FK_gozaresh = null
                        };

                        db.countnero_1218_1.Add(row);
                        saved++;
                    }

                    db.SaveChanges();
                    return $"✔ تعداد {saved} ردیف با موفقیت ثبت شد.";
                }
            }
            catch (Exception ex)
            {
                return "❌ خطا: " + ex.Message;
            }
        }







