        public Workbook SetDataExcel_safhedovom()
        {
            var Moalefeexcelfile = Workbook.Load(Server.MapPath("~/Content/ExcelFiles/tarifmoalfehgoz3.xlsx"));
            var sheet = Moalefeexcelfile.Sheets[1];

            using (var db = new SaabEntities())
            {
                var list0 = db.countnero_1218_0.ToList();
                var list1 = db.countnero_1218_1.ToList();



                int counter = 1;

                int maxRows = Math.Max(list0.Count, list1.Count);

                for (int i = 0; i < maxRows; i++)
                {
                    Row row = new Row() { Height = 20, Index = counter };


                    if (i < list1.Count)
                    {
                        row.AddCells(new List<Cell>()
         {
             new Cell() { Value = list1[i].kodmantageh, Index = 0, FontFamily = "B Nazanin", FontSize=12 },
             new Cell() { Value = list1[i].mantaghej, Index = 1, FontFamily = "B Nazanin", FontSize=12 }
         });
                    }


                    if (i < list0.Count)
                    {
                        row.AddCells(new List<Cell>()
         {
             new Cell() { Value = list0[i].cod, Index = 2, FontFamily = "B Nazanin", FontSize=12 },
             new Cell() { Value = list0[i].name, Index = 3, FontFamily = "B Nazanin", FontSize=12 }
         });
                    }

                    sheet.Rows.Add(row);
                    counter++;
                }
            }

            return Moalefeexcelfile;
        }


















