        public string GetDataFromExcel_safheDovom(HttpPostedFileBase MyExcelStream)
        {
            ExcelPackage.LicenseContext = OfficeOpenXml.LicenseContext.NonCommercial;

            using (var package = new ExcelPackage(MyExcelStream.InputStream))
            using (var db = new SaabEntities())
            {
                var ws = package.Workbook.Worksheets[1];
                int rowCount = ws.Dimension.End.Row;

                int inserted = 0, skipped = 0;

                for (int row = 2; row <= rowCount; row++)
                {
                    string kodMantagehStr = ws.Cells[row, 1].Text;
                    string name = ws.Cells[row, 2].Text;
                    string saghfStr = ws.Cells[row, 3].Text;
                    string codGozareshStr = ws.Cells[row, 4].Text;


                    if (string.IsNullOrWhiteSpace(kodMantagehStr) || string.IsNullOrWhiteSpace(name) ||
                        string.IsNullOrWhiteSpace(saghfStr) || string.IsNullOrWhiteSpace(codGozareshStr))
                    {
                        skipped++;
                        continue;
                    }

                    long kodMantageh, saghf, codGozaresh;
                    if (!long.TryParse(kodMantagehStr, out kodMantageh) ||
                        !long.TryParse(saghfStr, out saghf) ||
                        !long.TryParse(codGozareshStr, out codGozaresh))
                    {
                        skipped++;
                        continue;
                    }

                    var nero = db.countnero_1218_1
                                 .FirstOrDefault(x => x.kodmantageh == kodMantageh);
                    if (nero == null)
                    {
                        skipped++;
                        continue;
                    }


                    var gozaresh = db.countnero_1218_0
                                     .FirstOrDefault(x => x.cod == codGozaresh);
                    if (gozaresh == null)
                    {
                        skipped++;
                        continue;
                    }


                    var entity = new countnero_1218_2
                    {
                        FK_nero = nero.ID,
                        name = name,
                        saghf = saghf,
                        FK_gozaresh = gozaresh.ID
                    };

                    db.countnero_1218_2.Add(entity);
                    inserted++;
                }

                db.SaveChanges();

                return $"✔ {inserted} رکورد ثبت شد — ⚠ {skipped} رکورد به دلیل عدم match کدها ثبت نشد";
            }
        }







