        public ActionResult ExportCustomMatrixCsv()
        {
            Response.Clear();
            Response.Buffer = false;
            Response.AddHeader("Content-Disposition", "attachment;filename=CustomMatrix.csv");
            Response.ContentType = "text/csv";

            string connStr = GetSqlConnectionString();

            // ماتریس و دیکشنری ستون‌ها
            var matrix = new Dictionary<string, Dictionary<int, string>>();
            var fkList = new SortedDictionary<int, string>();

            using (var conn = new SqlConnection(connStr))
            {
                conn.Open();

                // گرفتن اطلاعات اصلی از erja_sabt_usr و erja_like_link
                var mainCmd = new SqlCommand(@"
            SELECT e.ID, e.unic, l.value AS linkedValue
            FROM erja_sabt_usr e
            LEFT JOIN erja_like_link l ON l.FK_erja_like = e.FK_omomi
            WHERE e.unic IS NOT NULL
        ", conn);

                var mainData = new List<(int ID, string value)>();
                using (var reader = mainCmd.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        string linkedValue = reader["linkedValue"]?.ToString();
                        if (string.IsNullOrEmpty(linkedValue)) continue;
                        mainData.Add((System.Convert.ToInt32(reader["ID"]), linkedValue));
                    }
                }

                // گرفتن اطلاعات از dbergharelimsertfk1_7 و dbergha2 فقط برای FK_db2 های مشخص
                var allowedFKs = new List<int> { 137, 136, 146, 153, 154 };

                foreach (var (ID, value) in mainData)
                {
                    var fkCmd = new SqlCommand(@"
                SELECT d.FK_db2, d.valueFK_db2, t2.name
                FROM dbergharelimsertfk1_7 d
                LEFT JOIN dbergha2 t2 ON d.FK_db2 = t2.ID
                WHERE d.valuunic = @Value AND d.FK_db2 IN (137,136,146,153,154)
            ", conn);
                    fkCmd.Parameters.AddWithValue("@Value", value);

                    using (var reader = fkCmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            int fk_db2 = System.Convert.ToInt32(reader["FK_db2"]);
                            string fk_name = reader["name"]?.ToString() ?? fk_db2.ToString();
                            string valFK = reader["valueFK_db2"]?.ToString() ?? "";

                            if (!matrix.ContainsKey(value))
                                matrix[value] = new Dictionary<int, string>();

                            matrix[value][fk_db2] = valFK;

                            if (!fkList.ContainsKey(fk_db2))
                                fkList[fk_db2] = fk_name;
                        }
                    }
                }
            }

            // نوشتن CSV
            using (var writer = new StreamWriter(Response.OutputStream, Encoding.UTF8))
            {
                writer.Write("valuunic");
                foreach (var fk in fkList.Keys)
                    writer.Write($",{fkList[fk]}");
                writer.WriteLine();

                foreach (var valuunic in matrix.Keys.OrderBy(x => x))
                {
                    writer.Write(valuunic);
                    foreach (var fk in fkList.Keys)
                    {
                        matrix[valuunic].TryGetValue(fk, out string val);
                        val = val?.Replace(",", " ");
                        writer.Write($",{val}");
                    }
                    writer.WriteLine();
                }
            }

            Response.End();
            return new EmptyResult();
        }
        public ActionResult ExportMatrixCsvWithLastValuebace()
        {
            Response.Clear();
            Response.Buffer = false;
            Response.AddHeader("Content-Disposition", "attachment;filename=Matrix.csv");
            Response.ContentType = "text/csv";

            string connStr = GetSqlConnectionString();

            // Dictionary برای ماتریس و FK_id -> Name
            var matrix = new Dictionary<string, Dictionary<int, string>>();
            var fkList = new SortedDictionary<int, string>();

            using (var conn = new SqlConnection(connStr))
            using (var cmd = new SqlCommand(@"
        WITH RankedData AS (
            SELECT t1.valuunic, t1.FK_db2, t2.name AS FK_db2_name, t1.valueFK_db2,
                   ROW_NUMBER() OVER(PARTITION BY t1.valuunic, t1.FK_db2 ORDER BY t1.ID DESC) AS rn
            FROM dbergharelimsertfk1_7_1218_bace t1
            LEFT JOIN dbergha2 t2 ON t1.FK_db2 = t2.ID
            WHERE t1.valuunic IS NOT NULL AND t1.FK_db2 IS NOT NULL
        )
        SELECT valuunic, FK_db2, FK_db2_name, valueFK_db2
        FROM RankedData
        WHERE rn = 1
        ORDER BY valuunic, FK_db2;
    ", conn))
            {
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandTimeout = 0;
                conn.Open();

                using (var reader = cmd.ExecuteReader(System.Data.CommandBehavior.SequentialAccess))
                {
                    while (reader.Read())
                    {
                        string valuunic = reader["valuunic"].ToString();
                        int fk_db2 = System.Convert.ToInt32(reader["FK_db2"]);
                        string fk_name = reader["FK_db2_name"]?.ToString() ?? fk_db2.ToString();
                        string valueFK = reader["valueFK_db2"]?.ToString();

                        // ساخت ماتریس مستقیم
                        if (!matrix.ContainsKey(valuunic))
                            matrix[valuunic] = new Dictionary<int, string>();

                        matrix[valuunic][fk_db2] = valueFK;

                        if (!fkList.ContainsKey(fk_db2))
                            fkList[fk_db2] = fk_name;
                    }
                }
            }

            // نوشتن CSV
            using (var writer = new StreamWriter(Response.OutputStream, Encoding.UTF8))
            {
                writer.Write("valuunic");
                foreach (var fk in fkList.Keys)
                    writer.Write($",{fkList[fk]}");
                writer.WriteLine();

                foreach (var valuunic in matrix.Keys.OrderBy(x => x))
                {
                    writer.Write(valuunic);
                    foreach (var fk in fkList.Keys)
                    {
                        matrix[valuunic].TryGetValue(fk, out string val);
                        val = val?.Replace(",", " ");
                        writer.Write($",{val}");
                    }
                    writer.WriteLine();
                }
            }

            Response.End();
            return new EmptyResult();
        }
        public ActionResult ExportMatrixCsvWithLastValue1()
        {
            Response.Clear();
            Response.Buffer = false;
            Response.AddHeader("Content-Disposition", "attachment;filename=Matrix.csv");
            Response.ContentType = "text/csv";

            string connStr = GetSqlConnectionString();

            // ===== گام 1: خواندن metadata ستون‌ها =====
            var fkList = new SortedDictionary<int, string>(); // FK_id -> Name

            using (var conn = new SqlConnection(connStr))
            using (var cmd = new SqlCommand(@"
        SELECT t3.FK_dbergharel2 AS FKID,
               t2.name AS ColumnName
        FROM dbergharel4_5 t3
        JOIN dbergha2 t2 ON t2.ID = t3.FK_dbergharel2
        WHERE t3.del = 0 OR t3.del IS NULL
        ORDER BY t3.FK_dbergharel2
    ", conn))
            {
                conn.Open();
                using (var reader = cmd.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        int fkid = System.Convert.ToInt32(reader["FKID"]);
                        string name = reader["ColumnName"]?.ToString() ?? fkid.ToString();
                        if (!fkList.ContainsKey(fkid))
                            fkList[fkid] = name;
                    }
                }
            }

            // ===== گام 2: خواندن داده‌ها =====
            var data = new List<(string valuunic, int fk_db2, string valueFK)>();

            using (var conn = new SqlConnection(connStr))
            using (var cmd = new SqlCommand(@"
        SELECT t1.valuunic, t1.FK_db2, t1.valueFK_db2
        FROM dbergharelimsertfk1_7_1218 t1
        WHERE t1.valuunic IS NOT NULL AND t1.FK_db2 IS NOT NULL
        ORDER BY t1.valuunic, t1.FK_db2, t1.ID
    ", conn))
            {
                cmd.CommandTimeout = 0;
                conn.Open();

                using (var reader = cmd.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        string valuunic = reader["valuunic"]?.ToString();
                        int fk_db2 = System.Convert.ToInt32(reader["FK_db2"]);
                        string valueFK = reader["valueFK_db2"]?.ToString();
                        data.Add((valuunic, fk_db2, valueFK));
                    }
                }
            }

            // ===== گام 3: ساخت ماتریس آخرین مقدار =====
            var matrix = new Dictionary<string, Dictionary<int, string>>();

            foreach (var row in data)
            {
                if (!matrix.TryGetValue(row.valuunic, out var dict))
                {
                    dict = new Dictionary<int, string>();
                    matrix[row.valuunic] = dict;
                }

                // آخرین مقدار برای هر FK_db2 نگه داشته می‌شود
                dict[row.fk_db2] = row.valueFK;
            }

            // ===== گام 4: نوشتن CSV =====
            using (var writer = new StreamWriter(Response.OutputStream, new UTF8Encoding(false)))
            {
                // Header
                writer.Write("valuunic");
                foreach (var fk in fkList.Values)
                    writer.Write("," + fk);
                writer.WriteLine();

                // Rows
                foreach (var valuunic in matrix.Keys.OrderBy(x => x))
                {
                    writer.Write(valuunic);
                    foreach (var fkId in fkList.Keys)
                    {
                        matrix[valuunic].TryGetValue(fkId, out string val);
                        val = val?.Replace(",", " "); // جلوگیری از خراب شدن CSV
                        writer.Write("," + (val ?? ""));
                    }
                    writer.WriteLine();
                }
            }

            Response.End();
            return new EmptyResult();
        }
        public ActionResult ExportMatrixCsv()
        {
            Response.Clear();
            Response.Buffer = false;
            Response.AddHeader("Content-Disposition", "attachment;filename=MatrixOutput.csv");
            Response.ContentType = "text/csv";

            string connStr = GetSqlConnectionString();

            using (var conn = new SqlConnection(connStr))
            {
                conn.Open();

                // اجرای Pivot و دریافت داده ها
                var cmd = new SqlCommand(@"
DECLARE @cols NVARCHAR(MAX), @fkCols NVARCHAR(MAX), @query NVARCHAR(MAX);

SELECT @cols =
    STRING_AGG(QUOTENAME(eo.Nam), ',')
FROM dbo.erja_omomi_edit eo
WHERE eo.vaziat = 2;

SELECT @fkCols =
    STRING_AGG(QUOTENAME(CAST(d2.ID AS VARCHAR)), ',')
FROM dbo.dbergha2 d2
WHERE d2.ID IN (137,146,150);

SET @query = '
SELECT
    u.usr_Name,
    u.usr_Family,
    u.usr_Personal_ID,
    np.*,
    p.*,
    x.value_cheek,
    x.unic,
    x.FK_omomi,
    x.FK_erja_omomi_edit
FROM
(
    SELECT 
        el.unic,
        eo.Nam,
        dbr.FK_db2,
        dbr.valueFK_db2,
        esu.value_cheek,
        esu.FK_omomi,
        esu.FK_erja_omomi_edit,
        esu.FK_usr
    FROM dbo.erja_sabt_usr esu
    INNER JOIN dbo.erja_like el 
        ON el.ID = esu.FK_omomi
    INNER JOIN dbo.erja_omomi_edit eo 
        ON eo.ID = esu.FK_erja_omomi_edit
    LEFT JOIN dbo.erja_like_link ell 
        ON ell.FK_erja_like = el.ID
    LEFT JOIN dbo.dbergharelimsertfk1_7 dbr
        ON dbr.FK_dbergharelinsert_6 = ell.ID
        AND dbr.FK_db2 IN (137,146,150)
    WHERE 
        esu.vaziat = 2
        AND el.vaziat = 2
        AND el.FK_job = 14
) x

PIVOT (
    MAX(valueFK_db2) FOR FK_db2 IN ('+@fkCols+')
) p

PIVOT (
    MAX(valueFK_db2) FOR Nam IN ('+@cols+')
) np

INNER JOIN Usser.tbUsers u 
    ON u.usr_ID = x.FK_usr

ORDER BY u.usr_Family, u.usr_Name;
';

EXEC(@query);
", conn);

                using (var reader = cmd.ExecuteReader())
                using (var writer = new StreamWriter(Response.OutputStream, Encoding.UTF8))
                {
                    // Header
                    for (int i = 0; i < reader.FieldCount; i++)
                    {
                        writer.Write(reader.GetName(i));
                        if (i < reader.FieldCount - 1)
                            writer.Write(",");
                    }
                    writer.WriteLine();

                    // Rows
                    while (reader.Read())
                    {
                        for (int i = 0; i < reader.FieldCount; i++)
                        {
                            string value = reader[i]?.ToString().Replace(",", " ") ?? "";
                            writer.Write(value);
                            if (i < reader.FieldCount - 1)
                                writer.Write(",");
                        }
                        writer.WriteLine();
                    }
                }
            }

            Response.End();
            return new EmptyResult();
        }
        public ActionResult ExportMatrixCsv1()
        {
            Response.Clear();
            Response.Buffer = false;
            Response.AddHeader("Content-Disposition", "attachment;filename=MatrixOutput.csv");
            Response.ContentType = "text/csv";

            string connStr = GetSqlConnectionString();

            using (var conn = new SqlConnection(connStr))
            {
                conn.Open();

                // اجرای Pivot و دریافت داده ها
                var cmd = new SqlCommand(@"
DECLARE @cols NVARCHAR(MAX), @fkCols NVARCHAR(MAX), @query NVARCHAR(MAX);

SELECT @cols =
    STRING_AGG(QUOTENAME(eo.Nam), ',')
FROM dbo.erja_omomi_edit eo
WHERE eo.vaziat = 2;

SELECT @fkCols =
    STRING_AGG(QUOTENAME(CAST(d2.ID AS VARCHAR)), ',')
FROM dbo.dbergha2 d2
WHERE d2.ID IN (137,146,150);

SET @query = '
SELECT
    u.usr_Name,
    u.usr_Family,
    u.usr_Personal_ID,
    np.*,
    p.*,
    x.value_cheek,
    x.unic,
    x.FK_omomi,
    x.FK_erja_omomi_edit
FROM
(
    SELECT 
        el.unic,
        eo.Nam,
        dbr.FK_db2,
        dbr.valueFK_db2,
        esu.value_cheek,
        esu.FK_omomi,
        esu.FK_erja_omomi_edit,
        esu.FK_usr
    FROM dbo.erja_sabt_usr esu
    INNER JOIN dbo.erja_like el 
        ON el.ID = esu.FK_omomi
    INNER JOIN dbo.erja_omomi_edit eo 
        ON eo.ID = esu.FK_erja_omomi_edit
    LEFT JOIN dbo.erja_like_link ell 
        ON ell.FK_erja_like = el.ID
    LEFT JOIN dbo.dbergharelimsertfk1_7 dbr
        ON dbr.FK_dbergharelinsert_6 = ell.ID
        AND dbr.FK_db2 IN (137,146,150)
    WHERE 
        esu.vaziat = 2
        AND el.vaziat = 2
        AND el.FK_job = 14
) x

PIVOT (
    MAX(valueFK_db2) FOR FK_db2 IN ('+@fkCols+')
) p

PIVOT (
    MAX(valueFK_db2) FOR Nam IN ('+@cols+')
) np

INNER JOIN Usser.tbUsers u 
    ON u.usr_ID = x.FK_usr

ORDER BY u.usr_Family, u.usr_Name;
';

EXEC(@query);
", conn);

                using (var reader = cmd.ExecuteReader())
                using (var writer = new StreamWriter(Response.OutputStream, Encoding.UTF8))
                {
                    // Header
                    for (int i = 0; i < reader.FieldCount; i++)
                    {
                        writer.Write(reader.GetName(i));
                        if (i < reader.FieldCount - 1)
                            writer.Write(",");
                    }
                    writer.WriteLine();

                    // Rows
                    while (reader.Read())
                    {
                        for (int i = 0; i < reader.FieldCount; i++)
                        {
                            string value = reader[i]?.ToString().Replace(",", " ") ?? "";
                            writer.Write(value);
                            if (i < reader.FieldCount - 1)
                                writer.Write(",");
                        }
                        writer.WriteLine();
                    }
                }
            }

            Response.End();
            return new EmptyResult();
        }

        public ActionResult ExportCustomMatrixCsv1()
        {
            Response.Clear();
            Response.Buffer = false;
            Response.AddHeader("Content-Disposition", "attachment;filename=CustomMatrix.csv");
            Response.ContentType = "text/csv";

            string connStr = GetSqlConnectionString();

            // ماتریس و دیکشنری ستون‌ها
            var matrix = new Dictionary<string, Dictionary<int, string>>();
            var fkList = new SortedDictionary<int, string>();

            using (var conn = new SqlConnection(connStr))
            {
                conn.Open();

                // گرفتن اطلاعات اصلی از erja_sabt_usr و erja_like_link
                var mainCmd = new SqlCommand(@"
            SELECT e.ID, e.unic, e.FK_usr, l.value AS linkedValue
            FROM erja_sabt_usr e
            LEFT JOIN erja_like_link l ON l.FK_erja_like = e.FK_omomi
            WHERE e.unic IS NOT NULL
        ", conn);

                var mainData = new List<(int ID, string value, int FK_usr)>();
                using (var reader = mainCmd.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        string linkedValue = reader["linkedValue"]?.ToString();
                        if (string.IsNullOrEmpty(linkedValue)) continue;
                        mainData.Add((System.Convert.ToInt32(reader["ID"]), linkedValue, System.Convert.ToInt32(reader["FK_usr"])));
                    }
                }

                // گرفتن اطلاعات کاربران از tbUsers
                var userCmd = new SqlCommand(@"
            SELECT usr_ID, usr_Name, usr_Family, usr_Personal_ID
            FROM Usser.tbUsers
        ", conn);
                var userDict = new Dictionary<int, (string Name, string Family, string PersonalID)>();
                using (var reader = userCmd.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        int usrId = System.Convert.ToInt32(reader["usr_ID"]);
                        string name = reader["usr_Name"]?.ToString() ?? "";
                        string family = reader["usr_Family"]?.ToString() ?? "";
                        string personalID = reader["usr_Personal_ID"]?.ToString() ?? "";
                        userDict[usrId] = (name, family, personalID);
                    }
                }

                // گرفتن اطلاعات از dbergharelimsertfk1_7 و dbergha2 فقط برای FK_db2 های مشخص
                var allowedFKs = new List<int> { 137, 136, 146, 153, 154 };

                foreach (var (ID, value, FK_usr) in mainData)
                {
                    var fkCmd = new SqlCommand(@"
                SELECT d.FK_db2, d.valueFK_db2, t2.name
                FROM dbergharelimsertfk1_7 d
                LEFT JOIN dbergha2 t2 ON d.FK_db2 = t2.ID
                WHERE d.valuunic = @Value AND d.FK_db2 IN (137,136,146,153,154)
            ", conn);
                    fkCmd.Parameters.AddWithValue("@Value", value);

                    using (var reader = fkCmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            int fk_db2 = System.Convert.ToInt32(reader["FK_db2"]);
                            string fk_name = reader["name"]?.ToString() ?? fk_db2.ToString();
                            string valFK = reader["valueFK_db2"]?.ToString() ?? "";

                            if (!matrix.ContainsKey(value))
                                matrix[value] = new Dictionary<int, string>();

                            matrix[value][fk_db2] = valFK;

                            if (!fkList.ContainsKey(fk_db2))
                                fkList[fk_db2] = fk_name;
                        }
                    }
                }

                // نوشتن CSV
                using (var writer = new StreamWriter(Response.OutputStream, Encoding.UTF8))
                {
                    // ستون‌های نام، نام خانوادگی و کد پرسنلی
                    writer.Write("Name,Family,PersonalID");
                    foreach (var fk in fkList.Keys)
                        writer.Write($",{fkList[fk]}");
                    writer.WriteLine();

                    foreach (var (ID, value, FK_usr) in mainData)
                    {
                        if (!userDict.TryGetValue(FK_usr, out var userInfo))
                            userInfo = ("", "", "");

                        writer.Write($"{userInfo.Name},{userInfo.Family},{userInfo.PersonalID}");

                        if (matrix.TryGetValue(value, out var valDict))
                        {
                            foreach (var fk in fkList.Keys)
                            {
                                valDict.TryGetValue(fk, out string val);
                                val = val?.Replace(",", " ");
                                writer.Write($",{val}");
                            }
                        }
                        else
                        {
                            foreach (var fk in fkList.Keys)
                                writer.Write(",");
                        }

                        writer.WriteLine();
                    }
                }
            }

            Response.End();
            return new EmptyResult();
        }
