        private void WriteRow(StreamWriter writer, List<(int fk_id, string name, int shomareh)> fkList, Dictionary<int, string> rowDict)
        {
            writer.Write("=\"A\"");
            foreach (var fk in fkList)
            {
                rowDict.TryGetValue(fk.fk_id, out string val);
                writer.Write($",{(val ?? "").Replace(",", " ")}");
            }
            writer.WriteLine();
        }






