        public ActionResult ExportMatrixCsvWithLastValue()
        {
            Response.Clear();
            Response.Buffer = false;
            Response.AddHeader("Content-Disposition", "attachment;filename=Matrix.csv");
            Response.ContentType = "text/csv";

            string connStr = GetSqlConnectionString();

            // گام 1: گرفتن تمام داده‌ها
            var data = new List<(string valuunic, int fk_db2, string fk_name, string valueFK)>();
            var fkList = new SortedDictionary<int, string>(); // FK_id -> Name

            using (var conn = new SqlConnection(connStr))
            using (var cmd = new SqlCommand(@"
            SELECT t1.valuunic, t1.FK_db2, t2.name AS FK_db2_name, t1.valueFK_db2
            FROM dbergharelimsertfk1_7_1218 t1
            LEFT JOIN dbergha2 t2 ON t1.FK_db2 = t2.ID
            WHERE t1.valuunic IS NOT NULL AND t1.FK_db2 IS NOT NULL
            ORDER BY t1.valuunic, t1.FK_db2, t1.ID
        ", conn))
            {
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandTimeout = 0;
                conn.Open();

                using (var reader = cmd.ExecuteReader(System.Data.CommandBehavior.SequentialAccess))
                {
                    while (reader.Read())
                    {
                        string valuunic = reader["valuunic"].ToString();
                        int fk_db2 = System.Convert.ToInt32(reader["FK_db2"]);
                        string fk_name = reader["FK_db2_name"]?.ToString() ?? fk_db2.ToString();
                        string valueFK = reader["valueFK_db2"]?.ToString();

                        data.Add((valuunic, fk_db2, fk_name, valueFK));

                        if (!fkList.ContainsKey(fk_db2))
                            fkList[fk_db2] = fk_name;
                    }
                }
            }

            // گام 2: ساخت Dictionary برای ماتریس، فقط آخرین valueFK برای هر valuunic
            var matrix = new Dictionary<string, Dictionary<int, string>>();
            foreach (var row in data)
            {
                if (!matrix.ContainsKey(row.valuunic))
                    matrix[row.valuunic] = new Dictionary<int, string>();

                // هر بار که مقدار می‌آید، مقدار جدید جایگزین شود -> آخرین مقدار نگه داشته می‌شود
                matrix[row.valuunic][row.fk_db2] = row.valueFK;
            }

            // گام 3: نوشتن CSV با نام ستون‌ها
            using (var writer = new StreamWriter(Response.OutputStream, Encoding.UTF8))
            {
                // Header
                writer.Write("valuunic");
                foreach (var fk in fkList.Keys)
                    writer.Write($",{fkList[fk]}"); // استفاده از name به جای FK_db2
                writer.WriteLine();

                // Rows
                foreach (var valuunic in matrix.Keys.OrderBy(x => x))
                {
                    writer.Write($"=\"{valuunic}\"");   // ✅ اینجا درست است
                    foreach (var fk in fkList.Keys)
                    {
                        matrix[valuunic].TryGetValue(fk, out string val);
                        val = val?.Replace(",", " "); // جلوگیری از خراب شدن CSV
                        writer.Write($",{val}");
                    }
                    writer.WriteLine();
                }
            }

            Response.End();
            return new EmptyResult();
        }

