        #region fish vaziatfish
        public async Task<ActionResult> start_vaziat(int month = 0, int year = 0, int id = 0)
        {
            try
            {
                var find = db.dbvaziat_fish.Where(s => s.month == month && s.year == year && s.tartib == id).FirstOrDefault();
                if (find != null)
                {
                    find.start = 1;
                    db.SaveChanges();

                }
                else
                {
                    dbvaziat_fish dbvaziat_fish = new dbvaziat_fish();
                    dbvaziat_fish.month = month;
                    dbvaziat_fish.year = year;
                    dbvaziat_fish.tartib = id;
                    dbvaziat_fish.start = 1;
                    db.dbvaziat_fish.Add(dbvaziat_fish);
                    db.SaveChanges();
                }
                return Content("True");

            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }
