        public async Task<ActionResult> eydiadash(int year)
        {
            try
            {
                //int year = 1404;
                // ابتدا findid را پیدا می‌کنیم
                var findid = db.tbContractMoalefeDastmozdi.FirstOrDefault(s => s.md_Title == "عیدی و پاداش (سالیانه - ریال)");

                // *** بررسی می‌کنیم که آیا findid پیدا شده است ***
                if (findid == null)
                {
                    // اگر پیدا نشد، یک پیام خطا برمی‌گردانیم
                    return Content("خطا: نوع قرارداد 'عیدی و پاداش (سالیانه - ریال)' یافت نشد.");
                }

                // بقیه کد شما...
                var find1960 = db.tbMoalefeValueFish.Where(s => s.FK_EXCel == null && (s.FK_Moalefe == 1960 || s.FK_Moalefe == 1964) && s.mlfvlfsh_Value > 0 && s.mlfvlfsh_Year == year).ToList();

                // این قسمت حذف مقادیر قدیمی را انجام می‌دهد
                var del = db.tbMoalefeValueFish.Where(s => s.mlfvlfsh_Month == 12 && s.FK_EXCel == null && s.mlfvlfsh_Year == year && (s.FK_Moalefe == 1975 || s.FK_Moalefe == 1948 || s.FK_Moalefe == findid.md_ID || s.FK_Moalefe == 1985 || s.FK_Moalefe == 1983 || s.FK_Moalefe == 1986 || s.FK_Moalefe == 1978 && s.FK_Moalefe == 1979)).ToList();
                db.tbMoalefeValueFish.RemoveRange(del);
                await db.SaveChangesAsync();

                var del2 = db.tbMoalefeValueFish.Where(s => s.mlfvlfsh_Month == 12 && s.FK_EXCel != null && s.mlfvlfsh_Year == year && s.FK_Moalefe == findid.md_ID).ToList();
                db.tbMoalefeValueFish.RemoveRange(del2);
                await db.SaveChangesAsync();

                // پیدا کردن رکوردهای اصلی برای محاسبه
                var find = db.tbMoalefeValueFish.Where(s => s.FK_Moalefe == 1960 && s.FK_EXCel == null && s.mlfvlfsh_Month == 12 && s.mlfvlfsh_Year == year && s.mlfvlfsh_Value > 0).ToList();
                var myDatetime = ConvertDateTimeToShamsi.ConvertShamsiYearToYear(year, 12);
                var fondtime = db.tbUserContracts.Where(p => p.usc_EndTime >= myDatetime && p.usc_StartTime <= myDatetime).ToList();

                // پیدا کردن findfk برای FK_EXCel
                var findfk = db.tbMoalefeValueFish.FirstOrDefault(s => s.Finalaccept == true && s.FK_EXCel != null && s.mlfvlfsh_Month == 12 && s.mlfvlfsh_Year == year);
                // اگر findfk مقدار null داشت، FK_EXCel هم null خواهد بود. این با عملگر ?. مدیریت می‌شود.
                var fkExcelValue = findfk?.FK_EXCel;

                List<tbMoalefeValueFish> tbMoalefeValueFish2 = new List<tbMoalefeValueFish>();
                foreach (var it in find)
                {
                    // پیدا کردن اطلاعات قرارداد کاربر فعلی
                    var contractinfo = fondtime.FirstOrDefault(p => p.FK_UserID == it.FK_User && p.usc_EndTime >= myDatetime && p.usc_StartTime <= myDatetime);

                    // *** بررسی می‌کنیم که آیا contractinfo پیدا شده است ***
                    if (contractinfo == null)
                    {
                        // اگر اطلاعات قرارداد کاربر پیدا نشد، از این کاربر رد می‌شویم و به کاربر بعدی می‌رویم
                        // می‌توانید اینجا لاگ هم ثبت کنید
                        continue;
                    }

                    // استفاده از عملگر ?? برای اطمینان از اینکه مقادیر null نیستند
                    var mozdsanavatroozane = contractinfo.jobgroup_ValueSanavat ?? "0";
                    mozdsanavatroozane = Regex.Replace(mozdsanavatroozane, ",", "");

                    var mozdshoqlroozane = contractinfo.jobgroup_ValueMozdGroup ?? "0";
                    mozdshoqlroozane = Regex.Replace(mozdshoqlroozane, ",", "");

                    // تبدیل به عدد صحیح
                    var rozaneh = System.Convert.ToInt32(mozdsanavatroozane);
                    var shoglroza = System.Convert.ToInt32(mozdshoqlroozane);

                    double eydivapadashsalane = (double)shoglroza + rozaneh;
                    int countday1 = 0;

                    // حلقه برای ماه‌های 1 تا 11
                    for (int i = 1; i <= 11; i++)
                    {
                        var countday = find1960.FirstOrDefault(s => s.mlfvlfsh_Month == i && s.FK_User == it.FK_User && s.mlfvlfsh_Year == year && s.FK_Moalefe == 1960 && s.mlfvlfsh_Value > 0);
                        if (countday != null)
                        {
                            countday1 += (int)countday.mlfvlfsh_Value;
                        }
                        var countday2 = find1960.FirstOrDefault(s => s.mlfvlfsh_Month == i && s.FK_User == it.FK_User && s.mlfvlfsh_Year == year && s.FK_Moalefe == 1964 && s.mlfvlfsh_Value > 0);
                        if (countday2 != null)
                        {
                            // پیدا کردن قرارداد پیمان
                            var peymanContract = db.tbPeymanContracts.FirstOrDefault(s => s.pec_Title == "کارگزاری خدمات توزیع نیروی برق بیرجند");
                            if (peymanContract != null) // اگر قرارداد پیدا شد
                            {
                                if (countday2.mlfvlfsh_Value > 3)
                                {
                                    countday1 += (int)countday2.mlfvlfsh_Value;
                                }
                            }
                            else // اگر قرارداد پیدا نشد
                            {
                                countday1 += (int)countday2.mlfvlfsh_Value;
                            }
                        }
                    }

                    // محاسبه برای ماه 12
                    var countday3 = find1960.FirstOrDefault(s => s.mlfvlfsh_Month == 12 && s.FK_User == it.FK_User && s.mlfvlfsh_Year == year && s.FK_Moalefe == 1964 && s.mlfvlfsh_Value > 0);
                    if (countday3 != null)
                    {
                        countday1 += (int)countday3.mlfvlfsh_Value;
                    }
                    countday1 += (int)it.mlfvlfsh_Value; // اضافه کردن مقدار ماه 12 از it

                    long countnumber = 0;
                    eydivapadashsalane = eydivapadashsalane * 60;
                    countnumber = (long)eydivapadashsalane / 365;
                    countnumber = countnumber * countday1;
                    eydivapadashsalane = (double)countnumber;

                    // ایجاد رکورد جدید برای ذخیره
                    var tbMoalefeValueFish = new tbMoalefeValueFish
                    {
                        FK_User = it.FK_User,
                        FK_Moalefe = findid.md_ID, // استفاده از findid که قبلا مقدارش چک شده
                        FK_EXCel = fkExcelValue, // استفاده از مقدار محاسبه شده که ممکن است null باشد
                        Finalaccept = true,
                        mlfvlfsh_Month = 12,
                        mlfvlfsh_Year = year,
                        mlfvlfsh_Value = eydivapadashsalane
                    };
                    tbMoalefeValueFish2.Add(tbMoalefeValueFish);
                }

                db.tbMoalefeValueFish.AddRange(tbMoalefeValueFish2);
                await db.SaveChangesAsync();
                return Content("true");
            }
            catch (Exception ex)
            {
                // **حتماً خطاهای رخ داده را لاگ کنید**
                // مثال: _logger.LogError(ex, "خطا در متد Eydiadashti1");
                return Content($"An error occurred: {ex.Message}");
            }
        }
