                return Content("داده‌ای یافت نشد");

            if (files.Count == 1)
            {
                var single = files[0];
                var tempPath = Path.GetTempFileName() + ".xlsx"; // مسیر موقت
                single.wb.Save(tempPath); // Save به مسیر فایل
                var fileBytes = System.IO.File.ReadAllBytes(tempPath);
                System.IO.File.Delete(tempPath); // حذف فایل موقت
                return File(
                    fileBytes,
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    single.fileName
                );
            }
            else // چند فایل → ZIP
            {
                using (var zipStream = new MemoryStream())
                {
                    // ساخت ZIP
                    using (var archive = new ZipArchive(zipStream, ZipArchiveMode.Create, true))
                    {
                        foreach (var f in files)
                        {
                            // تبدیل نام فایل به حروف انگلیسی ساده
                            var safeFileName = f.fileName
                                               .Replace(" ", "_")
                                               .Replace("پرداختی", "Pardakhti")
                                               .Replace("ـ", "")
                                               .Replace("های", "Files"); // می‌تونی بیشتر replace اضافه کنی

                            var entry = archive.CreateEntry(safeFileName);
                            using (var entryStream = entry.Open())
                            {
                                // فایل موقت XLSX
                                var tempPath = Path.GetTempFileName() + ".xlsx";
                                f.wb.Save(tempPath);

                                var fileBytes = System.IO.File.ReadAllBytes(tempPath);
                                entryStream.Write(fileBytes, 0, fileBytes.Length);

                                System.IO.File.Delete(tempPath);
                            }
                        }
                    }

                    zipStream.Position = 0;

                    // نام فایل ZIP ساده و انگلیسی
                    var zipFileName = $"Pardakhti_{month}_{year}.zip";
                    return File(zipStream.ToArray(), "application/zip", zipFileName);
                }
            }
        }

        public async Task<ActionResult> end_vaziat(int month = 0, int year = 0, int id = 0)
        {
            try
            {
                var find = db.dbvaziat_fish.Where(s => s.month == month && s.year == year && s.tartib == id).FirstOrDefault();
                if (find != null)
                {
                    find.finish = 1;
                    db.SaveChanges();

                }
                else
                {
                    dbvaziat_fish dbvaziat_fish = new dbvaziat_fish();
                    dbvaziat_fish.month = month;
                    dbvaziat_fish.year = year;
                    dbvaziat_fish.tartib = id;
                    dbvaziat_fish.finish = 1;
                    db.dbvaziat_fish.Add(dbvaziat_fish);
                    db.SaveChanges();
                }
                return Content("True");

            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }

