        public ActionResult asnaf_mali()
        {
            List<NatigeEshterakBala50> NatigeEshterakBala50 = new List<NatigeEshterakBala50>();
            var finddd = db.NatigeEshterakBala50.GroupBy(s => s.ShenaseGhabz).ToList();
            foreach (var it in finddd)
            {
                NatigeEshterakBala50.Add(db.NatigeEshterakBala50.Where(s => s.ShenaseGhabz == it.Key).OrderByDescending(t => t.ID).FirstOrDefault());
