        public string GetDataFromExcel_NatigeEshterakBala50(HttpPostedFileBase MyExcelStream)
        {
            try
            {
                using (var package = new ExcelPackage(MyExcelStream.InputStream))
                using (var db = new SaabEntities())
                {


                    var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                    if (cookie_user == null)
                        return "دسترسی غیرمجاز";

                    var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                    var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                    if (user == null)
                        return "کاربر یافت نشد";

                    int personal = user.usr_ID;
                    //ka
                    var ws = package.Workbook.Worksheets[0];
                    if (ws == null)
                        return "شیت اول یافت نشد";

                    int rowCount = ws.Dimension.End.Row;

                    for (int row = 3; row <= rowCount; row++)
                    {
                        var entity = new NatigeEshterakBala50();


                        entity.NameMoshtarak = ws.Cells[row, 1].Text.Trim();
                        entity.ShenaseGhabz = ws.Cells[row, 2].Text.Trim();
                        entity.MandeKolErja = ws.Cells[row, 18].Text.Trim();
                        entity.city_name = ws.Cells[row, 10].Text.Trim();
                        entity.value_bi = ws.Cells[row, 32].Text.Trim();

                        entity.SharhPeygiri = ws.Cells[row, 31].Text.Trim();
                        entity.time_sabt = DateTime.Now;
                        entity.UserSabt = personal;

                        for (int col = 20; col <= 29; col++)
                        {
                            var cellValue = ws.Cells[row, col].Text.Trim();

                            if (cellValue == "1")
                            {
                                switch (col)
                                {
                                    case 20: entity.NatigePeygiri = 1; break;
                                    case 21: entity.NatigePeygiri = 2; break;
                                    case 22: entity.NatigePeygiri = 3; break;
                                    case 23: entity.NatigePeygiri = 4; break;
                                    case 24: entity.NatigePeygiri = 5; break;
                                    case 25: entity.NatigePeygiri = 6; break;
                                    case 26: entity.NatigePeygiri = 7; break;
                                    case 27: entity.NatigePeygiri = 8; break;
                                    case 28: entity.NatigePeygiri = 9; break;
                                    case 29: entity.NatigePeygiri = 10; break;
                                }

                                break;
                            }
                        }

                        db.NatigeEshterakBala50.Add(entity);
                    }

                    db.SaveChanges();
                }

                return "اطلاعات با موفقیت ثبت شد";
            }
            catch (Exception ex)
            {
                return "خطا: " + ex.Message;
            }
        }



