        public async Task<ActionResult> olavaitmoh21FastCorrected()
        {
            try
            {
                // ================= SQL اصلاح‌شده =================
                string sql = @"
WITH LastFoz AS (
    SELECT *,
           ROW_NUMBER() OVER (
             PARTITION BY FK_table4
             ORDER BY ID DESC
           ) rn
    FROM dbergharelinsert_6
),
ValData AS (
    SELECT
        l.FK_link,
        l.vaziat_moh,
        l.alamat AS Olaviat,
        l.val1,
        l.olaviat AS OlaviatMap,
        r4.FK_namegozarwsh AS Type,
        f.ID AS FozID,
        CASE 
            WHEN r4.FK_namegozarwsh = 24 THEN b.valuunic
            WHEN r4.FK_namegozarwsh = 25 THEN v.valuunic
            ELSE s.valuunic
        END AS Valunic,
        b.valueFK_db2 AS ValBace,
        v.valueFK_db2 AS Val1218,
        s.valueFK_db2 AS Val7
    FROM olaviat_1218_link_olaviat l
    JOIN LastFoz f ON f.ID = l.FK_gozaresh1 AND f.rn = 1
    JOIN dbergharel_4 r4 ON r4.ID = f.FK_table4
    LEFT JOIN dbergharelimsertfk1_7_1218_bace b
        ON b.FK_dbergharelinsert_6 = f.ID AND b.FK_db2 = l.FK_name
    LEFT JOIN dbergharelimsertfk1_7_1218 v
        ON v.FK_dbergharelinsert_6 = f.ID AND v.FK_db2 = l.FK_name
    LEFT JOIN dbergharelimsertfk1_7 s
        ON s.FK_dbergharelinsert_6 = f.ID AND s.FK_db2 = l.FK_name
)
SELECT *
FROM ValData
ORDER BY FK_Link, Valunic
";

                var raw = new List<dynamic>();

                using (var conn = new SqlConnection(GetSqlConnectionString()))
                using (var cmd = new SqlCommand(sql, conn))
                {
                    await conn.OpenAsync();
                    using (var rd = await cmd.ExecuteReaderAsync())
                    {
                        while (await rd.ReadAsync())
                        {
                            raw.Add(new
                            {
                                Valunic = rd["Valunic"]?.ToString(),
                                FK_Link = System.Convert.ToInt64(rd["FK_Link"]),
                                VaziatMoh = rd["vaziat_moh"] == DBNull.Value ? 0 : System.Convert.ToInt32(rd["vaziat_moh"]),
                                Olaviat = rd["Olaviat"] == DBNull.Value ? 0 : System.Convert.ToInt32(rd["Olaviat"]),
                                ValBace = rd["ValBace"]?.ToString(),
                                Val1218 = rd["Val1218"]?.ToString(),
                                Val7 = rd["Val7"]?.ToString(),
                                Type = rd["Type"] == DBNull.Value ? 0 : System.Convert.ToInt32(rd["Type"]),
                                Val1 = rd["val1"]?.ToString(),
                                OlaviatMap = rd["OlaviatMap"] == DBNull.Value ? 0 : System.Convert.ToInt32(rd["OlaviatMap"])
                            });
                        }
                    }
                }

                // ================= ApplyOperation همانند EF =================
                long ApplyOperation(long result, long value, long alamat, int index)
                {
                    if (index == 1)
                    {
                        switch (alamat)
                        {
                            case 1: return result - value;
                            case 2: return result + value;
                            case 3: return result * value;
                            case 4: return value == 0 ? result : result / value;
                            default: return value;
                        }
                    }
                    else
                    {
                        switch (alamat)
                        {
                            case 1: return result - value;
                            case 2: return result + value;
                            case 3: return result * value;
                            case 4: return value == 0 ? result : result / value;
                            default: return result;
                        }
                    }
                }

                // ================= مرحله 1: محاسبه =================
                var tempDict = new Dictionary<string, List<MohResult>>();

                foreach (var groupVal in raw.GroupBy(x => x.Valunic))
                {
                    string valKey = groupVal.Key;
                    tempDict[valKey] = new List<MohResult>();

                    foreach (var shartGroup in groupVal.GroupBy(x => x.FK_Link))
                    {
                        long result = 0;
                        long alamat = 0;
                        int index = 0;
                        int vaziatMoh = 0;

                        foreach (var shart in shartGroup)
                        {
                            long value = 0;

                            if (shart.VaziatMoh == 1)
                            {
                                index++;
                                if (index == 1) alamat = shart.Olaviat;

                                string val =
                                    shart.Type == 24 ? shart.ValBace :
                                    shart.Type == 25 ? shart.Val1218 :
                                    shart.Val7;

                                value = long.TryParse(val, out var v) ? v : 0;

                                result = ApplyOperation(result, value, alamat, index);
                                alamat = shart.Olaviat;
                                vaziatMoh = 1;
                            }
                            else if (shart.VaziatMoh == 5)
                            {
                                result = shart.OlaviatMap;
                                vaziatMoh = 5;
                            }
                        }

                        tempDict[valKey].Add(new MohResult
                        {
                            Valunic = valKey,
                            FK_Link = shartGroup.Key,
                            Result = result,
                            Olaviat = shartGroup.Max(x => x.Olaviat),
                            Priority = 0,
                            VaziatMoh = vaziatMoh
                        });
                    }
                }

                // ================= مرحله 2: Rank2 =================
                var allResults = tempDict.Values.SelectMany(x => x).ToList();
                var sortedList = new List<MohResult>();
                var remaining = new List<MohResult>(allResults);

                while (remaining.Any())
                {
                    var first = remaining.First();
                    var group = remaining.Where(x =>
                        x.VaziatMoh == first.VaziatMoh &&
                        x.FK_Link == first.FK_Link &&
                        x.Olaviat == first.Olaviat).ToList();

                    if (first.VaziatMoh == 5)
                        group = group.OrderBy(x => x.Result).ToList();
                    else if (first.VaziatMoh == 1 && first.Olaviat == 6)
                        group = group.OrderByDescending(x => x.Result).ToList();
                    else
                        group = group.OrderBy(x => x.Result).ToList();

                    int r = 1;
                    long? last = null;
                    foreach (var g in group)
                    {
                        if (last != null && g.Result != last) r++;
                        g.Rank2 = r;
                        last = g.Result;
                    }

                    sortedList.AddRange(group);
                    foreach (var g in group) remaining.Remove(g);
                }

                // ================= مرحله 3: Rank نهایی =================
                var linkOrder = sortedList.Select(x => x.FK_Link).Distinct().ToList();

                var matrix = sortedList
                    .GroupBy(x => x.Valunic)
                    .ToDictionary(
                        g => g.Key,
                        g => g.ToDictionary(x => x.FK_Link, x => x.Rank2));

                var orderedValunic = matrix.Keys
                    .OrderBy(v => string.Join("|",
                        linkOrder.Select(l =>
                            matrix[v].ContainsKey(l)
                                ? matrix[v][l].ToString().PadLeft(5, '0')
                                : "99999"))).ToList();

                int finalRank = 1;
                foreach (var v in orderedValunic)
                {
                    foreach (var row in sortedList.Where(x => x.Valunic == v))
                        row.Rank = finalRank;
                    finalRank++;
                }

                // ================= خروجی =================
                return Json(new
                {
                    AllResults = sortedList,
                    UniqueResults = sortedList
                        .GroupBy(x => x.Valunic)
                        .Select(g => g.First())
                        .OrderBy(x => x.Rank)
                        .ToList()
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }


