                table.Columns.Add("valuunic", typeof(string));
                table.Columns.Add("SortRank", typeof(int));

                foreach (var r in uniqueRows)
                    table.Rows.Add(r.Valunic, r.Rank);

                using (var conn = new SqlConnection(connectionString))
                {
                    conn.Open();

                    // temp table
                    new SqlCommand(@"
        CREATE TABLE #RankTemp(valuunic NVARCHAR(500), SortRank INT)
    ", conn).ExecuteNonQuery();

                    // BulkCopy
                    using (var bulk = new SqlBulkCopy(conn))
                    {
                        bulk.DestinationTableName = "#RankTemp";
                        bulk.WriteToServer(table);
                    }

                    // Merge با مقدار پیش‌فرض P1..P5
                    var mergeCmd = new SqlCommand(@"
        MERGE ValuunicPriorityResult AS T
        USING
        (
            SELECT
                r.valuunic,
                r.SortRank,
                b.valueFK_db2 AS item4
            FROM #RankTemp r
            OUTER APPLY
            (
                SELECT TOP 1 valueFK_db2
                FROM dbergharelimsertfk1_7_1218_bace
                WHERE valuunic COLLATE Persian_100_BIN = r.valuunic COLLATE Persian_100_BIN
                  AND FK_db2 = 459
                ORDER BY ID DESC
            ) b
        ) AS S
        ON T.valuunic COLLATE Persian_100_BIN = S.valuunic COLLATE Persian_100_BIN
        WHEN MATCHED THEN
            UPDATE SET
                SortRank = S.SortRank,
                item4 = S.item4,
                P1 = ISNULL(P1,0),
                P2 = ISNULL(P2,0),
                P3 = ISNULL(P3,0),
                P4 = ISNULL(P4,0),
                P5 = ISNULL(P5,0),
                CreatedAt = GETDATE()
        WHEN NOT MATCHED THEN
            INSERT (valuunic, SortRank, item4, P1, P2, P3, P4, P5, CreatedAt)
            VALUES (S.valuunic, S.SortRank, S.item4, 0, 0, 0, 0, 0, GETDATE());
    ", conn);

                    mergeCmd.ExecuteNonQuery();
                }
             // <-- این } خیلی مهمه، بسته شدن using SqlConnection

                // ===================== خروجی =====================
                return Json(new
                {
                
                    UniqueResults = sortedList
                        .GroupBy(x => x.Valunic)
                        .Select(g => g.First())
                        .OrderBy(x => x.Rank)
                        .ToList()
                }, JsonRequestBehavior.AllowGet);
                 }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }

