            VALUES (S.valuunic, S.SortRank, S.item4, 0, 0, 0, 0, 0,   GETDATE(),
        S.day,
        S.month,
        S.yaer);
    ", conn);

                    mergeCmd.ExecuteNonQuery();
                }
                int totalRows = sortedList.Count;
                int uniqueCount = uniqueRows.Count;
                int maxRank = uniqueRows.Max(x => x.Rank);

