        public async Task<ActionResult> DistributeJobsByRank1()
        {
            try
            {
                string connectionString = GetSqlConnectionString();

                using (var conn = new SqlConnection(connectionString))
                {
                    await conn.OpenAsync();

                    var jobs = new List<(string valuunic, int rank, string mantaghe)>();

                    using (var cmd = new SqlCommand(@"
                SELECT valuunic, SortRank, item4
                FROM ValuunicPriorityResult
                WHERE item4 IS NOT NULL
                ORDER BY item4, SortRank
            ", conn))
                    using (var rd = await cmd.ExecuteReaderAsync())
                    {
                        while (await rd.ReadAsync())
                        {
                            jobs.Add((
                                rd["valuunic"].ToString(),
                                  System.Convert.ToInt32(rd["SortRank"]),
                                rd["item4"].ToString()
                            ));
                        }
                    }

                    var jobByRegion = jobs.GroupBy(x => x.mantaghe);
                    string today = PersianToday();

                    foreach (var regionGroup in jobByRegion)
                    {
                        var orderedJobs = regionGroup.OrderBy(x => x.rank).ToList();
                        int totalJobs = orderedJobs.Count;

                        // ---------- کاربران ----------
                        var users = new List<(int usr, int capacity)>();

                        using (var cmd = new SqlCommand(@"
                    SELECT FK_usr, count
                    FROM tbcount_car
                    WHERE mantaghe = @m
                ", conn))
                        {
                            cmd.Parameters.AddWithValue("@m", regionGroup.Key);

                            using (var rd = await cmd.ExecuteReaderAsync())
                            {
                                while (await rd.ReadAsync())
                                {
                                    users.Add((
                                          System.Convert.ToInt32(rd["FK_usr"]),
                                          System.Convert.ToInt32(rd["count"])
                                    ));
                                }
                            }
                        }

                        if (!users.Any()) continue;

                        // ---------- تقسیم مساوی ----------
                        int userCount = users.Count;
                        int baseShare = totalJobs / userCount;

                        // سهم اولیه هر کاربر
                        var shares = users
             .Select(u => new UserShare
             {
                 usr = u.usr,
                 capacity = u.capacity,
                 share = Math.Min(baseShare, u.capacity)
             })
             .ToList();


                        int assigned = shares.Sum(x => x.share);
                        int remaining = totalJobs - assigned;

                        foreach (var u in shares.OrderByDescending(x => x.capacity))
                        {
                            if (remaining <= 0) break;

                            int canTake = u.capacity - u.share;
                            int add = Math.Min(canTake, remaining);

                            u.share += add;   // ✅ حالا مجاز است
                            remaining -= add;
                        }


                        // ---------- تخصیص واقعی ----------
                        int jobIndex = 0;

                        foreach (var u in shares)
                        {
                            for (int i = 0; i < u.share; i++)
                            {
                                if (jobIndex >= orderedJobs.Count)
                                    break;

                                var job = orderedJobs[jobIndex++];
                                string unicFull = job.valuunic + "_" + today;

                                long erjaId;

                                using (var cmd = new SqlCommand(@"
                            INSERT INTO erja_like
                            (FK_usr, unic, vaziat, FK_job)
                            OUTPUT INSERTED.ID
                            VALUES (@usr, @unic, 0, 56)
                        ", conn))
                                {
                                    cmd.Parameters.AddWithValue("@usr", u.usr);
                                    cmd.Parameters.AddWithValue("@unic", unicFull);

                                    erjaId = (long)await cmd.ExecuteScalarAsync();
                                }

                                using (var cmd = new SqlCommand(@"
                            INSERT INTO erja_like_link
                            (FK_erja_like, FK_omomi, value, timesabt, vaziat)
                            VALUES (@id, 79, @val, GETDATE(), 0)
                        ", conn))
                                {
                                    cmd.Parameters.AddWithValue("@id", erjaId);
                                    cmd.Parameters.AddWithValue("@val", job.valuunic);
                                    await cmd.ExecuteNonQueryAsync();
                                }
                            }
                        }
                    }
                }

                return Content("OK - Balanced Distribution Done");
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }
        public async Task<ActionResult> DistributeJobsByRank2(DateTime fromDate)
        {
            try
            {
                var pc = new PersianCalendar();

                int shamsiYear = pc.GetYear(fromDate);
                int shamsiMonth = pc.GetMonth(fromDate);
                int shamsiDay = pc.GetDayOfMonth(fromDate);

                // تاریخ شمسی کامل به صورت رشته
                string shamsiDate =
                    $"{shamsiYear:0000}/{shamsiMonth:00}/{shamsiDay:00}";
                string connectionString = GetSqlConnectionString();

                using (var conn = new SqlConnection(connectionString))
                {
                    await conn.OpenAsync();

                    // ===================== خواندن کارها =====================
                    var jobs = new List<(string valuunic, int rank, string mantaghe)>();

                    using (var cmd = new SqlCommand(@"
                SELECT valuunic, SortRank, item4
                FROM ValuunicPriorityResult
                WHERE item4 IS NOT NULL
                ORDER BY item4, SortRank
            ", conn))
                    using (var rd = await cmd.ExecuteReaderAsync())
                    {
                        while (await rd.ReadAsync())
                        {
                            jobs.Add((
                                rd["valuunic"].ToString(),
                                  System.Convert.ToInt32(rd["SortRank"]),
                                rd["item4"].ToString()
                            ));
                        }
                    }

                    var jobByRegion = jobs.GroupBy(x => x.mantaghe);
                    string today = PersianToday();

                    // ===================== هر منطقه جدا =====================
                    foreach (var regionGroup in jobByRegion)
                    {
                        var orderedJobs = regionGroup.OrderBy(x => x.rank).ToList();
                        int totalJobs = orderedJobs.Count;

                        // ---------- کاربران منطقه ----------
                        var users = new List<(int usr, int capacity)>();

                        using (var cmd = new SqlCommand(@"
                    SELECT FK_usr, count
                    FROM tbcount_car
                    WHERE mantaghe = @m
                ", conn))
                        {
                            cmd.Parameters.AddWithValue("@m", regionGroup.Key);

                            using (var rd = await cmd.ExecuteReaderAsync())
                            {
                                while (await rd.ReadAsync())
                                {
                                    users.Add((
                                          System.Convert.ToInt32(rd["FK_usr"]),
                                          System.Convert.ToInt32(rd["count"])
                                    ));
                                }
                            }
                        }

                        if (!users.Any())
                            continue;

                        // ===================== سهم پایه =====================
                        int baseShare = totalJobs / users.Count;

                        var shares = users.Select(u => new UserShare
                        {
                            usr = u.usr,
                            capacity = u.capacity,
                            share = Math.Min(baseShare, u.capacity)
                        }).ToList();

                        int assigned = shares.Sum(x => x.share);
                        int remaining = totalJobs - assigned;

                        // ---------- باقی‌مانده → ظرفیت بیشتر ----------
                        foreach (var u in shares.OrderByDescending(x => x.capacity))
                        {
                            if (remaining <= 0) break;

                            int canTake = u.capacity - u.share;
                            int add = Math.Min(canTake, remaining);

                            u.share += add;
                            remaining -= add;
                        }

                        // ===================== تخصیص با fallback =====================
                        var givenCount = shares.ToDictionary(x => x.usr, x => 0);

                        foreach (var job in orderedJobs)
                        {
                            bool assignedToSomeone = false;

                            // کم‌کارترها اولویت بگیرند
                            foreach (var u in shares.OrderBy(x => givenCount[x.usr]))
                            {
                                if (givenCount[u.usr] >= u.share)
                                    continue;

                                // ----- چک تکرار بیش از 3 -----
                                int sentCount;

                                using (var checkCmd = new SqlCommand(@"
                            SELECT COUNT(*)
                            FROM erja_like L
                            JOIN erja_like_link LL ON LL.FK_erja_like = L.ID
                            WHERE L.FK_usr = @usr
                              AND L.FK_job = 56
                              AND L.vaziat = 0
                              AND LL.value = @val
                        ", conn))
                                {
                                    checkCmd.Parameters.AddWithValue("@usr", u.usr);
                                    checkCmd.Parameters.AddWithValue("@val", job.valuunic);

                                    sentCount = (int)await checkCmd.ExecuteScalarAsync();
                                }

                                if (sentCount >= 3)
                                    continue; // برو مأمور بعدی

                                // ----- درج -----
                                string unicFull = job.valuunic + "_" + today;

                                long erjaId;

                                using (var cmd = new SqlCommand(@"
                            INSERT INTO erja_like
                            (FK_usr, unic, vaziat, FK_job)
                            OUTPUT INSERTED.ID
                            VALUES (@usr, @unic, 0, 56)
                        ", conn))
                                {
                                    cmd.Parameters.AddWithValue("@usr", u.usr);
                                    cmd.Parameters.AddWithValue("@unic", unicFull);

                                    erjaId = (long)await cmd.ExecuteScalarAsync();
                                }

                                using (var cmd = new SqlCommand(@"
    INSERT INTO erja_like_link
    (FK_erja_like, FK_omomi, value, timesabt, vaziat)
    VALUES (@id, 79, @val, @fromDate, 0)
", conn))
                                {
                                    cmd.Parameters.AddWithValue("@id", erjaId);
                                    cmd.Parameters.AddWithValue("@val", job.valuunic);
                                    cmd.Parameters.Add("@fromDate", SqlDbType.DateTime).Value = fromDate;

                                    await cmd.ExecuteNonQueryAsync();
                                }

                                givenCount[u.usr]++;
                                assignedToSomeone = true;
                                break;
                            }

                            if (!assignedToSomeone)
                            {
                                // اینجا می‌توانی لاگ بزنی اگر هیچ مأموری نتوانست بگیرد
                            }
                        }
                    }
                }

                return Content("ok");
            }
            catch (Exception ex)
            {
                return Content(ex.ToString());
            }
        }

        private string PersianToday()
        {
            var pc = new System.Globalization.PersianCalendar();
            var now = DateTime.Now;

            return $"{pc.GetYear(now)}/{pc.GetMonth(now):00}/{pc.GetDayOfMonth(now):00}";
        }
