                                        foundMatch = true;
                                        break;
                                    }
                                }

                                if (!foundMatch)
                                {
                                    var maxO = shart5List.Max(x => x.olaviat ?? 0);
                                    result = maxO + 1;
                                }
                            }
                        }

                        // ===================== افزودن نتیجه به لیست نهایی =====================
                        var firstShart = shartGroup.FirstOrDefault();
                        if (firstShart != null)
                        {
                            int priority = firstShart.vaziat_moh == 1
                                ? GetPriorityForVaziat1((int?)firstShart.alamat)
                                : 0;

                            finalResults.Add(new MohResult
                            {
                                Valunic = groupVal.Key,
                                FK_Link = (long)shartGroup.Key,
                                Result = result,
                                Priority = priority,
                                VaziatMoh = (int)firstShart.vaziat_moh
                            });
                        }
                    }
                }

                // ===================== تعیین اولویت پویا برای vaziat_moh = 5 =====================
                var v5Groups = finalResults.Where(r => r.VaziatMoh == 5)
                                           .GroupBy(r => r.Valunic);

                foreach (var g in v5Groups)
                {
                    int dynPriority = 1;
                    foreach (var item in g.OrderBy(r => r.Result))
                    {
                        item.Priority = dynPriority;
                        dynPriority++;
                    }
                }

                // ===================== مرتب‌سازی نهایی =====================
                var sortedResults = finalResults
                    .OrderBy(r => r.Priority)
                    .ThenByDescending(r => r.Result)
                    .ToList();
                return Json(sortedResults, JsonRequestBehavior.AllowGet);

            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }
        long GetSortScore(MohResult x)
        {
            if (x.VaziatMoh == 5)
                return x.Priority;

            if (x.VaziatMoh == 1 && x.Olaviat == 6)
                return -x.Result;

            if (x.VaziatMoh == 1 && x.Olaviat == 10)
                return x.Result;

            return x.Result;
        }

