                                    var gozar2 = findFoz1.Where(f => f.dbergharel_4 != null && f.dbergharel_4.FK_namegozarwsh == s2.FK_gozaresh2)
                                                         .OrderByDescending(f => f.ID).FirstOrDefault();

                                    if (gozar1 == null || gozar2 == null) continue;

                                    string val1 = "";

                                    if (gozar1.dbergharel_4.FK_namegozarwsh == 24)
                                        val1 = findVaBace.Where(f => f.FK_dbergharelinsert_6 == gozar1.ID &&
                                                                     f.FK_db2 == s2.FK_name &&
                                                                     f.valuunic == groupVal.Key)
                                                          .OrderByDescending(f => f.ID)
                                                          .Select(f => f.valueFK_db2)
                                                          .FirstOrDefault() ?? "";
                                    else if (gozar1.dbergharel_4.FK_namegozarwsh == 25)
                                        val1 = findVal1.Where(f => f.FK_dbergharelinsert_6 == gozar1.ID &&
                                                                   f.FK_db2 == s2.FK_name &&
                                                                   f.valuunic == groupVal.Key)
                                                       .OrderByDescending(f => f.ID)
                                                       .Select(f => f.valueFK_db2)
                                                       .FirstOrDefault() ?? "";
                                    else
                                        val1 = findVal7.Where(f => f.FK_dbergharelinsert_6 == gozar1.ID &&
                                                                   f.FK_db2 == s2.FK_name &&
                                                                   f.valuunic == groupVal.Key)
                                                       .OrderByDescending(f => f.ID)
                                                       .Select(f => f.valueFK_db2)
                                                       .FirstOrDefault() ?? "";

                                    dynamic findSo1 = null;

                                    if (gozar2.dbergharel_4.FK_namegozarwsh == 24)
                                        findSo1 = findVaBace.FirstOrDefault(f => f.FK_dbergharelinsert_6 == gozar2.ID &&
                                                                                 f.valuunic == groupVal.Key &&
                                                                                 f.FK_db2 == s2.FK_name2 &&
                                                                                 f.valueFK_db2 == val1);
                                    else if (gozar2.dbergharel_4.FK_namegozarwsh == 25)
                                        findSo1 = findVal1.FirstOrDefault(f => f.FK_dbergharelinsert_6 == gozar2.ID &&
                                                                              f.valuunic == groupVal.Key &&
                                                                              f.FK_db2 == s2.FK_name2 &&
                                                                              f.valueFK_db2 == val1);
                                    else
                                        findSo1 = findVal7.FirstOrDefault(f => f.FK_dbergharelinsert_6 == gozar2.ID &&
                                                                              f.valuunic == groupVal.Key &&
                                                                              f.FK_db2 == s2.FK_name2 &&
                                                                              f.valueFK_db2 == val1);

                                    if ((s2.alamat == 2 && findSo1 != null) || (s2.alamat == 1 && findSo1 == null))
                                    {
                                        conditionMet = true; // Input_Day = 2
                                        exitAll = true;
                                        break;
                                    }
                                    else
                                    {
                                        rejectReason = $"vaziat_moh=2 failed at shartID={s2.ID}";
                                    }
                                }
                            }

                            // ================= vaziat_moh == 3 =================
                            else if (shart.vaziat_moh == 3)
                            {
                                var shart3List = findShart.Where(s => s.FK_link == shart.FK_link && s.vaziat_moh == 3).ToList();
                                foreach (var s3 in shart3List)
                                {
                                    if (exitAll) break;

                                    var gozar3 = findFoz1.Where(f => f.dbergharel_4 != null && f.dbergharel_4.FK_namegozarwsh == s3.FK_gozaresh1)
                                                         .OrderByDescending(f => f.ID).FirstOrDefault();
                                    if (gozar3 == null) continue;

                                    dynamic findSo3 = null;
                                    if (gozar3.dbergharel_4.FK_namegozarwsh == 24)
                                        findSo3 = findVaBace.FirstOrDefault(f => f.FK_dbergharelinsert_6 == gozar3.ID &&
                                                                                 f.valuunic == groupVal.Key &&
                                                                                 f.FK_db2 == s3.FK_name &&
                                                                                 f.valueFK_db2 == s3.val1);
                                    else if (gozar3.dbergharel_4.FK_namegozarwsh == 25)
                                        findSo3 = findVal1.FirstOrDefault(f => f.FK_dbergharelinsert_6 == gozar3.ID &&
                                                                              f.valuunic == groupVal.Key &&
                                                                              f.FK_db2 == s3.FK_name &&
                                                                              f.valueFK_db2 == s3.val1);
                                    else
                                        findSo3 = findVal7.FirstOrDefault(f => f.FK_dbergharelinsert_6 == gozar3.ID &&
                                                                              f.valuunic == groupVal.Key &&
                                                                              f.FK_db2 == s3.FK_name &&
                                                                              f.valueFK_db2 == s3.val1);

                                    bool condMet = (s3.shart == "=" && findSo3 != null) || (s3.shart != "=" && findSo3 == null);
                                    if (condMet)
                                    {
                                        conditionMet = true; // Input_Day = 2
                                        exitAll = true;
                                        break;
                                    }
                                    else
                                    {
                                        rejectReason = $"vaziat_moh=3 failed at shartID={s3.ID}";
                                    }
                                }
                            }
                        }
                    }

                    // ================= ذخیره نتیجه =================
                    if (conditionMet)
                    {
                        finalResult1.Add(new Result1218
                        {
                            valuunic = groupVal.Key,
                            Input_Day = 2
                        });
                    }
                    else
                    {
                        rejectedResult.Add(new Result1218_Rejected
                        {
                            valuunic = groupVal.Key,
                            Reason = rejectReason,
                            CheckDate = DateTime.Now,
                            Input_Day_ASL = DateTime.Now.Day
                        });
                    }
                }

                // ذخیره در دیتابیس
                db.Result1218.AddRange(finalResult1);
                db.Result1218_Rejected.AddRange(rejectedResult);
                await db.SaveChangesAsync();

                return Json(new { Accepted = finalResult1.Count, Rejected = rejectedResult.Count }, JsonRequestBehavior.AllowGet);
            }
            catch(Exception ex)
            {
                return Content(ex.Message);
            }
        }
        public async Task<ActionResult> MohasebeHotomat_DateTimefromDate2(DateTime fromDate)
        {
            try
            {
                var pc = new PersianCalendar();

                int shamsiYear = pc.GetYear(fromDate);
                int shamsiMonth = pc.GetMonth(fromDate);
                int shamsiDay = pc.GetDayOfMonth(fromDate);

                // تاریخ شمسی کامل به صورت رشته
                string shamsiDate =
                    $"{shamsiYear:0000}/{shamsiMonth:00}/{shamsiDay:00}";
                db.Configuration.AutoDetectChangesEnabled = false;
                var valuunicList = new List<string>
{
    "7111916509121",
    "7111951609120",
    "7111961009121",
    "7111961509124",
    "7111963909120"
};

                var findVal12 = await db.dbergharelimsertfk1_7_1218
                    .Where(x => valuunicList.Contains(x.valuunic))
                    .ToListAsync();

                var findShart = await db.olaviat_1218_link_shart
                 .Where(s=>s.olaviat_1218_alsil.vaziat==1)
                    .AsNoTracking()
                    .ToListAsync();

                var findFoz = await db.dbergharelinsert_6
                    .Include(x => x.dbergharel_4)
                    .AsNoTracking()
                    .ToListAsync();

                var fozMap = findFoz
                    .Where(x => x.dbergharel_4 != null)
                    .GroupBy(x => x.dbergharel_4.FK_namegozarwsh)
                    .ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.ID).First());

                var valuList = await db.dbergharelimsertfk1_7_1218
                    .AsNoTracking()
                    .Select(x => x.valuunic)
                    .Distinct()
                    .ToListAsync();
                var valuList2 = await db.dbergharelimsertfk1_7_1218
                                        .Where(x => valuunicList.Contains(x.valuunic))

                .AsNoTracking()
                .Select(x => x.valuunic)
                .Distinct()
                .ToListAsync();

                List<Result1218> accepted = new List<Result1218>();
                List<Result1218_Rejected> rejected = new List<Result1218_Rejected>();

                long ApplyOperation(long result, long value, long alamat)
                {
                    switch (alamat)
                    {
                        case 1: return result - value;
                        case 2: return result + value;
                        case 3: return result * value;
                        case 4: return value == 0 ? result : result / value;
                        default: return result;
                    }
                }

                bool CheckCondition(long result, string val3, long alamat)
                {
                    long n;
                    switch (alamat)
                    {
                        case 5: return result.ToString() == val3;
                        case 6:
                            var p = val3.Split(',');
                            return p.Length == 2 &&
                                   long.TryParse(p[0], out var min) &&
                                   long.TryParse(p[1], out var max) &&
                                   (result <= min || result >= max);
                        case 7: return long.TryParse(val3, out n) && result > n;
                        case 8: return long.TryParse(val3, out n) && result >= n;
                        case 9: return long.TryParse(val3, out n) && result < n;
                        case 10: return long.TryParse(val3, out n) && result <= n;
                        default: return false;
                    }
                }

                // ================= LOOP =================

                foreach (var valu in valuList)
                {
                    bool ok = false;
                    string reason = "";

                    foreach (var shartGroup in findShart.GroupBy(x => x.FK_link))
                    {
                        long result = 0;
                        long alamat = 0;
                        int index = 0;

                        foreach (var shart in shartGroup)
                        {
                            // ================= vaziat 1 =================
                            if (shart.vaziat_moh == 1)
                            {
                                if (!fozMap.TryGetValue(shart.FK_gozaresh1 ?? 0, out var foz))
                                    continue;

                                index++;
                                if (index == 1)
                                    alamat = shart.alamat ?? 0;

                                IQueryable<string> q = null;

                                if (foz.dbergharel_4.FK_namegozarwsh == 24)
                                    q = db.dbergharelimsertfk1_7_1218_bace.AsNoTracking()
                                        .Where(x => x.FK_dbergharelinsert_6 == foz.ID && x.FK_db2 == shart.FK_name && x.valuunic == valu)
                                        .Select(x => x.valueFK_db2);

                                else if (foz.dbergharel_4.FK_namegozarwsh == 25)
                                    q = db.dbergharelimsertfk1_7_1218.AsNoTracking()
                                        .Where(x => x.FK_dbergharelinsert_6 == foz.ID && x.FK_db2 == shart.FK_name && x.valuunic == valu)
                                        .Select(x => x.valueFK_db2);

                                else
                                    q = db.dbergharelimsertfk1_7.AsNoTracking()
                                        .Where(x => x.FK_dbergharelinsert_6 == foz.ID && x.FK_db2 == shart.FK_name && x.valuunic == valu)
                                        .Select(x => x.valueFK_db2);

                                var valueStr = await q.FirstOrDefaultAsync();
                                if (valueStr == null) continue;

                                long value = long.TryParse(valueStr, out var v) ? v : 0;

                                if (shart.alamat <= 4)
                                {
                                    result = ApplyOperation(result, value, alamat);
                                    alamat = shart.alamat ?? 0;
                                }
                                else
                                {
                                    result = ApplyOperation(result, value, alamat);
                                    if (CheckCondition(result, shart.val3, shart.alamat ?? 0))
                                    {
                                        ok = true;
                                        break;
                                    }
                                    reason = $"fail v1 {shart.ID}";
                                }
                            }

                            // ================= vaziat 2 =================
                            else if (shart.vaziat_moh == 2)
                            {
                                var list2 = shartGroup.Where(x => x.vaziat_moh == 2);

                                foreach (var s2 in list2)
                                {
                                    if (!fozMap.TryGetValue(s2.FK_gozaresh1 ?? 0, out var g1)) continue;
                                    if (!fozMap.TryGetValue(s2.FK_gozaresh2 ?? 0, out var g2)) continue;

                                    var val1 = await db.dbergharelimsertfk1_7_1218
                                        .AsNoTracking()
                                        .Where(x => x.FK_dbergharelinsert_6 == g1.ID &&
                                                    x.FK_db2 == s2.FK_name &&
                                                    x.valuunic == valu)
                                        .Select(x => x.valueFK_db2)
                                        .FirstOrDefaultAsync();

                                    if (val1 == null) continue;

                                    bool exists = await db.dbergharelimsertfk1_7_1218
                                        .AsNoTracking()
                                        .AnyAsync(x => x.FK_dbergharelinsert_6 == g2.ID &&
                                                       x.FK_db2 == s2.FK_name2 &&
                                                       x.valuunic == valu &&
                                                       x.valueFK_db2 == val1);

                                    if ((s2.alamat == 2 && exists) || (s2.alamat == 1 && !exists))
                                    {
                                        ok = true;
                                        break;
                                    }

                                    reason = $"fail v2 {s2.ID}";
                                }

                                if (ok) break;
                            }

                            // ================= vaziat 3 =================
                            else if (shart.vaziat_moh == 3)
                            {
                                var list3 = shartGroup.Where(x => x.vaziat_moh == 3);

                                foreach (var s3 in list3)
                                {
                                    if (!fozMap.TryGetValue(s3.FK_gozaresh1 ?? 0, out var g3))
                                        continue;

                                    bool exists = await db.dbergharelimsertfk1_7_1218
                                        .AsNoTracking()
                                        .AnyAsync(x => x.FK_dbergharelinsert_6 == g3.ID &&
                                                       x.FK_db2 == s3.FK_name &&
                                                       x.valuunic == valu &&
                                                       x.valueFK_db2 == s3.val1);

                                    bool cond = (s3.shart == "=" && exists) || (s3.shart != "=" && !exists);

                                    if (cond)
                                    {
                                        ok = true;
                                        break;
                                    }

                                    reason = $"fail v3 {s3.ID}";
                                }

                                if (ok) break;
                            }
                        }

                        if (ok) break;
                    }

                    if (ok)
                        accepted.Add(new Result1218 { valuunic = valu, Input_Day = 2 ,Input_Day_ASL= shamsiDay ,Input_Year= shamsiYear,Input_Month= shamsiMonth });
                    //else
                    //    rejected.Add(new Result1218_Rejected
                    //    {
                    //        valuunic = valu,
                    //        Reason = reason,
                    //        CheckDate = DateTime.Now,
                    //        Input_Day_ASL = DateTime.Now.Day
                    //    });

                    if (accepted.Count + rejected.Count >= 5000)
                    {
                        db.Result1218.AddRange(accepted);
                        //db.Result1218_Rejected.AddRange(rejected);
                        await db.SaveChangesAsync();
                        accepted.Clear();
                        rejected.Clear();
                    }
                }

                if (accepted.Any())
                {
                    db.Result1218.AddRange(accepted);
                    //db.Result1218_Rejected.AddRange(rejected);
                    await db.SaveChangesAsync();
                }

                db.Configuration.AutoDetectChangesEnabled = true;
                var totalAccepted = accepted.Count;
                var totalRejected = rejected.Count;

                return Json(new
                {
                    status = true,
                    message = "پردازش شرط‌ها با موفقیت انجام شد",
                    fromDate = fromDate,
                    acceptedCount = totalAccepted,
                    rejectedCount = totalRejected,
                    total = totalAccepted + totalRejected,
                    sampleRejected = rejected.Take(10).Select(x => new {
                        x.valuunic,
                        x.Reason
                    })
                }, JsonRequestBehavior.AllowGet);
                //return Json(new { OK = true }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    status = false,
                    message = ex.Message
                }, JsonRequestBehavior.AllowGet);
            }

        }

