        public async Task<ActionResult> MohasebeHotomat1()
        {
            // دریافت کل موجودیت‌ها از دیتابیس
            var findVal1 = await db.dbergharelimsertfk1_7_1218.ToListAsync();
            var findVal7 = await db.dbergharelimsertfk1_7
                                  .Where(s => s.FK_dbergharelinsert_6 == 20440)
                                  .ToListAsync();
            var findVaBace = await db.dbergharelimsertfk1_7_1218_bace.ToListAsync();
            var findShart = await db.olaviat_1218_link_shart.ToListAsync();
            var findFoz = await db.dbergharelinsert_6.Include(x => x.dbergharel_4).ToListAsync();

            List<dbergharelimsertfk1_7_1218> resultList = new List<dbergharelimsertfk1_7_1218>();

            // تابع کمکی برای اعمال عملیات ریاضی (alamat 1 تا 4)
            long ApplyOperation(long result, long value, long alamat)
            {
                switch (alamat)
                {
                    case 1: return result - value;
                    case 2: return result + value;
                    case 3: return result * value;
                    case 4: return value == 0 ? result : result / value; // جلوگیری از تقسیم بر صفر
                    default: return result;
                }
            }

            // تابع کمکی برای بررسی شروط 5 تا 10
            bool CheckCondition(long result, string val3, long alamat)
            {
                long numericVal;
                switch (alamat)
                {
                    case 5: // مساوی
                        return result.ToString() == val3;
                    case 6: // بازه "min,max"
                        var parts = val3.Split(',');
                        if (parts.Length == 2 &&
                            long.TryParse(parts[0], out long min) &&
                            long.TryParse(parts[1], out long max))
                            return result <= min || result >= max;
                        return false;
                    case 7: // بزرگ‌تر
                        return long.TryParse(val3, out numericVal) && result > numericVal;
                    case 8: // بزرگ‌تر یا مساوی
                        return long.TryParse(val3, out numericVal) && result >= numericVal;
                    case 9: // کوچکتر
                        return long.TryParse(val3, out numericVal) && result < numericVal;
                    case 10: // کوچکتر یا مساوی
                        return long.TryParse(val3, out numericVal) && result <= numericVal;
                    default:
                        return false;
                }
            }

            // حلقه اصلی گروه‌بندی بر اساس valuunic
            foreach (var groupVal in findVal1.GroupBy(s => s.valuunic))
            {
                bool exitAll = false;

                foreach (var shartGroup in findShart.GroupBy(s => s.FK_link))
                {
                    if (exitAll) break;

                    var shartList = shartGroup.ToList();
                    long result = 0;
                    long alamat = 0;

                    foreach (var shart in shartList)
                    {
                        if (exitAll) break;

                        if (shart.vaziat_moh == 1)
                        {
                            var fozRecord = findFoz.Where(f => f.dbergharel_4.FK_namegozarwsh == shart.FK_gozaresh1)
                                                   .OrderByDescending(f => f.ID)
                                                   .FirstOrDefault();

                            if (fozRecord != null)
                            {
                                dynamic findSo = null;

                                if (fozRecord.dbergharel_4.FK_namegozarwsh == 24)
                                {
                                    findSo = findVaBace.FirstOrDefault(f =>
                                        f.FK_dbergharelinsert_6 == fozRecord.ID &&
                                        f.FK_db2 == shart.FK_name &&
                                        f.valuunic == groupVal.Key);
                                }
                                else if (fozRecord.dbergharel_4.FK_namegozarwsh == 25)
                                {
                                    findSo = findVal1.FirstOrDefault(f =>
                                        f.FK_dbergharelinsert_6 == fozRecord.ID &&
                                        f.FK_db2 == shart.FK_name &&
                                        f.valuunic == groupVal.Key);
                                }
                                else
                                {
                                    findSo = findVal7.FirstOrDefault(f =>
                                        f.FK_dbergharelinsert_6 == fozRecord.ID &&
                                        f.FK_db2 == shart.FK_name &&
                                        f.valuunic == groupVal.Key);
                                }

                                if (findSo != null && !string.IsNullOrEmpty(findSo.valueFK_db2))
                                {
                                    // nullable handling و تبدیل صریح
                                    long value = 0;
                                    if (long.TryParse(findSo.valueFK_db2, out long parsedValue))
                                        value = parsedValue;

                                    // nullable handling برای alamat
                                    long alamatValue = shart.alamat ?? 0;

                                    result = ApplyOperation(result, value, alamatValue);

                                    if (CheckCondition(result, shart.val3, alamatValue))
                                    {
                                        resultList.AddRange(findVal1.Where(s => s.valuunic == groupVal.Key));
                                        exitAll = true;
                                        break;
                                    }

                                    alamat = alamatValue;
                                }
                            }
                        }
                    }
                }
            }

            return Json(resultList, JsonRequestBehavior.AllowGet);
        }


