        [HttpPost]
        public ActionResult SaveNahayeOlaviat1218(List<long> order, List<ChkState> checkboxStates)
        {


            long olaviatCounter = 1;
            foreach (var id in order)
            {
                var row = db.olaviat_1218_alsil.FirstOrDefault(x => x.ID == id);
                if (row != null)
                {
                    row.olavait = olaviatCounter;
                    olaviatCounter++;
                }
            }


            foreach (var item in checkboxStates)
            {
                var row = db.olaviat_1218_alsil.FirstOrDefault(x => x.ID == item.id);
                if (row != null)
                {
                    row.vaziat = item.vaziat;
                }
            }

            db.SaveChanges();


            return Json("OK", JsonRequestBehavior.AllowGet);
        }
