        [HttpPost]
        public ActionResult SaveOlaviat1218Calc2(OlaviatCalcSaveVM2 model)
        {
            try
            {
                using (SaabEntities db = new SaabEntities())
                {
                    if (model.Rows == null || !model.Rows.Any())
                        return Json(new { success = false, message = "هیچ ردیفی برای محاسبات وارد نشده است" });

                    // ابتدا ردیف‌های قبلی این کاربر را غیرفعال یا حذف کنید (اختیاری بر اساس نیاز پروژه)
                    // var oldRows = db.olaviat_1218_link_shart.Where(x => x.FK_link == model.UserId && x.vaziat_moh == 1);
                    // db.olaviat_1218_link_shart.RemoveRange(oldRows);

                    // استخراج اولین شرط (اگر وجود داشته باشد)
                    var firstCondition = model.IfConditions != null ? model.IfConditions.FirstOrDefault() : null;

                    foreach (var row in model.Rows)
                    {
                        var entity = new olaviat_1218_link_shart
                        {
                            FK_link = model.UserId,
                            FK_gozaresh1 = row.FK_gozaresh1,
                            FK_name = row.FK_name,
                            alamat = row.alamat,
                            val1 = model.Val1,
                            val2 = model.Val2,
                            val3 = model.Val3,

                            // فیلدهای مربوط به IF (بر اساس لیست شرط‌ها)
                            isif = model.IsIf,
                            // اگر شرط فعال بود، اطلاعات اولین شرط را در ردیف‌های محاسباتی ست می‌کنیم
                            FK_gozaresh_if = (model.IsIf == 1 && firstCondition != null) ? firstCondition.FK_gozaresh_if : null,
                            FK_name_if = (model.IsIf == 1 && firstCondition != null) ? firstCondition.FK_name_if : null,
                            alamat_if = (model.IsIf == 1 && firstCondition != null) ? firstCondition.alamat_if : null,
                            alamat_if_str = (model.IsIf == 1 && firstCondition != null) ? GetAlamatSign(firstCondition.alamat_if) : null,
                            shart_value = (model.IsIf == 1 && firstCondition != null) ? firstCondition.shart_value : null,

                            time_sabt = DateTime.Now,
                            FK_usr = (int)model.UserId,
                            vaziat_moh = 1,
                            actove = 1
                        };

                        db.olaviat_1218_link_shart.Add(entity);
                    }

                    // نکته مهم: اگر بیش از یک شرط (AND/OR) دارید، 
                    // باید ردیف‌های اضافی با vaziat_moh متفاوتی (مثلاً 4) ذخیره کنید 
                    // تا در زمان محاسبه، موتور پردازشگر شما بداند این‌ها شرط‌های تکمیلی هستند.
                    if (model.IsIf == 1 && model.IfConditions != null && model.IfConditions.Count > 1)
                    {
                        // ذخیره شرط‌های دوم به بعد
                        foreach (var cond in model.IfConditions.Skip(1))
                        {
                            var condEntity = new olaviat_1218_link_shart
                            {
                                FK_link = model.UserId,
                                isif = 1,
                                FK_gozaresh_if = cond.FK_gozaresh_if,
                                FK_name_if = cond.FK_name_if,
                                alamat_if = cond.alamat_if,
                                alamat_if_str = GetAlamatSign(cond.alamat_if),
                                shart_value = cond.shart_value,
                                // منطق AND/OR را می‌توانید در یک ستون جدید مثل logic_type یا در فیلد ملاحظات ذخیره کنید
                                val1 = cond.logic,

                                vaziat_moh = 1, // کد قراردادی برای "ادامه شرط‌های IF"
                                time_sabt = DateTime.Now,
                                FK_usr = (int)model.UserId,
                                actove = 1
                            };
                            db.olaviat_1218_link_shart.Add(condEntity);
                        }
                    }

                    db.SaveChanges();
                    return Json(new { success = true });
                }
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.InnerException?.Message ?? ex.Message });
            }
        }

        // متد کمکی برای تبدیل کد علامت به رشته
        private string GetAlamatSign(int? alamat)
        {
            switch (alamat)
            {
                case 1: return "=";
                case 2: return "!=";
                case 3: return ">";
                case 4: return "<";
                case 5: return ">=";
                case 6: return "<=";
                default: return "";
            }
        }


