    long? mablagh1_1, long? vaziat1, long? mablagh1_2, long? vaziat2)
        {
            try
            {
                using (var db = new SaabEntities())
                {


                    var existing = db.olaviat_1218_link.FirstOrDefault(x => x.FK_olaviat == FK_olaviat && x.input2 == input2);
                    if (existing != null)
                    {
                        existing.input1 = input1;
                        existing.input2 = input2;
                        existing.FK_db2 = FK_db2;
                        existing.FK_db4_4 = FK_db4_4;
                        existing.mablagh1_1 = mablagh1_1;
                        existing.vaziat1 = vaziat1;
                        existing.mablagh1_2 = mablagh1_2;
                        existing.vaziat2 = vaziat2;
                        existing.time = DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss");

                        db.SaveChanges();
                        return Json(new { success = true, message = "رکورد آپدیت شد" });
                    }



                    var entity = new olaviat_1218_link
                    {
                        FK_olaviat = FK_olaviat,
                        input1 = input1,
                        input2 = input2,
                        FK_db2 = FK_db2,
                        FK_db4_4 = FK_db4_4,
                        mablagh1_1 = mablagh1_1,
                        vaziat1 = vaziat1,
                        mablagh1_2 = mablagh1_2,
                        vaziat2 = vaziat2,
                        time = DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss")
                    };

                    db.olaviat_1218_link.Add(entity);
                    db.SaveChanges();
                }

                return Json(new { success = true, message = "رکورد جدید ثبت شد" });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }
