        //http://localhost:6061/Setting/Orders/tarighrozbadandghabl?day=28&year=1404&month=10
        //تاریخ
        public ActionResult tarighrozbadandghabl(int day = 0, int year = 0, int month = 0)
        {
            int day1 = 8;
            int day31 = 62;

            int day2 = 30;
            int day3 = 365;
            if (day == 0)
            {
                day = 19;
                year = 1404;
                month = 10;


            }
            //var del = db.Result1218_tarigh.RemoveRange(db.Result1218_tarigh.ToList());
            db.Result1218_tarigh.RemoveRange(db.Result1218_tarigh.ToList());
            // امروز شمسی
            var today = DateTime.Now;

                // تبدیل تاریخ امروز به شمسی (1404/08/29)
                PersianCalendar pc = new PersianCalendar();
                int y = pc.GetYear(today);
                int m = pc.GetMonth(today);
                int d = pc.GetDayOfMonth(today);
            DateTime endDate = new DateTime(1404, 1, 1, pc);

            DateTime shamsiToday = new DateTime(y, m, d, pc);
            DateTime startDate = new DateTime(year, month, day, pc);

            shamsiToday = new DateTime(year, month, day, pc);
            // ----------- ثبت وضعیت 1 از امروز تا day1 روز قبل -----------

            for (int i = 0; i <=day1; i++)
                {
                    DateTime t = shamsiToday.AddDays(-i);

                string shDate = $"{pc.GetYear(t)}/{pc.GetMonth(t):00}/{pc.GetDayOfMonth(t):00}";
                //string shDate = "1";

                Result1218_tarigh item = new Result1218_tarigh()
                    {
                        start_tme = shDate,
                        strart_end = shDate,
                        vaziat = 1,
                        active = 1
                    };

                    db.Result1218_tarigh.Add(item);
                }

                // ----------- ثبت وضعیت 2 از آخر day1 تا day2 روز قبل -----------

                for (int i = 0; i <=day2; i++)
                {
                    DateTime t = shamsiToday.AddDays(-i);

                    string shDate = $"{pc.GetYear(t)}/{pc.GetMonth(t):00}/{pc.GetDayOfMonth(t):00}";

                    Result1218_tarigh item = new Result1218_tarigh()
                    {
                        start_tme = shDate,
                        strart_end = shDate,
                        vaziat = 2,
                        active = 1
                    };

                    db.Result1218_tarigh.Add(item);
            }
            for (int i = 0; i <= day31; i++)
            {
                DateTime t = shamsiToday.AddDays(-i);

                string shDate = $"{pc.GetYear(t)}/{pc.GetMonth(t):00}/{pc.GetDayOfMonth(t):00}";

                Result1218_tarigh item = new Result1218_tarigh()
                {
                    start_tme = shDate,
                    strart_end = shDate,
                    vaziat = 4,
                    active = 1
                };

                db.Result1218_tarigh.Add(item);
            }
            //for (int i = 0; i <= day3; i++)
            //{
            //    DateTime t = shamsiToday.AddDays(-i);

            //    string shDate = $"{pc.GetYear(t)}/{pc.GetMonth(t):00}/{pc.GetDayOfMonth(t):00}";

            //    Result1218_tarigh item = new Result1218_tarigh()
            //    {
            //        start_tme = shDate,
            //        strart_end = shDate,
            //        vaziat = 3,
            //        active = 1
            //    };

            //    db.Result1218_tarigh.Add(item);
            //}
            DateTime currentDate = startDate;

            while (currentDate >= endDate)
            {
                string shDate = $"{pc.GetYear(currentDate)}/{pc.GetMonth(currentDate):00}/{pc.GetDayOfMonth(currentDate):00}";

                Result1218_tarigh item = new Result1218_tarigh()
                {
                    start_tme = shDate,
                    strart_end = shDate,
                    vaziat = 3,
                    active = 1
                };

                db.Result1218_tarigh.Add(item);

                currentDate = currentDate.AddDays(-1); // یک روز عقب
            }
            //DateTime currentDate = startDate;

            //DateTime currentDate = startDate;
            //for (int i = 0; i <= 1000; i++)
            //{
            //    DateTime t = startDate.AddDays(-i);

            //    int vaziat = (i / 60) + 4;
