        public async Task<string> GetDataFromExcel_zarfiat(HttpPostedFileBase MyExcelStream)
        {
            try
            {
                if (MyExcelStream == null || MyExcelStream.ContentLength == 0)
                    return "فایل ارسال نشده است.";

                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration()
                    {
                        ConfigureDataTable = _ => new ExcelDataTableConfiguration()
                        {
                            UseHeaderRow = true
                        }
                    });
                    
                    var sheet = dataSet.Tables[0];
                    if (sheet.Rows.Count == 0)
                        return "فایل اکسل فاقد داده است.";
                    var list = db.tbzarfiat_usr.ToList();
                    var usr = db.tbUsers.ToList();
                    List<tbzarfiat_usr> tbzarfiat_usr = new List<tbzarfiat_usr>();
                    foreach (DataRow row in sheet.Rows)
                    {
                        int.TryParse(row["کد پرسنلی"]?.ToString(), out int personalCode);

                        // 1. دریافت کد پرسنلی (تبدیل به استرینگ برای مقایسه راحت‌تر با دیتابیس)
                        //personalCode = row["کد پرسنلی"]?.ToString()?.Trim();

                        //if (string.IsNullOrEmpty(personalCode))
                        //    continue;

                        // پیدا کردن کاربر در جدول کاربران
                        var user = usr.FirstOrDefault(x => x.usr_Personal_ID == personalCode);
                        if (user == null)
                            continue; // اگر کاربر با این کد پرسنلی وجود نداشت، برو ردیف بعدی

                        // 2. دریافت مقادیر عددی (شغل و وضعیت)
                        // اگر در اکسل عدد وارد شده، مستقیماً Parse می‌کنیم
                        //int.TryParse(row["شغل"]?.ToString(), out int job);
                        //int.TryParse(row["فعال /غیر فعال"]?.ToString(), out int vaziat);

                        //// 3. دریافت مناطق (6 منطقه)
                        //int.TryParse(row["منطقه 1"]?.ToString(), out int m1);
                        //int.TryParse(row["منطقه 2"]?.ToString(), out int m2);
                        //int.TryParse(row["منطقه 3"]?.ToString(), out int m3);
                        //int.TryParse(row["منطقه 4"]?.ToString(), out int m4);
                        //int.TryParse(row["منطقه 5"]?.ToString(), out int m5);
                        //int.TryParse(row["منطقه 6"]?.ToString(), out int m6);
                        int.TryParse(row[2]?.ToString(), out int job);
                        int.TryParse(row[3]?.ToString(), out int vaziat);

                        int.TryParse(row[4]?.ToString(), out int m1);
                        int.TryParse(row[5]?.ToString(), out int m2);
                        int.TryParse(row[6]?.ToString(), out int m3);
                        int.TryParse(row[7]?.ToString(), out int m4);
                        int.TryParse(row[8]?.ToString(), out int m5);
                        int.TryParse(row[9]?.ToString(), out int m6);

                        // 4. عملیات Update یا Insert در جدول ظرفیت
                        var find = list.FirstOrDefault(x => x.FK_usr == user.usr_ID);

                        if (find != null)
                        {
                            // آپدیت رکورد موجود
                            find.job = job;
                            find.mantagheh7 = vaziat; // وضعیت در ستون 7 ذخیره می‌شود
                            find.mantagheh1 = m1;
                            find.mantagheh2 = m2;
                            find.mantagheh3 = m3;
                            find.mantagheh4 = m4;
                            find.mantagheh5 = m5;
                            find.mantagheh6 = m6;
                        }
                        else
                        {
                            // ایجاد رکورد جدید
                            tbzarfiat_usr item = new tbzarfiat_usr()
                            {
                                FK_usr = user.usr_ID,
                                job = job,
                                mantagheh7 = vaziat,
                                mantagheh1 = m1,
                                mantagheh2 = m2,
                                mantagheh3 = m3,
                                mantagheh4 = m4,
                                mantagheh5 = m5,
                                mantagheh6 = m6
                            };
                            tbzarfiat_usr.Add(item);
                        }
                    }
                    db.tbzarfiat_usr.AddRange(tbzarfiat_usr);
                    await db.SaveChangesAsync();
                    return "True";
                }
            }
            catch (Exception ex)
            {
                return "❌ خطا در پردازش فایل: " + ex.Message;
            }
        }
        public async Task<string> GetDataFromExcel_zarfiat3(HttpPostedFileBase MyExcelStream, int vaz)
        {
            try
            {
                if (MyExcelStream == null || MyExcelStream.ContentLength == 0)
                    return "فایل ارسال نشده است.";

                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null) return "کاربر یافت نشد";

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user3 = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user3 == null) return "کاربر یافت نشد";

                string cityname = "";
                var findcit = db.tbCities.FirstOrDefault(s => s.ID == user3.usr_City_Dutysystem);
                if (findcit != null) cityname = findcit.Name;

                long val = GetCityValue_2(cityname);
                long val2 = (long)((6*val) * 0.4); // سقف مجاز

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration()
                    {
                        ConfigureDataTable = _ => new ExcelDataTableConfiguration() { UseHeaderRow = true }
                    });

                    var sheet = dataSet.Tables[0];
                    if (sheet.Rows.Count == 0) return "فایل اکسل فاقد داده است.";

                    var users = db.tbUsers.ToList();
                    var userMap = users.Where(x => x.usr_Personal_ID != null)
                                       .GroupBy(x => x.usr_Personal_ID)
                                       .ToDictionary(x => x.Key, x => x.First());

                    // دریافت مبالغ قبلی از دیتابیس (اگر میخواهید فقط مبالغ همین vaz چک شود، شرط vaz را اضافه کنید)
                    var existingAmounts = db.dbergha6
                        .Where(x => x.FK_usr != null && x.mablagh != null)
                        .GroupBy(x => x.FK_usr.Value)
                        .ToDictionary(x => x.Key, x => x.Sum(y => (long?)y.mablagh) ?? 0);

                    List<dbergha6> newRecords = new List<dbergha6>();
                    var newFileAmountsByPersonalCode = new Dictionary<int, long>();

                    System.Globalization.PersianCalendar pc = new System.Globalization.PersianCalendar();
                    DateTime now = DateTime.Now;
                    int year = pc.GetYear(now); int month = pc.GetMonth(now); int day = pc.GetDayOfMonth(now);
                    var nowDb = DateTime.Now; // یا DateTime.UtcNow
                    int rowIndex = 1;                  // برای نمایش شماره ردیف (در حالت UseHeaderRow=true)

                    foreach (DataRow row in sheet.Rows)
                    {
                        rowIndex++;

                        // 1) کد پرسنلی
                        var pCodeText = row[1]?.ToString()?.Trim();

                        if (string.IsNullOrWhiteSpace(pCodeText))
                            return $"❌ ردیف {rowIndex}: کد پرسنلی خالی است.";

                        if (!int.TryParse(pCodeText, out int pCode) || pCode <= 0)
                            return $"❌ ردیف {rowIndex}: کد پرسنلی نامعتبر است: {pCodeText}";

                        // 2) پیدا نشدن کد پرسنلی در سیستم
                        if (!userMap.TryGetValue(pCode, out var user))
                            return $"❌ ردیف {rowIndex}: کد پرسنلی {pCode} در سیستم یافت نشد.";
                        //int.TryParse(row[1]?.ToString()?.Trim(), out int pCode);
                        //if (pCode == 0) continue;

                        var amountText = row[3]?.ToString()?.Trim().Replace(",", "").Replace("٬", "");
                        if (!long.TryParse(amountText, out long amount)) continue;

                        //if (!userMap.TryGetValue(pCode, out var user)) continue;

                        // جمع زدن مقادیر فایل جدید
                        if (newFileAmountsByPersonalCode.ContainsKey(pCode))
                            newFileAmountsByPersonalCode[pCode] += amount;
                        else
                            newFileAmountsByPersonalCode[pCode] = amount;

                        newRecords.Add(new dbergha6
                        {
                            FK_usr = user.usr_ID,
                            mablagh = amount,
                            mablagh2 = amount.ToString(),
                            vaz = vaz,
                            parvande = (vaz == 1 ? row[2]?.ToString()?.Trim() : null),
                            shenaseh = (vaz != 1 ? row[2]?.ToString()?.Trim() : null),
                            yaer = year,
                            month = month,
                            timesabt = nowDb,  
                            vaziiat=1,
                            // ✅ زمان ثبت
                            FK_usr_dabt = user3.usr_ID,       // ✅ (اختیاری) کاربری که فایل را آپلود کرده
                            Fullname_sabt = user3.FullName, //
                            day = day
                        });
                    }

                    // چک کردن سقف نهایی (دیتابیس + فایل جدید)
                    foreach (var item in newFileAmountsByPersonalCode)
                    {
                        if (userMap.TryGetValue(item.Key, out var user))
                        {
                            long oldAmt = existingAmounts.ContainsKey(user.usr_ID) ? existingAmounts[user.usr_ID] : 0;
                            if (oldAmt + item.Value > val2)
                            {
                                return $"کد پرسنلی {item.Key} از حد مجاز رد شده است. " +
                                       $"سقف: {val2:N0} | مجموع قبلی: {oldAmt:N0} | فایل فعلی: {item.Value:N0}";
                            }
                        }
                    }

                    if (newRecords.Count == 0) return "داده معتبری یافت نشد.";

                    db.dbergha6.AddRange(newRecords);
                    await db.SaveChangesAsync();
                    return "True";
                }
            }
            catch (Exception ex)
            {
                return "❌ خطا: " + ex.Message;
            }
        }

