        public string GetDataFromExcel_CityPriority(HttpPostedFileBase MyExcelStream)
        {
            //ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

            var errorLogs = new List<string>();

            try
            {
                using (var package = new ExcelPackage(MyExcelStream.InputStream))
                using (var db = new SaabEntities())
                using (var tran = db.Database.BeginTransaction())
                {
                    var ws = package.Workbook.Worksheets[0];
                    if (ws == null)
                        return "شیت اول یافت نشد";

                    int lastRow = ws.Dimension.End.Row;
                    int lastCol = ws.Dimension.End.Column;
                    int dayStartCol = 4; // ستون D

                    // --- کش کردن داده‌های دیتابیس (افزایش سرعت) ---
                    var dbData = db.CityPriority.ToList();

                    var insertList = new List<CityPriority>();

                    for (int row = 2; row <= lastRow; row++)
                    {
                        string cityName = ws.Cells[row, 1].Text?.Trim();

                        if (string.IsNullOrWhiteSpace(cityName))
                            continue;

                        for (int col = dayStartCol; col <= lastCol; col++)
                        {
                            try
                            {
                                string dayText = ws.Cells[1, col].Text?.Trim();
                                string priorityText = ws.Cells[row, col].Text?.Trim();

                                if (string.IsNullOrWhiteSpace(dayText))
                                    continue;

                                if (!int.TryParse(dayText, out int dayNumber))
                                {
                                    errorLogs.Add($"ردیف 1 ستون {col}: day_number نامعتبر");
                                    continue;
                                }

                                int? priorityVal = null;
                                if (!string.IsNullOrWhiteSpace(priorityText))
                                {
                                    if (int.TryParse(priorityText, out int p))
                                        priorityVal = p;
                                    else
                                    {
                                        errorLogs.Add($"ردیف {row} ستون {col}: priority نامعتبر");
                                        continue;
                                    }
                                }

                                var record = dbData.FirstOrDefault(x =>
                                    x.city_name == cityName &&
                                    x.day_number == dayNumber
                                );

                                if (record != null)
                                {
                                    // UPDATE
                                    record.priority = priorityVal;
                                }
                                else
                                {
                                    // INSERT
                                    insertList.Add(new CityPriority
                                    {
                                        city_name = cityName,
                                        day_number = dayNumber,
                                        priority = priorityVal
                                    });
                                }
                            }
                            catch (Exception exCell)
                            {
                                errorLogs.Add(
                                    $"خطا در شهر '{cityName}' | ردیف {row} | ستون {col} : {exCell.Message}"
                                );
                            }
                        }
                    }

                    // --- Bulk Insert ---
                    if (insertList.Any())
                        db.CityPriority.AddRange(insertList);

                    db.SaveChanges();
                    tran.Commit();

                    if (errorLogs.Any())
                    {
                        return "ذخیره انجام شد، اما خطاها:\n" + string.Join("\n", errorLogs);
                    }

                    return "عملیات CityPriority با موفقیت انجام شد.";
                }
            }
            catch (Exception ex)
            {
                return "خطای کلی: " + ex.Message;
            }
        }

        public string GetDataFromExcel_CityPriority2(HttpPostedFileBase MyExcelStream)
        {
            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
            var errorLogs = new List<string>();

            try
            {
                using (var db = new SaabEntities())
                using (var tran = db.Database.BeginTransaction())
                using (var package = new ExcelPackage(MyExcelStream.InputStream))
                {
                    var ws = package.Workbook.Worksheets[0];
                    if (ws?.Dimension == null) return "فایل اکسل خالی است یا شیت یافت نشد.";

                    int lastRow = ws.Dimension.End.Row;
                    int lastCol = ws.Dimension.End.Column;
                    int dayStartCol = 4;

                    // --- بهینه‌سازی: کش کردن داده‌ها در دیکشنری برای سرعت فوق‌العاده ---
                    // کلید دیکشنری ترکیبی از نام شهر و شماره روز است
                    var dbDataDict = db.CityPriority
                                       .AsNoTracking() // برای سرعت بیشتر در خواندن
                                       .ToDictionary(x => $"{x.city_name}_{x.day_number}", x => x);

                    var insertList = new List<CityPriority>();
                    var updateList = new List<CityPriority>();

                    for (int row = 2; row <= lastRow; row++)
                    {
                        string cityName = ws.Cells[row, 1].Text?.Trim();
                        if (string.IsNullOrEmpty(cityName)) continue;

                        for (int col = dayStartCol; col <= lastCol; col++)
                        {
                            try
                            {
                                string dayText = ws.Cells[1, col].Value?.ToString();
                                string priorityText = ws.Cells[row, col].Value?.ToString();

                                if (!int.TryParse(dayText, out int dayNumber)) continue;

                                int? priorityVal = null;
                                if (int.TryParse(priorityText, out int p)) priorityVal = p;

                                // جستجوی سریع در دیکشنری به جای دیتابیس
                                string key = $"{cityName}_{dayNumber}";

                                if (dbDataDict.TryGetValue(key, out var existingRecord))
                                {
                                    // عملیات آپدیت (باید رکورد را به Context متصل کنیم)
                                    var recordToUpdate = db.CityPriority.Find(existingRecord.ID); // فرض بر داشتن PK به نام id
                                    if (recordToUpdate != null)
                                    {
                                        recordToUpdate.priority = priorityVal;
                                    }
                                }
                                else
                                {
                                    // عملیات درج جدید
                                    insertList.Add(new CityPriority
                                    {
                                        city_name = cityName,
                                        day_number = dayNumber,
                                        priority = priorityVal
                                    });
                                }
                            }
                            catch (Exception ex)
                            {
                                errorLogs.Add($"خطا در ردیف {row} ستون {col}: {ex.Message}");
                            }
                        }
                    }

                    // انجام عملیات نهایی
                    if (insertList.Any()) db.CityPriority.AddRange(insertList);

                    db.SaveChanges();
                    tran.Commit();

                    return errorLogs.Any()
                        ? "ذخیره شد، اما با خطا: \n" + string.Join("\n", errorLogs.Take(10)) // نمایش فقط ۱۰ خطای اول
                        : "عملیات با موفقیت کامل انجام شد.";
                }
            }
            catch (Exception ex)
            {
                return "خطای بحرانی: " + ex.Message;
            }
        }


