            var jobs = new List<(string JobName, Func<dbdashbordmamor, double?> Selector)>
{
    ("کارشناس ستادی", x => x.job9),
    ("انبار داری", x => x.job8),
    ("نماینده مقیم", x => x.job7),
    ("ارزیاب", x => x.job6),
    ("پلیس برق", x => x.job5),
    ("نصب و اصلاح", x => x.job4),
    ("متصدی مشترکین", x => x.job3),
    ("وصول", x => x.job2),
    ("قرائت", x => x.job10)
};

            foreach (var job in jobs)
            {
                var values = data
                    .Select(job.Selector)
                    .Where(v => v.HasValue)
                    .Select(v => v.Value)
                    .ToList();

                var total = values.Count;

                // جلوگیری از تقسیم بر صفر
                if (total == 0)
                    total = 1;

                var under25 = values.Count(v => v < 0.25);
                var from25To50 = values.Count(v => v >= 0.25 && v < 0.50);
                var from50To75 = values.Count(v => v >= 0.50 && v < 0.75);
                var from75To100 = values.Count(v => v >= 0.75 && v <= 1.0);
                var over100 = values.Count(v => v > 1.0);

                var userRow = new FunctionModel.UserRow
                {
                    JobName = job.JobName,

                    Values = new Dictionary<string, decimal>
        {
            { "Under25", Math.Round((decimal)under25 * 100 / total, 0) },
            { "25_50", Math.Round((decimal)from25To50 * 100 / total, 0) },
            { "50_75", Math.Round((decimal)from50To75 * 100 / total, 0) },
            { "75_100", Math.Round((decimal)from75To100 * 100 / total, 0) },
            { "Over100", Math.Round((decimal)over100 * 100 / total, 0) },
            { "Total", values.Count } // اگر خواستی اینو حذف کن
        },

                    RawValues = values
                };

                model.Users.Add(userRow);
            }


            //var chart2Series = new List<FunctionModel.ChartSeries>();

            var categories = new List<string>
{
    "وصول",
    "قرائت",
    "متصدی مشترکین",
    "نصب و اصلاح",
    "پلیس برق",
    "ارزیاب",
    "نماینده مقیم",
    "انبار داری",
    "کارشناس ستادی"
};

            var chart2Series = data
                .GroupBy(x => x.jobname)   // گروه بندی بر اساس شغل کاربر
                .Select(g => new FunctionModel.ChartSeries
                {
                    name = g.Key,   // اسم شغل کاربر
                    data = new List<double>
{
    Math.Round(g.Sum(x => x.job2 ?? 0), 0),
    Math.Round(g.Sum(x => x.job10 ?? 0),0),
    Math.Round(g.Sum(x => x.job3 ?? 0), 0),
    Math.Round(g.Sum(x => x.job4 ?? 0), 0),
    Math.Round(g.Sum(x => x.job5 ?? 0), 0),
    Math.Round(g.Sum(x => x.job6 ?? 0), 0),
    Math.Round(g.Sum(x => x.job7 ?? 0), 0),
    Math.Round(g.Sum(x => x.job8 ?? 0), 0),
    Math.Round(g.Sum(x => x.job9 ?? 0), 0)
}
                })
                .ToList();

            ViewBag.Chart2Series = chart2Series;
            ViewBag.Chart2Categories = categories;

            // ارسال به View
       
            return View(model);
        }

