      .ToList();
            var dash = db.dashbord_talafat
        .Where(s => s.code >= 21 && s.code <= 24) // همه کدهای 21 تا 24
        .ToList();

            // اگر unic != "استان" فیلتر city انجام شود
            if (model.unicc != "استان")
                dash = dash.Where(s => s.city == model.unicc).ToList();

            // گروه‌بندی بر اساس city
            var groupedData = dash
       .GroupBy(s => s.city)
       .Select(g => new
       {
           City = g.Key,
           Scores = new double[]
           {
            Math.Round(double.TryParse(g.FirstOrDefault(x => x.code == 21)?.value, out double v21) ? v21 : 0, 1),
            Math.Round(double.TryParse(g.FirstOrDefault(x => x.code == 22)?.value, out double v22) ? v22 : 0, 1),
            Math.Round(double.TryParse(g.FirstOrDefault(x => x.code == 23)?.value, out double v23) ? v23 : 0, 1),
            Math.Round(double.TryParse(g.FirstOrDefault(x => x.code == 24)?.value, out double v24) ? v24 : 0, 1)
           }
       })
       .ToList();

            ViewBag.Categories = groupedData.Select(g => g.City).ToList();

            ViewBag.Series = new List<object>
{
