    new { name = "امتیاز وزنی تعویض کنتور", data = groupedData.Select(g => g.Scores[1]).ToArray() },
    new { name = "امتیاز وزنی جمع آوری غیرمجاز", data = groupedData.Select(g => g.Scores[2]).ToArray() },
    new { name = "امتیاز وزنی نصب کنتور جدید", data = groupedData.Select(g => g.Scores[3]).ToArray() },
};

            var dash2 = db.dashbord_talafat
          .Where(s => s.code == 3 || s.code == 7 || s.code == 8)
          .ToList();

            if (model.unicc != "استان")
                dash2 = dash2.Where(s => s.city == model.unicc).ToList();
            var grouped2 = dash2
                .GroupBy(s => s.city)
                .Select(g =>
                {
                    double v1403 = 0;
                    double v1404 = 0;
                    double weight = 0;

                    var val1403 = g.Where(x => x.code == 3)
                                   .OrderByDescending(x => x.ID)
                                   .FirstOrDefault()?.value;

                    var val1404 = g.Where(x => x.code == 7)
                                   .OrderByDescending(x => x.ID)
                                   .FirstOrDefault()?.value;

                    var valWeight = g.Where(x => x.code == 8)
                                     .OrderByDescending(x => x.ID)
                                     .FirstOrDefault()?.value;

                    double.TryParse(val1403, NumberStyles.Any, CultureInfo.InvariantCulture, out v1403);
                    double.TryParse(val1404, NumberStyles.Any, CultureInfo.InvariantCulture, out v1404);
                    double.TryParse(valWeight, NumberStyles.Any, CultureInfo.InvariantCulture, out weight);

                    return new
                    {
                        City = g.Key,
                        D1403 = Math.Round(v1403 * 100, 2),
                        D1404 = Math.Round(v1404 * 100, 2),
