    },
    new {
        name = "درصد تلفات ۱۴۰۴",
        type = "column",
        data = grouped2.Select(x => x.D1404).ToArray()
    },
    new {
        name = "وزن تلفات",
        type = "line",
        data = grouped2.Select(x => x.Weight).ToArray()
    }
};

            model.dbergapilike = db.dbergapilike.Where(s => s.FK_usr == personal).ToList();
            return View(model);
        }
