        public string GetDataFromExcel_dashbord1(HttpPostedFileBase MyExcelStream)
        {


            try
            {



                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return "دسترسی غیر مجاز";


                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return "کاربر یافت نشد";

                int personal = user.usr_ID;

                ExcelPackage.LicenseContext = OfficeOpenXml.LicenseContext.NonCommercial;
                using (var package = new ExcelPackage(MyExcelStream.InputStream))
                {
                    var workbook = package.Workbook;
                    var sheet = workbook.Worksheets[0];

                    int lastRow = sheet.Dimension.End.Row;
                    using (var db = new SaabEntities())
                    {
                        for (int row = 2; row <= lastRow; row++)
                        {
                            var onvan = sheet.Cells[row, 1].Text?.Trim();
                            var name_city = sheet.Cells[row, 2].Text?.Trim();
                            var vorodi1 = sheet.Cells[row, 3].Text?.Trim();
                            var vorodi2 = sheet.Cells[row, 4].Text?.Trim();
                            var vorodi3 = sheet.Cells[row, 5].Text?.Trim();
                            var vahd = sheet.Cells[row, 6].Text?.Trim();
                            var margah = sheet.Cells[row, 7].Text?.Trim();

                            // sumkol (nullable long)
                            var sumkolStr = sheet.Cells[row, 8].Text?.Trim();
                            long? sumkolVal = null;
                            if (long.TryParse(sumkolStr, out long sk))
                                sumkolVal = sk;

                            // avrage (nullable double)
                            var avrageStr = sheet.Cells[row, 9].Text?.Trim();
                            double? avrageVal = null;
                            if (double.TryParse(avrageStr, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out double av))
                                avrageVal = av;

                            // تاریخ شمسی
                            var astarighStr = sheet.Cells[row, 10].Text?.Trim(); // ستون 10
                            var tatarighStr = sheet.Cells[row, 11].Text?.Trim(); // ستون 11
                            var value_nv = sheet.Cells[row, 10].Text?.Trim(); // ستون 10
                            var group = sheet.Cells[row, 12].Text?.Trim(); // ستون 11
                            var group1 = sheet.Cells[row, 13].Text?.Trim(); // ستون 11
                            long? group1Val = null;
                            if (long.TryParse(group1, out long temp))
                            {
                                group1Val = temp;
                            }

                            DateTime? astarighVal = ConvertShamsiToMiladi(astarighStr);
                            DateTime? tatarighVal = ConvertShamsiToMiladi(tatarighStr);

                            //var value_nv = sheet.Cells[row, 12].Text?.Trim(); // ستون 12

                            // بررسی موجودیت در دیتابیس
                            var find = db.dbdashbord1.FirstOrDefault(p =>
                                p.astarigh == astarighVal &&
                                p.tatarigh == tatarighVal &&
                                p.name_city == name_city &&
                                p.vorodi1 == vorodi1 &&
                                p.vorodi2 == vorodi2 &&
                                p.vorodi3 == vorodi3 &&
                                p.vahd == vahd &&
                                p.tatarigh_shams==group&&
                                
                                p.margah == margah
                            );

                            if (find != null)
                            {
                                find.value_nv = astarighStr;
                                find.avrage = avrageVal;
                                find.sumkol = sumkolVal;
                                
                            }
                            else
                            {
                                var obj = new dbdashbord1
                                {
                                    time_sabt = DateTime.Now,
                                    FK_usr = personal,
                                    active = null,
                                    name_city = name_city,
                                    vorodi1 = vorodi1,
                                    vorodi2 = vorodi2,
                                    vorodi3 = vorodi3,
                                    vahd = vahd,
                                    margah = margah,
                                    sumkol = sumkolVal,
                                    avrage = avrageVal,
                                    astarigh = astarighVal,
                                    tatarigh = tatarighVal,
                                    astargh_shams = astarighStr,
                                    tatarigh_shams = group,
                                    valu_big = group1Val,
                                    value_nv = astarighStr
                                };
                                db.dbdashbord1.Add(obj);
                            }
                        }

                        db.SaveChanges();
                    }
                }

                return "عملیات با موفقیت انجام شد";
            }
            catch (Exception ex)
            {
                return "خطا: " + ex.Message;


            }
        }
        public string GetDataFromExcel_dashbord(HttpPostedFileBase MyExcelStream)
        {
            try
            {
                // بررسی کوکی کاربر
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return "دسترسی غیر مجاز";

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return "کاربر یافت نشد";

                int personal = user.usr_ID;

                ExcelPackage.LicenseContext = OfficeOpenXml.LicenseContext.NonCommercial;
                using (var package = new ExcelPackage(MyExcelStream.InputStream))
                {
                    var workbook = package.Workbook;
                    var sheet = workbook.Worksheets[0];
                    int lastRow = sheet.Dimension.End.Row;

                    using (var db = new SaabEntities())
                    {
                        db.Configuration.AutoDetectChangesEnabled = false; // افزایش سرعت

                        // ابتدا تمام رکوردهای موجود در جدول را بارگذاری می‌کنیم تا جلوی query داخل حلقه گرفته شود
                        var existingRecords = db.dbdashbord1
                            .Where(p => p.FK_usr == personal)
                            .ToList();

                        // ایجاد Dictionary برای lookup سریع
                        var recordLookup = existingRecords.ToDictionary(
                            r => $"{r.astarigh?.ToString("yyyyMMdd")}_{r.tatarigh?.ToString("yyyyMMdd")}_{r.name_city}_{r.vorodi1}_{r.vorodi2}_{r.vorodi3}_{r.vahd}_{r.margah}",
                            r => r
                        );

                        var newRecords = new List<dbdashbord1>();

                        for (int row = 2; row <= lastRow; row++)
                        {
                            var name_city = sheet.Cells[row, 2].Text?.Trim();
                            var vorodi1 = sheet.Cells[row, 3].Text?.Trim();
                            var vorodi2 = sheet.Cells[row, 4].Text?.Trim();
                            var vorodi3 = sheet.Cells[row, 5].Text?.Trim();
                            var vahd = sheet.Cells[row, 6].Text?.Trim();
                            var margah = sheet.Cells[row, 7].Text?.Trim();
                            var group = sheet.Cells[row, 12].Text?.Trim(); // ستون 11
                            var group1 = sheet.Cells[row, 13].Text?.Trim(); // ستون 11
                            long? group1Val = null;
                            if (long.TryParse(group1, out long temp))
                            {
                                group1Val = temp;
                            }
                            long? sumkolVal = null;
                            var sumkolText = sheet.Cells[row, 8].Text?.Trim();
                            if (!string.IsNullOrEmpty(sumkolText) &&
                                double.TryParse(sumkolText.Replace(",", "."), NumberStyles.Any, CultureInfo.InvariantCulture, out double sumkolDouble))
                            {
                                sumkolVal = (long)Math.Round(sumkolDouble); // گرد کردن به نزدیکترین عدد صحیح
                            }
                            double? avrageVal = null;
                            var avrageText = sheet.Cells[row, 9].Text?.Trim();
                            if (!string.IsNullOrEmpty(avrageText) &&
                                double.TryParse(avrageText.Replace(",", "."), NumberStyles.Any, CultureInfo.InvariantCulture, out double av))
                            {
                                avrageVal = av; // عدد اعشاری بدون تغییر
                            }

                            var astarighStr = sheet.Cells[row, 10].Text?.Trim();
                            var tatarighStr = sheet.Cells[row, 11].Text?.Trim();
                            var value_nv2 = sheet.Cells[row, 10].Text?.Trim();

                            DateTime? astarighVal = ConvertShamsiToMiladi(astarighStr);
                            DateTime? tatarighVal = ConvertShamsiToMiladi(tatarighStr);
                            DateTime? value_nv23 = ConvertShamsiToMiladi(value_nv2);

                            string value_nv = null;
                            var cellValue = sheet.Cells[row, 12].Value;

                            if (cellValue != null)
                            {
                                if (cellValue is double d)
                                    value_nv = Math.Round(d).ToString(CultureInfo.InvariantCulture); // گرد کردن به نزدیک‌ترین عدد صحیح
                                else if (cellValue is float f)
                                    value_nv = Math.Round(f).ToString(CultureInfo.InvariantCulture);
                                else
                                    value_nv = cellValue.ToString().Trim(); // سایر حالات به string
                            }

                            // کلید برای lookup
                            string key = $"{astarighVal?.ToString("yyyyMMdd")}_{tatarighVal?.ToString("yyyyMMdd")}_{name_city}_{vorodi1}_{vorodi2}_{vorodi3}_{vahd}_{margah}";

                            if (recordLookup.TryGetValue(key, out var existing))
                            {
                                // update رکورد موجود
                                existing.value_nv = group;
                                existing.sumkol = sumkolVal;
                                existing.avrage = avrageVal;
                            }
                            else
                            {
                                // insert رکورد جدید
                                var obj = new dbdashbord1
                                {
                                    time_sabt = DateTime.Now,
                                    FK_usr = personal,
                                    active = null,
                                    name_city = name_city,
                                    vorodi1 = vorodi1,
                                    vorodi2 = vorodi2,
                                    vorodi3 = vorodi3,
                                    vahd = vahd,
                                    margah = margah,
                                    sumkol = sumkolVal,
                                    avrage = avrageVal,
                                    astarigh = astarighVal,
                                    tatarigh = tatarighVal,
                                    astargh_shams = astarighStr,
                                    tatarigh_shams = astarighStr,
                                    valu_big = group1Val,

                                    value_nv = group
                                };
                                newRecords.Add(obj);
                                recordLookup[key] = obj; // اضافه کردن به lookup
                            }
                        }

                        // افزودن همه رکوردهای جدید یکجا
                        if (newRecords.Count > 0)
                            db.dbdashbord1.AddRange(newRecords);

                        db.SaveChanges(); // ذخیره تغییرات
                    }
                }

                return "عملیات با موفقیت انجام شد";
            }
            catch (Exception ex)
            {
                return "خطا: " + ex.Message;
            }
        }

