        public ActionResult GenerateExcelsForAllCities()
        {
            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

            // گرفتن همه شهرها به صورت یکتا
            var allCities = db.countnero_1218_5
                .AsNoTracking()
                .Select(x => x.name2)
                .Distinct()
                .ToList();

            // دیکشنری برای نگهداری فایل‌های بایت
            var resultFiles = new List<(string fileName, byte[] fileContent)>();

            foreach (var city in allCities)
            {
                // داده‌های اصلی هر جدول برای این شهر
                var baseData = db.ValuunicPriorityResult
                    .AsNoTracking()
                    .Where(x => x.city == city)
                    .OrderBy(x => x.SortRank)
                    .ToList();

                var telData = db.ValuunicPriorityResult2
                    .AsNoTracking()
                    .Where(x => x.city == city)
                    .OrderBy(x => x.SortRank)
                    .ToList();

                var counters = db.countnero_1218_5
                    .AsNoTracking()
                    .Where(x => x.name2 == city)
                    .ToList();

                var demandList = new List<ValuDto>();
                var adiList = new List<ValuDto>();
                var telList = new List<ValuDto>();
                var omomiList = new List<ValuDto>();
                var rejected = new Queue<ValuDto>();

                string demandKey = "ديماند".Replace('ي', 'ی');
                string demandKeyomo = "عمومی".Replace('ي', 'ی');
                string demandKeyadi = "عادی".Replace('ي', 'ی');

                var demandSource = baseData.Where(x => x.noeshtrak == demandKey && x.nametarefeh != demandKeyomo).ToList();
                var adiSource = baseData.Where(x => x.noeshtrak == "عادی").ToList();
                var omomiSource = baseData.Where(x => x.noeshtrak == demandKey && x.nametarefeh == demandKeyomo).ToList();

                omomiSource.AddRange(baseData.Where(x => x.nametarefeh == "عمومی" && x.noeshtrak == "ديماند").ToList());
                demandSource.AddRange(baseData.Where(x => x.noeshtrak == "ديماند" && x.nametarefeh != "عمومی").ToList());
                adiSource.AddRange(baseData.Where(x => x.noeshtrak == demandKeyadi).ToList());
                adiSource.AddRange(baseData.Where(x => x.noeshtrak == null).ToList());

                // پردازش counters
                foreach (var c in counters.Where(x => x.name != "تلفنی"))
                {
                    long need = (long)c.Meghdar;
                    long need2 = (long)c.Count;

                    if (need2 <= 0) continue;

                    string normalized = c.name.Replace('ي', 'ی');
                    bool isAmount = c.Meghdar > 0;

                    if (normalized == "دیماند")
                    {
                        foreach (var o in omomiSource)
                            omomiList.Add(MapFromMain(o));

                        TakeFast(demandSource, demandList, rejected, need, need2, isAmount);
                    }
                    else if (normalized == "عادی")
                    {
                        TakeFast(adiSource, adiList, rejected, need, need2, isAmount);
                    }
                }

                // پردازش تلفنی
                var telCounter = counters.FirstOrDefault(x => x.name == "تلفنی");
                if (telCounter != null)
                {
                    long need = (long)(telCounter.Meghdar > 0 ? telCounter.Meghdar : telCounter.Count);
                    var usedIds = new HashSet<string>();
                    foreach (var x in demandList) usedIds.Add(x.valuunic);
                    foreach (var x in adiList) usedIds.Add(x.valuunic);

                    while (need > 0 && rejected.Count > 0)
                    {
                        var item = rejected.Dequeue();
                        if (usedIds.Contains(item.valuunic)) continue;
                        telList.Add(item);
                        need--;
                    }

                    int i = 0;
                    while (need > 0 && i < telData.Count)
                    {
                        telList.Add(MapFromTel(telData[i]));
                        i++;
                        need--;
                    }
                }

                // شیت بالای 5 میلیون
                var highValueData = db.ValuunicPriorityResult3
                    .AsNoTracking()
                    .Where(x => x.city == city)
                    .OrderBy(x => x.SortRank)
                    .ToList();

                var highValueList = highValueData.Select(x => new ValuDto
                {
                    valuunic = x.valuunic,
                    city = x.city,
                    makaan = x.makaan,
                    nametarefeh = x.nametarefeh,
                    noeshtrak = x.noeshtrak,
                    mahdodeh = x.mahdodeh,
                    shomaremobile = x.shomaremobile,
                    parvandeh = x.parvandeh,
                    eshterak = x.eshterak,
                    roz = x.roz,
                    shenasehpardaght = x.shenasehpardaght,
                    P1 = x.P1,
                    P2 = x.P2,
                    P3 = x.P3,
                    P4 = x.P4,
                    P5 = x.P5,
                    //item2 = x.item2,
                    //item1 = x.item1,
                    SortRank = (long)x.SortRank,
                    CreatedAt = x.CreatedAt
                }).ToList();

                // ساخت اکسل
                using (var package = new ExcelPackage())
                {
                    CreateSheet(package, "دیماندی", demandList);
                    CreateSheet(package, "عادی", adiList);
                    CreateSheet(package, "تلفنی", telList);
                    CreateSheet(package, "ویژه", omomiList);
                    CreateSheet(package, "بالای 5 میلیون", highValueList);

                    string safeCity = city.Replace(" ", "_");
                    resultFiles.Add((
                        $"Result_{safeCity}.xlsx",
                        package.GetAsByteArray()
                    ));
                }
            }

            // مثال: برگرداندن فقط اولین فایل (یا می‌توانید ZIP کنید همه را)
            return File(resultFiles.First().fileContent,
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        resultFiles.First().fileName);
        }









