        public string GetDataFromExcel_Unicanother(HttpPostedFileBase MyExcelStream)
        {
            try
            {
                using (var package = new ExcelPackage(MyExcelStream.InputStream))
                using (var db = new SaabEntities())
                {
                    var ws = package.Workbook.Worksheets[0];
                    if (ws == null)
                        return "شیت اول یافت نشد";

                    // ---------- بخش اول ----------
                    string B2 = ws.Cells["B2"].Text?.Trim();
                    string C2 = ws.Cells["C2"].Text?.Trim();
                    string E2 = ws.Cells["E2"].Text?.Trim();
                    string F2 = ws.Cells["F2"].Text?.Trim();
                    string G2 = ws.Cells["G2"].Text?.Trim();
                    string H2 = ws.Cells["H2"].Text?.Trim();

                    if (string.IsNullOrWhiteSpace(B2) ||
                        string.IsNullOrWhiteSpace(C2) ||
                        string.IsNullOrWhiteSpace(E2) ||
                        string.IsNullOrWhiteSpace(F2) ||
                        string.IsNullOrWhiteSpace(G2) ||
                        string.IsNullOrWhiteSpace(H2))
                        return "مقادیر B2,C2,E2,F2,G2,H2 باید پر باشند.";

                    long fkName = db.dbergharel_4_4
                        .Where(x => x.ID.ToString() == B2)
                        .Select(x => x.ID)
                        .FirstOrDefault();

                    if (fkName == 0)
                        return "کد موجود در B2 در dbergharel_4_4 یافت نشد.";

                    long fkTable = db.dberganametanble2_2
                        .Where(x => x.ID.ToString() == E2)
                        .Select(x => x.ID)
                        .FirstOrDefault();

                    if (fkTable == 0)
                        return "کد موجود در E2 در dberganametanble2_2 یافت نشد.";

                    int typeVal = System.Convert.ToInt32(C2);
                    int radifstart = System.Convert.ToInt32(F2);
                    int startVal = System.Convert.ToInt32(G2);

                    // 🔹 UPSERT بخش اول
                    var header = db.dbergharel_4.FirstOrDefault(x =>
                        x.FK_namegozarwsh == fkName &&
                        x.type == typeVal &&
                        x.FK_table == fkTable &&
                        x.start == startVal
                    );

                    if (header != null)
                    {
                        // UPDATE
                        header.unic = H2;
                        header.radifstart = radifstart;
                        header.timesabt = DateTime.Now;
                    }
                    else
                    {
                        // INSERT
                        header = new dbergharel_4
                        {
                            FK_namegozarwsh = fkName,
                            type = typeVal,
                            FK_table = fkTable,
                            radifstart = radifstart,
                            start = startVal,
                            unic = H2,
                            timesabt = DateTime.Now,
                            del = false
                        };
                        db.dbergharel_4.Add(header);
                    }

                    db.SaveChanges();
                    long headerId = header.ID;

                    // ---------- بخش دوم ----------
                    int row = 4;
                    while (true)
                    {
                        string col1 = ws.Cells[row, 1].Text?.Trim(); // fkD2
                        string col2 = ws.Cells[row, 2].Text?.Trim(); // shomareh
                        string col3 = ws.Cells[row, 3].Text?.Trim(); // onvan

                        if (string.IsNullOrWhiteSpace(col1) &&
                            string.IsNullOrWhiteSpace(col2) &&
                            string.IsNullOrWhiteSpace(col3))
                            break;

                        if (string.IsNullOrWhiteSpace(col2))
                            return $"ردیف {row}: shomareh وارد نشده است.";

                        long fkD2 = db.dbergha2
                            .Where(x => x.ID.ToString() == col1)
                            .Select(x => x.ID)
                            .FirstOrDefault();

                        if (fkD2 == 0)
                            return $"ردیف {row}: کد '{col1}' در dbergha2 یافت نشد.";

                        long shomarehVal = System.Convert.ToInt64(col2);

                        // 🔹 پیدا کردن رکورد موجود بر اساس 3 شرط
                        var detail = db.dbergharel4_5.FirstOrDefault(x =>
                            x.FK_dbergharel4 == headerId &&
                            x.shomareh == shomarehVal &&
                            x.onvan == col3
                        );

                        if (detail != null)
                        {
                            // 🔄 UPDATE فقط fkD2
                            detail.FK_dbergharel2 = fkD2;
                            detail.timesabt = DateTime.Now;
                        }
                        else
                        {
                            // ➕ INSERT
                            detail = new dbergharel4_5
                            {
                                FK_dbergharel4 = headerId,
                                FK_dbergharel2 = fkD2,
                                shomareh = shomarehVal,
                                onvan = col3,
                                timesabt = DateTime.Now,
                                del = false
                            };
                            db.dbergharel4_5.Add(detail);
                        }

                        row++;
                    }


                    db.SaveChanges();
                    return "ذخیره و بروزرسانی با موفقیت انجام شد.";
                }
            }
            catch (Exception ex)
            {
                return "خطا: " + ex.Message;
            }
        }












