        public string GetDataFromExcel_TarifFieldErja(HttpPostedFileBase MyExcelStream)
        {
            try
            {
                ExcelPackage.LicenseContext = OfficeOpenXml.LicenseContext.NonCommercial;
                using (var package = new ExcelPackage(MyExcelStream.InputStream))
                {
                    var workbook = package.Workbook;
                    var sheet = workbook.Worksheets[0];

                    int lastRow = sheet.Dimension.End.Row;
                    using (var db = new SaabEntities())
                    {
                        for (int row = 2; row <= lastRow; row++)
                        {
                            var name = sheet.Cells[row, 1].Text?.Trim();
                            var typeStr = sheet.Cells[row, 2].Text?.Trim();


                            if (string.IsNullOrWhiteSpace(name) && string.IsNullOrWhiteSpace(typeStr))
                                continue;

                            int type = 0;
                            int.TryParse(typeStr, out type);

                            var obj = new dbergha2
                            {
                                name = name,
                                type = type,
                                vazn = null,
                                unic = null,
                                FK_usrsabt = null,
                                timesabt = DateTime.Now,
                                macAdress = null,
                                del = null
                            };

                            db.dbergha2.Add(obj);
                        }

                        db.SaveChanges();
                    }
                }

                return "عملیات با موفقیت انجام شد";
            }
            catch (Exception ex)
            {
                return "خطا: " + ex.Message;
            }
        }






