        public Workbook SetDataExcel_Unicanother()
        {
            var Moalefeexcelfile = Workbook.Load(Server.MapPath("~/Content/ExcelFiles/TarifMohtavaGozareshVorodi.xlsx"));
            var sheet = Moalefeexcelfile.Sheets[1];

            using (var db = new SaabEntities())
            {
                var t1 = db.dbergharel_4_4.ToList();
                var t2 = db.dberganametanble2_2.ToList();
                var t3 = db.dbergha2.ToList();

                // پاک‌سازی ردیف‌ها بجز هدر
                //while (sheet.Rows.Count > 1)
                //    sheet.Rows.RemoveAt(1);

                int nextIndex = 1;
                int maxCount = Math.Max(t1.Count, Math.Max(t2.Count, t3.Count));

                for (int i = 0; i < maxCount; i++)
                {
                    var a = i < t1.Count ? t1[i] : null;
                    var b = i < t2.Count ? t2[i] : null;
                    var c = i < t3.Count ? t3[i] : null;

                    var r = new Row() { Index = nextIndex };

                    r.AddCells(new List<Cell>()
      {
          MakeCell211(a?.name, 0),
          MakeCell211(a?.ID,   1),

          MakeCell211(b?.nametable, 2),
          MakeCell211(b?.ID,        3),

          MakeCell211(c?.name, 4),
          MakeCell211(c?.ID,   5)
      });

                    sheet.Rows.Add(r);
                    nextIndex++;
                }
            }

            for (int col = 0; col < 6; col++)
            {
                AutoFitColumn13(sheet, col);
            }

            return Moalefeexcelfile;
        }


        private void AutoFitColumn13(Worksheet sheet, int columnIndex)
        {
            int maxLen = 0;

            // بررسی طول تمام سلول‌های ستون
            foreach (var row in sheet.Rows)
            {
                foreach (var cell in row.Cells)
                {
                    if (cell.Index == columnIndex)
                    {
                        string val = cell.Value?.ToString() ?? "";
                        if (val.Length > maxLen)
                            maxLen = val.Length;
                    }
                }
            }

            // محاسبه پهنای مناسب (تقریباً 7 پیکسل به ازای هر کاراکتر)
            int finalWidth = (maxLen * 7) + 20;  // +20 برای فاصله اضافی

            // اگر خیلی کم بود حداقل عرض بده
            if (finalWidth < 80)
                finalWidth = 80;

            sheet.Columns[columnIndex].Width = finalWidth;
        }
        private Cell MakeCell211(object value, int index)
        {
            return new Cell()
            {
                Index = index,
                Value = value ?? "",
                FontFamily = "B Nazanin",
                FontSize = 12,

                TextAlign = "center",
                VerticalAlign = "center",
                Wrap = false
            };
        }



