        [HttpPost]
        public ActionResult AddShagheh(string title)
        {
            // ۱. بررسی تهی نبودن ورودی
            if (string.IsNullOrWhiteSpace(title))
            {
                return Json(new { success = false, message = "لطفاً عنوان را وارد نمایید." });
            }

            try
            {
                // ۲. احراز هویت کاربر از طریق کوکی ملی‌کد رمزگذاری شده
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                {
                    return Json(new { success = false, message = "کاربر یافت نشد. مجدداً وارد سیستم شوید." });
                }

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);

                // پیدا کردن کاربر از دیتابیس
                var user3 = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user3 == null)
                {
                    return Json(new { success = false, message = "کاربر یافت نشد." });
                }

                // ۳. ایجاد شیء جدید از مدل متناظر با جدول otamasoin1_createshagheh
                var newShagheh = new otamasoin1_createshagheh
                {
                    name = title.Trim(),
                    vaziat = 1,                 // وضعیت پیش‌فرض فعال
                    sabtusr = user3.usr_ID,     // ذخیره آی‌دی کاربر ثبت‌کننده (سازگار با نوع int)
                    vazit = 1
                };

                // افزودن به Context و ذخیره تغییرات در دیتابیس
                db.otamasoin1_createshagheh.Add(newShagheh);
                db.SaveChanges();

                return Json(new { success = true, message = "اطلاعات با موفقیت ثبت شد." });
            }
            catch (Exception ex)
            {
                // بازگرداندن متن خطای داخلی سرور یا دیتابیس به کلاینت جهت دیباگ
                return Json(new { success = false, message = "خطایی در ثبت اطلاعات رخ داد: " + ex.Message });
            }
        }


