        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult AddCretType(string name, long fkShagheh)
        {
            // ۱. اعتبارسنجی اولیه
            if (string.IsNullOrWhiteSpace(name) || fkShagheh <= 0)
            {
                return Json(new { success = false, message = "لطفاً عنوان را وارد و نوع شاخه را انتخاب کنید." });
            }

            try
            {
                // احراز هویت (مشابه متدهای قبلی)
                var cookieKey = Utility.Base64.Base64Encode("CodeMeli");
                var cookie_user = Request.Cookies[cookieKey];
                if (cookie_user == null) return Json(new { success = false, message = "خطا در احراز هویت." });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null) return Json(new { success = false, message = "کاربر یافت نشد." });

                // ۲. ذخیره در جدول جدید
                var newType = new otamasoin2_crettype
                {
                    name = name.Trim(),
                    FK_otamasoin1_createshagheh = fkShagheh,
                    usrsabt = (int)user.usr_ID // ذخیره آی‌دی کاربر ثبت‌کننده
                };

                db.otamasoin2_crettype.Add(newType);
                db.SaveChanges();

                return Json(new { success = true, message = "اطلاعات با موفقیت ثبت شد." });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = "خطا: " + ex.Message });
            }
        }




