        public ActionResult liinksharestan3(
       string name_city = "اسپکه",
       string name_city2 = "اسپکه",
       int item1 = 0,
       int item2 = 0,
       int item3 = 0,
       int item4 = 0,
       int item5 = 0,
       int item6 = 0,
       int item7 = 0)
        {
            // ۱. تعریف متغیر long و مقداردهی بر اساس نام شهر (name_city)
            long cityValue = 0;

            switch (name_city)
            {
                case "ایرانشهر":
                case "سراوان":
                case "چابهار":
                    cityValue = 700000000L; // 700,000,000
                    break;
                case "سوران":
                case "جالق":
                case "زابل":
                    cityValue = 600000000L; // 600,000,000
                    break;
                case "زاهدان 2":
                case "زاهدان 1":
                    cityValue = 550000000L; // 550,000,000
                    break;
                case "هیرمند":
                case "قصرقند":
                    cityValue = 400000000L; // 400,000,000
                    break;
                case "خاش":
                    cityValue = 350000000L; // 350,000,000
                    break;
                case "مهرستان":
                case "نیکشهر":
                case "زهک":
                case "نگور":
                    cityValue = 300000000L; // 300,000,000
                    break;
                case "دلگان":
                case "راسک":
                case "سرباز":
                case "بمپور":
                    cityValue = 250000000L; // 250,000,000
                    break;
                case "کورین":
                case "میرجاوه":
                case "اسپکه":
                    cityValue = 200000000L; // 200,000,000
                    break;
                case "فنوج":
                    cityValue = 180000000L; // 180,000,000
                    break;
                case "کنارک":
                    cityValue = 150000000L; // 150,000,000
                    break;
                default:
                    cityValue = 0; // مقدار پیش‌فرض در صورت عدم تطابق با لیست بالا
                    break;
            }

            // ۲. تبدیل متغیرهای عددی به رشته برای مقایسه در کوئری دیتابیس 
            // (این کار برای جلوگیری از خطاهای احتمالی ترجمه LINQ به SQL توصیه می‌شود)
            string strItem1 = item1.ToString();
            string strItem2 = item2.ToString();
            string strItem3 = item3.ToString();
            string strItem4 = item4.ToString();
            string strItem5 = item5.ToString();
            string strItem6 = item6.ToString();

            // ۳. اجرای کوئری با مقادیر اصلاح‌شده
            var baseData = db.ValuunicPriorityResult
                           .AsNoTracking()
                           .Where(x => x.city == name_city
                                    && x.item4 != strItem1
                                    && x.item4 != strItem2
                                    && x.item4 != strItem3
                                    && x.item4 != strItem4
                                    && x.item4 != strItem5
                                    && x.item4 != strItem6)
                           .OrderBy(x => x.SortRank)
                           .ToList();
         

            if (item7 == 1) // مقایسه عدد ۱ به جای رشته "1"
            {
                baseData = db.ValuunicPriorityResult
                             .AsNoTracking()
                             .Where(x => x.city == name_city&&
                             x.item4 == strItem1
                                      || x.item4 == strItem2
                                      || x.item4 == strItem3
                                      || x.item4 == strItem4
                                      || x.item4 == strItem5
                                      || x.item4 == strItem6)
                             .OrderBy(x => x.SortRank)
                             .ToList();
            }
            var listitem4 = baseData.GroupBy(s => s.item4).ToList();
            var item4Ints = baseData
                .Select(x => System.Convert.ToInt32(x.item4))
                .Distinct()
                .ToList();

            var fkUserCount = db.tbzarfiat_usr
                .Where(z =>
                    item4Ints.Contains(z.mantagheh1 ?? 0) ||
                    item4Ints.Contains(z.mantagheh2 ?? 0) ||
                    item4Ints.Contains(z.mantagheh3 ?? 0) ||
                    item4Ints.Contains(z.mantagheh4 ?? 0) ||
                    item4Ints.Contains(z.mantagheh5 ?? 0) ||
                    item4Ints.Contains(z.mantagheh6 ?? 0) ||
                    item4Ints.Contains(z.mantagheh7 ?? 0) ||
                    item4Ints.Contains(z.mantagheh8 ?? 0) ||
                    item4Ints.Contains(z.mantagheh9 ?? 0)
                )
                .Select(x => x.FK_usr)
                .Distinct()
                .Count();
            long val20darse = (long)((cityValue * 0.20)+ cityValue);
            long countt = (long)(fkUserCount * val20darse);

            string contstr = countt.ToString();
            decimal limit = System.Convert.ToDecimal(contstr);

            decimal sum = 0;
            List<ValuunicPriorityResult> selectedList = new List<ValuunicPriorityResult>();

            foreach (var item in baseData.OrderBy(x => x.SortRank))
            {
                if (sum + item.P5 > limit)
                    break;

                sum += item.P5;
                selectedList.Add(item);
            }
            // در این قسمت می‌توانید از متغیر cityValue استفاده کنید یا آن را به View بفرستید.
            // به عنوان مثال:
            ViewBag.CityValue = cityValue;

            return View(baseData);
        }
        private decimal TryParseDecimal(string value)
        {
            decimal result;
            return decimal.TryParse(value, out result) ? result : 0;
        }
        private decimal AllocateRemainingRecords(
    List<ValuunicPriorityResult> remainingRecords,
    Dictionary<int?, decimal> userBalances,
    List<tbUsers> usttlist,
    List<ValuunicPriorityResult> targetAllocatedList,
    decimal currentTotalSum,
    decimal maxUserLimit)
        {
            foreach (var record in remainingRecords
                .OrderBy(x => x.eshterak)
                .ThenBy(x => x.SortRank))
            {
                decimal p5 = System.Convert.ToDecimal(record.P5);

                var assignedUser = userBalances
                    .OrderBy(u => u.Value)
                    .FirstOrDefault(u => u.Value + p5 <= maxUserLimit);

                if (assignedUser.Key != null)
                {
                    AssignRecordToUser(record, assignedUser.Key, usttlist);

                    userBalances[assignedUser.Key] += p5;
                    targetAllocatedList.Add(record);
                    currentTotalSum += p5;
                }
            }

            return currentTotalSum;
        }

        public ActionResult liinksharestan7(
    string name_city = "اسپکه",
    string name_city2 = "اسپکه",
    string valu = "0",
    int item1 = 0, int item2 = 0, int item3 = 0, int item4 = 0,
    int item5 = 0, int item6 = 0, int item7 = 0)
        {
            // ۱. تعیین مقدار پایه بر اساس شهر
            long cityValue = GetCityValue(name_city);
            long val20darse = (long)(6 * ((cityValue * 0.20) + cityValue));

            // ۲. آماده‌سازی پارامترهای فیلتر
            string[] items =
            {
        item1.ToString(),
        item2.ToString(),
        item3.ToString(),
        item4.ToString(),
        item5.ToString(),
        item6.ToString()
    };

            decimal valuNumber = 0;
            decimal.TryParse(valu, out valuNumber);

            // ۳. استخراج داده‌های پایه
            var query = db.ValuunicPriorityResult
                .AsNoTracking()
                .Where(x => x.city == name_city);

            if (item7 == 1)
                query = query.Where(x => items.Contains(x.item4));
            else
                query = query.Where(x => !items.Contains(x.item4));

            var usttlist = db.tbUsers.ToList();

            var allData = query
                .OrderBy(x => x.SortRank)
                .ToList();

            // عادی
            var baseData = allData
                .Where(s => s.noeshtrak == "عادی" && s.P5 <= valuNumber)
                .OrderBy(x => x.SortRank)
                .ToList();

            // دیماند
            var baseDatademand = allData
                .Where(s => s.noeshtrak == "دیماند" && s.nametarefeh != "عمومی" && s.P5 <= valuNumber)
                .OrderBy(x => x.SortRank)
                .ToList();

            // ویژه
            var baseDatavaegaeh = allData
                .Where(s => (s.noeshtrak == "دیماند" && s.nametarefeh == "عمومی") || s.P5 > valuNumber)
                .OrderBy(x => x.SortRank)
                .ToList();

            // ۴. پیدا کردن کاربران واجد شرایط
            // خیلی مهم: مناطق عادی و دیماند را جدا بگیر
            var item4IntsNormal = baseData
                .Select(x =>
                {
                    int valx;
                    return int.TryParse(x.item4, out valx) ? valx : 0;
                })
                .Distinct()
                .ToList();

            var item4IntsDemand = baseDatademand
                .Select(x =>
                {
                    int valx;
                    return int.TryParse(x.item4, out valx) ? valx : 0;
                })
                .Distinct()
                .ToList();

            var item4IntsSayer = baseData
                .Select(x =>
                {
                    int valx;
                    return int.TryParse(x.item4, out valx) ? valx : 0;
                })
                .Distinct()
                .ToList();

            // نیروهای عادی - job = 1
            var eligibleUsers = db.tbzarfiat_usr
                .Where(z =>
                    item4IntsNormal.Contains(z.mantagheh1 ?? 0) ||
                    item4IntsNormal.Contains(z.mantagheh2 ?? 0) ||
                    item4IntsNormal.Contains(z.mantagheh3 ?? 0) ||
                    item4IntsNormal.Contains(z.mantagheh4 ?? 0) ||
                    item4IntsNormal.Contains(z.mantagheh5 ?? 0) ||
                    item4IntsNormal.Contains(z.mantagheh6 ?? 0) ||
                    item4IntsNormal.Contains(z.mantagheh7 ?? 0) ||
                    item4IntsNormal.Contains(z.mantagheh8 ?? 0) ||
                    item4IntsNormal.Contains(z.mantagheh9 ?? 0))
                .Where(s => s.job == 1)
                .Select(x => x.FK_usr)
                .Distinct()
                .ToList();

            // نیروهای دیماند - job = 2
            var eligibleUsersdemand = db.tbzarfiat_usr
                .Where(z =>
                    item4IntsDemand.Contains(z.mantagheh1 ?? 0) ||
                    item4IntsDemand.Contains(z.mantagheh2 ?? 0) ||
                    item4IntsDemand.Contains(z.mantagheh3 ?? 0) ||
                    item4IntsDemand.Contains(z.mantagheh4 ?? 0) ||
                    item4IntsDemand.Contains(z.mantagheh5 ?? 0) ||
                    item4IntsDemand.Contains(z.mantagheh6 ?? 0) ||
                    item4IntsDemand.Contains(z.mantagheh7 ?? 0) ||
                    item4IntsDemand.Contains(z.mantagheh8 ?? 0) ||
                    item4IntsDemand.Contains(z.mantagheh9 ?? 0))
                .Where(s => s.job == 2)
                .Select(x => x.FK_usr)
                .Distinct()
                .ToList();

            // سایر - job = 3
            var eligibleUserssayer = db.tbzarfiat_usr
                .Where(z =>
                    item4IntsSayer.Contains(z.mantagheh1 ?? 0) ||
                    item4IntsSayer.Contains(z.mantagheh2 ?? 0) ||
                    item4IntsSayer.Contains(z.mantagheh3 ?? 0) ||
                    item4IntsSayer.Contains(z.mantagheh4 ?? 0) ||
                    item4IntsSayer.Contains(z.mantagheh5 ?? 0) ||
                    item4IntsSayer.Contains(z.mantagheh6 ?? 0) ||
                    item4IntsSayer.Contains(z.mantagheh7 ?? 0) ||
                    item4IntsSayer.Contains(z.mantagheh8 ?? 0) ||
                    item4IntsSayer.Contains(z.mantagheh9 ?? 0))
                .Where(s => s.job == 3)
                .Select(x => x.FK_usr)
                .Distinct()
                .ToList();

            // اگر نیروی دیماند نبود، دیماند را با عادی یکی کن
            if (eligibleUsersdemand.Count == 0)
            {
                baseData = allData
                    .Where(s =>
                        (s.noeshtrak == "عادی" && s.P5 <= valuNumber) ||
                        (s.noeshtrak == "دیماند" && s.nametarefeh != "عمومی" && s.P5 <= valuNumber))
                    .OrderBy(x => x.SortRank)
                    .ToList();
            }

            // ۵. ساخت ظرفیت کاربران
            var userBalances = eligibleUsers
                .Where(x => x.HasValue)
                .ToDictionary(id => id, id => 0m);

            var userBalancesdemane = eligibleUsersdemand
                .Where(x => x.HasValue)
                .ToDictionary(id => id, id => 0m);

            var userBalancessayer = eligibleUserssayer
                .Where(x => x.HasValue)
                .ToDictionary(id => id, id => 0m);

            decimal totalLimit = eligibleUsers.Count * 1m * val20darse;
            decimal totalLimitdemand = eligibleUsersdemand.Count * 1m * val20darse;
            decimal totalLimitsayer = eligibleUserssayer.Count * 1m * val20darse;

            decimal currentTotalSum = 0;
            decimal currentTotalSumdeman = 0;
            decimal currentTotalSumsayer = 0;

            List<ValuunicPriorityResult> finalAllocatedList = new List<ValuunicPriorityResult>();
            List<ValuunicPriorityResult> finalAllocatedListdemand = new List<ValuunicPriorityResult>();
            List<ValuunicPriorityResult> finalAllocatedListsayer = new List<ValuunicPriorityResult>();
            List<ValuunicPriorityResult> finalAllocatedListsayergas = new List<ValuunicPriorityResult>();

            decimal baseUserLimit = val20darse;
            decimal minUserLimit = baseUserLimit * 0.85m;
            decimal maxUserLimit = baseUserLimit * 1.15m;

            // --------------------------------------------------
            // مرحله ۱: Cut List برای عادی
            // --------------------------------------------------
            var cutList = new List<ValuunicPriorityResult>();
            decimal cutTotalSum = 0;

            foreach (var record in baseData)
            {
                decimal p5 = System.Convert.ToDecimal(record.P5);
                if (cutTotalSum + p5 <= totalLimit)
                {
                    cutList.Add(record);
                    cutTotalSum += p5;
                }
                else
                {
                    break;
                }
            }

            // --------------------------------------------------
            // مرحله ۲: Cut List برای دیماند
            // --------------------------------------------------
            var cutListdemand = new List<ValuunicPriorityResult>();
            decimal cutTotalSumdemand = 0;

            foreach (var record in baseDatademand)
            {
                decimal p5 = System.Convert.ToDecimal(record.P5);
                if (cutTotalSumdemand + p5 <= totalLimitdemand)
                {
                    cutListdemand.Add(record);
                    cutTotalSumdemand += p5;
                }
                else
                {
                    break;
                }
            }

            // --------------------------------------------------
            // تخصیص اولیه عادی
            // --------------------------------------------------
            var sortedCutList = cutList
                .OrderBy(x => x.eshterak)
                .ThenBy(x => x.SortRank)
                .ToList();

            var rejectCounts = userBalances.ToDictionary(id => id.Key, id => 0);
            int rejectLimit = 3;

            foreach (var record in sortedCutList)
            {
                bool allocated = false;
                decimal p5 = System.Convert.ToDecimal(record.P5);

                foreach (var user in userBalances.Keys.ToList())
                {
                    if (rejectCounts[user] >= rejectLimit)
                        continue;

                    if (userBalances[user] + p5 <= maxUserLimit)
                    {
                        AssignRecordToUser(record, user, usttlist);

                        userBalances[user] += p5;
                        finalAllocatedList.Add(record);
                        currentTotalSum += p5;

                        allocated = true;
                        break;
                    }
                    else
                    {
                        rejectCounts[user]++;
                    }
                }
            }

            // --------------------------------------------------
            // تخصیص اولیه دیماند
            // --------------------------------------------------
            var sortedCutListdemand = cutListdemand
                .OrderBy(x => x.eshterak)
                .ThenBy(x => x.SortRank)
                .ToList();

            var rejectCountDemand = userBalancesdemane.ToDictionary(id => id.Key, id => 0);
            rejectLimit = 3;

            foreach (var record in sortedCutListdemand)
            {
                bool allocated = false;
                decimal p5 = System.Convert.ToDecimal(record.P5);

                foreach (var user in userBalancesdemane.Keys.ToList())
                {
                    if (rejectCountDemand[user] >= rejectLimit)
                        continue;

                    if (userBalancesdemane[user] + p5 <= maxUserLimit)
                    {
                        AssignRecordToUser(record, user, usttlist);

                        userBalancesdemane[user] += p5;
                        finalAllocatedListdemand.Add(record);
                        currentTotalSumdeman += p5;

                        allocated = true;
                        break;
                    }
                    else
                    {
                        rejectCountDemand[user]++;
                    }
                }

                if (currentTotalSumdeman >= totalLimitdemand)
                    break;
            }

            // --------------------------------------------------
            // Cross Allocation
            // اگر دیماند باقی ماند -> عادی‌ها بزنند
            // اگر عادی باقی ماند -> دیماندی‌ها بزنند
            // --------------------------------------------------

            var remainingNormalRecords = baseData
                .Where(x => !finalAllocatedList.Any(f => f.ID == x.ID) &&
                            !finalAllocatedListdemand.Any(f => f.ID == x.ID))
                .ToList();

            var remainingDemandRecords = baseDatademand
                .Where(x => !finalAllocatedListdemand.Any(f => f.ID == x.ID) &&
                            !finalAllocatedList.Any(f => f.ID == x.ID))
                .ToList();

            // دیماندهای باقی‌مانده -> بده به نیروهای عادی
            if (remainingDemandRecords.Any() && userBalances.Any())
            {
                currentTotalSum = AllocateRemainingRecords(
                    remainingDemandRecords,
                    userBalances,
                    usttlist,
                    finalAllocatedList,
                    currentTotalSum,
                    maxUserLimit);
            }

            // عادی‌های باقی‌مانده -> بده به نیروهای دیماند
            if (remainingNormalRecords.Any() && userBalancesdemane.Any())
            {
                currentTotalSumdeman = AllocateRemainingRecords(
                    remainingNormalRecords,
                    userBalancesdemane,
                    usttlist,
                    finalAllocatedListdemand,
                    currentTotalSumdeman,
                    maxUserLimit);
            }

            // --------------------------------------------------
            // تخصیص سایر
            // --------------------------------------------------
            var remainingRecordsForSayer = baseData
                .Where(x => !finalAllocatedList.Any(f => f.ID == x.ID) &&
                            !finalAllocatedListdemand.Any(f => f.ID == x.ID))
                .ToList();

            var cutListsayer = new List<ValuunicPriorityResult>();
            decimal cutTotalSumsayer = 0;

            foreach (var record in remainingRecordsForSayer)
            {
                decimal p5 = System.Convert.ToDecimal(record.P5);
                if (cutTotalSumsayer + p5 <= totalLimitsayer)
                {
                    cutListsayer.Add(record);
                    cutTotalSumsayer += p5;
                }
                else
                {
                    break;
                }
            }

            var sortedCutLissayer = cutListsayer
                .OrderBy(x => x.eshterak)
                .ThenBy(x => x.SortRank)
                .ToList();

            foreach (var record in sortedCutLissayer)
            {
                decimal p5 = System. Convert.ToDecimal(record.P5);

                var assignedUser = userBalancessayer
                    .OrderBy(u => u.Value)
                    .FirstOrDefault(u => u.Value + p5 <= minUserLimit);

                if (assignedUser.Key != null)
                {
                    AssignRecordToUser(record, assignedUser.Key, usttlist);

                    userBalancessayer[assignedUser.Key] += p5;
                    finalAllocatedListsayer.Add(record);
                    currentTotalSumsayer += p5;
                }
                else
                {
                    var assignedUser2 = userBalancessayer
                        .OrderBy(u => u.Value)
                        .FirstOrDefault(u => u.Value + p5 <= maxUserLimit);

                    if (assignedUser2.Key != null)
                    {
                        AssignRecordToUser(record, assignedUser2.Key, usttlist);

                        userBalancessayer[assignedUser2.Key] += p5;
                        finalAllocatedListsayer.Add(record);
                        currentTotalSumsayer += p5;
                    }
                }
            }

            // --------------------------------------------------
            // ویژه
            // --------------------------------------------------
            foreach (var record in baseDatavaegaeh)
            {
                record.item3 = "ویژه";
                finalAllocatedListsayergas.Add(record);
            }

            // --------------------------------------------------
            // ترکیب نهایی
            // --------------------------------------------------
            var allFinalRecords = finalAllocatedList
                .Concat(finalAllocatedListdemand)
                .Concat(finalAllocatedListsayergas)
                //.Concat(finalAllocatedListsayer)
                .GroupBy(x => x.ID)
                .Select(g => g.First())
                .ToList();

            // --------------------------------------------------
            // تبدیل به جدول مقصد
            // --------------------------------------------------
            var insertList = allFinalRecords.Select(x => new ValuunicPriorityResult3
            {
                valuunic = x.valuunic,
                city = x.city,
                makaan = x.makaan,
                nametarefeh = x.nametarefeh,
                noeshtrak = x.noeshtrak,
                mahdodeh = x.mahdodeh,
                shomaremobile = x.shomaremobile,
                parvandeh = x.parvandeh,
                eshterak = x.eshterak,
                roz = x.roz,
                shenasehpardaght = x.shenasehpardaght,

                P1 = x.P1,
                P2 = x.P2,
                P3 = x.P3,
                P4 = x.P4,
                P5 = x.P5,

                SortRank = x.SortRank,
                day = x.day,
                month = x.month,
                yaer = x.yaer,

                CreatedAt = DateTime.Now,

                item1 = x.item1,
                item2 = x.item2,
                item3 = x.item3,
                item4 = x.item4
            }).ToList();

            // --------------------------------------------------
            // ذخیره در دیتابیس
            // --------------------------------------------------
            db.ValuunicPriorityResult3.AddRange(insertList);
            db.SaveChanges();

            // --------------------------------------------------
            // خروجی اکسل
            // --------------------------------------------------
            using (var workbook = new XLWorkbook())
            {
                // شیت عادی
                var normalSheet = workbook.Worksheets.Add("عادی");
                var normalData = insertList
                    .Where(x => x.noeshtrak == "عادی" && x.item3 != "ویژه")
                    .ToList();
                FillAllocationSheet(normalSheet, normalData);

                // شیت دیماند
                var demandSheet = workbook.Worksheets.Add("دیماند");
                var demandData = insertList
                    .Where(x => x.noeshtrak == "دیماند" && x.item3 != "ویژه")
                    .ToList();
                FillAllocationSheet(demandSheet, demandData);

                // شیت ویژه
                var specialSheet = workbook.Worksheets.Add("ویژه");
                var specialData = insertList
                    .Where(x => x.item3 == "ویژه")
                    .ToList();
                FillAllocationSheet(specialSheet, specialData);

                using (var stream = new MemoryStream())
                {
                    workbook.SaveAs(stream);
                    stream.Position = 0;

                    string fileName = name_city2 + "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".xlsx";

                    return File(
                        stream.ToArray(),
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        fileName
                    );
                }
            }
        }
        private void AssignRecordToUser(
    ValuunicPriorityResult record,
    int? userId,
    List<tbUsers> usttlist)
        {
            if (!userId.HasValue)
                return;

            var findusr = usttlist.FirstOrDefault(s => s.usr_ID == userId.Value);
            if (findusr != null)
            {
                record.roz = findusr.FullName;
                record.item3 = findusr.usr_NationalCode;
                record.P1 = (int)findusr.usr_Personal_ID;
            }
        }
        public ActionResult view_excel()
        {
            return View();
        }
        private bool UserHasRegion(List<tbzarfiat_usr> zarfiatUsers, int? userId, string item4, int job)
        {
            if (userId == null)
                return false;

            if (!int.TryParse(item4, out int region))
                return false;

            return zarfiatUsers.Any(z =>
                z.FK_usr == userId &&
                z.job == job &&
                (
                    z.mantagheh1 == region ||
                    z.mantagheh2 == region ||
                    z.mantagheh3 == region ||
                    z.mantagheh4 == region ||
                    z.mantagheh5 == region ||
                    z.mantagheh6 == region ||
                    z.mantagheh7 == region ||
                    z.mantagheh8 == region ||
                    z.mantagheh9 == region
                )
            );
        }

        //http://localhost:6061/Setting/Orders/liinksharestan5?name_city=&name_city2=&item1=62&item2=63&item3=67&valu=1500000000
        //http://localhost:6061/Setting/Orders/liinksharestan5?name_city=%D8%B2%D8%A7%D9%87%D8%AF%D8%A7%D9%86%201&name_city2=%D8%B2%D8%A7%D9%87%D8%AF%D8%A7%D9%86%201&item1=62&item2=63&item3=67&valu=1500000000
        public ActionResult liinksharestan5(
    string name_city = "اسپکه",
    string name_city2 = "اسپکه",
    string valu = "0",
    int item1 = 0, int item2 = 0, int item3 = 0, int item4 = 0,
    int item5 = 0, int item6 = 0, int item7 = 0)
        {
            // ۱. تعیین مقدار پایه بر اساس شهر
            long cityValue = GetCityValue(name_city);
            long val20darse = (long)(6*((cityValue * 0.20) + cityValue));
            long val20darse2 = (long)(6 * (((cityValue * 0.20) + cityValue) * 1.3));

            // ۲. آماده‌سازی پارامترهای فیلتر
            string[] items = { item1.ToString(), item2.ToString(), item3.ToString(), item4.ToString(), item5.ToString(), item6.ToString() };

            // ۳. استخراج داده‌های پایه
            var query = db.ValuunicPriorityResult.AsNoTracking().Where(x => x.city == name_city);

            if (item7 == 1)
                query = query.Where(x => items.Contains(x.item4));
            else
                query = query.Where(x => !items.Contains(x.item4));
         
            decimal valuNumber = 0;
            decimal.TryParse(valu, out valuNumber);
            var usttlist = db.tbUsers.ToList();
            var allData = query
                .OrderBy(x => x.SortRank)
                .ToList();

            var baseData = allData
      .Where(s => s.noeshtrak == "عادی" && s.P5 <= valuNumber) // مستقیماً مقایسه کنید
      .OrderBy(x => x.SortRank)
      .ToList();

            var baseDatademand = allData
                .Where(s => s.noeshtrak == "دیماند" && s.nametarefeh != "عمومی" && (s.P5*2) <= valuNumber)
                .OrderBy(x => x.SortRank)
                .ToList();

            var baseDatavaegaeh = allData
                .Where(s => (s.noeshtrak == "دیماند" && s.nametarefeh == "عمومی") || (s.P5 *2)> valuNumber)
                .OrderBy(x => x.SortRank)
                .ToList();


            // ۴. پیدا کردن کاربران واجد شرایط (FK_usr)
            var item4Ints = baseData.Select(x => System.Convert.ToInt32(x.item4)).Distinct().ToList();

            var eligibleUsers = db.tbzarfiat_usr
                .Where(z => item4Ints.Contains(z.mantagheh1 ?? 0) || item4Ints.Contains(z.mantagheh2 ?? 0) ||
                            item4Ints.Contains(z.mantagheh3 ?? 0) || item4Ints.Contains(z.mantagheh4 ?? 0) ||
                            item4Ints.Contains(z.mantagheh5 ?? 0) || item4Ints.Contains(z.mantagheh6 ?? 0) ||
                            item4Ints.Contains(z.mantagheh7 ?? 0) || item4Ints.Contains(z.mantagheh8 ?? 0) ||
                            item4Ints.Contains(z.mantagheh9 ?? 0))
                   .Where(s => s.job == 1)
                .Select(x => x.FK_usr)
                .Distinct()
                .ToList();
            var eligibleUsersdemand = db.tbzarfiat_usr
      .Where(z => item4Ints.Contains(z.mantagheh1 ?? 0) || item4Ints.Contains(z.mantagheh2 ?? 0) ||
                  item4Ints.Contains(z.mantagheh3 ?? 0) || item4Ints.Contains(z.mantagheh4 ?? 0) ||
                  item4Ints.Contains(z.mantagheh5 ?? 0) || item4Ints.Contains(z.mantagheh6 ?? 0) ||
                  item4Ints.Contains(z.mantagheh7 ?? 0) || item4Ints.Contains(z.mantagheh8 ?? 0) ||
                  item4Ints.Contains(z.mantagheh9 ?? 0))
      .Where(s=>s.job==2)
      .Select(x => x.FK_usr)
      .Distinct()
      .ToList();
            var eligibleUserssayer = db.tbzarfiat_usr
              .Where(z => item4Ints.Contains(z.mantagheh1 ?? 0) || item4Ints.Contains(z.mantagheh2 ?? 0) ||
                          item4Ints.Contains(z.mantagheh3 ?? 0) || item4Ints.Contains(z.mantagheh4 ?? 0) ||
                          item4Ints.Contains(z.mantagheh5 ?? 0) || item4Ints.Contains(z.mantagheh6 ?? 0) ||
                          item4Ints.Contains(z.mantagheh7 ?? 0) || item4Ints.Contains(z.mantagheh8 ?? 0) ||
                          item4Ints.Contains(z.mantagheh9 ?? 0))
                 .Where(s => s.job == 3)
              .Select(x => x.FK_usr)
              .Distinct()
              .ToList();
            if (eligibleUsersdemand.Count == 0)
            {
                 baseData = allData
.Where(s => s.noeshtrak == "عادی" && s.P5 <= valuNumber ||(s.noeshtrak == "دیماند" && s.nametarefeh != "عمومی" && s.P5 <= valuNumber)) // مستقیماً مقایسه کنید
.OrderBy(x => x.SortRank)
.ToList();
            }
            // ۵. ایجاد لیستی برای مدیریت ظرفیت هر کاربر
            // Key: FK_usr , Value: مجموع P5 اختصاص یافته فعلی
            var userBalances = eligibleUsers.ToDictionary(id => id, id => 0m);
            var userBalancesdemane = eligibleUsersdemand.ToDictionary(id => id, id => 0m);
            var userBalancessayer = eligibleUserssayer.ToDictionary(id => id, id => 0m);

            decimal totalLimit = (decimal)eligibleUsers.Count  *1* val20darse2;
            decimal totalLimitdemand = (decimal)userBalancesdemane.Count  *1 * val20darse2;
            decimal totalLimitsayer = (decimal)userBalancessayer.Count * 1 * val20darse2;

            decimal currentTotalSum = 0;
            List<ValuunicPriorityResult> finalAllocatedList = new List<ValuunicPriorityResult>();
            List<ValuunicPriorityResult> finalAllocatedListdemand = new List<ValuunicPriorityResult>();
            List<ValuunicPriorityResult> finalAllocatedListsayer = new List<ValuunicPriorityResult>();
            List<ValuunicPriorityResult> finalAllocatedListsayergas = new List<ValuunicPriorityResult>();

            decimal currentTotalSumdeman = 0;
            decimal currentTotalSumsayer = 0;
            //List<ValuunicPriorityResult> finalAllocatedList = new List<ValuunicPriorityResult>();
            decimal baseUserLimit = val20darse;
            decimal minUserLimit = baseUserLimit * 0.85m;
            decimal maxUserLimit = baseUserLimit * 1.15m;

            // مرحله ۱: انتخاب رکوردها بر اساس SortRank تا سقف totalLimit
            var cutList = new List<ValuunicPriorityResult>();
            decimal cutTotalSum = 0;

            foreach (var record in baseData)
            {
                if (cutTotalSum + record.P5 <= totalLimit)
                {
                    cutList.Add(record);
                    cutTotalSum += record.P5;
                }
                else
                {
                    break;
                }
            }
            var cutListdemand = new List<ValuunicPriorityResult>();
            decimal cutTotalSumdemand = 0;

            foreach (var record in baseDatademand)
            {
                if (cutTotalSumdemand + record.P5 <= totalLimitdemand)
                {
                    cutListdemand.Add(record);
                    cutTotalSumdemand += record.P5;
                }
                else
                {
                    break;
                }
            }
        

            // مرحله ۲: مرتب‌سازی همان رکوردهای انتخاب‌شده بر اساس eshterak
            var sortedCutList = cutList
                .OrderBy(x => x.eshterak)
                .ToList();
            var rejectCounts = eligibleUsers.ToDictionary(id => id, id => 0);
            int rejectLimit = 3;

            //foreach (var record in sortedCutList)
            //{
            //    var assignedUser = userBalances
            //        .Where(u => rejectCounts[u.Key] < rejectLimit)
            //        .FirstOrDefault(u => u.Value + record.P5 <= maxUserLimit);

            //    if (assignedUser.Key != 0)
            //    {
            //        var findusr = usttlist.FirstOrDefault(s => s.usr_ID == assignedUser.Key);

            //        if (findusr != null)
            //        {
            //            record.roz = findusr.FullName;
            //            record.item3 = findusr.usr_NationalCode;
            //            record.P1 = (int)findusr.usr_Personal_ID;
            //        }

            //        userBalances[assignedUser.Key] += record.P5;

