        public ActionResult liinksharestan9(
 string name_city = "اسپکه",
 string name_city2 = "اسپکه",
 string valu = "0",
 int item1 = 0, int item2 = 0, int item3 = 0, int item4 = 0,
 int item5 = 0, int item6 = 0, int item7 = 0)
        {
            // ۱. تعیین مقدار پایه بر اساس شهر
            long cityValue = GetCityValue(name_city);
            long val20darse = (long)(6 * ((cityValue * 0.20) + cityValue));
            long val20darse2 = (long)(6 * (((cityValue * 0.20) + cityValue) * 1.3));

            // ۲. آماده‌سازی پارامترهای فیلتر
            string[] items = { item1.ToString(), item2.ToString(), item3.ToString(), item4.ToString(), item5.ToString(), item6.ToString() };

            // ۳. استخراج داده‌های پایه
            var query = db.ValuunicPriorityResult.AsNoTracking().Where(x => x.city == name_city);

            if (item7 == 1)
                query = query.Where(x => items.Contains(x.item4));
            else
                query = query.Where(x => !items.Contains(x.item4));

            decimal valuNumber = 0;
            decimal.TryParse(valu, out valuNumber);
            var usttlist = db.tbUsers.ToList();
            var allData = query
                .OrderBy(x => x.SortRank)
                .ToList();

            var baseData = allData
      .Where(s => s.noeshtrak == "عادی" && s.P5 <= valuNumber) // مستقیماً مقایسه کنید
      .OrderBy(x => x.SortRank)
      .ToList();

            var baseDatademand = allData
                .Where(s => s.noeshtrak == "دیماند" && s.nametarefeh != "عمومی" && s.P5 <= valuNumber)
                .OrderBy(x => x.SortRank)
                .ToList();

            var baseDatavaegaeh = allData
                .Where(s => (s.noeshtrak == "دیماند" && s.nametarefeh == "عمومی") || s.P5 > valuNumber)
                .OrderBy(x => x.SortRank)
                .ToList();


            // ۴. پیدا کردن کاربران واجد شرایط (FK_usr)
            var item4Ints = baseData.Select(x => System.Convert.ToInt32(x.item4)).Distinct().ToList();

            var eligibleUsers = db.tbzarfiat_usr
                .Where(z => item4Ints.Contains(z.mantagheh1 ?? 0) || item4Ints.Contains(z.mantagheh2 ?? 0) ||
                            item4Ints.Contains(z.mantagheh3 ?? 0) || item4Ints.Contains(z.mantagheh4 ?? 0) ||
                            item4Ints.Contains(z.mantagheh5 ?? 0) || item4Ints.Contains(z.mantagheh6 ?? 0) ||
                            item4Ints.Contains(z.mantagheh7 ?? 0) || item4Ints.Contains(z.mantagheh8 ?? 0) ||
