                foreach (var user in userBalances.Keys.ToList())
                {
                    // اگر این کاربر 3 بار رد شده، دیگر بررسی نشود
                    if (rejectCounts[user] >= rejectLimit)
                        continue;

                    // اگر این رکورد داخل ظرفیت کاربر جا می‌شود
                    if (userBalances[user] + record.P5 <= maxUserLimit)
                    {
                        var findusr = usttlist.FirstOrDefault(s => s.usr_ID == user);

                        if (findusr != null)
                        {
                            record.roz = findusr.FullName;
                            record.item3 = findusr.usr_NationalCode;
                            record.P1 = (int)findusr.usr_Personal_ID;
                        }

                        userBalances[user] += record.P5;

                        finalAllocatedList.Add(record);
