                    if (assignedUser2.Key != null)
                    {
                        var findusr = usttlist.Where(s => s.usr_ID == assignedUser2.Key).FirstOrDefault();
                        if (findusr != null)
                        {
                            record.item3 = findusr.usr_NationalCode;

