                worksheet.Cell(row, 2).Value = item.city;
                worksheet.Cell(row, 3).Value = item.makaan;
                worksheet.Cell(row, 4).Value = item.nametarefeh;
                worksheet.Cell(row, 5).Value = item.noeshtrak;
                worksheet.Cell(row, 6).Value = item.mahdodeh;
                worksheet.Cell(row, 7).Value = item.shomaremobile;

                // پرونده به صورت عدد واقعی
