                if (long.TryParse(item.parvandeh, out long parvandehNumber))
                {
                    parvandehCell.Value = parvandehNumber;
                    parvandehCell.Style.NumberFormat.Format = "0";
                }
                else
                {
                    parvandehCell.Value = "";
                }

                worksheet.Cell(row, 9).Value = item.eshterak;
                worksheet.Cell(row, 10).Value = item.roz;
                worksheet.Cell(row, 11).Value = item.shenasehpardaght;

                //worksheet.Cell(row, 12).Value = item.P1;
                //worksheet.Cell(row, 13).Value = item.P2;
                //worksheet.Cell(row, 14).Value = item.P3;
                //worksheet.Cell(row, 15).Value = item.P4;

                // P5 رند شده و سه رقم سه رقم جدا
                var p5Cell = worksheet.Cell(row, 12);

                if (item.P5.HasValue)
                {
                    p5Cell.Value = Math.Round(item.P5.Value, 0);
                    p5Cell.Style.NumberFormat.Format = "#,##0";
                }
                else
                {
                    p5Cell.Value = "";
                }

                //worksheet.Cell(row, 17).Value = item.SortRank;
                //worksheet.Cell(row, 18).Value = item.day;
                //worksheet.Cell(row, 19).Value = item.month;
                //worksheet.Cell(row, 20).Value = item.yaer;

                worksheet.Cell(row, 13).Value = item.item1;
                //worksheet.Cell(row, 22).Value = item.item2;
                worksheet.Cell(row, 14).Value = item.item3;
                worksheet.Cell(row, 15).Value = item.item4;
                //worksheet.Cell(row, 25).Value = item.CreatedAt;

                row++;
                index++;
            }

            if (row > 2)
            {
                var dataRange = worksheet.Range(1, 1, row - 1, 15);
                dataRange.Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
                dataRange.Style.Border.InsideBorder = XLBorderStyleValues.Thin;
                dataRange.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            }

            worksheet.Columns().AdjustToContents();

            // Freeze header
            worksheet.SheetView.FreezeRows(1);
        }
        private void FillAllocationSheet2(IXLWorksheet worksheet, List<ValuunicPriorityResult3> data)
        {
            worksheet.RightToLeft = true;

            worksheet.Cell(1, 1).Value = "پرونده";
            worksheet.Cell(1, 2).Value = "کد ملی مامور";

            var headerRange = worksheet.Range(1, 1, 1, 2);
            headerRange.Style.Font.Bold = true;
            headerRange.Style.Fill.BackgroundColor = XLColor.LightGray;
            headerRange.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            headerRange.Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
            headerRange.Style.Border.InsideBorder = XLBorderStyleValues.Thin;

            int row = 2;

            foreach (var item in data)
            {
                var parvandehCell = worksheet.Cell(row, 1);
                if (long.TryParse(item.parvandeh, out long parvandehNumber))
                {
                    parvandehCell.Value = parvandehNumber;
                    parvandehCell.Style.NumberFormat.Format = "0";
                }
                else
                {
                    parvandehCell.Value = item.parvandeh ?? "";
                }

                var nationalCodeCell = worksheet.Cell(row, 2);
                if (long.TryParse(item.item3, out long nationalCode))
                {
                    nationalCodeCell.Value = nationalCode;
                    nationalCodeCell.Style.NumberFormat.Format = "0";
                }
                else
                {
                    nationalCodeCell.Value = item.item3 ?? "";
                }

                row++;
            }

            if (row > 2)
            {
                var dataRange = worksheet.Range(1, 1, row - 1, 2);
                dataRange.Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
                dataRange.Style.Border.InsideBorder = XLBorderStyleValues.Thin;
                dataRange.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            }

            worksheet.Columns().AdjustToContents();
            worksheet.SheetView.FreezeRows(1);
        }

        private void AddExcelToZip(
            ZipArchive archive,
            List<ValuunicPriorityResult3> data,
            string cityName,
            int fileIndex)
        {
            using (var workbook = new XLWorkbook())
            {
                var sheet = workbook.Worksheets.Add("Data");
                FillAllocationSheet2(sheet, data);

                using (var excelStream = new MemoryStream())
                {
                    workbook.SaveAs(excelStream);
                    excelStream.Position = 0;

                    string safeCityName = string.IsNullOrWhiteSpace(cityName) ? "Result" : cityName;
                    string entryName = safeCityName + "_part_" + fileIndex + ".xlsx";

                    var entry = archive.CreateEntry(entryName, System.IO.Compression.CompressionLevel.Fastest);
                    using (var entryStream = entry.Open())
                    {
                        excelStream.CopyTo(entryStream);
                    }
                }
            }
        }

        private FileResult ExportAllocationFiles(List<ValuunicPriorityResult3> sourceData, string name_city2)
        {
            const int maxRowsPerFile = 1000;

            var exportData = sourceData
                .Where(x => !string.IsNullOrWhiteSpace(x.item3))
                .OrderBy(x => x.item3)
                .ThenBy(x => x.parvandeh)
                .ToList();

            if (!exportData.Any())
            {
                using (var workbook = new XLWorkbook())
                {
                    var sheet = workbook.Worksheets.Add("Data");
                    FillAllocationSheet2(sheet, exportData);

                    using (var stream = new MemoryStream())
                    {
                        workbook.SaveAs(stream);
                        stream.Position = 0;

                        string fileName = (string.IsNullOrWhiteSpace(name_city2) ? "Result" : name_city2) +
                                          "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".xlsx";

                        return File(
                            stream.ToArray(),
                            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                            fileName
                        );
                    }
                }
            }

            var groupedData = exportData
                .GroupBy(x => x.item3)
                .ToList();

            var excelParts = new List<List<ValuunicPriorityResult3>>();
            var currentChunk = new List<ValuunicPriorityResult3>();

            foreach (var group in groupedData)
            {
                var groupList = group.ToList();

                if (groupList.Count > maxRowsPerFile)
                {
                    if (currentChunk.Any())
                    {
                        excelParts.Add(new List<ValuunicPriorityResult3>(currentChunk));
                        currentChunk.Clear();
                    }

                    for (int i = 0; i < groupList.Count; i += maxRowsPerFile)
                    {
                        excelParts.Add(groupList.Skip(i).Take(maxRowsPerFile).ToList());
                    }

                    continue;
                }

                if (currentChunk.Any() && currentChunk.Count + groupList.Count > maxRowsPerFile)
                {
                    excelParts.Add(new List<ValuunicPriorityResult3>(currentChunk));
                    currentChunk.Clear();
                }

                currentChunk.AddRange(groupList);
            }

            if (currentChunk.Any())
            {
                excelParts.Add(currentChunk);
            }

            if (excelParts.Count == 1)
            {
                using (var workbook = new XLWorkbook())
                {
                    var sheet = workbook.Worksheets.Add("Data");
                    FillAllocationSheet2(sheet, excelParts[0]);

                    using (var stream = new MemoryStream())
                    {
                        workbook.SaveAs(stream);
                        stream.Position = 0;

                        string fileName = (string.IsNullOrWhiteSpace(name_city2) ? "Result" : name_city2) +
                                          "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".xlsx";

                        return File(
                            stream.ToArray(),
                            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                            fileName
                        );
                    }
                }
            }

            using (var zipStream = new MemoryStream())
            {
                using (var archive = new ZipArchive(zipStream, ZipArchiveMode.Create, true))
                {
                    for (int i = 0; i < excelParts.Count; i++)
                    {
                        AddExcelToZip(archive, excelParts[i], name_city2, i + 1);
                    }
                }

                zipStream.Position = 0;

                string zipFileName = (string.IsNullOrWhiteSpace(name_city2) ? "Result" : name_city2) +
                                     "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".zip";

                return File(
                    zipStream.ToArray(),
                    "application/zip",
                    zipFileName
                );
            }
        }
