        // متد کمکی برای تمیز شدن کد
        private long GetCityValue(string city)
        {
            switch (city)
            {
                case "ایرانشهر": case "سراوان": case "چابهار": return 700000000L;
                case "سوران":  case "زابل": return 600000000L;
                case "جالق": return 900000000L;
                case "زاهدان 2": case "زاهدان 1": return 550000000L;
                case "هیرمند": case "قصرقند": return 400000000L;
                case "خاش": return 350000000L;
                case "مهرستان": case "نیکشهر": case "زهک": case "نگور": return 300000000L;
                case "دلگان": case "راسک": case "سرباز": case "بمپور": return 250000000L;
                case "کورین": case "میرجاوه": case "اسپکه": return 200000000L;
                case "فنوج": return 180000000L;
                case "کنارک": return 150000000L;
                default: return 0;
            }
        }

        private void TakeFast(
          List<ValuunicPriorityResult> source,
          List<ValuDto> target,
          Queue<ValuDto> rejected,
          long need, long need2,

          bool isAmount)
        {
            if (!isAmount)
            {
                //long take = Math.Min(need, source.Count);
                long i = 0;
                decimal total = 0;

                foreach (var item in source)
                {
                    decimal amount =

                          (item.P5);
                    total += amount;
                    if (i < need2)
                    {
                        target.Add(MapFromMain(item));
                    }
                    else
                    {
                        if (total < need)
                        {
                            target.Add(MapFromMain(item));

                        }
                        else
                        {
                            rejected.Enqueue(MapFromMainAsTel(item));
                            total -= amount;

                        }
                    }
                    //rejected.Enqueue(MapFromMainAsTel(item));
                    i++;
                }
            }
            else
            {
                long i = 0;
                decimal total = 0;

                foreach (var item in source)
                {
                    decimal amount =

                          (item.P5);
                    total += amount;
                    if (i < need2)
                    {
                        target.Add(MapFromMain(item));
                    }
                    else
                    {
                        if (total < need)
                        {
                            target.Add(MapFromMain(item));

                        }
                        else
                        {
                            rejected.Enqueue(MapFromMainAsTel(item));
                            total -= amount;

                        }
                    }
                    //rejected.Enqueue(MapFromMainAsTel(item));
                    i++;
                }
                //decimal total = 0;

                //foreach (var item in source)
                //{
                //    decimal amount =

                //        (item.P5);
                //    total += amount;

                //    if (total < need)
                //    {
                //        target.Add(MapFromMain(item));

                //    }
                //    else
                //    {
                //        rejected.Enqueue(MapFromMainAsTel(item));
                //        total -= amount;

                //    }
                //}
            }
        }
        private ValuDto MapFromMainAsTel(ValuunicPriorityResult x)
        {
            var dto = MapFromMain(x);
            //dto.noeshtrak = "تلفنی";
            return dto;
        }


        private ValuDto MapFromMain(ValuunicPriorityResult x)
        {
            return new ValuDto
            {
                valuunic = x.valuunic,
                city = x.city,
                makaan = x.makaan,
                nametarefeh = x.nametarefeh,
                noeshtrak = x.noeshtrak,
                mahdodeh = x.mahdodeh,
                shomaremobile = x.shomaremobile,
                parvandeh = x.parvandeh,
                eshterak = x.eshterak,
                roz = x.roz,
                shenasehpardaght = x.shenasehpardaght,
                P1 = x.P1,
                P2 = x.P2,
                P3 = x.P3,
                P4 = x.P4,
                P5 = x.P5,
                item2 = x.item2,
                item1 = x.item1,
                item4=x.item4,
                SortRank = x.SortRank,
                CreatedAt = x.CreatedAt
            };
        }

