                    parvandehCell.Style.Numberformat.Format = "0";
                }
                else
                {
                    parvandehCell.Value = null;
                }

                //if (!string.IsNullOrEmpty(x.parvandeh))
                //{
                //    parvandehCell.Value = x.parvandeh; // رُند
                //    parvandehCell.Style.Numberformat.Format = "##0"; // نمایش عدد بدون کاما
                //}
                //else
                //{
                //    parvandehCell.Value = "";

                //}
