                //if (!string.IsNullOrEmpty(x.parvandeh))
                //{
                //    parvandehCell.Value = double.Parse(x.parvandeh);
                //}
                //else
                //{
                //    parvandehCell.Value = "";
                //}
                //ws.Cells[r, c++].Value = x.parvandeh;
                ws.Cells[r, c++].Value = x.eshterak;
                ws.Cells[r, c++].Value = x.item2;
                ws.Cells[r, c++].Value = x.makaan;
                ws.Cells[r, c++].Value = x.item4;

                ws.Cells[r, c++].Value = x.city;

                ws.Cells[r, c++].Value = x.shomaremobile;

                ws.Cells[r, c++].Value = x.nametarefeh;
                ws.Cells[r, c++].Value = x.noeshtrak;
                ws.Cells[r, c++].Value = x.mahdodeh;
        
        
                //ws.Cells[r, c++].Value = x.P5;
                var p5Cell = ws.Cells[r, c++];

                if (x.P5.HasValue)
                {
                    p5Cell.Value = Math.Round(x.P5.Value, 0); // رُند
                    p5Cell.Style.Numberformat.Format = "#,##0"; // سه‌رقمی
                }

                r++;
            }

            ws.Cells.AutoFitColumns();
        }
