        public Workbook SetDataExcel_Chaharom()
        {
            var Moalefeexcelfile = Workbook.Load(Server.MapPath("~/Content/ExcelFiles/tarifmedgdargoz5.xlsx"));
            var sheet = Moalefeexcelfile.Sheets[1];

            using (var db = new SaabEntities())
            {
                var list0 = db.countnero_1218_0.ToList();
                var list1 = db.countnero_1218_1.ToList();

                // پاک کردن ردیف‌ها از ردیف دوم به بعد (هدر حفظ شود)
                while (sheet.Rows.Count > 1)
                    sheet.Rows.RemoveAt(1);

                int rowIndex = 1; // ردیف دوم

                int maxCount = Math.Max(list0.Count, list1.Count);

                for (int i = 0; i < maxCount; i++)
                {
                    var r = new Row()
                    {
                        Index = rowIndex,
                        Height = 20
                    };

                    var a = i < list0.Count ? list0[i] : null;
                    var b = i < list1.Count ? list1[i] : null;

                    r.AddCells(new List<Cell>()
     {
         // countnero_1218_0
         MakeCell(a != null ? a.name : "", 0),
         MakeCell(a != null ? (object)a.ID : "", 1),

         // countnero_1218_1
         MakeCell(b != null ? b.namcity : "", 2),
         MakeCell(b != null ? (object)b.ID : "", 3),
     });

                    sheet.Rows.Add(r);
                    rowIndex++;
                }
            }

            // ================= AutoFit =================
            for (int col = 0; col < 4; col++)
            {
                AutoFitColumn3(sheet, col);
            }

            return Moalefeexcelfile;
        }



        private void AutoFitColumn3(Worksheet sheet, int columnIndex)
        {
            int maxLen = 0;

            // بررسی طول تمام سلول‌های ستون
            foreach (var row in sheet.Rows)
            {
                foreach (var cell in row.Cells)
                {
                    if (cell.Index == columnIndex)
                    {
                        string val = cell.Value?.ToString() ?? "";
                        if (val.Length > maxLen)
                            maxLen = val.Length;
                    }
                }
            }

            int finalWidth = (maxLen * 7) + 20;
            if (finalWidth < 80)
                finalWidth = 80;

            // ⬅⬅⬅ بخش حیاتی: اطمینان از وجود ستون
            while (sheet.Columns.Count <= columnIndex)
            {
                sheet.Columns.Add(new Telerik.Web.Spreadsheet.Column()
                {
                    Index = sheet.Columns.Count,
                    Width = 80
                });

            }

            sheet.Columns[columnIndex].Width = finalWidth;
        }


        private Cell MakeCell(object value, int index)
        {
            return new Cell()
            {
                Index = index,
                Value = value ?? "",
                FontFamily = "B Nazanin",
                FontSize = 12,

                TextAlign = "center",
                VerticalAlign = "center",
                Wrap = false
            };
        }









        



