        public string GetDataFromExcel_SafheChaharom(HttpPostedFileBase MyExcelStream)
        {
            try
            {
                ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

                //ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

                using (var package = new ExcelPackage(MyExcelStream.InputStream))
                
                    using (var db = new SaabEntities())
                using (var tran = db.Database.BeginTransaction())
                {
                    try
                    {
                        var ws = package.Workbook.Worksheets[0];
                        if (ws == null)
                            return "شیت اول یافت نشد";

                        int lastRow = ws.Dimension.End.Row;

                        for (int row = 2; row <= lastRow; row++)
                        {
                            string col2 = ws.Cells[row, 2].Text?.Trim();
                            string col3 = ws.Cells[row, 3].Text?.Trim();
                            string col1 = ws.Cells[row, 1].Text?.Trim();

                            string col4 = ws.Cells[row, 4].Text?.Trim();
                            string col5 = ws.Cells[row, 5].Text?.Trim();
                            string col6 = ws.Cells[row, 6].Text?.Trim(); 
                            string col7 = ws.Cells[row, 7].Text?.Trim();
                            string col8= ws.Cells[row, 8].Text?.Trim();
                            string col9 = ws.Cells[row, 9].Text?.Trim();
                            string col10 = ws.Cells[row, 10].Text?.Trim();
                            string col11 = ws.Cells[row, 11].Text?.Trim(); 
                            string col12 = ws.Cells[row, 12].Text?.Trim();

                            string col13 = ws.Cells[row, 13].Text?.Trim();


                            if (string.IsNullOrWhiteSpace(col2) &&
                                string.IsNullOrWhiteSpace(col4) &&
                                string.IsNullOrWhiteSpace(col5) &&
                                string.IsNullOrWhiteSpace(col6))
                                continue;

                            if (string.IsNullOrWhiteSpace(col2) || string.IsNullOrWhiteSpace(col4))
                                throw new Exception($"ردیف {row}: ستون‌های B و D الزامی هستند.");

                            long? fkGozaresh = db.countnero_1218_0
                                .Where(x => x.ID.ToString() == col2)
                                .Select(x => (long?)x.ID)
                                .FirstOrDefault();

                            if (fkGozaresh == null)
                                throw new Exception($"ردیف {row}: مقدار ستون B در countnero_1218_0 یافت نشد.");

                            long? fkCity = db.countnero_1218_1
                                .Where(x => x.ID.ToString() == col4)
                                .Select(x => (long?)x.ID)
                                .FirstOrDefault();

                            if (fkCity == null)
                                throw new Exception($"ردیف {row}: مقدار ستون D در countnero_1218_1 یافت نشد.");

                            long? countVal = string.IsNullOrWhiteSpace(col5)
         ? (long?)null
         : System.Convert.ToInt64(col5);

                            long? meghdarVal = string.IsNullOrWhiteSpace(col6)
                                ? (long?)null
                                : System.Convert.ToInt64(col6);
                            int? day = string.IsNullOrWhiteSpace(col7)
                           ? (int?)null
                           : System.Convert.ToInt32(col7);

                            int? month = string.IsNullOrWhiteSpace(col8)
                       ? (int?)null
                       : System.Convert.ToInt32(col8);

                            int? year = string.IsNullOrWhiteSpace(col9)
                       ? (int?)null
                       : System.Convert.ToInt32(col9);

                            long? vosolkol = string.IsNullOrWhiteSpace(col10)
                           ? (long?)null
                           : System.Convert.ToInt64(col10);

                            long? vosolday = string.IsNullOrWhiteSpace(col13)
                    ? (long?)null
                    : System.Convert.ToInt64(col13);
                            long? entezarkol = string.IsNullOrWhiteSpace(col11)
                    ? (long?)null
                    : System.Convert.ToInt64(col11);
                            long? entezarday = string.IsNullOrWhiteSpace(col12)
                    ? (long?)null
                    : System.Convert.ToInt64(col12);
                            var record = db.countnero_1218_5.FirstOrDefault(x =>
                                x.Fk_gozaresh == fkGozaresh &&
                                x.day==day &&x.month==month &&x.yaer==year &&
                                x.Fk_city == fkCity
                            );

                            if (record != null)
                            {
                                record.Count = countVal;
                                record.Had_vosol_shodeh_kol = vosolkol;
                                record.Had_vosol_shodeh_day = vosolday;
                                record.Had_entezar_inday = entezarday;
                                record.Had_entezar_kol = entezarkol;
                                record.Meghdar = meghdarVal;
                            }
                            else
                            {
                                db.countnero_1218_5.Add(new countnero_1218_5
                                {
                                    Fk_gozaresh = fkGozaresh,
                                    Fk_city = fkCity,
                                    name = col1,
                                    name2 = col3,
                                    day = day,
                                    month=month,
                                    yaer=year,
                                    Had_vosol_shodeh_kol=vosolkol,
                                    Had_vosol_shodeh_day=vosolday,
                                    Had_entezar_inday=entezarday,
                                    Had_entezar_kol=entezarkol,
                                    Count = countVal,
                                    Meghdar = meghdarVal
                                }); ;
                            }
                        }

                        db.SaveChanges();
                        tran.Commit();

                        return "اطلاعات  موفقیت ذخیره و بروزرسانی شد.";
                    }
                    catch (Exception ex)
                    {
                        tran.Rollback();
                        return "خطا : " + ex.Message;
                    }
                }
            }
            catch (Exception ex)
            {
                return "خطای سیستمی: " + ex.Message;
            }
        }

