                .Where(d => d.FK_dbergharelinsert_6 == find5.ID)
                .ToListAsync();

            // 3️⃣ گروه‌بندی Result1218
            var find = db.Result1218
                .Where(s => s.valuunic != null)
                .GroupBy(t => t.valuunic)
                .ToList();


            // 4️⃣ ساخت گروه‌ها + تمام اولویت‌ها
            var groups = find
                .Select(g =>
                {
                    // ========================
                    //   🔵 شرط ۵ → اختلاف‌ها
                    // ========================

                    // FK_db2 = 190
                    int val190 = findd2118
                        .Where(x => x.valuunic == g.Key && x.FK_db2 == 190)
                        .Select(x =>
                        {
                            int v;
                            return int.TryParse(x.valueFK_db2, out v) ? v : 0;
                        })
                        .DefaultIfEmpty(0)
                        .FirstOrDefault();

                    // FK_db2 = 189
                    int val189 = findd2118
                        .Where(x => x.valuunic == g.Key && x.FK_db2 == 189)
                        .Select(x =>
                        {
                            int v;
                            return int.TryParse(x.valueFK_db2, out v) ? v : 0;
                        })
                        .DefaultIfEmpty(0)
                        .FirstOrDefault();

                    int diff190_189 = val190 - val189;


                    // FK_db2 = 450
                    int val450 = findd21
                        .Where(x => x.valuunic == g.Key && x.FK_db2 == 450)
                        .Select(x =>
                        {
                            int v;
                            return int.TryParse(x.valueFK_db2, out v) ? v : 0;
                        })
                        .DefaultIfEmpty(0)
                        .FirstOrDefault();

                    // FK_db2 = 449
                    int val449 = findd21
                        .Where(x => x.valuunic == g.Key && x.FK_db2 == 449)
                        .Select(x =>
                        {
                            int v;
                            return int.TryParse(x.valueFK_db2, out v) ? v : 0;
                        })
                        .DefaultIfEmpty(0)
                        .FirstOrDefault();

                    int diff450_449 = val450 - val449;

                    // شرط ۵:
                    int P5 = diff190_189 + diff450_449;



                    // ========================
                    //   🔴 شرط ۱ تا ۴
                    // ========================

                    var P1 =
                        findd21.Any(x => x.valuunic == g.Key && x.FK_db2 == 412 && x.valueFK_db2 == "دیماند") ? 1 :
                        findd21.Any(x => x.valuunic == g.Key && x.FK_db2 == 412 && x.valueFK_db2 == "عادی") ? 2 :
                        3;

                    var P2 =
                        findd21.Any(x => x.valuunic == g.Key && x.FK_db2 == 411 && x.valueFK_db2 == "سایر مصارف") ? 1 :
                        findd21.Any(x => x.valuunic == g.Key && x.FK_db2 == 411 && x.valueFK_db2 == "خانگی") ? 2 :
                        3;

                    var P3 =
                        findd21
                            .Where(x => x.valuunic == g.Key && x.FK_db2 == 413)
                            .Select(x =>
                            {
                                int val;
                                if (int.TryParse(x.valueFK_db2, out val))
                                    return val == 0 ? 100 : val;
                                return 100;
                            })
                            .DefaultIfEmpty(100)
                            .Min();

                    var P4 =
                        findd21
                            .Where(x => x.valuunic == g.Key && x.FK_db2 == 411)
                            .Select(x =>
                            {
                                if (x.valueFK_db2 == "سایر مصارف") return 1;
                                if (x.valueFK_db2 == "خانگی") return 2;
                                if (x.valueFK_db2 == "کشاورزی") return 3;
                                if (x.valueFK_db2 == "صنعتی") return 4;
                                if (x.valueFK_db2 == "عمومی") return 5;
                                return 6;
                            })
                            .DefaultIfEmpty(6)
                            .Min();


                    return new
                    {
                        Key = g.Key,
                        Items = findd21.Where(s => s.valuunic == g.Key).ToList(),

                        P1 = P1,
                        P2 = P2,
                        P3 = P3,
                        P4 = P4,
                        P5 = P5
                    };
                })

                // ========================
                //   🔥 مرتب‌سازی نهایی
                // ========================
                .OrderBy(x => x.P1)
                .ThenBy(x => x.P2)
                .ThenBy(x => x.P3)
                .ThenBy(x => x.P4)
                .ThenByDescending(x => x.P5) // شرط ۵ از زیاد به کم
                .ToList();


            // خروجی نهایی valuunic ها
            var sortedValuunicList = groups.Select(g => g.Key).ToList();

            ViewBag.SortedValuunicList = sortedValuunicList;
            ViewBag.SortedGroups = groups;

            return View();
        }

