        public ActionResult dasbord_1218_see(string id = "0")
        {
            int personal = 0;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");
            personal = user.usr_ID;
            var model = new FunctionModel
            {
                tbAdamAdam2 = new List<tbAdamAdam2>(),

                tbAdamAdam = new List<tbAdamAdam>(),
                arzyzbi5_time = new List<arzyzbi5_time>(),
                arzyzbi5_time2 = new List<arzyzbi5_time2>(),
                dbergharel_4_4 = new List<dbergharel_4_4>(),
                dbergapilike = new List<dbergapilike>(),
                dbergharelimsertfk1_7 = new List<dbergharelimsertfk1_7>(),

            };
            if (id == "0")
            {
                var fidunic = db.dbergapilike.Where(s => s.FK_usr == personal).FirstOrDefault();
                if (fidunic != null)
                {
                    model.unicc = fidunic.unic;

                }
                else
                {
                    model.unicc = "";

                }
            }
            else
            {
                var fidunic = db.dbergapilike.Where(s => s.FK_usr == personal && s.unic == id).FirstOrDefault();
                if (fidunic != null)
                {
                    model.unicc = fidunic.unic;

                }
                else
                {
                    model.unicc = "";

                }
            }
            model.dbergapilike = db.dbergapilike.Where(s => s.FK_usr == personal).ToList();
            model.dbergharelimsertfk1_7 = db.dbergharelimsertfk1_7.Where(s => s.valuunic == model.unicc &&s.dbergharelinsert_6.dbergharel_4.FK_namegozarwsh==15).ToList();
            //model.dbergharel_4_4 = db.dbergharel_4_4.ToList();
            return PartialView("~/Areas/Setting/Views/Orders/dasbord_1218_see.cshtml", model);
        }
        public class CheckIdKarbarViewModel
        {
            public int usr_Personal_ID { get; set; }
            public int value { get; set; }
