        [HttpPost]
        public async Task<ActionResult> CheckIdKarbar1(CheckIdKarbarViewModel model)
        {
            try
            {

                var Find1 = await db.tbUsers.FirstOrDefaultAsync(p => p.usr_Personal_ID == model.usr_Personal_ID);


                if (Find1 == null)
                {
                    return Json(new { success = false, message = "کاربر یافت نشد" });
                }


                var Find2 = await db.tbAdamShahr.FirstOrDefaultAsync(m => m.idkarbar == Find1.usr_ID);


                if (Find2 != null)
                {
                    Find2.value = model.value;
                }
                else
                {
                    var entity = new tbAdamShahr
                    {
                        idkarbar = Find1.usr_ID,
                        value = model.value
                    };

                    db.tbAdamShahr.Add(entity);
                }

                await db.SaveChangesAsync();

                return Json(new { success = true });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }

