                var val284 = db.dbergharelimsertfk1_7
                               .Where(x => x.FK_dbergharelinsert_6 == 75 && x.FK_db2 == 284 && x.valuunic == it.Key)
                               .Select(x => x.valueFK_db2)
                               .FirstOrDefault() ?? "";

                var val282 = db.dbergharelimsertfk1_7
                               .Where(x => x.FK_dbergharelinsert_6 == 75 && x.FK_db2 == 282 && x.valuunic == it.Key)
                               .Select(x => x.valueFK_db2)
                               .FirstOrDefault() ?? "";

                var val271 = db.dbergharelimsertfk1_7
                               .Where(x => x.FK_dbergharelinsert_6 == 75 && x.FK_db2 == 271 && x.valuunic == it.Key)
                               .Select(x => x.valueFK_db2)
                               .FirstOrDefault() ?? "";

