        public ActionResult DeleteDetails(long D = 0)
        {
            try
            {
                using (SaabEntities db = new SaabEntities())
                {
                    // حذف تمام رکوردهای مرتبط در جدول dbergharelimsertfk1_7 با یک دستور SQL
                    string sql = @"DELETE FROM dbergharelimsertfk1_7 WHERE FK_dbergharelinsert_6 = @p0";
                    db.Database.ExecuteSqlCommand(sql, D);

                    // حذف رکورد اصلی از جدول dbergharelinsert_6
                    var mainRecord = db.dbergharelinsert_6.SingleOrDefault(s => s.ID == D);
                    if (mainRecord != null)
                    {
                        db.dbergharelinsert_6.Remove(mainRecord);
                        db.SaveChanges();
                        return Content("با موفقیت حذف شد");
                    }
                    else
                    {
                        return Content("رکوردی یافت نشد");
                    }
                }
            }
            catch (Exception ex)
            {
                return Content("خطا: " + ex.Message);
            }
        }
