        public ActionResult countshahri1(string tarighstart = "", string tarighend = "", long ID = 0, int month = 0, int year = 0)
        {
            // 1️⃣ آخرین فرم
            var lastFormId = db.dbergharelinsert_6
                .Where(x => x.dbergharel_4.FK_namegozarwsh == 6)
                .OrderByDescending(x => x.ID)
                .Select(x => x.ID)
                .FirstOrDefault();

            if (lastFormId == 0) return View();

            // 2️⃣ داده‌های فرم
            var data = db.dbergharelimsertfk1_7
                .Where(x => x.FK_dbergharelinsert_6 == lastFormId)
                .ToList();

            // 3️⃣ فیلتر تاریخ
            var validValuUnic = data
                .Where(x => x.FK_db2 == 205 &&
                    string.Compare(x.valueFK_db2, tarighstart) >= 0 &&
                    string.Compare(x.valueFK_db2, tarighend) <= 0)
                .Select(x => x.valuunic)
                .Distinct()
                .ToHashSet();

            var filtered = data
                .Where(x => validValuUnic.Contains(x.valuunic))
                .GroupBy(x => x.valuunic)
                .ToList();

            // 4️⃣ Dictionary کاربران (کلید تکراری امن)
            var userDict = db.tbLink_name_usr
                .GroupBy(x => x.name)
                .ToDictionary(g => g.Key, g => (int)g.First().FK_usr);

            // 5️⃣ اطلاعات روستا/شهری
            var rostaFormId = db.dbergharelinsert_6
                .Where(x => x.dbergharel_4.FK_namegozarwsh == 7)
                .Select(x => x.ID)
                .FirstOrDefault();

            var rostaDict = db.dbergharelimsertfk1_7
                .Where(x => x.FK_dbergharelinsert_6 == rostaFormId && x.FK_db2 == 210)
                .GroupBy(x => x.valuunic)
                .ToDictionary(g => g.Key, g => g.First().valueFK_db2);

            // 6️⃣ ساخت لیست نهایی
            var result = new List<tbcreat_countjob_Fish>();

            foreach (var g in filtered)
            {
                var name = g.FirstOrDefault(x => x.FK_db2 == 198)?.valueFK_db2;
                var countStr = g.FirstOrDefault(x => x.FK_db2 == 204)?.valueFK_db2;

                if (name == null || !long.TryParse(countStr, out long count)) continue;
                if (!userDict.TryGetValue(name, out int usrId)) continue;

                rostaDict.TryGetValue(g.Key, out string rosta);

                var item = new tbcreat_countjob_Fish
                {
                    FK_usr = usrId,
                    FK_gaval = ID,
                    active = 1,
                    shahr = 0,
                    rostai = 0,
                    chargh = 0
                };

                if (rosta == "شهری")
                    item.shahr = count;
                else if (rosta == "روستایی")
                    item.rostai = count;
                else if (rosta == "خارج از محدوده")
                    item.chargh = count;
                else
                    item.shahr = count; // fallback

                result.Add(item);
            }

            // 7️⃣ حذف قدیمی و ذخیره جدید (با جمع کردن بر اساس کاربر)
            db.tbcreat_countjob_Fish.RemoveRange(
                db.tbcreat_countjob_Fish.Where(x => x.FK_gaval == ID)
            );

            db.tbcreat_countjob_Fish.AddRange(
                result.GroupBy(x => x.FK_usr)
                    .Select(g => new tbcreat_countjob_Fish
                    {
                        FK_usr = g.Key,
                        FK_gaval = ID,
                        active = 1,
                        shahr = g.Sum(x => x.shahr),
                        rostai = g.Sum(x => x.rostai),
                        chargh = g.Sum(x => x.chargh)
                    })
            );

            db.SaveChanges();
            return View();
        }

        public ActionResult countshahri(string tarighstart = "", string tarighend = "", long ID = 0, int month = 0, int year = 0)

        {


            var fidn = db.dbergharelinsert_6
                         .Where(s => s.dbergharel_4.FK_namegozarwsh == 6)
                         .OrderByDescending(t => t.ID)
                         .FirstOrDefault();
            List<tbcreat_countjob_Fish> tbcreat_countjob_Fish2 = new List<tbcreat_countjob_Fish>();

            if (fidn != null)
            {
                // کل لیست داده‌های مرتبط با ID پیدا شده
                var list = db.dbergharelimsertfk1_7
                             .Where(s => s.FK_dbergharelinsert_6 == fidn.ID)
                             .ToList();

                // مرحله ۱: پیدا کردن valuunic هایی که تاریخشان در بازه است
                var dateItems = list
                    .Where(s => s.FK_db2 == 205 &&
                                string.Compare(s.valueFK_db2, tarighstart) >= 0 &&
                                string.Compare(s.valueFK_db2, tarighend) <= 0)
                    .Select(s => s.valuunic)
                    .Distinct()
                    .ToList();

                // مرحله ۲: فقط همان valuunic‌ها را نگه دار
                var filteredList = list
                    .Where(s => dateItems.Contains(s.valuunic))
                    .ToList();

                var listname = db.tbLink_name_usr.ToList();
                var fidn1 = db.dbergharelinsert_6
                           .Where(s => s.dbergharel_4.FK_namegozarwsh == 7)
                           //.OrderByDescending(t => t.ID)
                           .FirstOrDefault();
                var list2 = db.dbergharelimsertfk1_7
                                     .Where(s => s.FK_dbergharelinsert_6 == fidn1.ID)
                                     .ToList();
                var list3 = db.dbergharelimsertfk1_7
                                     .Where(s => s.FK_db2 == 210)
                                     .ToList();
                // گروه‌بندی بر اساس valuunic
                var group = filteredList.GroupBy(s => s.valuunic).ToList();
                foreach (var it in group)
                {
                    string name = "";
                    string cod = "";
                    string rosta = "";
                    int usrid = 0;
                    long count = 0;


                    var x = filteredList.Where(s => s.valuunic == it.Key).ToList();

                    foreach (var tt in x)
                    {
                        if (tt.FK_db2 == 202)
                        {
                            cod = tt.valueFK_db2;

                        }
                        else if (tt.FK_db2 == 200)
                        {
                            name = tt.valueFK_db2;
                        }
                    }

              

                    if (fidn1 != null)
                    {
                       

                        // ✅ پیدا کردن valuunic هایی که در list2 هم cod دارند و هم name
                        var matchValuUnic = list2
                            .GroupBy(s => s.valuunic)
                            .Where(g => g.Any(x1 => x1.valueFK_db2 == cod) &&
                                        g.Any(t => t.valueFK_db2 == name))
                            .Select(g => g.Key)
                            .FirstOrDefault();
                        var result210 = list3
          .Where(s => s.valuunic == matchValuUnic && s.FK_db2 == 210)
          .Select(s => s.valueFK_db2)   // فقط خود مقدار رشته‌ای را انتخاب کن
          .FirstOrDefault();

                        rosta = result210;  // حالا result210 خودش string است

                        var findname = filteredList.Where(s => s.valuunic == it.Key && s.FK_db2 == 198).FirstOrDefault();
                        if (findname != null)
                        {
                            var findusr = listname.Where(s => s.name == findname.valueFK_db2).FirstOrDefault();
                            if (findusr != null)
                            {
                                usrid = (int)findusr.FK_usr;
                            }
                        }
                        var findnamecount = filteredList.Where(s => s.valuunic == it.Key && s.FK_db2 == 204).FirstOrDefault();

                        if (findnamecount != null && long.TryParse(findnamecount.valueFK_db2, out long parsedCount))
                        {
                            count = parsedCount;
                        }
                        if (usrid != 0)
                        {
                            tbcreat_countjob_Fish tbcreat_countjob_Fish = new tbcreat_countjob_Fish();
                            if (rosta == "شهری")
                            {
                                tbcreat_countjob_Fish.shahr = count;
                                tbcreat_countjob_Fish.rostai = 0;
                                tbcreat_countjob_Fish.chargh = 0;


                            }
                            else if (rosta == "روستایی")
                            {
                                tbcreat_countjob_Fish.rostai = count;
                                tbcreat_countjob_Fish.shahr = 0;
                                tbcreat_countjob_Fish.chargh = 0;

                            }
                            else if (rosta == "خارج از محدوده")
                            {
                                tbcreat_countjob_Fish.chargh = count;
                                tbcreat_countjob_Fish.rostai = 0;
                                tbcreat_countjob_Fish.shahr = 0;

                            }
                            else
                            {
                                tbcreat_countjob_Fish.shahr = count;
                                tbcreat_countjob_Fish.rostai = 0;
                                tbcreat_countjob_Fish.chargh = 0;
                            }
                            tbcreat_countjob_Fish.FK_usr = usrid;
                            tbcreat_countjob_Fish.FK_gaval = ID;

                            tbcreat_countjob_Fish2.Add(tbcreat_countjob_Fish);
                        }


                    }
                }
            }
            var x12 = db.tbcreat_countjob_Fish.Where(s => s.FK_gaval == ID).ToList();
            var del = db.tbcreat_countjob_Fish.RemoveRange(x12);
            db.tbcreat_countjob_Fish.AddRange(tbcreat_countjob_Fish2);
            db.SaveChanges();

            var finalList = tbcreat_countjob_Fish2
                    .GroupBy(x => new { x.FK_usr })
                    .Select(g => new tbcreat_countjob_Fish
                    {
                        FK_usr = g.Key.FK_usr,

                        shahr = g.Sum(x => x.shahr),
                        chargh = g.Sum(x => x.chargh),
                        rostai = g.Sum(x => x.rostai),
                        active=1,
                        FK_gaval = ID,

                    }).ToList();
            db.tbcreat_countjob_Fish.AddRange(finalList);
            db.SaveChanges();
            return View();
        }
        public ActionResult ExportGozareshMoalefeh()
        {
            var find2 = db.dbvaziat_FIsh1Set.FirstOrDefault();

            int month = 11, year = 1404;
            if (find2 != null)
            {
                month = (int)find2.month;
                year = (int)find2.yaer;
            }

            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return Json(new { success = false, message = "دسترسی غیرمجاز" });

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user1 = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user1 == null)
                return Json(new { success = false, message = "کاربر یافت نشد" });

            int personal = user1.usr_ID;
            db.Database.CommandTimeout = 600;

            string sql = @"
SELECT 
    u.usr_ID,
    u.usr_Name + ' ' + u.usr_Family AS FullName,
    u.usr_Personal_ID,
    md.md_Title,
    v.MoalfeVal_Value AS Value,
    c.Name AS CityName,
    mp.Moadel,
    j.Name AS JobName
FROM [Salary].[tbMoalefeDastmozdiValueFromExcel] v
INNER JOIN [Usser].[tbUsers] u
    ON v.MoalfeVal_FKUser = u.usr_ID
INNER JOIN [Contract].[tbContractMoalefeDastmozdi] md
    ON v.MoalfeVal_FKMoalafeDastmozdi = md.md_ID
INNER JOIN [dbo].[tbAdamAdam] aa
    ON aa.nam = u.usr_ID
    AND aa.Name = @personal
    AND aa.Value = 1
LEFT JOIN [dbo].[tbCities] c
    ON u.usr_City_Dutysystem = c.ID
LEFT JOIN [Salary].[tbMoadelPadashJarimeAyab] mp
    ON mp.UserID = u.usr_ID
    AND mp.Month = @month
    AND mp.Year = @year
LEFT JOIN [User].[tbjob] j
    ON u.usr_typeshoghl = j.ID
WHERE v.MoalfeVal_Month = @month
  AND v.MoalfeVal_Year = @year
  AND v.Final_accept = 1
ORDER BY u.usr_ID
";

            var data = db.Database.SqlQuery<TempResult>(sql,
                new SqlParameter("@month", month),
                new SqlParameter("@year", year),
                new SqlParameter("@personal", personal)
            ).ToList();

            var titles = data.Select(x => x.md_Title).Distinct().ToList();
            var grouped = data.GroupBy(x => x.usr_ID);

            using (var workbook = new ClosedXML.Excel.XLWorkbook())
            {
                var ws = workbook.Worksheets.Add("گزارش");

                int totalColumns = 5 + titles.Count; // FullName + PersonalID + JobName + City + Moadel + مولفه‌ها

                // ===== عنوان گزارش =====
                ws.Range(1, 1, 1, totalColumns).Merge();
                ws.Cell(1, 1).Value = $"گزارش مولفه‌ها - ماه {month} سال {year}";
                ws.Cell(1, 1).Style.Font.Bold = true;
                ws.Cell(1, 1).Style.Font.FontSize = 14;
                ws.Cell(1, 1).Style.Alignment.Horizontal = ClosedXML.Excel.XLAlignmentHorizontalValues.Center;
                ws.Cell(1, 1).Style.Fill.BackgroundColor = ClosedXML.Excel.XLColor.LightGray;

                // ===== هدر جدول =====
                int col = 1;
                ws.Cell(3, col++).Value = "نام و نام خانوادگی";
                ws.Cell(3, col++).Value = "کد پرسنلی";
                ws.Cell(3, col++).Value = "شغل"; // اضافه شد
                ws.Cell(3, col++).Value = "شهرستان";
                ws.Cell(3, col++).Value = "معادل";

                foreach (var t in titles)
                    ws.Cell(3, col++).Value = t;

                ws.Row(3).Style.Font.Bold = true;
                ws.Row(3).Style.Alignment.Horizontal = ClosedXML.Excel.XLAlignmentHorizontalValues.Center;

                // Freeze تا هدر
                ws.SheetView.FreezeRows(3);

                // ===== داده‌ها =====
                int rowIndex = 4;

                foreach (var user in grouped)
                {
                    var first = user.First();
                    col = 1;

                    ws.Cell(rowIndex, col++).Value = first.FullName;
                    ws.Cell(rowIndex, col++).Value = first.usr_Personal_ID ?? 0;
                    ws.Cell(rowIndex, col++).Value = first.JobName; // اضافه شد
                    ws.Cell(rowIndex, col++).Value = first.CityName;
                    ws.Cell(rowIndex, col++).Value = first.Moadel ?? 0;
                    ws.Cell(rowIndex, col - 1).Style.NumberFormat.Format = "#,##0.000"; // 3 رقم اعشار برای معادل

                    foreach (var t in titles)
                    {
                        var val = user
                            .Where(x => x.md_Title == t)
                            .Sum(x => x.Value ?? 0);

                        ws.Cell(rowIndex, col++).Value = val;
                        ws.Cell(rowIndex, col - 1).Style.NumberFormat.Format = "#,##0.0"; // 1 رقم اعشار برای مولفه‌ها
                    }

                    rowIndex++;
                }

                ws.Columns().AdjustToContents();

                using (var stream = new MemoryStream())
                {
                    workbook.SaveAs(stream);
                    stream.Position = 0;

                    return File(stream.ToArray(),
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        $"GozareshMoalefeh_{month}_{year}.xlsx");
                }
            }
        }
        public ActionResult ExportGozareshMoalefeh2()
        {
            int month = 8; int year = 1404;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return Json(new { success = false, message = "دسترسی غیرمجاز" });

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user1 = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user1 == null)
                return Json(new { success = false, message = "کاربر یافت نشد" });

            int personal = user1.usr_ID;

            db.Database.CommandTimeout = 600;

            string sql = @"
SELECT 
    u.usr_ID,
    u.usr_Name + ' ' + u.usr_Family AS FullName,
    u.usr_Personal_ID,
    md.md_Title,
    SUM(v.MoalfeVal_Value) AS Value
FROM [sistan29azar].[Salary].[tbMoalefeDastmozdiValueFromExcel] v
INNER JOIN [sistan29azar].[Usser].[tbUsers] u
    ON v.MoalfeVal_FKUser = u.usr_ID
INNER JOIN [sistan29azar].[Contract].[tbContractMoalefeDastmozdi] md
    ON v.MoalfeVal_FKMoalafeDastmozdi = md.md_ID

-- ✅ محدودیت دسترسی
INNER JOIN [sistan29azar].[dbo].[tbAdamAdam] aa
    ON aa.nam = u.usr_ID
    AND aa.Name = @personal
    AND aa.Value = 1

WHERE v.MoalfeVal_Month = @month
  AND v.MoalfeVal_Year = @year
  AND v.Final_accept = 1

GROUP BY 
    u.usr_ID,
    u.usr_Name,
    u.usr_Family,
    u.usr_Personal_ID,
    md.md_Title

ORDER BY u.usr_ID
";

            var data = db.Database.SqlQuery<TempResult>(
                sql,
                new SqlParameter("@month", month),
                new SqlParameter("@year", year),
                new SqlParameter("@personal", personal)
            ).ToList();

            var titles = data.Select(x => x.md_Title).Distinct().ToList();
            var grouped = data.GroupBy(x => x.usr_ID);

            using (var workbook = new ClosedXML.Excel.XLWorkbook())
            {
                var ws = workbook.Worksheets.Add("گزارش");

                int col = 1;

                // هدر ثابت
                ws.Cell(1, col++).Value = "نام و نام خانوادگی";
                ws.Cell(1, col++).Value = "کد پرسنلی";

                // هدر داینامیک
                foreach (var t in titles)
                    ws.Cell(1, col++).Value = t;

                ws.Row(1).Style.Font.Bold = true;

                int rowIndex = 2;

                foreach (var user in grouped)
                {
                    var first = user.First();
                    col = 1;

                    ws.Cell(rowIndex, col++).Value = first.FullName;
                    ws.Cell(rowIndex, col++).Value = first.usr_Personal_ID ?? 0;

                    foreach (var t in titles)
                    {
                        var val = user
                            .Where(x => x.md_Title == t)
                            .Sum(x => x.Value ?? 0);

                        ws.Cell(rowIndex, col++).Value = val;
                    }

                    rowIndex++;
                }

                ws.Columns().AdjustToContents();

                using (var stream = new MemoryStream())
                {
                    workbook.SaveAs(stream);
                    stream.Position = 0;

                    return File(stream.ToArray(),
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        $"GozareshMoalefeh_{month}_{year}.xlsx");
                }
            }
        }
