        public ActionResult karkard_notsystem()
        {
            var find2 = db.dbvaziat_FIsh1Set.FirstOrDefault();

            int month = 11;
            int year = 1404;
            int datasl = 0;
            if (find2 != null)
            {
                month = (int)find2.month;
                year = (int)find2.yaer;
                var findd2 = db.tbtatialtmoadel.Where(s => s.month == month && s.year == year).FirstOrDefault();
                if (findd2 != null)
                {
                    datasl = (int)findd2.khales;

                }
            }

            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return Json(new { success = false, message = "دسترسی غیرمجاز" });

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user1 = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);

            if (user1 == null)
                return Json(new { success = false, message = "کاربر یافت نشد" });

            int personal = user1.usr_ID;

            db.Database.CommandTimeout = 6000;

            string sql = @"
SELECT 
    u.usr_ID,
    u.usr_Name + ' ' + u.usr_Family AS FullName,
    u.usr_Personal_ID,
    c.Name AS CityName,
    ISNULL(mp.Moadel,0) AS Moadel,
    ISNULL(kn.moadel_kol,0) AS MoadelGheirSystem

FROM [Usser].[tbUsers] u

INNER JOIN [dbo].[tbAdamAdam] aa
    ON aa.nam = u.usr_ID
    AND aa.Name = @personal
    AND aa.Value = 1

LEFT JOIN [dbo].[tbCities] c
    ON u.usr_City_Dutysystem = c.ID

LEFT JOIN [Salary].[tbMoadelPadashJarimeAyab] mp
    ON mp.UserID = u.usr_ID
    AND mp.Month = @month
    AND mp.Year = @year

LEFT JOIN (
    SELECT t1.FK_usr, t1.moadel_kol
    FROM [Salary].[tbkarkard_notsystem] t1
    INNER JOIN (
        SELECT FK_usr, MAX(timesabt) AS MaxTime
        FROM [Salary].[tbkarkard_notsystem]
        WHERE month = @month 
          AND year = @year 
          AND active = 1

        GROUP BY FK_usr
    ) t2 
      ON t1.FK_usr = t2.FK_usr 
     AND t1.timesabt = t2.MaxTime
     AND t1.month = @month
     AND t1.year = @year
     AND t1.active = 1
) kn
    ON kn.FK_usr = u.usr_ID

ORDER BY u.usr_ID
";
            var data = db.Database.SqlQuery<TempResult2>(
                sql,
                new SqlParameter("@month", month),
                new SqlParameter("@year", year),
                new SqlParameter("@personal", personal)
            ).ToList();

            var model = new FunctionModel();
            model.Users = new List<FunctionModel.UserRow>();

            foreach (var item in data)
            {
                model.Users.Add(new FunctionModel.UserRow
                {datasl= datasl,
                    UserId = item.usr_ID,
                    FullName = item.FullName,
                    PersonalId = item.usr_Personal_ID ?? 0,
                    CityName = item.CityName,
                    Moadel = item.Moadel ?? 0,
                    MoadelGheirSystem = item.MoadelGheirSystem ?? 0
                });
            }

            return View("~/Areas/Setting/Views/Orders/karkard_notsystem.cshtml", model);
        }
