                var yuuu = caran
                    .FirstOrDefault(p => p.FK_Moalefe_ID == it.MoalfeVal_FKMoalafeDastmozdi && p.CaranStandard != 0);

                var roundedValue = Math.Round(it.MoalfeVal_Value ?? 0);

                if (yuuu == null)
                {
                    var u = caran
                        .FirstOrDefault(p => p.FK_Moalefe_ID == it.MoalfeVal_FKMoalafeDastmozdi && p.CaranAyabOZahab != 0);

