                    {
                        mode.Add($"{it.tbContractMoalefeDastmozdi.md_Title} ( {u.CaranAyabOZahab}/ 0 /{roundedValue} )----");
                    }
                }
                else
                {
                    mode.Add($"{it.tbContractMoalefeDastmozdi.md_Title} ( {yuuu.CaranAyabOZahab}/ {yuuu.CaranStandard} /{roundedValue} )---");
                }
            }

            // تبدیل به رشته نهایی
