[HttpPost]
    // HttpPostedFileBase MyExcelStream را نگه می‌داریم، ولی usrId, moadelKol, items را حذف می‌کنیم
    public ActionResult SaveKarkardNotSystem(HttpPostedFileBase MyExcelStream)
    {
        try
        {
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return Json(new { success = false, message = "دسترسی غیرمجاز" });

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user1 = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);

            if (user1 == null)
                return Json(new { success = false, message = "کاربر یافت نشد" });

            int personal = user1.usr_ID;
            string fullname = user1.FullName;
            int codpersonal = (int)user1.usr_Personal_ID;

            var find2 = db.dbvaziat_FIsh1Set.FirstOrDefault();
            int month = find2 != null ? (int)find2.month : 11;
            int year = find2 != null ? (int)find2.yaer : 1404;

            // 🎯 **مهم:** خواندن مقادیر از Request
            int usrId = System.Convert.ToInt32(Request["usrId"]);
            double moadelKol = System.Convert.ToDouble(Request["moadelKol"]);

            // خواندن و Deserialization لیست items
            var itemsJson = Request["items"];
            List<KarkardNotSystemDto> items = new List<KarkardNotSystemDto>();
            if (!string.IsNullOrEmpty(itemsJson))
            {
                // برای این قسمت حتماً نیاز به نصب بسته Newtonsoft.Json دارید
                items = JsonConvert.DeserializeObject<List<KarkardNotSystemDto>>(itemsJson);
            }
            else
            {
                // اگر items ارسال نشده بود (و نباید خالی باشد)
                return Json(new { success = false, message = "لیست آیتم‌ها ارسال نشده است." });
            }

                // 🔹 پردازش فایل Excel (اگر ارسال شده باشد)

                string FileSystemName = "";
                string FileName = "";
                if (MyExcelStream != null && MyExcelStream.ContentLength > 0)
                {
                    var segment = MyExcelStream.FileName.Split('.');
                    string file_type = segment[segment.Length - 1];
                    var filename = (DateTime.Now.ToString("yyyy_MM_dd_mm_ss") + '.' + file_type).ToString();
                    MyExcelStream.SaveAs(System.Web.HttpContext.Current.Server.MapPath("~/Areas/Suggestion/Contents/" + filename));
                    FileSystemName = filename;
                    FileName = MyExcelStream.FileName;
                    // اینجا می‌توانید منطق ذخیره یا خواندن فایل Excel را اضافه کنید
                    // به عنوان مثال:


                    // اگر نیاز دارید اطلاعات Excel را بخوانید، باید از کتابخانه‌ای مثل EPPlus استفاده کنید
                    // و اطلاعات خوانده شده را در لیست `items` (یا یک لیست جدید) بریزید.
                    // مثال:
                    // using (var package = new ExcelPackage(new FileInfo(path)))
                    // {
                    //     var worksheet = package.Workbook.Worksheets[0]; // اولین شیت
                    //     // ... کد خواندن دیتا از worksheet ...
                    // }
                }

                // 🔸 ادامه منطق قبلی برای ذخیره در دیتابیس
                foreach (var item in items)
            {
                var existing = db.tbkarkard_notsystem.FirstOrDefault(x =>
                    x.FK_usr == usrId &&
                    x.FK_moaldeh == item.FK_moaldeh &&
                    x.month == month &&
                    x.year == year &&
                    x.usrsabt == personal);

                if (existing != null)
                    {
                        existing.FileSystemName = FileSystemName;
                        existing.FileName = FileName;
                        // 🔵 UPDATE
                        existing.moadel = item.moadel;
                    existing.moadel_kol = moadelKol;
                    existing.timesabt = DateTime.Now;
                    existing.active = 1;
                }
                else
                    {
               


                        // 🟢 INSERT
                        db.tbkarkard_notsystem.Add(new tbkarkard_notsystem
                    {
                            FileSystemName= FileSystemName,
                            FileName= FileName,
                        FK_usr = usrId,
                        FK_moaldeh = item.FK_moaldeh,
                        fullname = fullname,
                        code_pesonsabt = codpersonal,
                        moadel = item.moadel,
                        moadel_kol = moadelKol,
                        month = month,
                        year = year,
                        usrsabt = personal,
                        timesabt = DateTime.Now,
                        active = 1
                    });
                }
            }

            db.SaveChanges();

            return Json(new { success = true });
        }
        catch (Exception ex)
        {
            // در محیط واقعی، جزئیات خطا را در لاگ ذخیره کنید نه اینکه مستقیماً به کاربر نشان دهید
            return Json(new { success = false, message = "خطا در پردازش اطلاعات: " + ex.Message });
        }
    }
        public ActionResult ExportGozareshMoragasiExcel(int Year, int asMonth, int taMonth)
        {
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null) return null;

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user1 = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user1 == null) return null;

            int personal = user1.usr_ID;

            var monthRange = Enumerable.Range(asMonth, taMonth - asMonth + 1).ToList();

            List<string> columns = new List<string>();
            columns.Add("جمع کل");

            foreach (var m in monthRange)
                columns.Add(GetPersianMonthName(m));

            var userIds = db.tbAdamAdam
                .Where(s => s.Name == personal && s.Value == 1)
                .Select(s => s.nam)
                .ToList();

            var findmor = db.tbContractMoalefeDastmozdi
                .FirstOrDefault(s => s.md_Title == "تعداد روز استحقاقی");

            var users = db.tbUsers.Where(u => userIds.Contains(u.usr_ID)).ToList();

            var cities = db.tbCities.ToList();
            var jobs = db.tbjob.ToList();

            var fishh = db.tbMoalefeValueFish
                .Where(s =>
                    userIds.Contains(s.FK_User) &&
                    s.mlfvlfsh_Year == Year &&
                    s.mlfvlfsh_Month >= asMonth &&
                    s.mlfvlfsh_Month <= taMonth &&
                    s.FK_Moalefe == findmor.md_ID &&
                    s.Finalaccept == true)
                .ToList();

            using (var package = new OfficeOpenXml.ExcelPackage())
            {
                var ws = package.Workbook.Worksheets.Add("Report");

                int col = 1;

                ws.Cells[1, 1].Value = "گزارش مرخصی کارکنان";
                ws.Cells[1, 1, 1, 10].Merge = true;

                ws.Cells[2, 1].Value =
                    "از ماه " + GetPersianMonthName(asMonth) +
                    " تا ماه " + GetPersianMonthName(taMonth) +
                    " - سال " + Year;

                ws.Cells[2, 1, 2, 10].Merge = true;

                int headerRow = 3;

                ws.Cells[headerRow, col++].Value = "نام و نام خانوادگی";
                ws.Cells[headerRow, col++].Value = "کد پرسنلی";
                ws.Cells[headerRow, col++].Value = "شهرستان";
                ws.Cells[headerRow, col++].Value = "شغل";

                foreach (var c in columns)
                {
                    ws.Cells[headerRow, col++].Value = c;
                }

                int row = 4;

                foreach (var u in users)
                {
                    var city = cities.FirstOrDefault(c => c.ID == u.usr_City_Dutysystem);
                    var job = jobs.FirstOrDefault(j => j.ID == u.usr_typeshoghl);

                    col = 1;

                    ws.Cells[row, col++].Value = u.usr_Name + " " + u.usr_Family;
                    ws.Cells[row, col++].Value = u.usr_Personal_ID;
                    ws.Cells[row, col++].Value = city?.Name;
                    ws.Cells[row, col++].Value = job?.Name;

                    decimal total = 0;
                    Dictionary<int, decimal> monthValues = new Dictionary<int, decimal>();

                    foreach (var m in monthRange)
                    {
                        decimal val = fishh
                            .Where(x => x.FK_User == u.usr_ID && x.mlfvlfsh_Month == m)
                            .Sum(x => (decimal?)x.mlfvlfsh_Value ?? 0);

                        monthValues.Add(m, val);
                        total += val;
                    }

                    ws.Cells[row, col++].Value = total;

                    foreach (var m in monthRange)
                    {
                        ws.Cells[row, col++].Value = monthValues[m];
                    }

                    row++;
                }

                ws.Cells.AutoFitColumns();

                var bytes = package.GetAsByteArray();

                return File(bytes,
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    "GozareshMoragasi.xlsx");
            }
        }

        public ActionResult viewgozaresh_moragasi_see(int Year = 0, int asMonth = 0, int taMonth = 0)
        {
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return Json(new { success = false, message = "دسترسی غیرمجاز" }, JsonRequestBehavior.AllowGet);

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user1 = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user1 == null)
                return Json(new { success = false, message = "کاربر یافت نشد" }, JsonRequestBehavior.AllowGet);

            if (Year == 0 || asMonth == 0 || taMonth == 0)
                return Content("<div class='alert alert-danger'>سال و بازه ماه را انتخاب کنید.</div>");

            if (asMonth > taMonth)
                return Content("<div class='alert alert-danger'>از ماه نمی‌تواند بزرگ‌تر از تا ماه باشد.</div>");

            int personal = user1.usr_ID;

            var model = new FunctionModel();
            model.Users = new List<FunctionModel.UserRow>();
            model.MoalefehTitles = new List<string>();

            // ماه‌های بازه
            var monthRange = Enumerable.Range(asMonth, taMonth - asMonth + 1).ToList();

            // عنوان ستون‌ها: هر ماه + جمع کل
            foreach (var m in monthRange)
            {
                model.MoalefehTitles.Add(GetPersianMonthName(m));
            }
            model.MoalefehTitles.Add("جمع کل");

            // کاربران زیرمجموعه/مجاز
            var userIds = db.tbAdamAdam
                .Where(s => s.Name == personal && s.Value == 1)
                .Select(s => s.nam)
                .ToList();

            var findmor = db.tbContractMoalefeDastmozdi
                .FirstOrDefault(s => s.md_Title == "تعداد روز استحقاقی");

            if (findmor == null)
                return PartialView("_viewgozaresh_moragasi", model);

            var users = db.tbUsers
                .Where(u => userIds.Contains(u.usr_ID))
                .ToList();

            var cities = db.tbCities.ToList();
            var jobs = db.tbjob.ToList();

            // همه اطلاعات مرخصی در یک بار خواندن
            var fishh = db.tbMoalefeValueFish
                .Where(s =>
                    userIds.Contains(s.FK_User) &&
                    s.mlfvlfsh_Year == Year &&
                    s.mlfvlfsh_Month >= asMonth &&
                    s.mlfvlfsh_Month <= taMonth &&
                    s.FK_Moalefe == findmor.md_ID &&
                    s.Finalaccept == true)
                .ToList();

            foreach (var u in users)
            {
                var city = cities.FirstOrDefault(c => c.ID == u.usr_City_Dutysystem);
                var job = jobs.FirstOrDefault(j => j.ID == u.usr_typeshoghl);

                var row = new FunctionModel.UserRow
                {
                    UserId = u.usr_ID,
                    FullName = (u.usr_Name ?? "") + " " + (u.usr_Family ?? ""),
                    PersonalId = u.usr_Personal_ID ?? 0,
                    CityName = city != null ? city.Name : "",
                    JobName = job != null ? job.Name : "",
                    Moadel = 0,
                    Values = new Dictionary<string, decimal>()
                };

                decimal total = 0;
                Dictionary<string, decimal> monthValues = new Dictionary<string, decimal>();


                foreach (var month in monthRange)
                {
                    decimal monthValue = fishh
                        .Where(x => x.FK_User == u.usr_ID && x.mlfvlfsh_Month == month)
                        .Sum(x => (decimal?)(x.mlfvlfsh_Value) ?? 0);

                    monthValues.Add(GetPersianMonthName(month), monthValue);
                    total += monthValue;
                }

                // اول جمع
                row.Values.Add("جمع کل", total);

                // بعد ماه‌ها
                foreach (var item in monthValues)
                {
                    row.Values.Add(item.Key, item.Value);
                }

                //row.Values.Add("جمع کل", total);

                model.Users.Add(row);
            }

            return PartialView( model);
        }

        private string GetPersianMonthName(int month)
        {
            switch (month)
            {
                case 1: return "فروردین";
                case 2: return "اردیبهشت";
                case 3: return "خرداد";
                case 4: return "تیر";
                case 5: return "مرداد";
                case 6: return "شهریور";
                case 7: return "مهر";
                case 8: return "آبان";
                case 9: return "آذر";
                case 10: return "دی";
                case 11: return "بهمن";
                case 12: return "اسفند";
                default: return "";
            }
        }

        public ActionResult GozareshMoalefeh()
        {
            var find2 = db.dbvaziat_FIsh1Set.FirstOrDefault();
            
            int month =2; int year = 1405;
            if (find2 != null)
            {
                month = (int)find2.month;
                year = (int)find2.yaer;

            }
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return Json(new { success = false, message = "دسترسی غیرمجاز" });

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user1 = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user1 == null)
                return Json(new { success = false, message = "کاربر یافت نشد" });

            int personal = user1.usr_ID;

            var model = new FunctionModel();
            model.Users = new List<FunctionModel.UserRow>();

            db.Database.CommandTimeout = 6000;

            string sql = @"
SELECT 
    u.usr_ID,
    u.usr_Name + ' ' + u.usr_Family AS FullName,
    u.usr_Personal_ID,
    md.md_Title,
    v.MoalfeVal_Value AS Value,
    c.Name AS CityName,
    mp.Moadel,
    j.Name AS JobName  -- اضافه شد
FROM [Salary].[tbMoalefeDastmozdiValueFromExcel] v
INNER JOIN [Usser].[tbUsers] u
    ON v.MoalfeVal_FKUser = u.usr_ID
INNER JOIN [Contract].[tbContractMoalefeDastmozdi] md
    ON v.MoalfeVal_FKMoalafeDastmozdi = md.md_ID
INNER JOIN [dbo].[tbAdamAdam] aa
    ON aa.nam = u.usr_ID
    AND aa.Name = @personal
    AND aa.Value = 1
LEFT JOIN [dbo].[tbCities] c
    ON u.usr_City_Dutysystem = c.ID
LEFT JOIN [Salary].[tbMoadelPadashJarimeAyab] mp
    ON mp.UserID = u.usr_ID
    AND mp.Month = @month
    AND mp.Year = @year
LEFT JOIN [User].[tbjob] j
    ON u.usr_typeshoghl = j.ID
WHERE v.MoalfeVal_Month = @month
  AND v.MoalfeVal_Year = @year
  AND v.Final_accept = 1
ORDER BY u.usr_ID
";

            var data = db.Database.SqlQuery<TempResult>(
       sql,
       new SqlParameter("@month", month),
       new SqlParameter("@year", year),
       new SqlParameter("@personal", personal)
   ).ToList();

            // گرفتن لیست مولفه‌ها
            model.MoalefehTitles = data
                .Select(x => x.md_Title)
                .Distinct()
                .ToList();

            var grouped = data.GroupBy(x => x.usr_ID);

            foreach (var user in grouped)
            {
                var first = user.First();

                var row = new FunctionModel.UserRow
                {
                    UserId = (int)first.usr_ID,
                    FullName = first.FullName,
                    PersonalId = (int)first.usr_Personal_ID,
                    CityName = first.CityName,   // اضافه شد
                    Moadel = first.Moadel ?? 0, // اضافه شد
                    JobName = first.JobName, // اضافه شد

                    Values = new Dictionary<string, decimal>()
                };

                foreach (var title in model.MoalefehTitles)
                {
                    var val = user
      .Where(x => x.md_Title == title)
      .Sum(x => x.Value ?? 0);

                    row.Values.Add(title, (decimal)val);
                }
              
                model.Users.Add(row);
            }

            return View(model);
        }

