        public ActionResult GetFinalZarib1275Excel()
        {
            try
            {
                db.Database.CommandTimeout = 1000;

                string sql = @"
;WITH LatestRecord AS
(
    SELECT MAX(ID) AS MaxID
    FROM [sistan6mehr].[dbo].[dbergharelinsert_6]
    WHERE FK_table4 = 28
),

UserData AS
(
    SELECT 
        L.name,
        MIN(L.FK_usr) AS FK_usr
    FROM [sistan6mehr].[Salary].[tbLink_name_usr] L
    GROUP BY L.name
),

ValuUnic92 AS
(
    SELECT 
        T2.valuunic AS valuunic_form,
        T3.valuunic AS valuunic_bace,
        T2.valueFK_db2 AS value92
    FROM [sistan6mehr].[dbo].[dbergharelimsertfk1_7] T2
    LEFT JOIN [sistan6mehr].[dbo].[dbergharelimsertfk1_7_1218_bace] T3
        ON T2.valueFK_db2 = T3.valueFK_db2
       AND T3.FK_db2 = 92
    WHERE 
        T2.FK_dbergharelinsert_6 = (SELECT MaxID FROM LatestRecord)
        AND T2.FK_db2 = 171
),

BaceData AS
(
    SELECT 
        B.valuunic,
        MAX(CASE WHEN B.FK_db2 = 411 THEN B.valueFK_db2 END) AS v411,
        MAX(CASE WHEN B.FK_db2 = 412 THEN B.valueFK_db2 END) AS v412,
        MAX(CASE WHEN B.FK_db2 = 415 THEN B.valueFK_db2 END) AS v415
    FROM [sistan6mehr].[dbo].[dbergharelimsertfk1_7_1218_bace] B
    WHERE B.FK_db2 IN (411,412,415)
    GROUP BY B.valuunic
),

T1218Data AS
(
    SELECT 
        T.valuunic,
        MAX(T.valueFK_db2) AS v185
    FROM [sistan6mehr].[dbo].[dbergharelimsertfk1_7_1218] T
    WHERE 
        T.FK_db2 = 185
        AND T.FK_dbergharelinsert_6 =
        (
            SELECT MAX(FK_dbergharelinsert_6)
            FROM [sistan6mehr].[dbo].[dbergharelimsertfk1_7_1218]
        )
    GROUP BY T.valuunic
),

FormData AS
(
    SELECT 
        F.valuunic,

        MAX(CASE WHEN F.FK_db2 = 169 THEN F.valueFK_db2 END) AS [1275_نام شهر],
        MAX(CASE WHEN F.FK_db2 = 170 THEN F.valueFK_db2 END) AS [1275_اشتراک],
        MAX(CASE WHEN F.FK_db2 = 171 THEN F.valueFK_db2 END) AS [1275_پرونده],
        MAX(CASE WHEN F.FK_db2 = 172 THEN F.valueFK_db2 END) AS [1275_نام مشترک],
        MAX(CASE WHEN F.FK_db2 = 173 THEN F.valueFK_db2 END) AS [1275_مبلغ بدهي],
        MAX(CASE WHEN F.FK_db2 = 174 THEN F.valueFK_db2 END) AS [1275_مبلغ وصول شده],
        MAX(CASE WHEN F.FK_db2 = 175 THEN F.valueFK_db2 END) AS [1275_درصد وصولي],
        MAX(CASE WHEN F.FK_db2 = 176 THEN F.valueFK_db2 END) AS [1275_آيا درخواست وصل مجدد ثبت شده است؟],
        MAX(CASE WHEN F.FK_db2 = 177 THEN F.valueFK_db2 END) AS [1275_تاريخ پرداخت],
        MAX(CASE WHEN F.FK_db2 = 178 THEN F.valueFK_db2 END) AS [1275_نام مامور]

    FROM [sistan6mehr].[dbo].[dbergharelimsertfk1_7] F
    INNER JOIN ValuUnic92 V
        ON V.valuunic_form = F.valuunic
    WHERE 
        F.FK_db2 BETWEEN 169 AND 178
        AND F.FK_dbergharelinsert_6 = (SELECT MaxID FROM LatestRecord)
    GROUP BY F.valuunic
),

BaseData AS
(
    SELECT
        VU.value92,
        VU.valuunic_bace,

        BD.v411,
        BD.v412,
        BD.v415,

        TD.v185,
        R.vaziat,

        FD.[1275_نام شهر],
        FD.[1275_اشتراک],
        FD.[1275_پرونده],
        FD.[1275_نام مشترک],
        FD.[1275_مبلغ بدهي],
        FD.[1275_مبلغ وصول شده],
        FD.[1275_درصد وصولي],
        FD.[1275_آيا درخواست وصل مجدد ثبت شده است؟],
        FD.[1275_تاريخ پرداخت],
        FD.[1275_نام مامور],

        U.name AS usr_name,
        U.FK_usr AS usr_id,

        TRY_CAST(FD.[1275_مبلغ وصول شده] AS DECIMAL(18,2)) AS Amount174

    FROM ValuUnic92 VU
    LEFT JOIN BaceData BD
        ON BD.valuunic = VU.valuunic_bace
    LEFT JOIN T1218Data TD
        ON TD.valuunic = VU.valuunic_bace
    LEFT JOIN FormData FD
        ON FD.valuunic = VU.valuunic_form
    LEFT JOIN [sistan6mehr].[dbo].[Result1218_tarigh] R
        ON R.start_tme = TD.v185
    LEFT JOIN UserData U
        ON U.name = FD.[1275_نام مامور]
)

SELECT
    B.value92,
    B.valuunic_bace,

    B.v411,
    B.v412,
    B.v415,

    B.v185,
    B.vaziat,

    B.[1275_نام شهر],
    B.[1275_اشتراک],
    B.[1275_پرونده],
    B.[1275_نام مشترک],
    B.[1275_مبلغ بدهي],
    B.[1275_مبلغ وصول شده],
    B.[1275_درصد وصولي],
    B.[1275_آيا درخواست وصل مجدد ثبت شده است؟],
    B.[1275_تاريخ پرداخت],
    B.[1275_نام مامور],

    B.usr_name,
    B.usr_id,

    X.Zarib411,
    X.Zarib412,
    X.Zarib415,
    X.Zarib185,

    Z.ZaribFinal,

    ISNULL(B.Amount174, 0) * Z.ZaribFinal AS FinalAmount

FROM BaseData B

CROSS APPLY
(
    SELECT
        CASE 
            WHEN B.v411 IS NULL THEN 1
            WHEN B.v411 = N'خانگی' THEN 1.3
            WHEN B.v411 IN (N'سایر مصارف', N'عمومی') THEN 1.1
            WHEN B.v411 IN (N'کشاورزی', N'صنعتی') THEN 0.9
            WHEN B.v411 = N'روشنایی معابر' THEN 0
            ELSE 1
        END AS Zarib411,

        CASE
            WHEN B.v412 IS NULL THEN 1
            WHEN B.v412 = N'عادی' THEN 1
            WHEN B.v412 = N'دیماند' THEN 0.7
            ELSE 1
        END AS Zarib412,

        CASE
            WHEN B.v415 IS NULL THEN 1
            WHEN B.v415 = N'شهری' THEN 1
            WHEN B.v415 = N'روستایی' THEN 1.2
            WHEN B.v415 = N'خارج از محدوده' THEN 0
            ELSE 1
        END AS Zarib415,

        CASE
            WHEN B.v185 IS NULL THEN 1
            WHEN B.vaziat IN (1,2,4) THEN 1
            WHEN B.vaziat = 5 THEN 1.1
            WHEN B.vaziat = 6 THEN 1.2
            WHEN B.vaziat = 7 THEN 1.3
            WHEN B.vaziat = 8 THEN 1.4
            WHEN B.vaziat = 9 THEN 1.5
            WHEN B.vaziat > 9 THEN 1.6
            ELSE 1
        END AS Zarib185
) X

CROSS APPLY
(
    SELECT 
        X.Zarib411 * 
        X.Zarib412 * 
        X.Zarib415 * 
        X.Zarib185 AS ZaribFinal
) Z

WHERE ISNULL(B.Amount174, 0) <> 0
ORDER BY B.valuunic_bace;
";

                var data = db.Database.SqlQuery<FinalZarib1275ExcelDto>(sql).ToList();

                using (var workbook = new XLWorkbook())
                {
                    var ws = workbook.Worksheets.Add("FinalZarib1275");

                    // Header
                    ws.Cell(1, 1).Value = "value92";
                    ws.Cell(1, 2).Value = "valuunic_bace";
