                    ws.Cell(1, 11).Value = "1275_نام مشترک";
                    ws.Cell(1, 12).Value = "1275_مبلغ بدهي";
                    ws.Cell(1, 13).Value = "1275_مبلغ وصول شده";
                    ws.Cell(1, 14).Value = "1275_درصد وصولي";
                    ws.Cell(1, 15).Value = "1275_آيا درخواست وصل مجدد ثبت شده است؟";
                    ws.Cell(1, 16).Value = "1275_تاريخ پرداخت";
                    ws.Cell(1, 17).Value = "1275_نام مامور";

                    ws.Cell(1, 18).Value = "usr_name";
                    ws.Cell(1, 19).Value = "usr_id";

                    ws.Cell(1, 20).Value = "Zarib411";
                    ws.Cell(1, 21).Value = "Zarib412";
                    ws.Cell(1, 22).Value = "Zarib415";
                    ws.Cell(1, 23).Value = "Zarib185";
                    ws.Cell(1, 24).Value = "ZaribFinal";
                    ws.Cell(1, 25).Value = "FinalAmount";

                    int row = 2;
                    foreach (var item in data)
                    {
                        ws.Cell(row, 1).Value = item.value92;
                        ws.Cell(row, 2).Value = item.valuunic_bace;
                        ws.Cell(row, 3).Value = item.v411;
