                        ws.Cell(row, 8).Value = item.نام_شهر_1275;
                        ws.Cell(row, 9).Value = item.اشتراک_1275;
                        ws.Cell(row, 10).Value = item.پرونده_1275;
                        ws.Cell(row, 11).Value = item.نام_مشترک_1275;
                        ws.Cell(row, 12).Value = item.مبلغ_بدهی_1275;
                        ws.Cell(row, 13).Value = item.مبلغ_وصول_شده_1275;
                        ws.Cell(row, 14).Value = item.درصد_وصولی_1275;
                        ws.Cell(row, 15).Value = item.آیا_درخواست_وصل_مجدد_ثبت_شده_است_1275;
                        ws.Cell(row, 16).Value = item.تاریخ_پرداخت_1275;
