        public ActionResult GetFinalZaribReport()
        {
            try
            {
                db.Database.CommandTimeout = 1000;

                string sql = @"
;WITH LatestRecord AS
(
    SELECT MAX(ID) AS MaxID
    FROM sistan29azar.dbo.dbergharelinsert_6
    WHERE FK_table4 = 28
),
ValuUnic92 AS
(
    SELECT 
        T2.valuunic AS valuunic_form,
        T3.valuunic AS valuunic_bace,
        T3.valueFK_db2 AS value92
    FROM sistan29azar.dbo.dbergharelimsertfk1_7 T2
    INNER JOIN sistan29azar.dbo.dbergharelimsertfk1_7_1218_bace T3
        ON T2.valueFK_db2 = T3.valueFK_db2
    CROSS JOIN LatestRecord LR
    WHERE T2.FK_dbergharelinsert_6 = LR.MaxID
      AND T2.FK_db2 = 170
      AND T3.FK_db2 = 92
),
BaceData AS
(
    SELECT 
        valuunic,
        MAX(CASE WHEN FK_db2 = 411 THEN valueFK_db2 END) AS v411,
        MAX(CASE WHEN FK_db2 = 412 THEN valueFK_db2 END) AS v412,
        MAX(CASE WHEN FK_db2 = 415 THEN valueFK_db2 END) AS v415
    FROM sistan29azar.dbo.dbergharelimsertfk1_7_1218_bace
    WHERE FK_db2 IN (411,412,415)
    GROUP BY valuunic
),
T1218Data AS
(
    SELECT 
        valuunic,
        MAX(CASE WHEN FK_db2 = 185 THEN valueFK_db2 END) AS v185
    FROM sistan29azar.dbo.dbergharelimsertfk1_7_1218
    WHERE FK_db2 = 185
    GROUP BY valuunic
),
FormData AS
(
    SELECT 
        valuunic,
        MAX(CASE WHEN FK_db2 = 174 THEN valueFK_db2 END) AS v174,
        MAX(CASE WHEN FK_db2 = 178 THEN valueFK_db2 END) AS v178,
        MAX(CASE WHEN FK_db2 = 177 THEN valueFK_db2 END) AS v177,
        MAX(CASE WHEN FK_db2 = 175 THEN valueFK_db2 END) AS v175
    FROM sistan29azar.dbo.dbergharelimsertfk1_7
    WHERE FK_db2 IN (174,178,177,175)
    GROUP BY valuunic
)

SELECT
    VU.value92,
    VU.valuunic_bace,
    BD.v411,
    BD.v412,
    BD.v415,
    TD.v185,
    R.vaziat,
    FD.v174,
    FD.v178,
    FD.v177,
    FD.v175,

    (
        CASE WHEN BD.v411 = N'خانگی' THEN 1.3
             WHEN BD.v411 = N'سایر مصارف' THEN 1.1
             WHEN BD.v411 = N'عمومی' THEN 1.1
             WHEN BD.v411 = N'کشاورزی' THEN 0.9
             WHEN BD.v411 = N'صنعتی' THEN 0.9
             WHEN BD.v411 = N'روشنایی معابر' THEN 0
             ELSE 0 END
        *
        CASE WHEN BD.v412 = N'عادی' THEN 1 
             WHEN BD.v412 = N'دیماند' THEN 0.7 ELSE 0 END
        *
        CASE WHEN BD.v415 = N'شهری' THEN 1 
             WHEN BD.v415 = N'روستایی' THEN 1.2
             WHEN BD.v415 = N'خارج از محدوده' THEN 0
             ELSE 0 END
        *
        CASE WHEN R.vaziat = 1 THEN 1 
             WHEN R.vaziat IN (2,4) THEN 1
             WHEN R.vaziat = 5 THEN 1.1
             WHEN R.vaziat = 6 THEN 1.2
             WHEN R.vaziat = 7 THEN 1.3
             WHEN R.vaziat = 8 THEN 1.4
             WHEN R.vaziat = 9 THEN 1.5
             WHEN R.vaziat > 9 THEN 1.6
             ELSE 0 END
    ) AS ZaribFinal,

    ISNULL(TRY_CAST(FD.v174 AS DECIMAL(18,2)),0) *
    (
        CASE WHEN BD.v411 = N'خانگی' THEN 1.3
             WHEN BD.v411 = N'سایر مصارف' THEN 1.1
             WHEN BD.v411 = N'عمومی' THEN 1.1
             WHEN BD.v411 = N'کشاورزی' THEN 0.9
             WHEN BD.v411 = N'صنعتی' THEN 0.9
             WHEN BD.v411 = N'روشنایی معابر' THEN 0
             ELSE 0 END
        *
        CASE WHEN BD.v412 = N'عادی' THEN 1 
             WHEN BD.v412 = N'دیماند' THEN 0.7 ELSE 0 END
        *
        CASE WHEN BD.v415 = N'شهری' THEN 1 
             WHEN BD.v415 = N'روستایی' THEN 1.2
             WHEN BD.v415 = N'خارج از محدوده' THEN 0
             ELSE 0 END
        *
        CASE WHEN R.vaziat = 1 THEN 1 
             WHEN R.vaziat IN (2,4) THEN 1
             WHEN R.vaziat = 5 THEN 1.1
             WHEN R.vaziat = 6 THEN 1.2
             WHEN R.vaziat = 7 THEN 1.3
             WHEN R.vaziat = 8 THEN 1.4
             WHEN R.vaziat = 9 THEN 1.5
             WHEN R.vaziat > 9 THEN 1.6
             ELSE 0 END
    ) AS FinalAmount

FROM ValuUnic92 VU
LEFT JOIN BaceData BD ON BD.valuunic = VU.valuunic_bace
LEFT JOIN T1218Data TD ON TD.valuunic = VU.valuunic_bace
LEFT JOIN FormData FD ON FD.valuunic = VU.valuunic_form
LEFT JOIN sistan29azar.dbo.Result1218_tarigh R ON R.start_tme = TD.v185

WHERE ISNULL(TRY_CAST(FD.v174 AS DECIMAL(18,2)), 0) <> 0;
";

                var data = db.Database.SqlQuery<FinalZaribDto>(sql).ToList();

                return new JsonResult
                {
                    Data = data,
                    JsonRequestBehavior = JsonRequestBehavior.AllowGet,
                    MaxJsonLength = int.MaxValue
                };
            }
            catch (Exception ex)
            {
                return Json(new { error = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }
