            try
            {
                db.Database.CommandTimeout = 1000;

                string sql = @"
;WITH LatestRecord AS
(
    SELECT MAX(ID) AS MaxID
    FROM dbo.dbergharelinsert_6
    WHERE FK_table4 = 28
),

UserData AS
(
    SELECT 
        L.name,
        MIN(L.FK_usr) AS FK_usr
    FROM Salary.tbLink_name_usr L
    GROUP BY L.name
),

ValuUnic92 AS
(
