        T2.valueFK_db2 AS value92
    FROM dbo.dbergharelimsertfk1_7 T2

    LEFT JOIN dbo.dbergharelimsertfk1_7_1218_bace T3
        ON T2.valueFK_db2 = T3.valueFK_db2
       AND T3.FK_db2 = 92

    WHERE T2.FK_dbergharelinsert_6 = (SELECT MaxID FROM LatestRecord)
      AND T2.FK_db2 = 171
),

BaceData AS
(
    SELECT 
        B.valuunic,
        MAX(CASE WHEN B.FK_db2 = 411 THEN B.valueFK_db2 END) AS v411,
        MAX(CASE WHEN B.FK_db2 = 412 THEN B.valueFK_db2 END) AS v412,
        MAX(CASE WHEN B.FK_db2 = 415 THEN B.valueFK_db2 END) AS v415
    FROM dbo.dbergharelimsertfk1_7_1218_bace B
    WHERE B.FK_db2 IN (411,412,415)
    GROUP BY B.valuunic
),

T1218Data AS
(
    SELECT 
        T.valuunic,
        MAX(T.valueFK_db2) AS v185
    FROM dbo.dbergharelimsertfk1_7_1218 T
    WHERE T.FK_db2 = 185
    GROUP BY T.valuunic
),

FormData AS
(
    SELECT 
        F.valuunic,

        MAX(CASE WHEN F.FK_db2 = 169 THEN F.valueFK_db2 END) AS shahr,
        MAX(CASE WHEN F.FK_db2 = 170 THEN F.valueFK_db2 END) AS eshterak,
        MAX(CASE WHEN F.FK_db2 = 171 THEN F.valueFK_db2 END) AS parvande,
        MAX(CASE WHEN F.FK_db2 = 172 THEN F.valueFK_db2 END) AS moshtarak,
        MAX(CASE WHEN F.FK_db2 = 173 THEN F.valueFK_db2 END) AS bedehi,
        MAX(CASE WHEN F.FK_db2 = 174 THEN F.valueFK_db2 END) AS vosool,
        MAX(CASE WHEN F.FK_db2 = 175 THEN F.valueFK_db2 END) AS darsad,
        MAX(CASE WHEN F.FK_db2 = 176 THEN F.valueFK_db2 END) AS darkhast,
        MAX(CASE WHEN F.FK_db2 = 177 THEN F.valueFK_db2 END) AS tarikh,
        MAX(CASE WHEN F.FK_db2 = 178 THEN F.valueFK_db2 END) AS mamor

    FROM dbo.dbergharelimsertfk1_7 F

    INNER JOIN ValuUnic92 V
        ON V.valuunic_form = F.valuunic

    WHERE F.FK_db2 BETWEEN 169 AND 178
      AND F.FK_dbergharelinsert_6 = (SELECT MaxID FROM LatestRecord)

    GROUP BY F.valuunic
),

BaseData AS
(
    SELECT
        VU.value92,
        VU.valuunic_bace,

        BD.v411,
        BD.v412,
        BD.v415,

        TD.v185,
        R.vaziat,

        FD.shahr,
