        MIN(L.FK_usr) AS FK_usr
    FROM Salary.tbLink_name_usr L
    GROUP BY L.name
),
ValuUnic92 AS
(
    SELECT 
        T2.valuunic AS valuunic_form,
        T3.valuunic AS valuunic_bace,
        T2.valueFK_db2 AS value92
    FROM dbo.dbergharelimsertfk1_7 T2
    LEFT JOIN dbo.dbergharelimsertfk1_7_1218_bace T3
        ON T2.valueFK_db2 = T3.valueFK_db2
        AND T3.FK_db2 = 92
    WHERE T2.FK_dbergharelinsert_6 = (SELECT MaxID FROM LatestRecord)
      AND T2.FK_db2 = 171
),
BaceData AS
(
    SELECT 
        B.valuunic,
        MAX(CASE WHEN B.FK_db2 = 411 THEN B.valueFK_db2 END) AS v411,
        MAX(CASE WHEN B.FK_db2 = 412 THEN B.valueFK_db2 END) AS v412,
        MAX(CASE WHEN B.FK_db2 = 415 THEN B.valueFK_db2 END) AS v415
    FROM dbo.dbergharelimsertfk1_7_1218_bace B
    WHERE B.FK_db2 IN (411,412,415)
    GROUP BY B.valuunic
),
T1218Data AS
(
    SELECT 
        T.valuunic,
        MAX(T.valueFK_db2) AS v185
    FROM dbo.dbergharelimsertfk1_7_1218 T
    WHERE T.FK_db2 = 185
    GROUP BY T.valuunic
),
FormData AS
(
    SELECT 
        F.valuunic,
        MAX(CASE WHEN F.FK_db2 = 174 THEN F.valueFK_db2 END) AS v174,
        MAX(CASE WHEN F.FK_db2 = 178 THEN F.valueFK_db2 END) AS v178,
        MAX(CASE WHEN F.FK_db2 = 177 THEN F.valueFK_db2 END) AS v177,
        MAX(CASE WHEN F.FK_db2 = 175 THEN F.valueFK_db2 END) AS v175
    FROM dbo.dbergharelimsertfk1_7 F
    INNER JOIN ValuUnic92 V
        ON V.valuunic_form = F.valuunic
    WHERE F.FK_db2 IN (174,175,177,178)
      AND F.FK_dbergharelinsert_6 = (SELECT MaxID FROM LatestRecord)
    GROUP BY F.valuunic
),
BaseData AS
(
    SELECT
        VU.value92,
        VU.valuunic_bace,
        BD.v411,
        BD.v412,
        BD.v415,
        TD.v185,
        R.vaziat,
        FD.v174,
        FD.v178,
        FD.v177,
        FD.v175,
        U.name AS usr_name,
        U.FK_usr AS usr_id,
        TRY_CAST(FD.v174 AS DECIMAL(18,2)) AS Amount174
    FROM ValuUnic92 VU
    LEFT JOIN BaceData BD
        ON BD.valuunic = VU.valuunic_bace
    LEFT JOIN T1218Data TD
        ON TD.valuunic = VU.valuunic_bace
    LEFT JOIN FormData FD
        ON FD.valuunic = VU.valuunic_form
    LEFT JOIN dbo.Result1218_tarigh R
        ON R.start_tme = TD.v185
    LEFT JOIN UserData U
        ON U.name = FD.v178
),
FinalData AS
(
    SELECT
        B.value92,
        B.valuunic_bace,
        B.v411,
        B.v412,
        B.v415,
        B.v185,
        B.vaziat,
        B.v174,
        B.v178,
        B.v177,
        B.v175,
        B.usr_name,
        B.usr_id,
        ISNULL(B.Amount174, 0) *
        (
            CASE 
                WHEN B.v411 = N'خانگی' THEN 1.3
                WHEN B.v411 IN (N'سایر مصارف', N'عمومی') THEN 1.1
                WHEN B.v411 IN (N'کشاورزی', N'صنعتی') THEN 0.9
                WHEN B.v411 = N'روشنایی معابر' THEN 0
                ELSE 1
            END
            *
            CASE
                WHEN B.v412 = N'عادی' THEN 1
                WHEN B.v412 = N'دیماند' THEN 0.7
                ELSE 1
            END
            *
            CASE
                WHEN B.v415 = N'شهری' THEN 1
                WHEN B.v415 = N'روستایی' THEN 1.2
                WHEN B.v415 = N'خارج از محدوده' THEN 0
                ELSE 1
            END
            *
            CASE
                WHEN B.vaziat IN (1,2,4) THEN 1
                WHEN B.vaziat = 5 THEN 1.1
                WHEN B.vaziat = 6 THEN 1.2
                WHEN B.vaziat = 7 THEN 1.3
                WHEN B.vaziat = 8 THEN 1.4
                WHEN B.vaziat = 9 THEN 1.5
                WHEN B.vaziat > 9 THEN 1.6
                ELSE 1
            END
        ) AS FinalAmount
    FROM BaseData B
    WHERE ISNULL(B.Amount174, 0) <> 0
)

SELECT
    F.usr_id,
    MAX(F.usr_name) AS usr_name,
    U.usr_Personal_ID,
    MAX(U1.Name) AS usr_city,
    SUM(F.FinalAmount) AS SumFinalAmount
FROM FinalData F
LEFT JOIN Usser.tbUsers U
    ON U.usr_ID = F.usr_id
LEFT JOIN dbo.tbCities U1
    ON U1.ID = U.usr_City_Dutysystem
GROUP BY
    F.usr_id,
    U.usr_Personal_ID
ORDER BY
    usr_name
";

                var data = db.Database.SqlQuery<FinalZaribReportDto>(sql).ToList();

                using (var workbook = new ClosedXML.Excel.XLWorkbook())
                {
                    var ws = workbook.Worksheets.Add("Report");

                    ws.Cell(1, 1).Value = "کد کاربر";
                    ws.Cell(1, 2).Value = "نام کاربر";
                    ws.Cell(1, 3).Value = "کد پرسنلی";
                    ws.Cell(1, 4).Value = "شهر";
                    ws.Cell(1, 5).Value = "جمع مبلغ";

                    int row = 2;

                    foreach (var item in data)
                    {
                        ws.Cell(row, 1).Value = item.usr_id;
                        ws.Cell(row, 2).Value = item.usr_name;
                        ws.Cell(row, 3).Value = item.usr_Personal_ID;
                        ws.Cell(row, 4).Value = item.usr_city;
                        ws.Cell(row, 5).Value = item.SumFinalAmount;

                        row++;
                    }

                    ws.Columns().AdjustToContents();

                    ws.RightToLeft = true;

                    using (var stream = new MemoryStream())
                    {
                        workbook.SaveAs(stream);

                        return File(
                            stream.ToArray(),
                            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                            "FinalZaribReport.xlsx"
                        );
                    }
                }
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    success = false,
                    message = ex.Message
                }, JsonRequestBehavior.AllowGet);
            }
        }
