        public ActionResult GeneratePriority(int day, int month, int year)
        {
            try
            {
                db.Database.CommandTimeout = 10000;

                string sql = @"

SET NOCOUNT ON;

DECLARE @day INT=@p_day;
DECLARE @month INT=@p_month;
DECLARE @yaer INT=@p_year;

DECLARE @Last21 BIGINT, @Last5 BIGINT, @find17 BIGINT, @find19 BIGINT;

SELECT TOP(1) @Last21 = d.ID 
FROM dbergharelinsert_6 d 
JOIN dbergharel_4 f ON d.FK_table4 = f.ID 
WHERE f.FK_namegozarwsh = 21 
ORDER BY d.ID DESC;

SELECT TOP(1) @find17 = d.ID 
FROM dbo.dbergharelinsert_6 d 
JOIN dbo.dbergharel_4 g ON d.FK_table4 = g.ID 
WHERE g.FK_namegozarwsh = 17 
ORDER BY d.ID DESC;

SELECT TOP(1) @Last5 = d.ID 
FROM dbergharelinsert_6 d 
JOIN dbergharel_4 f ON d.FK_table4 = f.ID 
WHERE f.FK_namegozarwsh = 5 
ORDER BY d.ID DESC;

SELECT TOP(1) @find19 = d.ID 
FROM dbo.dbergharelinsert_6 d 
JOIN dbo.dbergharel_4 g ON d.FK_table4 = g.ID 
WHERE g.FK_namegozarwsh = 19 
ORDER BY d.ID DESC;

IF OBJECT_ID('tempdb..#CalcResult') IS NOT NULL DROP TABLE #CalcResult;
IF OBJECT_ID('tempdb..#Exclude17') IS NOT NULL DROP TABLE #Exclude17;

SELECT ID, valuunic, FK_db2, valueFK_db2
INTO #f17
FROM dbo.dbergharelimsertfk1_7
WHERE FK_dbergharelinsert_6 = @find17;

SELECT DISTINCT valuunic
INTO #f19
FROM dbo.dbergharelimsertfk1_7
WHERE FK_dbergharelinsert_6 = @find19;

WITH 
Data21 AS (
    SELECT valuunic, FK_db2, valueFK_db2 
    FROM dbergharelimsertfk1_7_1218_bace 
    WHERE FK_dbergharelinsert_6 = @Last21
),
Data5 AS (
    SELECT valuunic, FK_db2, valueFK_db2 
    FROM dbergharelimsertfk1_7_1218 
    WHERE FK_dbergharelinsert_6 = @Last5
),
AllValuunic AS (
    SELECT DISTINCT r18.valuunic 
    FROM Result12182 r18
    WHERE r18.Input_Month=@month AND r18.Input_Year=@yaer AND r18.Input_Day=@day
)

SELECT
v.valuunic,

(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=103) AS city,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=98) AS makaan,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=411) AS nametarefeh,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=412) AS noeshtrak,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=415) AS mahdodeh,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=99) AS shomaremobile,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=92) AS parvandeh,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=94) AS eshterak,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=432) AS roz,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=91) AS namemosh,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=95) AS shomarehshenasaei,
(SELECT TOP 1 d.valueFK_db2 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=100) AS mantagh,
(SELECT TOP 1 d.valueFK_db2 FROM Data5 d WHERE d.valuunic=v.valuunic AND d.FK_db2=456) AS shenasehpardaght,

CASE
WHEN EXISTS (SELECT 1 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=412 AND d.valueFK_db2=N'دیماند') THEN 1
WHEN EXISTS (SELECT 1 FROM Data21 d WHERE d.valuunic=v.valuunic AND d.FK_db2=412 AND d.valueFK_db2=N'عادی') THEN 2
ELSE 3
END AS P1,

CASE
WHEN EXISTS (
SELECT 1 FROM Data21 d
WHERE d.valuunic=v.valuunic AND d.FK_db2=411
AND (d.valueFK_db2=N'سایر مصارف' OR d.valueFK_db2=N'خانگی')
) THEN 1 ELSE 2
END AS P2

INTO #CalcResult
FROM AllValuunic v;

SELECT DISTINCT d.valuunic
INTO #Exclude17
FROM dbergharelimsertfk1_7_1218_bace d
JOIN #f17 f ON (
(f.FK_db2 = 393 AND d.FK_db2 = 434 AND f.valueFK_db2 = d.valueFK_db2) OR
(f.FK_db2 = 394 AND d.FK_db2 = 435 AND f.valueFK_db2 = d.valueFK_db2) OR
(f.FK_db2 = 392 AND d.FK_db2 = 431 AND f.valueFK_db2 = d.valueFK_db2)
)
WHERE d.FK_dbergharelinsert_6 = @Last21;

TRUNCATE TABLE dbo.ValuunicPriorityResult2;

INSERT INTO dbo.ValuunicPriorityResult2
(valuunic,city,makaan,nametarefeh,noeshtrak,mahdodeh,shomaremobile,parvandeh,eshterak,roz,shenasehpardaght,P1,P2,P3,P4,P5,item1,item2,item4,SortRank,[day],[month],[yaer])
SELECT
c.valuunic,c.city,c.makaan,c.nametarefeh,c.noeshtrak,c.mahdodeh,c.shomaremobile,
c.parvandeh,c.eshterak,c.roz,c.shenasehpardaght,
c.P1,c.P2,1,1,0,
NULL,NULL,NULL,
ROW_NUMBER() OVER (PARTITION BY c.city ORDER BY c.P1),
@day,@month,@yaer
FROM #CalcResult c
WHERE c.valuunic NOT IN (SELECT valuunic FROM #Exclude17)
AND c.valuunic NOT IN (SELECT valuunic FROM #f19);

INSERT INTO Result1218_Rejected
(valuunic,Reason,Year,Month,Input_Day_ASL,TotalVosol)
SELECT
c.valuunic,'2',@yaer,@month,@day,0
FROM #CalcResult c
WHERE c.valuunic IN (SELECT valuunic FROM #Exclude17);

";

                db.Database.ExecuteSqlCommand(
                    sql,
                    new SqlParameter("@p_day", day),
                    new SqlParameter("@p_month", month),
                    new SqlParameter("@p_year", year)
                );

                return Content("done");
            }
            catch (Exception ex)
            {
                return Content(ex.Message);
            }
        }

        public ActionResult RunMohasebat(
    int MonthSh,
    int YearSh,
    int Day1,
    int Day2,
    int day,
    string TodayDate)
        {
            try
            {
                db.Database.CommandTimeout = 10000;

                string sql = @"

SET NOCOUNT ON;

TRUNCATE TABLE dbo.Result12182;
TRUNCATE TABLE dbo.Result1218_Rejected2;

DECLARE @find5 BIGINT, @find16 BIGINT, @find18 BIGINT, @find19 BIGINT,
        @find17 BIGINT, @find20 BIGINT, @find21 BIGINT;

SELECT @find5  = MAX(CASE WHEN g.FK_namegozarwsh = 5  THEN d.ID END),
       @find16 = MAX(CASE WHEN g.FK_namegozarwsh = 16 THEN d.ID END),
       @find17 = MAX(CASE WHEN g.FK_namegozarwsh = 17 THEN d.ID END),
       @find18 = MAX(CASE WHEN g.FK_namegozarwsh = 18 THEN d.ID END),
       @find19 = MAX(CASE WHEN g.FK_namegozarwsh = 19 THEN d.ID END),
       @find20 = MAX(CASE WHEN g.FK_namegozarwsh = 20 THEN d.ID END),
       @find21 = MAX(CASE WHEN g.FK_namegozarwsh = 21 THEN d.ID END)
FROM dbergharelinsert_6 d
JOIN dbergharel_4 g ON d.FK_table4 = g.ID
WHERE g.FK_namegozarwsh IN (5,16,17,18,19,20,21);

DROP TABLE IF EXISTS #findd;
SELECT ID, valuunic COLLATE DATABASE_DEFAULT AS valuunic, FK_db2, valueFK_db2 COLLATE DATABASE_DEFAULT AS valueFK_db2
INTO #findd
FROM dbergharelimsertfk1_7_1218
WHERE FK_dbergharelinsert_6 = @find5;

CREATE CLUSTERED INDEX IX_findd ON #findd(valuunic, FK_db2);

DROP TABLE IF EXISTS #findd16;
SELECT valuunic COLLATE DATABASE_DEFAULT AS valuunic
INTO #findd16
FROM dbergharelimsertfk1_7
WHERE FK_dbergharelinsert_6 = @find16
GROUP BY valuunic;

CREATE UNIQUE CLUSTERED INDEX IX_findd16 ON #findd16(valuunic);

DROP TABLE IF EXISTS #findd18;
SELECT valuunic COLLATE DATABASE_DEFAULT AS valuunic, FK_db2, valueFK_db2 COLLATE DATABASE_DEFAULT AS valueFK_db2
INTO #findd18
FROM dbergharelimsertfk1_7
WHERE FK_dbergharelinsert_6 = @find18
AND FK_db2 = 399;

CREATE CLUSTERED INDEX IX_findd18 ON #findd18(valuunic, FK_db2);

DROP TABLE IF EXISTS #findd19;
SELECT valuunic COLLATE DATABASE_DEFAULT AS valuunic
INTO #findd19
FROM dbergharelimsertfk1_7
WHERE FK_dbergharelinsert_6 = @find19
GROUP BY valuunic;

CREATE UNIQUE CLUSTERED INDEX IX_findd19 ON #findd19(valuunic);

DROP TABLE IF EXISTS #findd20;
SELECT valuunic COLLATE DATABASE_DEFAULT AS valuunic, FK_db2, valueFK_db2 COLLATE DATABASE_DEFAULT AS valueFK_db2
INTO #findd20
FROM dbergharelimsertfk1_7
WHERE FK_dbergharelinsert_6 = @find20
AND FK_db2 IN (401,402);

CREATE CLUSTERED INDEX IX_findd20 ON #findd20(FK_db2, valuunic);

DROP TABLE IF EXISTS #findd21;
SELECT valuunic COLLATE DATABASE_DEFAULT AS valuunic, FK_db2, valueFK_db2 COLLATE DATABASE_DEFAULT AS valueFK_db2
INTO #findd21
FROM dbergharelimsertfk1_7_1218_bace
WHERE FK_dbergharelinsert_6 = @find21
AND FK_db2 IN (91.414,431,411,452,453,432);

CREATE CLUSTERED INDEX IX_findd21 ON #findd21(valuunic, FK_db2);

DECLARE @startValue INT;

SELECT TOP (1) @startValue = TRY_CAST(valuunic AS INT)
FROM #findd20
WHERE FK_db2 = 402
AND valueFK_db2 = @TodayDate;

DROP TABLE IF EXISTS #RozList;

CREATE TABLE #RozList (
value NVARCHAR(50) COLLATE DATABASE_DEFAULT PRIMARY KEY
);

IF @startValue IS NOT NULL
BEGIN
INSERT INTO #RozList(value)
SELECT valueFK_db2
FROM #findd20
WHERE FK_db2 = 401
AND TRY_CAST(valuunic AS INT) BETWEEN @startValue - 7 AND @startValue + 7;
END

DROP TABLE IF EXISTS #finddAgg;

SELECT
valuunic,
MAX(CASE WHEN FK_db2 = 186 THEN valueFK_db2 END) AS d186,
MAX(CASE WHEN FK_db2 = 185 THEN valueFK_db2 END) AS d187,
MAX(CASE WHEN FK_db2 = 189 THEN valueFK_db2 END) AS vosol,
MAX(CASE WHEN FK_db2 = 190 THEN valueFK_db2 END) AS vosol1
INTO #finddAgg
FROM #findd
WHERE FK_db2 IN (185,186,189,190)
GROUP BY valuunic;

CREATE UNIQUE CLUSTERED INDEX IX_finddAgg ON #finddAgg(valuunic);

DROP TABLE IF EXISTS #findd21Agg;

SELECT
valuunic,
MAX(CASE WHEN FK_db2 = 453 THEN valueFK_db2 END) AS vosol3,
MAX(CASE WHEN FK_db2 = 452 THEN valueFK_db2 END) AS vosol2,
MAX(CASE WHEN FK_db2 = 414 THEN valueFK_db2 END) AS active_flag,
MAX(CASE WHEN FK_db2 = 431 THEN valueFK_db2 END) AS bc,
MAX(CASE WHEN FK_db2 = 411 THEN valueFK_db2 END) AS m,
MAX(CASE WHEN FK_db2 = 432 THEN valueFK_db2 END) AS urooz
INTO #findd21Agg
FROM #findd21
GROUP BY valuunic;

CREATE UNIQUE CLUSTERED INDEX IX_findd21Agg ON #findd21Agg(valuunic);

DROP TABLE IF EXISTS #findd20Agg;

SELECT
valuunic,
MAX(CASE WHEN FK_db2 = 402 THEN valueFK_db2 END) AS urooz2
INTO #findd20Agg
FROM #findd20
WHERE FK_db2 = 402
GROUP BY valuunic;

CREATE UNIQUE CLUSTERED INDEX IX_findd20Agg ON #findd20Agg(valuunic);

DROP TABLE IF EXISTS #BaseData;

SELECT
d.valuunic,
a.d186,
a.d187,
a.vosol,
a.vosol1,
a21.vosol2,
a21.vosol3,
a21.active_flag,
a21.bc,
a21.m,
a21.urooz,
a20.urooz2,
ISNULL(TRY_CONVERT(DECIMAL(38,4), a.vosol1),0)
+ ISNULL(TRY_CONVERT(DECIMAL(38,4), a21.vosol3),0)
- ISNULL(TRY_CONVERT(DECIMAL(38,4), a21.vosol2),0)
- ISNULL(TRY_CONVERT(DECIMAL(38,4), a.vosol),0) AS TotalVosol
INTO #BaseData
FROM (SELECT DISTINCT valuunic FROM #findd) d
LEFT JOIN #finddAgg a ON d.valuunic = a.valuunic
LEFT JOIN #findd21Agg a21 ON d.valuunic = a21.valuunic
LEFT JOIN #findd20Agg a20 ON d.valuunic = a20.valuunic;

CREATE UNIQUE CLUSTERED INDEX IX_BaseData ON #BaseData(valuunic);

DROP TABLE IF EXISTS #FinalCheck;

SELECT
b.*,
CASE 
WHEN (b.d186 IS NOT NULL AND EXISTS (SELECT 1 FROM Result1218_tarigh t WHERE t.start_tme = b.d186 AND t.vaziat = 1)) THEN N'5'
WHEN (b.d187 IS NOT NULL AND EXISTS (SELECT 1 FROM Result1218_tarigh t WHERE t.start_tme = b.d187 AND t.vaziat = 2)) THEN N'5'
WHEN b.active_flag <> N'فعال' THEN N'1'
WHEN ((b.bc = N'31' AND b.m IN (N'کشاورزی',N'عمومی',N'صنعتی'))
OR (b.bc = N'76' AND b.m IN (N'خانگی',N'کشاورزی',N'عمومی',N'صنعتی'))) THEN N'2'
WHEN EXISTS (SELECT 1 FROM #findd16 f16 WHERE f16.valuunic = b.valuunic) THEN N'4'
WHEN EXISTS (SELECT 1 FROM #findd18 f18 WHERE f18.valuunic = b.valuunic AND f18.FK_db2 = 399 AND f18.valueFK_db2 <> '1') THEN N'3'
WHEN EXISTS (SELECT 1 FROM #findd19 f19 WHERE f19.valuunic = b.valuunic) THEN N'2'
WHEN b.urooz IS NULL THEN N'5'
WHEN ISNULL(TRY_CONVERT(DECIMAL(38,4), b.urooz),0) > 45 THEN N'5'
WHEN b.TotalVosol > 10000000 THEN N'5'
WHEN b.TotalVosol < 5000000 THEN N'5'
WHEN EXISTS (
SELECT 1
FROM #findd21 f21
WHERE f21.valuunic = b.valuunic
AND f21.FK_db2 = 411
AND f21.valueFK_db2 LIKE N'%روشنایی معابر%'
) THEN N'5'
WHEN EXISTS (SELECT 1 FROM #RozList r WHERE r.value = b.urooz) THEN N'5'
ELSE NULL
END AS RejectReason
INTO #FinalCheck
FROM #BaseData b;

INSERT INTO dbo.Result1218_Rejected2(valuunic, Reason, Year, Month, Input_Day_ASL, TotalVosol)
SELECT valuunic, RejectReason, @YearSh, @MonthSh, @day, CONVERT(NVARCHAR(500), TotalVosol)
FROM #FinalCheck
WHERE RejectReason IS NOT NULL;

INSERT INTO dbo.Result12182(valuunic, Input_Year, Input_Month, Input_Day, Input_Day_ASL)
SELECT valuunic, @YearSh, @MonthSh, @day, TRY_CAST(urooz AS INT)
FROM #FinalCheck
WHERE RejectReason IS NULL;

";

                db.Database.ExecuteSqlCommand(
                    sql,
                    new SqlParameter("@MonthSh", MonthSh),
                    new SqlParameter("@YearSh", YearSh),
                    new SqlParameter("@Day1", Day1),
                    new SqlParameter("@Day2", Day2),
                    new SqlParameter("@day", day),
                    new SqlParameter("@TodayDate", TodayDate)
                );

                return Content("با موفقیت اجرا شد");
            }
            catch (Exception ex)
            {
                return Content("خطا: " + ex.Message);
            }
        }

        public ActionResult SaveFinalZaribReport(
    string tarighstart = "",
    string tarighend = "",
    long FK_gozaresh = 0,
    int month = 0,
    int year = 0)
        {
            try
            {
                db.Database.CommandTimeout = 1000;

                db.Database.ExecuteSqlCommand(
                    "DELETE FROM Salary.tbgozaresh_1275_Fish WHERE FK_gozaresh = @FK",
                    new SqlParameter("@FK", FK_gozaresh)
                );

                string sql = @"

;WITH UserData AS
(
    SELECT 
        L.name,
        MIN(L.FK_usr) AS FK_usr
    FROM Salary.tbLink_name_usr L
    GROUP BY L.name
),

ValuUnic92 AS
(
    SELECT 
        T2.valuunic AS valuunic_form,
        T3.valuunic AS valuunic_bace,
        T2.valueFK_db2 AS value92
    FROM dbo.dbergharelimsertfk1_7 T2

    LEFT JOIN dbo.dbergharelimsertfk1_7_1218_bace T3
        ON T2.valueFK_db2 = T3.valueFK_db2
        AND T3.FK_db2 = 92

    WHERE 
        T2.FK_dbergharelinsert_6 = @FK_gozaresh
        AND T2.FK_db2 = 171
),

BaceData AS
(
    SELECT 
        B.valuunic,

        MAX(CASE WHEN B.FK_db2 = 411 THEN B.valueFK_db2 END) AS v411,
        MAX(CASE WHEN B.FK_db2 = 412 THEN B.valueFK_db2 END) AS v412,
        MAX(CASE WHEN B.FK_db2 = 415 THEN B.valueFK_db2 END) AS v415

    FROM dbo.dbergharelimsertfk1_7_1218_bace B

    WHERE B.FK_db2 IN (411,412,415)

    GROUP BY B.valuunic
),

T1218Data AS
(
    SELECT 
        T.valuunic,
        MAX(T.valueFK_db2) AS v185

    FROM dbo.dbergharelimsertfk1_7_1218 T

    WHERE 
        T.FK_db2 = 185
        AND T.FK_dbergharelinsert_6 =
        (
            SELECT MAX(FK_dbergharelinsert_6)
            FROM dbo.dbergharelimsertfk1_7_1218
        )

    GROUP BY T.valuunic
),

FormData AS
(
    SELECT 
        F.valuunic,

        MAX(CASE WHEN F.FK_db2 = 174 THEN F.valueFK_db2 END) AS v174,
        MAX(CASE WHEN F.FK_db2 = 178 THEN F.valueFK_db2 END) AS v178

    FROM dbo.dbergharelimsertfk1_7 F

    INNER JOIN ValuUnic92 V
        ON V.valuunic_form = F.valuunic

    WHERE 
        F.FK_db2 IN (174,178)
        AND F.FK_dbergharelinsert_6 = @FK_gozaresh

    GROUP BY F.valuunic
),

BaseData AS
(
    SELECT
        BD.v411,
        BD.v412,
        BD.v415,

        TD.v185,

        R.vaziat,

        FD.v174,
        FD.v178,

        U.FK_usr AS usr_id,

        TRY_CAST(FD.v174 AS FLOAT) AS Amount174

    FROM ValuUnic92 VU

    LEFT JOIN BaceData BD
        ON BD.valuunic = VU.valuunic_bace

    LEFT JOIN T1218Data TD
        ON TD.valuunic = VU.valuunic_bace

    LEFT JOIN FormData FD
        ON FD.valuunic = VU.valuunic_form

    LEFT JOIN dbo.Result1218_tarigh R
        ON R.start_tme = TD.v185

    LEFT JOIN UserData U
        ON U.name = FD.v178
),

FinalData AS
(
    SELECT
        usr_id,

        ISNULL(Amount174,0)
        *
        (
            CASE 
                WHEN v411 = N'خانگی' THEN 1.3
                WHEN v411 IN (N'سایر مصارف', N'عمومی') THEN 1.1
                WHEN v411 IN (N'کشاورزی', N'صنعتی') THEN 0.9
                WHEN v411 = N'روشنایی معابر' THEN 0
                ELSE 1
            END

            *

            CASE
                WHEN v412 = N'عادی' THEN 1
                WHEN v412 = N'دیماند' THEN 0.7
                ELSE 1
            END

            *

            CASE
                WHEN v415 = N'شهری' THEN 1
                WHEN v415 = N'روستایی' THEN 1.2
                WHEN v415 = N'خارج از محدوده' THEN 0
                ELSE 1
            END

            *

            CASE
                WHEN vaziat IN (1,2,4) THEN 1
                WHEN vaziat = 5 THEN 1.1
                WHEN vaziat = 6 THEN 1.2
                WHEN vaziat = 7 THEN 1.3
                WHEN vaziat = 8 THEN 1.4
                WHEN vaziat = 9 THEN 1.5
                WHEN vaziat > 9 THEN 1.6
                ELSE 1
            END
        ) AS SumFinalAmount

    FROM BaseData

    WHERE 
        ISNULL(Amount174,0) <> 0
)

INSERT INTO Salary.tbgozaresh_1275_Fish
(
    FK_usr,
    count_darsad,
    month,
    year,
    FK_gozaresh,
    active
)

SELECT
    usr_id,
    CAST(SUM(SumFinalAmount) AS DECIMAL(18,2)),
    @month,
    @year,
    @FK_gozaresh,
    1

FROM FinalData

WHERE usr_id IS NOT NULL

GROUP BY usr_id
";

                db.Database.ExecuteSqlCommand(
                    sql,
                    new SqlParameter("@month", month),
                    new SqlParameter("@year", year),
                    new SqlParameter("@FK_gozaresh", FK_gozaresh)
                );

                return Content("با موفقیت ذخیره شد");
            }
            catch (Exception ex)
            {
                return Content("خطا: " + ex.Message);
            }
        }

        public ActionResult GetFinalZaribReport1()
        {
            try
            {
                db.Database.CommandTimeout = 1000;

                string sql = @"
;WITH LatestRecord AS
(
    SELECT MAX(ID) AS MaxID
    FROM dbo.dbergharelinsert_6
    WHERE FK_table4 = 28
),
ValuUnic92 AS
(
    SELECT 
        T2.valuunic AS valuunic_form,
        T3.valuunic AS valuunic_bace,
        T3.valueFK_db2 AS value92
    FROM dbo.dbergharelimsertfk1_7 T2
    INNER JOIN dbo.dbergharelimsertfk1_7_1218_bace T3
        ON T2.valueFK_db2 = T3.valueFK_db2
    CROSS JOIN LatestRecord LR
    WHERE T2.FK_dbergharelinsert_6 = LR.MaxID
      AND T2.FK_db2 = 170
      AND T3.FK_db2 = 92
),
BaceData AS
(
    SELECT 
        valuunic,
        MAX(CASE WHEN FK_db2 = 411 THEN valueFK_db2 END) AS v411,
        MAX(CASE WHEN FK_db2 = 412 THEN valueFK_db2 END) AS v412,
        MAX(CASE WHEN FK_db2 = 415 THEN valueFK_db2 END) AS v415
    FROM dbo.dbergharelimsertfk1_7_1218_bace
    WHERE FK_db2 IN (411,412,415)
    GROUP BY valuunic
),
T1218Data AS
(
    SELECT 
        valuunic,
        MAX(CASE WHEN FK_db2 = 185 THEN valueFK_db2 END) AS v185
    FROM dbo.dbergharelimsertfk1_7_1218
    WHERE FK_db2 = 185
    GROUP BY valuunic
),
FormData AS
(
    SELECT 
        valuunic,
        MAX(CASE WHEN FK_db2 = 174 THEN valueFK_db2 END) AS v174,
        MAX(CASE WHEN FK_db2 = 178 THEN valueFK_db2 END) AS v178,
        MAX(CASE WHEN FK_db2 = 177 THEN valueFK_db2 END) AS v177,
        MAX(CASE WHEN FK_db2 = 175 THEN valueFK_db2 END) AS v175
    FROM dbo.dbergharelimsertfk1_7
    WHERE FK_db2 IN (174,178,177,175)
    GROUP BY valuunic
)

SELECT
    VU.value92,
    VU.valuunic_bace,
    BD.v411,
    BD.v412,
    BD.v415,
    TD.v185,
    R.vaziat,
    FD.v174,
    FD.v178,
    FD.v177,
    FD.v175,

    (
        CASE WHEN BD.v411 = N'خانگی' THEN 1.3
             WHEN BD.v411 = N'سایر مصارف' THEN 1.1
             WHEN BD.v411 = N'عمومی' THEN 1.1
             WHEN BD.v411 = N'کشاورزی' THEN 0.9
             WHEN BD.v411 = N'صنعتی' THEN 0.9
             WHEN BD.v411 = N'روشنایی معابر' THEN 0
             ELSE 0 END
        *
        CASE WHEN BD.v412 = N'عادی' THEN 1 
             WHEN BD.v412 = N'دیماند' THEN 0.7 ELSE 0 END
        *
        CASE WHEN BD.v415 = N'شهری' THEN 1 
             WHEN BD.v415 = N'روستایی' THEN 1.2
             WHEN BD.v415 = N'خارج از محدوده' THEN 0
             ELSE 0 END
        *
        CASE WHEN R.vaziat = 1 THEN 1 
             WHEN R.vaziat IN (2,4) THEN 1
             WHEN R.vaziat = 5 THEN 1.1
             WHEN R.vaziat = 6 THEN 1.2
             WHEN R.vaziat = 7 THEN 1.3
             WHEN R.vaziat = 8 THEN 1.4
             WHEN R.vaziat = 9 THEN 1.5
             WHEN R.vaziat > 9 THEN 1.6
             ELSE 0 END
    ) AS ZaribFinal,

    ISNULL(TRY_CAST(FD.v174 AS DECIMAL(18,2)),0) *
    (
        CASE WHEN BD.v411 = N'خانگی' THEN 1.3
             WHEN BD.v411 = N'سایر مصارف' THEN 1.1
             WHEN BD.v411 = N'عمومی' THEN 1.1
             WHEN BD.v411 = N'کشاورزی' THEN 0.9
             WHEN BD.v411 = N'صنعتی' THEN 0.9
             WHEN BD.v411 = N'روشنایی معابر' THEN 0
             ELSE 0 END
        *
        CASE WHEN BD.v412 = N'عادی' THEN 1 
             WHEN BD.v412 = N'دیماند' THEN 0.7 ELSE 0 END
        *
        CASE WHEN BD.v415 = N'شهری' THEN 1 
             WHEN BD.v415 = N'روستایی' THEN 1.2
             WHEN BD.v415 = N'خارج از محدوده' THEN 0
             ELSE 0 END
        *
        CASE WHEN R.vaziat = 1 THEN 1 
             WHEN R.vaziat IN (2,4) THEN 1
             WHEN R.vaziat = 5 THEN 1.1
             WHEN R.vaziat = 6 THEN 1.2
             WHEN R.vaziat = 7 THEN 1.3
             WHEN R.vaziat = 8 THEN 1.4
             WHEN R.vaziat = 9 THEN 1.5
             WHEN R.vaziat > 9 THEN 1.6
             ELSE 0 END
    ) AS FinalAmount

FROM ValuUnic92 VU
LEFT JOIN BaceData BD ON BD.valuunic = VU.valuunic_bace
LEFT JOIN T1218Data TD ON TD.valuunic = VU.valuunic_bace
LEFT JOIN FormData FD ON FD.valuunic = VU.valuunic_form
LEFT JOIN dbo.Result1218_tarigh R ON R.start_tme = TD.v185

WHERE ISNULL(TRY_CAST(FD.v174 AS DECIMAL(18,2)), 0) <> 0;
";

                var data = db.Database.SqlQuery<FinalZaribDto>(sql).ToList();
                return Content("1");
              
            }
            catch (Exception ex)
            {
                return Json(new { error = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        public ActionResult countshahri_1275(string tarighstart = "", string tarighend = "", long ID = 0, int month = 0, int year = 0)
        {
            try
            {
                db.Database.ExecuteSqlCommand(
            "DELETE FROM Salary.tbgozaresh_1275_Fish WHERE FK_gozaresh = @FK",
            new SqlParameter("@FK", ID)
        );
                                    db.Database.CommandTimeout = 600; // به ثانیه، اینجا 5 دقیقه

                string sql = @"
;WITH DateItems AS (
    SELECT DISTINCT s.valuunic
    FROM dbergharelimsertfk1_7 s
    WHERE s.FK_db2 = 177
      AND s.valueFK_db2 >= @start
      AND s.valueFK_db2 <= @end
      AND s.FK_dbergharelinsert_6 = @FK_gozaresh
),
Filtered AS (
    SELECT s.*
    FROM dbergharelimsertfk1_7 s
    INNER JOIN DateItems d ON d.valuunic = s.valuunic
    WHERE s.FK_dbergharelinsert_6 = @FK_gozaresh
),
Pivoted AS (
    SELECT
        valuunic,
        MAX(CASE WHEN FK_db2 = 178 THEN valueFK_db2 END) AS name,
        MAX(CASE WHEN FK_db2 = 173 THEN TRY_CAST(valueFK_db2 AS FLOAT) END) AS v173,
        MAX(CASE WHEN FK_db2 = 174 THEN TRY_CAST(valueFK_db2 AS FLOAT) END) AS v174
    FROM Filtered
    GROUP BY valuunic
),
UniqueUsers AS (
    SELECT name, MIN(FK_usr) AS FK_usr
    FROM Salary.tbLink_name_usr
    GROUP BY name
),
FinalData AS (
    SELECT
        u.FK_usr,
        CASE 
            WHEN p.v174 IS NULL OR p.v173 IS NULL OR p.v173 = 0 OR p.v174 = 0 THEN 0
            ELSE p.v174 / p.v174
        END AS count_darsad
    FROM Pivoted p
    INNER JOIN UniqueUsers u ON u.name = p.name
)
INSERT INTO Salary.tbgozaresh_1275_Fish
    (FK_usr, count_darsad, month, year, FK_gozaresh, active)
SELECT
    FK_usr,
    SUM(count_darsad) AS count_darsad,
    @month,
    @year,
    @FK_gozaresh,
    1 -- مستقیم فعال
FROM FinalData
GROUP BY FK_usr;
";



                db.Database.ExecuteSqlCommand(
                    sql,
                    new System.Data.SqlClient.SqlParameter("@start", tarighstart),
                    new System.Data.SqlClient.SqlParameter("@end", tarighend),
                    new System.Data.SqlClient.SqlParameter("@month", month),
                    new System.Data.SqlClient.SqlParameter("@year", year),
                    new System.Data.SqlClient.SqlParameter("@FK_gozaresh", ID)
                );

                return Content("با موفقیت پردازش شد");
            }
            catch (Exception ex)
            {
                return Content("خطا: " + ex.Message);
            }
        }
