        public ActionResult countshahri_12752(string tarighstart = "", string tarighend = "", long ID = 0, int month = 0, int year = 0)
        {
            try
            {
                var fidn = db.dbergharelinsert_6
                    .Where(s => s.ID == ID)
                    .FirstOrDefault();

                if (fidn != null)
                {
                    var list = db.dbergharelimsertfk1_7
                        .Where(s => s.FK_dbergharelinsert_6 == fidn.ID)
                        .ToList();

                    var dateItems = list
                        .Where(s => s.FK_db2 == 177 &&
                                    string.Compare(s.valueFK_db2, tarighstart) >= 0 &&
                                    string.Compare(s.valueFK_db2, tarighend) <= 0)
                        .Select(s => s.valuunic)
                        .Distinct()
                        .ToList();

                    var filteredList = list
                        .Where(s => dateItems.Contains(s.valuunic))
                        .ToList();

                    var group = filteredList.GroupBy(s => s.valuunic);

                    var result = new List<tbgozaresh_1275_Fish>();

                    foreach (var it in group)
                    {
                        var findname = filteredList
                            .Where(s => s.valuunic == it.Key && s.FK_db2 == 178)
                            .FirstOrDefault();

                        if (findname != null)
                        {
                            var findusr = db.tbLink_name_usr
                                .Where(s => s.name == findname.valueFK_db2)
                                .FirstOrDefault();

                            if (findusr != null)
                            {
                                var usrid = (int)findusr.FK_usr;

                                var findnamecount173 = filteredList
                                    .Where(s => s.valuunic == it.Key && s.FK_db2 == 173)
                                    .FirstOrDefault();

                                var findnamecount174 = filteredList
                                    .Where(s => s.valuunic == it.Key && s.FK_db2 == 174)
                                    .FirstOrDefault();

                                if (findnamecount173 != null && findnamecount174 != null)
                                {
                                    double parsedCount = double.Parse(findnamecount173.valueFK_db2);
                                    double parsedCount1 = double.Parse(findnamecount174.valueFK_db2);

                                    if (parsedCount != 0)
                                    {
                                        double darsad = parsedCount1 / parsedCount;

                                        tbgozaresh_1275_Fish tbcreat_countjob_Fish = new tbgozaresh_1275_Fish
                                        {
                                            FK_usr = usrid,
                                            month = month,
                                            year = year,
                                            FK_gozaresh = ID,
                                            count_darsad = darsad
                                        };

                                        result.Add(tbcreat_countjob_Fish);
                                    }
                                }
                            }
                        }
                    }

                    db.tbgozaresh_1275_Fish.AddRange(result);
                    db.SaveChanges();

                    // اجرای کوئری SQL
                    var sql = @"
                INSERT INTO [Salary].[tbgozaresh_1275_Fish] 
                    (FK_usr, count_darsad, month, year, FK_gozaresh, active)
                SELECT 
                    FK_usr,
                    SUM(count_darsad) AS count_darsad,
                    @month AS month,
                    @year AS year,
                    @FK_gozaresh AS FK_gozaresh,
                    1 AS active
                FROM [Salary].[tbgozaresh_1275_Fish]
                WHERE FK_gozaresh = @FK_gozaresh AND month = @month AND year = @year
                GROUP BY FK_usr;
            ";

                    db.Database.ExecuteSqlCommand(
                        sql,
                        new[] {
                    new SqlParameter("@month", month),
                    new SqlParameter("@year", year),
                    new SqlParameter("@FK_gozaresh", ID)
                        }
                    );

                    return Content("با موفقیت پردازش شد");
                }

                return Content("خطا");
            }
            catch (Exception ex)
            {
                return Content("خطا: " + ex.Message);
            }
        }
