            var fidn = db.dbergharelinsert_6
                         .Where(s => s.ID == ID)
                         .OrderByDescending(t => t.ID)
                         .FirstOrDefault();

            List<gozaresh_1121_Fish> tbgozaresh_1275_Fish = new List<gozaresh_1121_Fish>();

            if (fidn != null)
            {
                var list = db.dbergharelimsertfk1_7
                             .Where(s => s.FK_dbergharelinsert_6 == fidn.ID)
                             .ToList();

                var dateItems = list.Select(s => s.valuunic).Distinct().ToList();
                var filteredList = list.Where(s => dateItems.Contains(s.valuunic)).ToList();
                var dell = db.gozaresh_1121_Fish.Where(s => s.FK_gozaresh == ID).ToList();
                db.gozaresh_1121_Fish.RemoveRange(dell);
                db.SaveChanges();
                List<valuestring> valueList = new List<valuestring>();
                var group = filteredList.GroupBy(s => s.valuunic).ToList();

                foreach (var it in group)
                {
                    int usrid = 0;

                    var val288 = list.Where(x => x.FK_dbergharelinsert_6 == fidn.ID && x.FK_db2 == 369 && x.valuunic == it.Key)
                                     .Select(x => x.valueFK_db2).FirstOrDefault() ?? "";

                    var val284 = list.Where(x => x.FK_dbergharelinsert_6 == fidn.ID && x.FK_db2 == 215 && x.valuunic == it.Key)
                                     .Select(x => x.valueFK_db2).FirstOrDefault() ?? "";

                    var val282 = list.Where(x => x.FK_dbergharelinsert_6 == fidn.ID && x.FK_db2 == 218 && x.valuunic == it.Key)
                                     .Select(x => x.valueFK_db2).FirstOrDefault() ?? "";

                    var val271 = list.Where(x => x.FK_dbergharelinsert_6 == fidn.ID && x.FK_db2 == 221 && x.valuunic == it.Key)
                                     .Select(x => x.valueFK_db2).FirstOrDefault() ?? "";

                    var val274 = list.Where(x => x.FK_dbergharelinsert_6 == fidn.ID && x.FK_db2 == 230 && x.valuunic == it.Key)
                                     .Select(x => x.valueFK_db2).FirstOrDefault() ?? "";

                    var val276 = list.Where(x => x.FK_dbergharelinsert_6 == fidn.ID && x.FK_db2 == 238 && x.valuunic == it.Key)
                                     .Select(x => x.valueFK_db2).FirstOrDefault() ?? "";

                    bool exists = valueList.Any(v =>
                        v.value_288 == val288 &&
                        v.value_284 == val284 &&
                        v.value_282 == val282 &&
                        v.value_271 == val271 &&
                        v.value_274 == val274 &&
                        v.value_276 == val276
                    );

                    if (!exists)
                    {
                        valueList.Add(new valuestring
                        {
                            value_288 = val288,
                            value_284 = val284,
                            value_282 = val282,
                            value_271 = val271,
                            value_274 = val274,
                            value_276 = val276
                        });

                        var findname = filteredList.Where(s => s.valuunic == it.Key && s.FK_db2 == 238).FirstOrDefault();
                        if (findname != null)
                        {
                            var findusr = db.tbLink_name_usr.Where(s => s.name == findname.valueFK_db2).FirstOrDefault();
                            if (findusr != null)
                                usrid = (int)findusr.FK_usr;
                        }

                        var faz = filteredList.Where(s => s.valuunic == it.Key && s.FK_db2 == 220)
                                              .Select(t => t.valueFK_db2).FirstOrDefault();
                        var eshterak = filteredList.Where(s => s.valuunic == it.Key && s.FK_db2 == 221)
                                                   .Select(t => t.valueFK_db2).FirstOrDefault();
                        var tarifeh = filteredList.Where(s => s.valuunic == it.Key && s.FK_db2 == 219)
                                                  .Select(t => t.valueFK_db2).FirstOrDefault();

                        if (usrid != 0)
                        {
                            tbgozaresh_1275_Fish.Add(new gozaresh_1121_Fish
                            {
                                FK_usr = usrid,
                                type_shari1 = tarifeh,
                                type_takfaz1 = faz,
                                type_deman1 = eshterak,
                                count = 1,
                                start_time = tarighstart,
                                end_time = tarighend,
                                month = month,
                                year = year,
                                FK_gozaresh=ID,
                            });
                        }
                    }
                }

                // **مرحله گروه‌بندی نهایی و جمع کردن count**
                var finalList = tbgozaresh_1275_Fish
                    .GroupBy(x => new { x.FK_usr, x.type_shari1, x.type_takfaz1, x.type_deman1 })
                    .Select(g => new gozaresh_1121_Fish
                    {
                        FK_usr = g.Key.FK_usr,
                        type_shari1 = g.Key.type_shari1,
                        type_takfaz1 = g.Key.type_takfaz1,
                        type_deman1 = g.Key.type_deman1,
                        count = g.Sum(x => x.count),
                        start_time = tarighstart,
                        end_time = tarighend,
                        month = month,
                        year = year,
                        FK_gozaresh=ID,
                       active=1,
                        cod_person = 1 // مقدار ثابت 1 برای cod_person
                    }).ToList();

                db.gozaresh_1121_Fish.AddRange(finalList);
                db.SaveChanges();
            }

            return View();
        }


