        public ActionResult countshahri_Hoshmand(string tarighstart = "", string tarighend = "", long ID = 0, int month = 0, int year = 0)
        {
            var fidn = db.dbergharelinsert_6
                         .Where(s => s.ID == ID)
                         .OrderByDescending(t => t.ID)
                         .FirstOrDefault();
            var fidnus = db.tbUsers
             .Where(s => s.usr_Personal_ID != null)
          
             .ToList();
            List<tbgozaresh_Hoshmand_Fish> tbgozaresh_1275_Fish = new List<tbgozaresh_Hoshmand_Fish>();

            if (fidn != null)
            {
                var list = db.dbergharelimsertfk1_7
                             .Where(s => s.FK_dbergharelinsert_6 == fidn.ID)
                             .ToList();

                var dateItems = list.Select(s => s.valuunic).Distinct().ToList();
                var filteredList = list.Where(s => dateItems.Contains(s.valuunic)).ToList();

                List<valuestring> valueList = new List<valuestring>();
                var group = filteredList.GroupBy(s => s.valuunic).ToList();

                foreach (var it in group)
                {




                    int usrid = 0;
                    var findname = filteredList.Where(s => s.valuunic == it.Key && s.FK_db2 == 256).FirstOrDefault();
                    if (findname != null)
                    {
                        int personalId;
                        if (int.TryParse(findname.valueFK_db2, out personalId))
                        {
                            var findusr = fidnus
                                .FirstOrDefault(s => s.usr_Personal_ID == personalId);

                            if (findusr != null)
                                usrid = findusr.usr_ID;
                        }
                   
                    }




                    if (usrid != 0)
                    {
               
                            tbgozaresh_1275_Fish.Add(new tbgozaresh_Hoshmand_Fish
                            {
                                FK_usr = usrid,
                                count = 1,

                                FK_gozaresh = ID,


                            });
                        

                    }

                }
                var x1 = db.tbgozaresh_Hoshmand_Fish.Where(s => s.FK_gozaresh == ID).ToList();
                var del = db.tbgozaresh_Hoshmand_Fish.RemoveRange(x1);
                // **مرحله گروه‌بندی نهایی و جمع کردن count**
                var finalList = tbgozaresh_1275_Fish
                    .GroupBy(x => new { x.FK_usr })
                    .Select(g => new tbgozaresh_Hoshmand_Fish
                    {
                        FK_usr = g.Key.FK_usr,

                        count = g.Sum(x => x.count),
                        FK_gozaresh = ID,
                    
                    }).ToList();

                db.tbgozaresh_Hoshmand_Fish.AddRange(finalList);
                db.SaveChanges();
            }

            return View();
        }


