        public bool Save(IEnumerable<HttpPostedFileBase> files = null, FormCollection data = null, string Description = "",int select_peyman=0, string Title = "", bool Type = false)
        {
            try
            {
                var obj = new tbSuggestion_Admin();
                if (files != null)
                {
                    foreach (var file in files)
                    {
                        if (file.ContentLength > 0)
                        {
                            var segment = file.FileName.Split('.');
                            string file_type = segment[segment.Length - 1];
                            var filename = (DateTime.Now.ToString("yyyy_MM_dd_mm_ss") + '.' + file_type).ToString();
                            file.SaveAs(System.Web.HttpContext.Current.Server.MapPath("~/Areas/Suggestion/Contents/" + filename));
                            obj.FileSystemName = filename;
                            obj.FileName = file.FileName;
                        }
                    }
                }
                obj.Title = Title;
                obj.timesabt = DateTime.Now;
                obj.FK_usr = select_peyman;
                //obj.IsSeen = false;
                //obj.IsSuggest = Type;

                #region به دست آوردن ایدی کاربر لاگین شده
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user != null)
                {
                    var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                    using (SaabEntities db = new SaabEntities())
                    {
                        obj.FK_usrsabt = db.tbUsers.Where(p => p.usr_NationalCode.ToString() == nationalcode).Select(p => p.usr_ID).FirstOrDefault();
                    }

                }
                #endregion

                using (var db = new SaabEntities())
                {
                    db.tbSuggestion_Admin.Add(obj);
                    db.SaveChanges();
                }
                return true;
            }
            catch (Exception ex)
            {

                return false;
            }

        }

