        public bool deletee(int id=0)
        {
            try
            {
                var x = db.tbSuggestion_Admin.Where(t => t.ID == id).ToList();
                db.tbSuggestion_Admin.RemoveRange(x);
                db.SaveChanges();
                return true;
            }
            catch (Exception ex)
            {

                return false;
            }


        }
        public ActionResult viewersdal_list()
        { int FK_usrsabt = 0;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user != null)
            {
                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                using (SaabEntities db = new SaabEntities())
                {
                    FK_usrsabt = db.tbUsers.Where(p => p.usr_NationalCode.ToString() == nationalcode).Select(p => p.usr_ID).FirstOrDefault();
                }

            }
            var x = db.tbSuggestion_Admin.Where(s => s.FK_usr == FK_usrsabt ).OrderByDescending(t=>t.ID).ToList();
            return View(x);
        }
