        public ActionResult ExportGpzareshTicketMotaghazi()
        {
            var OutPutFile = SetDataExcel_GpzareshTicketMotaghazi();

            string extension = ".xlsx";

            var stream = new MemoryStream();
            OutPutFile.Save(stream, extension);
            var mimeType = MimeTypes.ByExtension[extension];
            return File(stream.ToArray(), mimeType, "GpzareshTicketMotaghazi" + extension);
        }





        public Workbook SetDataExcel_GpzareshTicketMotaghazi()
        {
            var Moalefeexcelfile = Workbook.Load(
                Server.MapPath("~/Content/ExcelFiles/GpzareshTicketMotaghazi.xlsx")
            );

            var sheet = Moalefeexcelfile.Sheets[0];

            using (var db = new SaabEntities())
            {
                var tickets = db.Ticket_motaghazi1.ToList();
                var users = db.tbUsers.ToList();

                while (sheet.Rows.Count > 1)
                    sheet.Rows.RemoveAt(1);

                int rowIndex = 1;

                foreach (var t in tickets)
                {
                    var user = users.FirstOrDefault(u => u.usr_ID == t.UserSabt);

                    string fullName = user != null
                        ? (user.usr_Name + " " + user.usr_Family)
                        : "";

                    var r = new Row()
                    {
                        Index = rowIndex,
                        Height = 22
                    };

                    r.AddCells(new List<Cell>()
     {

         MakeCell2(user != null ? (object)user.usr_Personal_ID : "", 0),


         MakeCell2(fullName, 1),

         MakeCell2(GetOnvanDarkhastText(t.OnvanDarkhast), 2),
         MakeCell2(t.Sharh, 3),
         MakeCell2(t.ElatYaRishe, 4),
         MakeCell2(t.BehbodKarayi, 5),
         MakeCell2(t.KomakBeSayerBakhshHa, 6),
         MakeCell2(GetOlaviatText(t.Olaviat), 7),
         MakeCell2(t.ZamanAnjam, 8),
         MakeCell2(t.Farayand, 9),
         MakeCell2(ToShamsi(t.TimeSabt), 10)
     });

                    sheet.Rows.Add(r);
                    rowIndex++;
                }
            }


            for (int col = 0; col < 11; col++)
            {
                AutoFitColumn22(sheet, col);
            }

            return Moalefeexcelfile;
        }

        private string GetOnvanDarkhastText(int? val)
        {
            switch (val)
            {
                case 1: return "رفع باگ";
                case 2: return "رفع خطا";
                case 3: return "بهبود خدمات";
                case 4: return "تولید گزارش جدید";
                case 5: return "نیاز به راهنما";
                case 6: return "سایر";
                default: return "";
            }
        }




        private string GetOlaviatText(int? val)
        {
            switch (val)
            {
                case 1: return "اضطراری";
                case 2: return "بالا";
                case 3: return "متوسط";
                case 4: return "پایین";
                default: return "";
            }
        }



        private string ToShamsi(DateTime? date)
        {

            if (!date.HasValue)
                return "";

            var pc = new System.Globalization.PersianCalendar();

            return string.Format("{0:0000}/{1:00}/{2:00} {3:00}:{4:00}",
                pc.GetYear(date.Value),
                pc.GetMonth(date.Value),
                pc.GetDayOfMonth(date.Value),
                pc.GetHour(date.Value),
                pc.GetMinute(date.Value)
            );
        }



        private void AutoFitColumn22(Worksheet sheet, int columnIndex)
        {
            int maxLen = 0;

            foreach (var row in sheet.Rows)
            {
                foreach (var cell in row.Cells)
                {
                    if (cell.Index == columnIndex)
                    {
                        string val = cell.Value?.ToString() ?? "";
                        if (val.Length > maxLen)
                            maxLen = val.Length;
                    }
                }
            }

            // محاسبه عرض
            int finalWidth = (maxLen * 7) + 20;

            // حداقل و حداکثر مجاز Telerik
            if (finalWidth < 80)
                finalWidth = 80;

            if (finalWidth > 2000)
                finalWidth = 2000;

            // اطمینان از وجود ستون
            while (sheet.Columns.Count <= columnIndex)
            {
                sheet.Columns.Add(new Telerik.Web.Spreadsheet.Column()
                {
                    Index = sheet.Columns.Count,
                    Width = 100
                });
            }

            sheet.Columns[columnIndex].Width = finalWidth;
        }









        private Cell MakeCell2(object value, int index)
        {
            return new Cell()
            {
                Index = index,
                Value = value ?? "",
                FontFamily = "Calibri",
                FontSize = 12,

                TextAlign = "center",
                VerticalAlign = "center",
                Wrap = false
            };
        }
























