        public class TicketBarnameNevisiVM
        {
            public long Fk_Ticket_motaghazi1 { get; set; }
            public long Fk_Ticket_Barnamerizi3 { get; set; }
            public bool DarDastorKar { get; set; }
            public bool AnjamShode { get; set; }
            public string EslahFarayand { get; set; }

        }



        [HttpPost]
        public ActionResult SaveBarnameNavisi(TicketBarnameNevisiVM model)
        {
            try
            {

                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return Json(new { success = false, message = "دسترسی غیرمجاز" });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return Json(new { success = false, message = "کاربر یافت نشد" });

                int personal = user.usr_ID;


                var oldRecords = db.Ticket_TimBarnamenervisi4
                    .Where(x =>
                        x.Fk_Ticket_Barnamerizi3 == model.Fk_Ticket_Barnamerizi3 &&
                        x.UserSabt == personal)
                    .ToList();

                if (oldRecords.Any())
                {
                    db.Ticket_TimBarnamenervisi4.RemoveRange(oldRecords);
                    db.SaveChanges();
                }


                Ticket_TimBarnamenervisi4 entity = new Ticket_TimBarnamenervisi4
                {
                    Fk_Ticket_motaghazi1 = model.Fk_Ticket_motaghazi1,
                    Fk_Ticket_Barnamerizi3 = model.Fk_Ticket_Barnamerizi3,
                    EslahFarayand = model.EslahFarayand,
                    DarDastorKar = model.DarDastorKar,
                    AnjamShode = model.AnjamShode,
                    UserSabt = personal,
                    TimeSabt = DateTime.Now
                };

                db.Ticket_TimBarnamenervisi4.Add(entity);
                db.SaveChanges();

                return Json(new { success = true, message = "ثبت اطلاعات با موفقیت انجام شد" });
            }
            catch (System.Data.Entity.Infrastructure.DbUpdateException ex)
            {
                // 🔥 خطای FK Constraint
                if (ex.InnerException?.InnerException is System.Data.SqlClient.SqlException sqlEx &&
                    sqlEx.Number == 547)
                {
                    return Json(new
                    {
                        success = false,
                        message = "به دلیل دیده شدن درخواست در بخش مربوطه، امکان ویرایش وجود ندارد"
                    });
                }

                return Json(new
                {
                    success = false,
                    message = "خطا در ذخیره اطلاعات رخ داده است"
                });
            }
            catch (Exception)
            {
                return Json(new
                {
                    success = false,
                    message = "خطای غیرمنتظره‌ای رخ داده است"
                });
            }
        }






