                var oldRecords = db.Ticket_IT_2
                    .Where(x => x.Fk_Darkhast_Ticket_motaghazi1 == model.Fk_Darkhast_Ticket_motaghazi1)
                    .ToList();

                if (oldRecords.Any())
                {
                    // 🔴 2️⃣ اگر کاربر متفاوت بود → عدم اجازه
                    if (oldRecords.Any(x => x.UserSabt != personal))
                    {
                        return Json(new
                        {
                            success = false,
                            message = "شما اجازه ویرایش ندارید"
                        });
                    }

                    // 🔥 3️⃣ اگر در برنامه‌ریزی استفاده شده بود → قفل
                    var itIds = oldRecords.Select(x => x.ID).ToList();

                    bool usedInBarnamerizi = db.Ticket_Barnamerizi3.Any(x =>
                        itIds.Contains(x.FK_Ticket_it_2.Value) &&
                        x.UserSabt == personal
                    );

                    if (usedInBarnamerizi)
                    {
                        return Json(new
                        {
                            success = false,
                            message = "به دلیل دیده شدن درخواست در بخش مربوطه، امکان ویرایش وجود ندارد"
                        });
                    }

                    // 🧹 4️⃣ حذف رکوردهای قبلی (Update منطقی)
                    db.Ticket_IT_2.RemoveRange(oldRecords);
                    db.SaveChanges();
                }

                // 🟢 5️⃣ Insert داده‌های جدید
                foreach (var item in model.Items)
                {
                    db.Ticket_IT_2.Add(new Ticket_IT_2
                    {
                        Fk_Darkhast_Ticket_motaghazi1 = model.Fk_Darkhast_Ticket_motaghazi1,
                        Anjamdahande = model.Anjamdahande, // یا مقدار دیگه‌ای استفاده کنید
                        zamanKar = item.ZamanKar,
                        AfradAnjamdahande = item.AfradAnjamdahande,
                        Olaviat = model.Olaviat,
                        Hazine = model.Hazine,
                        BarasiFarayand = model.BarasiFarayand,
                        SayerToziihat = model.SayerToziihat,
                        UserSabt = personal,
                        TimeSabt = DateTime.Now
                    });
                }

                db.SaveChanges();

                return Json(new { success = true, message = "ثبت اطلاعات با موفقیت انجام شد" });
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    success = false,
                    message = ex.Message
                });
            }
        }





