        public ActionResult SaveOlaviat(SaveOlaviatVM model)
        {
            try
            {
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return Json(new { success = false, message = "دسترسی غیرمجاز" });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return Json(new { success = false, message = "کاربر یافت نشد" });

                int personal = user.usr_ID;




                if (model?.OlaviatList == null || !model.OlaviatList.Any())
                    return Json(new { success = false, message = "لیست اولویت خالی است" });

                var fkIds = model.OlaviatList
                                 .Select(x => x.FK_Ticket_Motaghazi1)
                                 .ToList();

                // 🔴 چک برنامه‌نویسی شروع شده؟
                bool hasAnyRecord = db.Ticket_TimBarnamenervisi4
                    .Any(x => x.Fk_Ticket_motaghazi1.HasValue &&
                              fkIds.Contains(x.Fk_Ticket_motaghazi1.Value));

                if (hasAnyRecord)
                {
                    return Json(new
                    {
                        success = false,
                        message = "برای یکی از درخواست‌ها عملیات برنامه‌نویسی شروع شده و امکان تغییر اولویت وجود ندارد"
                    });
                }

                foreach (var item in model.OlaviatList)
                {
                    var barnamerizi = db.Ticket_Barnamerizi3
                        .FirstOrDefault(x => x.FK_Ticket_Motaghazi1 == item.FK_Ticket_Motaghazi1 && x.UserSabt == personal);


                    if (barnamerizi == null)
                    {


                        return Json(new
                        {
                            success = false,
                            message = "برای یک یا چند مورد از درخواست ها دراین بخش هنوز اطلاعاتی ثبت نشده لطفا پس از وارد کردن اطلاعات دوباره اولویت بندی کنید "
                        });


                    }
                    else
                    {

                        barnamerizi.Olaviat2 = item.Priority;

                    }
                }

                db.SaveChanges();

                return Json(new
                {
                    success = true,
                    message = "اولویت‌ها با موفقیت برای هر درخواست ثبت شد"
                });
            }
            catch (System.Data.Entity.Validation.DbEntityValidationException ex)
            {
                var errors = ex.EntityValidationErrors
                    .SelectMany(x => x.ValidationErrors)
                    .Select(x => $"{x.PropertyName}: {x.ErrorMessage}");

                return Json(new
                {
                    success = false,
                    message = string.Join(" | ", errors)
                });
            }
            catch (Exception)
            {
                return Json(new
                {
                    success = false,
                    message = "خطای غیرمنتظره‌ای رخ داد"
                });
            }
        }



