        [HttpPost]
        public ActionResult SaveBarnameRizi(TicketBarnameRiziVM model)
        {
            try
            {
                // 🔹 گرفتن UserSabt از کوکی
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return Json(new { success = false, message = "دسترسی غیرمجاز" });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return Json(new { success = false, message = "کاربر یافت نشد" });

                int personal = user.usr_ID;

                // 🔴 حذف رکوردهای قبلی این تیکت برای همین کاربر
                var oldRecords = db.Ticket_Barnamerizi3
                    .Where(x =>
                        x.FK_Ticket_it_2 == model.FK_Ticket_it_2 &&
                        x.UserSabt == personal)
                    .ToList();

                if (oldRecords.Any())
                {
                    db.Ticket_Barnamerizi3.RemoveRange(oldRecords);
                    db.SaveChanges(); // ⛔ ممکن است خطای FK بدهد
                }

                // 🟢 درج اطلاعات جدید
                Ticket_Barnamerizi3 entity = new Ticket_Barnamerizi3
                {
                    FK_Ticket_Motaghazi1 = model.FK_Ticket_Motaghazi1,
                    FK_Ticket_it_2 = model.FK_Ticket_it_2,
                    SayerTozihat = model.SayerTozihat,
                    ZaroratAnjam = model.ZaroratAnjam,
                    Olaviat = model.Olaviat,
                    UserSabt = personal,
                    TimeSabt = DateTime.Now
                };

                db.Ticket_Barnamerizi3.Add(entity);
                db.SaveChanges();

                return Json(new { success = true, message = "ثبت اطلاعات با موفقیت انجام شد" });
            }
            catch (System.Data.Entity.Infrastructure.DbUpdateException ex)
            {
                // 🔥 خطای FK Constraint
                if (ex.InnerException?.InnerException is System.Data.SqlClient.SqlException sqlEx &&
                    sqlEx.Number == 547)
                {
                    return Json(new
                    {
                        success = false,
                        message = "به دلیل دیده شدن درخواست در بخش مربوطه، امکان ویرایش وجود ندارد"
                    });
                }

                return Json(new
                {
                    success = false,
                    message = "خطا در ذخیره اطلاعات رخ داده است"
                });
            }
            catch (Exception)
            {
                return Json(new
                {
                    success = false,
                    message = "خطای غیرمنتظره‌ای رخ داده است"
                });
            }
        }





















