        public async Task<string> GetDataFromExcel_FishtAEADediteditt2(HttpPostedFileBase MyExcelStream, long ID, long IDgozareh = 0)
        {
            // ۱. دریافت تنظیمات مپینگ و کش کردن آن‌ها در رم برای سرعت بالا
            var allFidnds = db.dbergharel_4.Where(s => s.FK_namegozarwsh == ID).ToList();
            var fidndIds = allFidnds.Select(f => f.ID).ToList();

            // رفع خطای Contains با تبدیل به لیست long
            var allMappings = await db.dbergharel4_5
                .Where(m => fidndIds.Contains((long)m.FK_dbergharel4) && m.del != true)
                .ToListAsync();

            string filePath = @"D:\po\1218--01-01-1404--29-09-1404.xls";
            int totalInserted = 0;
            const int BatchSize = 100000; // دسته‌های ۱۰۰ هزارتایی
            DateTime batchTime = DateTime.Now;
            int personal = GetUserIdFromCookie();

            try
            {
                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                // ۲. تنظیمات اختصاصی برای باز شدن آنی فایل XLS (بدون معطلی)
                var readerConfig = new ExcelReaderConfiguration()
                {
                    FallbackEncoding = System.Text.Encoding.GetEncoding(1252)
                };

                // باز کردن فایل با بافر ۲ مگابایتی و مد پیمایش خطی
                using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, 2097152, FileOptions.SequentialScan))
                {
                    using (var reader = ExcelReaderFactory.CreateBinaryReader(stream, readerConfig))
                    {
                        int currentSheetIndex = 0;
                        List<dbergharelimsertfk1_7DTO> bulkData = new List<dbergharelimsertfk1_7DTO>();

                        do
                        {
                            var currentFidnd = allFidnds.FirstOrDefault(f => f.start == currentSheetIndex);
                            if (currentFidnd != null)
                            {
                                var mappingsForThisSheet = allMappings.Where(m => m.FK_dbergharel4 == currentFidnd.ID).ToList();
                                int unicIndex = ColumnLetterToIndex(currentFidnd.unic);
                                var mapIndexes = mappingsForThisSheet.Select(m => new { m.FK_dbergharel2, Index = ColumnLetterToIndex(m.onvan) }).ToList();

                                long gozarType = (long)currentFidnd.FK_namegozarwsh;

                                int rowCounter = 0;
                                while (reader.Read()) // ⚡️ شروع خواندن سطر به سطر بدون معطلی
                                {
                                    rowCounter++;
                                    if (rowCounter <= currentFidnd.radifstart) continue;

                                    var valUnic = reader.GetValue(unicIndex);
                                    if (valUnic == null) continue; // پرش از سطرهای خالی برای سرعت بیشتر

                                    string unicValue = valUnic.ToString();
                                    if (string.IsNullOrWhiteSpace(unicValue)) continue;

                                    foreach (var item in mapIndexes)
                                    {
                                        bulkData.Add(new dbergharelimsertfk1_7DTO
                                        {
                                            FK_dbergharelinsert_6 = IDgozareh,
                                            valuunic = unicValue,
                                            FK_db2 = item.FK_dbergharel2,
                                            valueFK_db2 = reader.GetValue(item.Index)?.ToString(),
                                            timesabt = batchTime,
                                            FK_usrsabt = personal
                                        });
                                    }

                                    if (bulkData.Count >= BatchSize)
                                    {
                                        await ExecuteBatchInsert(bulkData, gozarType);
                                        totalInserted += (bulkData.Count / (mapIndexes.Count > 0 ? mapIndexes.Count : 1));
                                        bulkData.Clear();
                                        GC.Collect(); // جلوگیری از پر شدن RAM
                                    }
                                }

                                // درج باقی‌مانده شیت فعلی
                                if (bulkData.Count > 0)
                                {
                                    await ExecuteBatchInsert(bulkData, gozarType);
                                    totalInserted += (bulkData.Count / (mapIndexes.Count > 0 ? mapIndexes.Count : 1));
                                    bulkData.Clear();
                                }
                            }
                            currentSheetIndex++;
                        } while (reader.NextResult());
                    }
                }
                return $"عملیات با موفقیت پایان یافت. تعداد کل رکوردها: {totalInserted}";
            }
            catch (Exception ex)
            {
                return "خطا در پردازش: " + ex.Message;
            }
        }

        // متد مدیریت جداول مقصد (اصلاح شده برای C# 7.3)
        private async Task ExecuteBatchInsert(List<dbergharelimsertfk1_7DTO> data, long gozar)
        {
            string tableName;

            switch (gozar)
            {
                case 5:
                    tableName = "dbo.dbergharelimsertfk1_7_1218";
                    break;
                case 21:
                    tableName = "dbo.dbergharelimsertfk1_7_1218_bace";
                    break;
                case 23:
                    tableName = "dbo.dbergharelimsertfk1_7_GIS";
                    break;
                default:
                    tableName = "dbo.dbergharelimsertfk1_7";
                    break;
            }

            var dt = CreateDataTable_General(data);
            await BulkInsertToDatabase(dt, tableName);
        }

        // عملیات Bulk Insert مستقیم با استفاده از TableLock برای سرعت انفجاری
        private async Task BulkInsertToDatabase(System.Data.DataTable dataTable, string tableName)
        {
            using (SqlConnection connection = new SqlConnection(GetSqlConnectionString()))
            {
                await connection.OpenAsync();
                using (SqlBulkCopy bulkCopy = new SqlBulkCopy(connection, SqlBulkCopyOptions.TableLock | SqlBulkCopyOptions.CheckConstraints, null))
                {
                    bulkCopy.DestinationTableName = tableName;
                    bulkCopy.BatchSize = 50000;
                    bulkCopy.BulkCopyTimeout = 0; // بدون محدودیت زمانی برای حجم‌های میلیونی

                    foreach (DataColumn column in dataTable.Columns)
                        bulkCopy.ColumnMappings.Add(column.ColumnName, column.ColumnName);

                    await bulkCopy.WriteToServerAsync(dataTable);
                }
            }
        }

        // تبدیل لیست به DataTable برای سازگاری با SqlBulkCopy
        private System.Data.DataTable CreateDataTable_General(List<dbergharelimsertfk1_7DTO> data)
        {
            System.Data.DataTable dataTable = new System.Data.DataTable();
            dataTable.Columns.Add("FK_dbergharelinsert_6", typeof(long));
            dataTable.Columns.Add("valuunic", typeof(string));
            dataTable.Columns.Add("FK_db2", typeof(long));
            dataTable.Columns.Add("valueFK_db2", typeof(string));
            dataTable.Columns.Add("timesabt", typeof(DateTime));
            dataTable.Columns.Add("FK_usrsabt", typeof(int));

            foreach (var item in data)
            {
                dataTable.Rows.Add(
                    item.FK_dbergharelinsert_6,
                    item.valuunic ?? (object)DBNull.Value,
                    item.FK_db2,
                    item.valueFK_db2 ?? (object)DBNull.Value,
                    item.timesabt,
                    item.FK_usrsabt
                );
            }
            return dataTable;
        }

        private int ColumnLetterToIndex2(string column)
        {
            if (string.IsNullOrEmpty(column)) return 0;
            int sum = 0;
            for (int i = 0; i < column.Length; i++)
            {
                sum *= 26;
                sum += (char.ToUpper(column[i]) - 'A' + 1);
            }
            return sum - 1;
        }

        private int GetUserIdFromCookie()
        {
            try
            {
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user != null)
                {
                    var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                    return db.tbUsers.Where(p => p.usr_NationalCode == nationalcode).Select(p => p.usr_ID).FirstOrDefault();
                }
            }
            catch { }
            return 0;
        }
