        private long GetCityValue_2(string city)
        {
            switch (city)
            {
                case "ایرانشهر": case "سراوان": case "ايرانشهر": case "چاه بهار": case "چابهار": return 700000000L;
                case "سوران": case "جالق": case "زابل": return 600000000L;
                case "زاهدان 2": case "زاهدان": case "زاهدان2": case "زاهدان 1": return 550000000L;
                case "هيرمند": case "قصرقند": return 400000000L;
                case "خاش": return 350000000L;
                case "مهرستان": case "نيک شهر": case "زهک": case "نگور": return 300000000L;
                case "دلگان": case "راسک": case "سرباز": case "بمپور": return 250000000L;
                case "کورین": case "ميرجاوه": case "اسپکه": return 200000000L;
                case "فنوج": return 180000000L;
                case "کنارک": return 150000000L;
                default: return 0;
            }
        }
        public async Task<string> GetDataFromExcel_erja_omomi(HttpPostedFileBase MyExcelStream)
        {
            int totalInserted = 0;

            try
            {
                List<erja_omomi> items = new List<erja_omomi>();

                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration()
                    {
                        ConfigureDataTable = _ => new ExcelDataTableConfiguration()
                        {
                            UseHeaderRow = true // چون ستون‌ها هدر دارند
                        }
                    });

                    var sheet = dataSet.Tables[0];
                    if (sheet.Rows.Count == 0)
                        return "فایل اکسل فاقد داده است.";

                    foreach (DataRow row in sheet.Rows)
                    {
                        var entity = new erja_omomi();

                        string input = row["input"]?.ToString()?.Trim();
                        string select = row["select"]?.ToString()?.Trim();
                        string codeTable = row["کد جدول"]?.ToString()?.Trim();
                        string uniqueVal = row["یونیک"]?.ToString()?.Trim();
                        string title = row["عنوان"]?.ToString()?.Trim();
                        string codeField = row["کد فیلد جدول"]?.ToString()?.Trim();
                        string insertFlag = row["درج شود"]?.ToString()?.Trim();
                        string tableField = row["جدول فیلد"]?.ToString()?.Trim();
                        string job = row["شغل"]?.ToString()?.Trim();

                        // 📘 وضعیت
                        if (input == "1")
                            entity.vaziat = 1;
                        else if (select == "1")
                            entity.vaziat = 0;

                        // 📘 یونیک
                        entity.unic = (uniqueVal == "1" || uniqueVal?.ToLower() == "true");

                        // 📘 کد جدول
                        if (long.TryParse(codeTable, out long fkGozaresh))
                            entity.FK_gozaresh = fkGozaresh;
                        else
                            entity.FK_gozaresh = null;

                        // 📘 کد فیلد جدول
                        if (long.TryParse(codeField, out long fkLink))
                            entity.FK_link = fkLink;
                        else
                            entity.FK_link = null;

                        // 📘 عنوان
                        entity.title = title;

                        // 📘 درج شود
                        if (int.TryParse(insertFlag, out int insertVal))
                            entity.dargeshavad = insertVal;
                        else
                            entity.dargeshavad = 0;

                        // 📘 جدول فیلد
                        if (long.TryParse(tableField, out long fkLinkCheck))
                            entity.FK_link_cjeek = fkLinkCheck;
                        else
                            entity.FK_link_cjeek = null;

                        // 📘 شغل
                        if (long.TryParse(job, out long fkJob))
                            entity.FK_job = fkJob;
                        else
                            entity.FK_job = null;

                        // مقدار سایر فیلدهای لازم
                        entity.FK_gozaresh_cheeck = null;

                        items.Add(entity);
                    }
                }

                // ذخیره در دیتابیس
                db.erja_omomi.AddRange(items);
                await db.SaveChangesAsync();

                totalInserted = items.Count;
                return "True";
            }
            catch (Exception ex)
            {
                return $"❌ خطا: {ex.Message}";
            }
        }
