        public string Save12(IEnumerable<HttpPostedFileBase> files, string description1, long select_peyman, out string message)
        {
            message = ""; // مقدار اولیه
            try
            {
                using (SaabEntities db = new SaabEntities())
                {
                    #region گرفتن آی‌دی کاربر لاگین شده
                    var userid = 0;
                    var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                    if (cookie_user != null)
                    {
                        var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                        var User = db.tbUsers
                                     .Where(p => p.usr_NationalCode.ToString() == nationalcode)
                                     .Select(p => p.usr_ID)
                                     .FirstOrDefault();
                        if (User != 0)
                            userid = User;
                    }
                    #endregion

                    // چک کردن فایل تکراری
                    if (files != null)
                    {
                        foreach (var file in files)
                        {
                            if (file != null && file.ContentLength > 0)
                            {
                                string extension = Path.GetExtension(file.FileName).ToLower();
                                string filename = Path.GetFileName(file.FileName);

                                bool exists = db.madarek_sabtdoreh_4.Any(x =>
                                    x.FK_namedoreh == select_peyman &&x.FK_usr== userid
                                    );

                                if (exists)
                                {
                                    message = "این فایل قبلاً برای این دوره ثبت شده است.از جدول پایین برای ادیت اگر دسترسی باز بود کمک بگیرید";
                                    return message; // همون‌جا متوقف بشه
                                }
                            }
                        }
                    }

                    // چک کردن صحت فایل‌ها (فرمت و حجم)
                    if (files != null)
                    {
                        foreach (var file in files)
                        {
                            if (file != null && file.ContentLength > 0)
                            {
                                int maxFileSize = 5 * 1024 * 1024; // 5MB
                                string extension = Path.GetExtension(file.FileName).ToLower();
                                string[] allowedExtensions = { ".jpg", ".jpeg", ".png", ".gif", ".bmp", ".pdf" , ".zip" };

                                if (!allowedExtensions.Contains(extension))
                                {
                                    message = "فرمت فایل " + file.FileName + " معتبر نیست. فقط فرمت‌های jpg, jpeg, png, gif, bmp, pdf, zip مجاز هستند.";
                                    return message;
                                }

                                if (file.ContentLength > maxFileSize)
                                {
                                    message = "حجم فایل " + file.FileName + " بیشتر از حد مجاز (5MB) است.";
                                    return message; // کل عملیات متوقف
                                }
                            }
                        }
                    }

                    var find = db.madarek_sabtdoreh_4
                                 .FirstOrDefault(p => p.FK_usr == userid && p.FK_namedoreh == select_peyman);

                    if (find != null)
                    {
                        find.sharh = description1;
                        find.timesabt = DateTime.Now;
                        find.vaziat = 0;

                        if (files != null)
                        {
                            foreach (var file in files)
                            {
                                if (file != null && file.ContentLength > 0)
                                {
                                    string extension = Path.GetExtension(file.FileName).ToLower();
                                    string filename = DateTime.Now.ToString("yyyy_MM_dd_HH_mm_ss") + extension;
                                    string path = System.Web.HttpContext.Current.Server.MapPath("~/Areas/Suggestion/Contents/" + filename);
                                    file.SaveAs(path);

                                    find.System_FIle = filename;
                                    find.Realname_namefile = file.FileName;
                                }
                            }
                        }
                    }
                    else
                    {
                        var madarek = new madarek_sabtdoreh_4();
                        if (files != null)
                        {
                            foreach (var file in files)
                            {
                                if (file != null && file.ContentLength > 0)
                                {
                                    string extension = Path.GetExtension(file.FileName).ToLower();
                                    string filename = DateTime.Now.ToString("yyyy_MM_dd_HH_mm_ss") + extension;
                                    string path = System.Web.HttpContext.Current.Server.MapPath("~/Areas/Suggestion/Contents/" + filename);
                                    file.SaveAs(path);

                                    madarek.System_FIle = filename;
                                    madarek.Realname_namefile = file.FileName;
                                }
                            }
                        }
                        madarek.sharh = description1;
                        madarek.timesabt = DateTime.Now;
                        madarek.FK_namedoreh = select_peyman;
                        madarek.FK_usr = userid;
                        madarek.vaziat = 0;

                        db.madarek_sabtdoreh_4.Add(madarek);
                    }

                    db.SaveChanges();
                }
                return "True";
            }
            catch (Exception ex)
            {
                message = "خطا در ذخیره: " + ex.Message;
                return message;
            }
        }
