        // تبدیل حروف ستون (A,B,AA,...) به اندیس صفر-مبنا
        private int ColumnLetterToIndex(string column)
        {
            if (string.IsNullOrEmpty(column)) return 0;

            int sum = 0;
            for (int i = 0; i < column.Length; i++)
            {
                sum *= 26;
                sum += (column[i] - 'A' + 1);
            }
            return sum - 1; // چون ایندکس از صفر شروع میشه
        }
