        private async Task RemoveDuplicatesLastTwo(string connectionString)
        {
            string sql = @"
;WITH ranked AS (
    SELECT *,
           ROW_NUMBER() OVER(PARTITION BY valuunic, FK_db2 ORDER BY timesabt DESC) AS rn
    FROM dbo.dbergharelimsertfk1_7
)
, duplicates AS (
    SELECT curr.ID
    FROM ranked curr
    INNER JOIN ranked prev
        ON curr.valuunic = prev.valuunic
       AND curr.FK_db2 = prev.FK_db2
       AND curr.rn = 1      -- رکورد آخر
       AND prev.rn = 2      -- رکورد قبل آخر
       AND ISNULL(curr.valueFK_db2,'') = ISNULL(prev.valueFK_db2,'') -- اگر یکسان بود
)
DELETE t
FROM dbo.dbergharelimsertfk1_7 t
INNER JOIN duplicates d ON t.ID = d.ID;
";

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();

                using (SqlCommand command = new SqlCommand(sql, connection))
                {
                    command.CommandTimeout = 0;
                    await command.ExecuteNonQueryAsync();
                }
            }
        }

        private async Task RemoveDuplicatesLatestBatch(string connectionString, DateTime batchTime)
        {
            string sql = @"
;WITH latest AS (
    SELECT *
    FROM dbo.dbergharelimsertfk1_7
    WHERE timesabt = @batchTime
),
duplicates AS (
    SELECT l.ID
    FROM latest l
    INNER JOIN dbo.dbergharelimsertfk1_7 t
        ON t.valuunic = l.valuunic
       AND t.FK_db2 = l.FK_db2
       AND ISNULL(t.valueFK_db2,'') = ISNULL(l.valueFK_db2,'')
       AND t.timesabt < l.timesabt
)
DELETE t
FROM dbo.dbergharelimsertfk1_7 t
INNER JOIN duplicates d ON t.ID = d.ID;
";

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();

                using (SqlCommand command = new SqlCommand(sql, connection))
                {
                    command.Parameters.AddWithValue("@batchTime", batchTime);
                    command.CommandTimeout = 0;
                    await command.ExecuteNonQueryAsync();
                }
            }
        }
        public ActionResult RunSalary(int year, int month)
        {
            try
            {
                using (SqlConnection conn = new SqlConnection(GetSqlConnectionString()))
                {
                    using (SqlCommand cmd = new SqlCommand("Salary.sp_SalaryCalculation", conn))
                    {
                        cmd.CommandType = CommandType.StoredProcedure;

                        cmd.Parameters.AddWithValue("@Year", year);
                        cmd.Parameters.AddWithValue("@Month", month);
                        cmd.Parameters.AddWithValue("@tarigh", new DateTime(2025, 09, 21)); // متغیر
                        cmd.Parameters.AddWithValue("@day", 30.0);

                        conn.Open();
                        cmd.CommandTimeout = 900;
                        cmd.ExecuteNonQuery();
                    }
                }

                return Json(new { success = true, message = "✅ پردازش حقوق انجام شد" });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }
        public double TeadaroozMonth(int Month, int year)
        {
            PersianCalendar pc = new PersianCalendar();

            if (Month < 7)
            {
                return 31.0;
            }
            else if (Month < 12)
            {

                return 30.0;
            }
            else
            {
                if (pc.IsLeapYear(year))
                {
                    return 30.0;
                }
                else
                {
                    return 29.0;
                }
            }
        }
        public ActionResult rozgaybatkasri(int UserID, int Month, int Year, double moadelkarkar)
        {
            double ragamkol = 0;
            var mozdsayer = "0";
            var hagholadbase = "0";
            var aghlammasrafikhanevarbase = "0";
            var tedadroozmah = TeadaroozMonth(Month, Year);
            var haghmaskanbase = "0";
            var myDatetime = ConvertDateTimeToShamsi.ConvertShamsiYearToYear(Year, Month);
            var contractinfo = db.tbUserContracts.Where(p => p.FK_UserID == UserID && p.usc_EndTime >= myDatetime && p.usc_StartTime <= myDatetime).FirstOrDefault();
            if (contractinfo != null)
            {
                var listmoalefeqarardadi = db.tbUserContractsAndMoalefeGhararDadi.Where(p => p.FKContractID == contractinfo.usc_ID).ToList();
                foreach (var it in listmoalefeqarardadi)
                {
                    ragamkol += (double)it.Value;
                }
                var mozdsanavatroozane = Regex.Replace(contractinfo.jobgroup_ValueSanavat, ",", "");
                if (mozdsanavatroozane == null)
                {
                    mozdsanavatroozane = "0";
                }
                double mozdmahaneh = System.Convert.ToDouble(mozdsanavatroozane) * tedadroozmah;

                var mozdshoqlroozane = Regex.Replace(contractinfo.jobgroup_ValueMozdGroup, ",", "");
                if (mozdshoqlroozane == null)
                {
                    mozdshoqlroozane = "0";
                }
                double mozdmahanehshogl = System.Convert.ToDouble(mozdshoqlroozane) * tedadroozmah;

                if (contractinfo.jobgroup_MozdSayer != null)
                {
                    mozdsayer = Regex.Replace(contractinfo.jobgroup_MozdSayer, ",", "");

                    if (mozdsayer == null)
                    {
                        mozdsayer = "0";
                    }
                }
                if (contractinfo.jobgroup_HagheMaskan != null)
                {
                    haghmaskanbase = Regex.Replace(contractinfo.jobgroup_HagheMaskan, ",", "");
                    if (haghmaskanbase == null)
                    {
                        haghmaskanbase = "0";
                    }

                }
                if (contractinfo.jobgroup_HagheOlad != null)
                {

                    hagholadbase = Regex.Replace(contractinfo.jobgroup_HagheOlad, ",", "");
                    if (hagholadbase == null)
                    {
                        hagholadbase = "0";
                    }
                }
                if (contractinfo.jobgroup_KharoBar != null)
                {

                    aghlammasrafikhanevarbase = Regex.Replace(contractinfo.jobgroup_KharoBar, ",", "");
                    if (aghlammasrafikhanevarbase == null)
                    {
                        aghlammasrafikhanevarbase = "0";
                    }
                }
                ragamkol = ragamkol + System.Convert.ToDouble(aghlammasrafikhanevarbase) + System.Convert.ToDouble(hagholadbase) + System.Convert.ToDouble(haghmaskanbase) + System.Convert.ToDouble(mozdmahaneh) + System.Convert.ToDouble(mozdmahanehshogl);
