                    var del = db.tbmoalfehkasri.Where(s => s.month == month && s.year == year).ToList();
                    db.tbmoalfehkasri.RemoveRange(del);
                    db.SaveChanges();
                    var find = db.tbMoadelPadashJarimeAyab.Where(s => s.Month == month && s.Year == year && s.Moadel < 1 && s.Moadel > 0).ToList();
                    foreach (var it in find)
                    {
                        var x = rozgaybatkasri((int)it.UserID, month, year, it.Moadel);
                    }
