                DateTime miladiDate = ConvertShamsiToMiladi(year, month);
                DateTime miladiDate1 = ConvertShamsiToMiladi1(year, month);

                using (SqlConnection conn = new SqlConnection(GetSqlConnectionString()))
                {
                    using (SqlCommand cmd = new SqlCommand("Salary.FISH", conn))
                    {
                        cmd.CommandType = CommandType.StoredProcedure;

                        cmd.Parameters.AddWithValue("@Year", year);
                        cmd.Parameters.AddWithValue("@Month", month);
                        cmd.Parameters.AddWithValue("@tarigh", miladiDate); // متغیر
