        private string GetSqlConnectionString()
        {
            try
            {
                // روش 1: استخراج از Entity Connection موجود
                var entityConnection = new EntityConnection(ConfigurationManager.ConnectionStrings["SaabEntities"].ConnectionString);
                return entityConnection.StoreConnection.ConnectionString;
            }
            catch
            {
                // روش 2: استفاده از connection string مستقیم (اگر روش اول کار نکرد)
                return "REPLACE_WITH_CONNECTION_STRING";
            }
        }
        private long GetMaxId(string tableName)
        {
            using (var connection = new SqlConnection(GetSqlConnectionString()))
            {
                connection.Open();
                using (var cmd = new SqlCommand($"SELECT ISNULL(MAX(ID), 0) FROM {tableName}", connection))
                {
                    return (long)cmd.ExecuteScalar();
                }
            }
        }
        private async Task BulkInsert(string tableName, System.Data.DataTable dataTable)
        {
            string connectionString = GetSqlConnectionString();

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();

                using (SqlBulkCopy bulkCopy = new SqlBulkCopy(connection,
                    SqlBulkCopyOptions.TableLock | SqlBulkCopyOptions.CheckConstraints, null))
                {
                    bulkCopy.DestinationTableName = tableName;
                    bulkCopy.BatchSize = 10000;
                    bulkCopy.BulkCopyTimeout = 0;

                    // مپ کردن ستون‌ها بر اساس اسم ستون دیتاتیبل
                    foreach (DataColumn column in dataTable.Columns)
                    {
                        bulkCopy.ColumnMappings.Add(column.ColumnName, column.ColumnName);
                    }

                    await bulkCopy.WriteToServerAsync(dataTable);
                }
            }
        }

        public async Task<string> GetDataFromExcel_filetaeed88(HttpPostedFileBase MyExcelStream, long jobId = 0, int month = 0, int year = 0)
        {
            int totalInserted = 0;

            try
            {
                // ثبت انکدینگ برای ExcelDataReader
                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                List<long> realJobIds = new List<long>();
                var unicRows = new List<(string unic, int cityId, List<string> values)>();

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration()
                    {
                        ConfigureDataTable = _ => new ExcelDataTableConfiguration()
                        {
                            UseHeaderRow = false
                        }
                    });

                    var sheet = dataSet.Tables[0];
                    if (sheet.Rows.Count <= 1)
                        return "این شیت فاقد اطلاعات است";

                    // --- ردیف اول: realJobIds ---
                    for (int col = 3; col < sheet.Columns.Count; col++)
                    {
                        if (long.TryParse(sheet.Rows[0][col]?.ToString(), out long realId))
                            realJobIds.Add(realId);
                    }

                    // --- ردیف‌های بعدی: unic + cityId + values ---
                    for (int i = 2; i < sheet.Rows.Count; i++)
                    {
                        string unicValue = sheet.Rows[i][0]?.ToString();
                        if (string.IsNullOrEmpty(unicValue)) continue;

                        int cityId = 0;
                        int.TryParse(sheet.Rows[i][2]?.ToString(), out cityId);

                        var values = new List<string>();
                        for (int col = 3; col < sheet.Columns.Count; col++)
                        {
                            values.Add(sheet.Rows[i][col]?.ToString());
                        }

                        unicRows.Add((unicValue, cityId, values));
                    }

                    totalInserted = unicRows.Count;
                }

                // مرحله 1: Insert در Create_linkjob_2
                var groupedByCity = unicRows.GroupBy(x => x.cityId);

                var dtLinkJob2 = new System.Data.DataTable();
                dtLinkJob2.Columns.Add("month", typeof(int));
                dtLinkJob2.Columns.Add("year", typeof(int));
                dtLinkJob2.Columns.Add("FK_city", typeof(int));
                dtLinkJob2.Columns.Add("FK_job", typeof(long));

                foreach (var g in groupedByCity)
                {
                    dtLinkJob2.Rows.Add(month, year, g.Key, jobId);
                }

                await BulkInsert("dbo.Create_linkjob_2", dtLinkJob2);

                // گرفتن آخرین ID ها برای مپ کردن
                var linkJob2Ids = db.Create_linkjob_2
                                    .OrderByDescending(x => x.ID)
                                    .Take(groupedByCity.Count())
                                    .Select(x => x.ID)
                                    .ToList();

                var cityToLinkJob2Id = groupedByCity
                    .Select((g, idx) => new { CityId = g.Key, LinkJob2Id = linkJob2Ids[idx] })
                    .ToDictionary(x => x.CityId, x => x.LinkJob2Id);

                // مرحله 2: Insert در Create_linkrelation2job_3
                var dtLinkRelation2 = new System.Data.DataTable();
                dtLinkRelation2.Columns.Add("ID", typeof(long));
                dtLinkRelation2.Columns.Add("FK_linkjob", typeof(long));
                dtLinkRelation2.Columns.Add("unic", typeof(string));

                long relation2IdSeed = GetMaxId("dbo.Create_linkrelation2job_3") + 1;

                var relation2Map = new Dictionary<string, long>(); // unic → relation2Id

                foreach (var row in unicRows)
                {
                    long newId = relation2IdSeed++;
                    dtLinkRelation2.Rows.Add(newId, cityToLinkJob2Id[row.cityId], row.unic);
                    relation2Map[row.unic] = newId;
                }

                await BulkInsert("dbo.Create_linkrelation2job_3", dtLinkRelation2);

                // مرحله 3: Insert در Create_linkrelation4detailjob_4
                var dtDetail = new System.Data.DataTable();
                dtDetail.Columns.Add("FK_Create_linkrelation2job_3", typeof(long));
                dtDetail.Columns.Add("Create_realjob2_2", typeof(long));
                dtDetail.Columns.Add("unic", typeof(string));
                dtDetail.Columns.Add("value", typeof(string));
                dtDetail.Columns.Add("vaziat", typeof(int));

                foreach (var row in unicRows)
                {
                    long relation2Id = relation2Map[row.unic];

                    for (int idx = 0; idx < realJobIds.Count; idx++)
                    {
                        dtDetail.Rows.Add(
                            relation2Id,
                            realJobIds[idx],
                            row.unic,
                            row.values[idx],
                            DBNull.Value
                        );
                    }
                }

                await BulkInsert("dbo.Create_linkrelation4detailjob_4", dtDetail);

                return $"با موفقیت {totalInserted} ردیف درج شد (شامل {realJobIds.Count} ستون داده‌ای)";
            }
            catch (Exception ex)
            {
                return "خطا: " + ex.Message;
            }
        }


