        public async Task<string> GetDataFromExcel_FishtAEADedit(HttpPostedFileBase MyExcelStream, long ID, long IDgozareh = 0)
        {
            try
            {
                var fidnds = db.dbergharel_4
                    .Where(s => s.FK_namegozarwsh == ID)
                    .OrderBy(s => s.start)
                    .ToList();

                if (fidnds.Count == 0)
                    return "هیچ رکوردی برای این گزارش یافت نشد";

                long gozar = (long)db.dbergharelinsert_6
                    .Where(s => s.ID == IDgozareh)
                    .Select(s => s.dbergharel_4.FK_namegozarwsh)
                    .FirstOrDefault();

                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                using (var reader = ExcelReaderFactory.CreateReader(MyExcelStream.InputStream))
                {
                    int sheetIndex = -1;

                    do
                    {
                        sheetIndex++;

                        // پیدا کردن fidnd که start == sheetIndex
                        var fidnd = fidnds.FirstOrDefault(f => f.start == sheetIndex);
                        if (fidnd == null)
                            continue; // این شیت مورد نیاز نیست

                        // ایجاد بافر
                        var bufferTable = CreateDataTableTemplate();
                        int batchSize = 100_000;
                        int currentBatchCount = 0;

                        // خواندن mapping‌ها
                        var mappings = await db.dbergharel4_5
                             .Where(m => m.FK_dbergharel4 == fidnd.ID && m.del != true)
                             .ToListAsync();

                        if (mappings.Count == 0)
                            return "هیچ مپینگی برای این گزارش ثبت نشده است";

                        // محاسبه ایندکس ستون‌ها
                        int unicIndex = ColumnLetterToIndex(fidnd.unic);
                        var mapIndexes = mappings.ToDictionary(m => m.FK_dbergharel2,
                            m => ColumnLetterToIndex(m.onvan));

                        int startRow = (int)fidnd.radifstart;
                        int rowIndex = -1;

                        DateTime batchTime = DateTime.Now;

                        // گرفتن کاربر
                        int personal = 0;
                        var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                        if (cookie_user != null)
                        {
                            var nc = Utility.Base64.Base64Decode(cookie_user.Value);
                            var usr = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nc);
                            if (usr != null) personal = usr.usr_ID;
                        }

                        // پیمایش سطرهای این شیت
                        while (reader.Read())
                        {
                            rowIndex++;
                            if (rowIndex < startRow)
                                continue;

                            string unicValue = SafeGetCell(reader, unicIndex);

                            foreach (var map in mappings)
                            {
                                string val = SafeGetCell(reader, mapIndexes[map.FK_dbergharel2]);

                                bufferTable.Rows.Add(
                                    IDgozareh,
                                    unicValue ?? (object)DBNull.Value,
                                    map.FK_dbergharel2,
                                    val ?? (object)DBNull.Value,
                                    batchTime,
                                    personal
                                );

                                currentBatchCount++;

                                if (currentBatchCount >= batchSize)
                                {
                                    await BulkInsertFinal(bufferTable, gozar);
                                    bufferTable.Clear();
                                    currentBatchCount = 0;
                                }
                            }
                        }

                        // ارسال باقی‌مانده‌ها
                        if (currentBatchCount > 0)
                        {
                            await BulkInsertFinal(bufferTable, gozar);
                        }

                    } while (reader.NextResult());
                }

                return "عملیات با موفقیت انجام شد.";
            }
            catch (Exception ex)
            {
                return "خطا: " + ex.Message;
            }
        }
        private System.Data.DataTable CreateDataTableTemplate()
        {
            System.Data.DataTable dt = new System.Data.DataTable();

            dt.Columns.Add("FK_dbergharelinsert_6", typeof(long));
            dt.Columns.Add("valuunic", typeof(string));
            dt.Columns.Add("FK_db2", typeof(long));
            dt.Columns.Add("valueFK_db2", typeof(string));
            dt.Columns.Add("timesabt", typeof(DateTime));
