                return Json(new { success = false, message = "No data received" });

            try
            {
                // ذخیره در جدول dbergharel_4
                var report = new dbergharel_4
                {
                    FK_namegozarwsh = model.FK_namegozarwsh,
                    type = model.Type,
                    start = model.Start,
                    unic = model.Unic,
                    FK_table=model.dberganametanble2_2,
                    radifstart=model.radifstart

                };

                db.dbergharel_4.Add(report);
                db.SaveChanges();

                // ذخیره جزئیات
                if (model.Details != null && model.Details.Any())
                {
                    foreach (var detail in model.Details)
                    {
                        var child = new dbergharel4_5
