        public JsonResult SaveProduct(ProductViewModel model)
        {
            if (model == null)
                return Json(new { success = false, message = "No data received" });

            try
            {
                // Save main table
                var main = new dbergha2
                {
                    name = model.Title,
                    vazn = model.Weight,
                    type = model.Type,
                    unic = false
                };

                db.dbergha2.Add(main);
                db.SaveChanges();

                // Save children
                if (model.ExtraFields != null && model.ExtraFields.Any())
                {
                    foreach (var sub in model.ExtraFields)
                    {
                        var child = new dbergharel2_3
                        {
                            FK_dbergha2 = main.ID,
                            name = sub.SubTitle,
                            olavait = sub.Priority
                        };
                        db.dbergharel2_3.Add(child);
                    }
                    db.SaveChanges();
                }

                return Json(new { success = true, message = "Saved successfully." });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }

        public async Task<ActionResult> SaveUserDataAndAnswersEMTEHAN(UserAndAnswersViewModel model)
        {
            try
            {
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];

                int personal = 0;
                string fullnamesabt = "";

                if (cookie_user != null)
                {
                    var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                    var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                    personal = user.usr_ID;
                    fullnamesabt = user.FullName;
                }

                // ذخیره اطلاعات کاربر
                var userInfo = db.arzyzbi7_value_usr.FirstOrDefault(x => x.FK_usr == model.FK_usr && x.usr_sabt == personal);
                if (userInfo == null)
                {
                    userInfo = new arzyzbi7_value_usr
                    {
                        FK_usr = model.FK_usr,
                        FK_Doreh = model.FK_doreh,
                        job = model.Job,
                        tahsilat = model.Tahsilat,
                        sabgheh_job = model.SabghehJob,
                        phon_number = model.PhonNumber,
                        usr_sabt = personal,
                        sokonat = model.sokonat,
                        Full_namesabt = fullnamesabt,
                        Actuve = true,
                        datatme_sabt = DateTime.Now
                    };
                    db.arzyzbi7_value_usr.Add(userInfo);
                }
                else
                {
                    userInfo.job = model.Job;
                    userInfo.tahsilat = model.Tahsilat;
                    userInfo.sabgheh_job = model.SabghehJob;
                    userInfo.phon_number = model.PhonNumber;
                    userInfo.datatme_sabt = DateTime.Now;
                    userInfo.sokonat = model.sokonat;
                }

                // ذخیره پاسخ‌ها (هر چک‌باکس یک رکورد جدا)
                foreach (var ans in model.Answers)
                {
                    var find = db.arzyzbi6_value.FirstOrDefault(s =>
                        s.FK_doreh == ans.FK_doreh &&
                        s.FK_usr == ans.FK_usr &&
                        s.FK_usr_sabt == personal &&
                        s.FK_soal == ans.FK_soal &&
                        s.FK_gozeneh == ans.FK_gozeneh);

                    if (find != null)
                    {
                        find.sharhsoal = ans.sharhsoal;
                    }
                    else
                    {
                        db.arzyzbi6_value.Add(new arzyzbi6_value
                        {
                            FK_usr = ans.FK_usr,
                            FK_doreh = ans.FK_doreh,
                            FK_soal = ans.FK_soal,
                            FK_gozeneh = ans.FK_gozeneh,
                            sharhsoal = ans.sharhsoal,
                            datatime = DateTime.Now,
                            FK_usr_sabt = personal,
                            FULL_namesabt = fullnamesabt,
                            Active = true
                        });
                    }
                }

                await db.SaveChangesAsync();
                return Content("ثبت با موفقیت انجام شد");
            }
            catch (Exception ex)
            {
                return Content("False" + ex.Message);
            }

        }

