        public ActionResult EXCEL_timearzyab_mostakrin(int month = 0, int year = 0)
        {
            var usr = db.Create_linkrelation2job_3
       .Where(s => s.Create_linkjob_2.month == month && s.Create_linkjob_2.year == year)
       .Select(s => new { s.unic, JobName = s.Create_linkjob_2.Create_job_1.name })
       .AsNoTracking();

            using (var package = new ExcelPackage())
            {
                var ws = package.Workbook.Worksheets.Add("Data");

                // هدرها
                ws.Cells[1, 1].Value = "کد یکتا";
                ws.Cells[1, 2].Value = "نام شغل";

                // داده‌ها مستقیم از دیتابیس → اکسل
                int row = 2;
                foreach (var item in usr)
                {
                    ws.Cells[row, 1].Value = item.unic;
                    ws.Cells[row, 2].Value = item.JobName;
                    row++;
                }

                // خروجی
                var stream = new MemoryStream();
                package.SaveAs(stream);
                stream.Position = 0;
                string fileName = $"moshtrak_{year}_{month}.xlsx";

                return File(stream,
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    fileName);
            }
        }

