                                    //DateTime persianDate = PersianDateToDateTime(inputDate);
                                    //DateTime persianDate2 = PersianDateToDateTime(inputDate2);

                                    // تبدیل تاریخ به فرمت مناسب برای SQL Server
                                    //string sqlFormattedDate = persianDate.ToString("yyyy-MM-dd ", CultureInfo.InvariantCulture);
                                    //string toendedDate = persianDate2.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);

                                    DateTime persianDate = PersianDateToDateTime(inputDate);
                                    DateTime persianDate2 = PersianDateToDateTime(inputDate2);
                                    var find = db.arzyzbi5_time.Where(s => s.FK_arzyzbi1 == IDD && s.namedoreh == name).FirstOrDefault();
                                    if (find == null)
                                    {
                                        obj4.FK_arzyzbi1 = IDD;
                                        obj4.datastart = persianDate; // اصلاح شد
                                        obj4.dataend = persianDate2;  // اصلاح شد
                                        obj4.datatimesabt = DateTime.Now;
                                        obj4.namedoreh = name;


                                        arzyzbi5_time.Add(obj4);
                                    }
                                    else
