        public ActionResult SaveCheckList(FormCollection form)
        {
            try
            {
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                int personal = 0;

                if (cookie_user != null)
                {
                    var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                    var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                    personal = user.usr_ID;
                }

                var model = new arzyzbi8_edit();

                // مامور قرائت
                model.FK_usr = System.Convert.ToInt32(form["typegozarwsh"]);

                // درب بسته
                model.vaziat = form["open"] == "on" ? 1 : 0;

                // گزارش‌ها (radio)
                for (int i = 1; i <= 5; i++) // اگر فقط 5 تا دارید می‌توانید تا 5 بگذارید
                {
                    var val = form["Label" + i];
                    if (!string.IsNullOrEmpty(val))
                    {
                        int v = 0;
                        if (val.Contains("ناصحیح")) v = 1;
                        else if (val.Contains("نشده")) v = 2;
                        else if (val.Contains("صحیح")) v = 3;

                        typeof(arzyzbi8_edit).GetProperty("vazsoal" + i)?.SetValue(model, v);
                    }
                }

                // شماره موبایل
                model.edittelephon = string.IsNullOrEmpty(form["edittelephon"]) ? 0 : System.Convert.ToInt32(form["edittelephon"]);
                model.shomareh = form["shomareh"];
                model.shomareh2 = form["shomareh2"];

                // مصرف انتخابی و مبلغ
                model.kilovat = string.IsNullOrEmpty(form["kilovat"]) ? 0 : System.Convert.ToInt32(form["kilovat"]);
                model.mablagh4kilovat = string.IsNullOrEmpty(form["mablagh4kilovat"]) ? 0 : System.Convert.ToInt64(form["mablagh4kilovat"]);

                // کد مانع
                model.codmaneh = string.IsNullOrEmpty(form["codmaneg"]) ? 0 : System.Convert.ToInt32(form["codmaneg"]);

                // مبلغ وصولی
                model.mablagh_vosoli = string.IsNullOrEmpty(form["mablaghvosaol"]) ? 0 : System.Convert.ToInt64(form["mablaghvosaol"]);

                // صحت جدول زمان بندی
                model.vaziatshomareh = form["vaziatshomareh"] == "on" ? 1 : 0;

                // منطقه و روزکار
                model.mantagheh = string.IsNullOrEmpty(form["mantegheh"]) ? 0 : System.Convert.ToInt32(form["mantegheh"]);
                model.rozkar = string.IsNullOrEmpty(form["rozkar"]) ? 0 : System.Convert.ToInt32(form["rozkar"]);
                var user1 = db.tbUsers.FirstOrDefault(u => u.usr_ID == personal);

                // ثبت کننده
                model.usrsabt = personal;
                model.codepersanalysabt = user1.usr_Personal_ID;
                model.fullnamesabt = user1.FullName;

                model.datatimesabt = DateTime.Now;

                db.arzyzbi8_edit.Add(model);
                db.SaveChanges();

                return Json(new { success = true, message = "با موفقیت ثبت شد" });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }



        public async Task<ActionResult> arzyabitestvalue()
        {
            var model = new FunctionModel
            {
                tbAdamAdam2 = new List<tbAdamAdam2>(),

                tbAdamAdam = new List<tbAdamAdam>(),
                arzyzbi5_time = new List<arzyzbi5_time>()
            };

            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;

            var findurlist = db.arzyzbi4_link
                .Where(s => s.FK_usr == personal && s.vaziat == true && s.arzyzbi1.Active != false)
                .ToList();

            //var findurlistusr = await db.tbAdamAdam
            //    .Where(s => s.Name == personal && s.Value == 1)
            //    .ToListAsync();

            //model.tbAdamAdam.AddRange(findurlistusr);
            var findurlistusr1 = await db.tbAdamAdam
    .Where(s => s.Name == personal && s.Value == 1)
    .ToListAsync();

            foreach (var adam in findurlistusr1)
            {
                var user1 = db.tbUsers.FirstOrDefault(u => u.usr_ID == adam.nam);
                if (user1 != null)
                {
                    var tbAdamAdam22 = new tbAdamAdam2();
                    tbAdamAdam22.ID = user1.usr_ID;
                    tbAdamAdam22.fullname = user1.FullName;
                    model.tbAdamAdam2.Add(tbAdamAdam22);

                }

                //adam.ExtraFullname = user.fullname; // این پراپرتی باید به صورت دستی به tbAdamAdam اضافه بشه (ViewModel یا Partial Class)
            }
            foreach (var it in findurlist)
            {
                var nowDate = DateTime.Now.Date;

                var times = await db.arzyzbi5_time
                    .Where(s => s.FK_arzyzbi1 == it.FK_arzyzbi1 &&
                                s.datastart <= nowDate &&
                                s.dataend >= nowDate
                                && s.arzyzbi1.typegozaresh == 2

                                )
                    .ToListAsync();


                foreach (var time in times)
                {
                    // فقط اگر namedoreh هنوز داخل مدل وجود نداشت، اضافه کن
                    if (!model.arzyzbi5_time.Any(x => x.namedoreh == time.namedoreh && x.FK_arzyzbi1 == time.FK_arzyzbi1))
                    {
                        model.arzyzbi5_time.Add(time);
                    }
                }
            }

            return PartialView("~/Areas/Setting/Views/Orders/arzyabitestvalue.cshtml", model);

        }

        public class GeoInfo
        {
            public string Country { get; set; }
            public string RegionName { get; set; }
            public string City { get; set; }
            public double Lat { get; set; }
            public double Lon { get; set; }
            public string Query { get; set; } // IP
        }

        [HttpGet]
        public async Task<ActionResult> GetLocation()
        {
            string ip = GetClientIp();
            var location = await GetGeoByIp(ip);
            return Json(location, JsonRequestBehavior.AllowGet);
        }

        private string GetClientIp()
        {
            var ip = Request.ServerVariables["HTTP_X_FORWARDED_FOR"];
            if (string.IsNullOrEmpty(ip))
                ip = Request.ServerVariables["REMOTE_ADDR"];
            return ip;
        }

        private async Task<GeoInfo> GetGeoByIp(string ip)
        {
            var url = $"http://ip-api.com/json/{ip}?lang=fa";
            using (var client = new HttpClient())
            {
                var json = await client.GetStringAsync(url);
                return JsonConvert.DeserializeObject<GeoInfo>(json);
            }
        }
