        [HttpPost]
        public ActionResult SabtTicket_motaghazi(
    long ID,
    int OnvanDarkhast,
    string Dalil,
    string Ellat,
    string Behbood,
    string Komak,
    int Olaviyat,
    string Mohlat,
    string Farayand)
        {
            int personal = 0;
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return Json(new { success = false, message = "کوکی یافت نشد" });

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return Json(new { success = false, message = "کاربر یافت نشد" });

            personal = user.usr_ID;

            try
            {
                using (SaabEntities db = new SaabEntities())
                {

                    if (ID > 0)
                    {

                        var ticket = db.Ticket_motaghazi1.FirstOrDefault(x => x.ID == ID);
                        if (ticket == null)
                            return Json(new { success = false, message = "تیکت یافت نشد" });

                        if (ticket.UserSabt != personal)
                            return Json(new { success = false, message = "شما مجاز به ویرایش این تیکت نیستید" });


                        bool seenByIT = db.Ticket_IT_2
                            .Any(p => p.Fk_Darkhast_Ticket_motaghazi1 == ID);

                        if (seenByIT)
                            return Json(new
                            {
                                success = false,
                                message = "به دلیل دیده شدن درخواست توسط بخش مربوطه، امکان ویرایش وجود ندارد"
                            });


                        ticket.OnvanDarkhast = OnvanDarkhast;
                        ticket.Sharh = Dalil;
                        ticket.ElatYaRishe = Ellat;
                        ticket.BehbodKarayi = Behbood;
                        ticket.KomakBeSayerBakhshHa = Komak;
                        ticket.Olaviat = Olaviyat;
                        ticket.ZamanAnjam = Mohlat;
                        ticket.Farayand = Farayand;
                        ticket.TimeSabt = DateTime.Now;
                    }

                    else
                    {
                        Ticket_motaghazi1 newTicket = new Ticket_motaghazi1()
                        {
                            OnvanDarkhast = OnvanDarkhast,
                            Sharh = Dalil,
                            ElatYaRishe = Ellat,
                            BehbodKarayi = Behbood,
                            KomakBeSayerBakhshHa = Komak,
                            Olaviat = Olaviyat,
                            ZamanAnjam = Mohlat,
                            Farayand = Farayand,
                            UserSabt = personal,
                            TimeSabt = DateTime.Now
                        };

                        db.Ticket_motaghazi1.Add(newTicket);
                    }

                    db.SaveChanges();
                }

                return Json(new { success = true, message = "ثبت اطلاعات با موفقیت انجام شد" });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }





        [HttpPost]
        public ActionResult DeleteTicket_motaghazi(int id)
        {
            try
            {

                int personal = 0;
                var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                if (cookie_user == null)
                    return Json(new { success = false, message = "دسترسی غیرمجاز" });

                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                if (user == null)
                    return Json(new { success = false, message = "کاربر یافت نشد" });

                personal = user.usr_ID;


                var ticket = db.Ticket_motaghazi1.FirstOrDefault(x => x.ID == id);
                if (ticket == null)
                    return Json(new { success = false, message = "تیکت یافت نشد" });


                if (ticket.UserSabt != personal)
                    return Json(new { success = false, message = "شما مجاز به حذف این تیکت نیستید" });
                bool seenByIT = db.Ticket_IT_2
                                                 .Any(p => p.Fk_Darkhast_Ticket_motaghazi1 == id);

                if (seenByIT)
                    return Json(new
                    {
                        success = false,
                        message = "به دلیل دیده شدن درخواست توسط بخش مربوطه، امکان حذف وجود ندارد"
                    });
                db.Ticket_motaghazi1.Remove(ticket);
                db.SaveChanges();

                return Json(new { success = true, message = "تیکت با موفقیت حذف شد" });
            }
            catch
            {
                return Json(new { success = false, message = "خطا در حذف اطلاعات" });
            }
        }






