        public async Task< ActionResult> countarzyabi()
        {
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;     
            var findurlistusr1 = await db.tbAdamAdam
.Where(s => s.Name == personal  && s.Value == 1)
.ToListAsync();
            List<arzyzbi5_time> arzyzbi5_time = new List<arzyzbi5_time>();
            List<arzyzbi5_time> arzyzbi5_time2 = new List<arzyzbi5_time>();

            var findurlist =await db.arzyzbi4_link
    .Where(s => s.FK_usr == personal  && s.vaziat == true && s.arzyzbi1.Active != false)
    .ToArrayAsync();
            foreach (var it in findurlist)
            {
                var nowDate = DateTime.Now.Date;

                var findarzyab = await db.arzyzbi5_time
                    .Where(s => s.FK_arzyzbi1 == it.FK_arzyzbi1 &&
                                s.datastart <= nowDate &&
                                s.dataend >= nowDate
                                && s.arzyzbi1.typegozaresh == 1

                                )
                    .ToListAsync();
                foreach (var time in findarzyab)
                {
                    // فقط اگر namedoreh هنوز داخل مدل وجود نداشت، اضافه کن
                    if (!arzyzbi5_time.Any(x => x.namedoreh == time.namedoreh && x.FK_arzyzbi1 == time.FK_arzyzbi1))
                    {
                        arzyzbi5_time.Add(time);
                    }
                }
            }
            foreach (var it in findurlist)
            {
                var nowDate = DateTime.Now.Date;

              var  findarzyab = await db.arzyzbi5_time
                    .Where(s => s.FK_arzyzbi1 == it.FK_arzyzbi1 &&
                                s.datastart <= nowDate &&
                                s.dataend >= nowDate
                                && s.arzyzbi1.typegozaresh == 2

                                )
                    .ToListAsync();

                foreach (var time in findarzyab)
                {
                    // فقط اگر namedoreh هنوز داخل مدل وجود نداشت، اضافه کن
                    if (!arzyzbi5_time2.Any(x => x.namedoreh == time.namedoreh && x.FK_arzyzbi1 == time.FK_arzyzbi1))
                    {
                        arzyzbi5_time2.Add(time);
                    }
                }
            }
            int count = 1;         // عدد کلی برای رنگ آیکون
            int evaluation = 0;    // تعداد ارزیابی‌ها
            int poll = 0;          // تعداد نظرسنجی‌ها

            foreach (var it in arzyzbi5_time)
            {
                var find = db.arzyzbi6_value.Where(s => s.FK_usr_sabt == personal &&s.FK_usr==personal && s.FK_doreh == it.ID).FirstOrDefault();
                if (find == null)
                {
                    poll += 1;
                    count = 3;
                }
            }

            foreach (var it in arzyzbi5_time2)
            {

                if (count != 3)
                {

                    var find = db.arzyzbi6_value.Where(s => s.FK_usr_sabt == personal && s.FK_doreh == it.ID).FirstOrDefault();
                    if (find == null)
                    {
                        evaluation += 1;
                        count = 3;
                    }
                    else
                    {
                        var nameList = findurlistusr1.Select(x => x.Name).ToList();

                        // بررسی اینکه Name در لیست هست، ولی FK_usr نه
                        //bool nameExists = nameList.Contains(personal);
                        bool atLeastOneMissing = nameList.Any(name =>
               !db.arzyzbi6_value.Any(v =>
                   v.FK_usr == name && v.FK_doreh == it.ID));

                        if (atLeastOneMissing)
                        {
                            evaluation += 1;
                            count = 2;
                            // کار دلخواه شما (مثلاً ثبت لاگ یا افزایش شمارنده خاص)
                        }
                    }
                }

            }


            return Json(new
            {
                count = count,
                evaluation = evaluation,
                poll = poll
            });
        }
     

