        public async Task<ActionResult> SaveAnswers( List<Arzyzbi6ValueViewModel> answers)
        {
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            int personal = 0;
            string fullnamesabt = "";
            if (cookie_user != null)
            {
                var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                personal = user.usr_ID;
                fullnamesabt = user.FullName;
            }
            if (answers == null || !answers.Any())
                return Content("پاسخی دریافت نشد");

            foreach (var ans in answers)
            {
                var find = db.arzyzbi6_value.Where(s => s.FK_doreh == ans.FK_doreh&&s.FK_usr==ans.FK_usr && s.FK_usr_sabt == personal&&s.Active!=false && s.FK_soal == ans.FK_soal).FirstOrDefault();
                if (find != null)
                {
                    find.FK_gozeneh = ans.FK_gozeneh;
                    find.sharhsoal = ans.sharhsoal;
                    find.datatime = DateTime.Now;

                }
                else
                {
                    var newValue = new arzyzbi6_value
                    {
                        FK_usr = ans.FK_usr,
                        FK_doreh = ans.FK_doreh,
                        FK_soal = ans.FK_soal,
                        FK_gozeneh = ans.FK_gozeneh,
                        sharhsoal = ans.sharhsoal,
                        datatime = DateTime.Now,
                        FK_usr_sabt = personal,
                        FULL_namesabt = fullnamesabt,
                        Active = true // یا false به دلخواه
                    };

                    db.arzyzbi6_value.Add(newValue);
                }
            
            }

