                long fkarzyab = 0;
                var find = db.arzyzbi5_time.Where(s => s.ID == id).FirstOrDefault();
                if (find != null)
                {
                    fkarzyab = (long)find.FK_arzyzbi1;
                }
              
                if (cookie_user != null)
                {
                    var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                    var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
                    personal = user.usr_ID;
                    fullnamesabt = user.FullName;
                    if (usrID == -5)
                    {
                        usrID = user.usr_ID;

                    }
                    var user2 = db.tbUsers.FirstOrDefault(p => p.usr_ID == usrID);
                    fullnamesabtusr = user2.FullName;

                }

                // لیست پاسخ‌های ثبت‌شده
                var existingAnswers = db.arzyzbi6_value
                    .Where(a => a.FK_usr == usrID && a.FK_usr_sabt == personal && a.FK_doreh == id)
                    .ToList();

                // بازیابی اطلاعات arzyzbi7_value_usr
                var userExtraInfo = db.arzyzbi7_value_usr
                    .FirstOrDefault(x => x.FK_usr == usrID && x.usr_sabt == personal);

                // سوالات + گزینه‌ها
                var soalList = db.arzyzbi2_soal
                    .Where(s => s.FK_arzyzbi1 == fkarzyab && s.Active != false)
                    .Select(s => new SoalWithGozinehViewModel
                    {
                        SoalId = s.ID,
                        SoalText = s.soal,
                        GozinehList = db.arzyzbi3_gozeneh
                            .Where(g => g.FK_arzyabisoal == s.ID && g.Active != false)
                            .Select(g => new GozinehItem
                            {
                                GozinehId = g.ID,
                                GozinehText = g.gozineh,
                                Selected = false
                            }).ToList(),
                        SharhSoal = ""
                    }).ToList();

                // اعمال پاسخ‌های قبلی روی سوالات
                foreach (var soal in soalList)
                {
                    var oldAnswer = existingAnswers.FirstOrDefault(x => x.FK_soal == soal.SoalId);
                    if (oldAnswer != null)
                    {
                        soal.SharhSoal = oldAnswer.sharhsoal;

                        foreach (var goz in soal.GozinehList)
                        {
                            if (goz.GozinehId == oldAnswer.FK_gozeneh)
                            {
                                goz.Selected = true;
                            }
                        }
                    }
                }
                if (userExtraInfo != null)
                {
                    var model = new FunctionModel
                    {
                        SoalList = soalList,
                        Job = userExtraInfo.job ?? "",
                        Tahsilat = userExtraInfo.tahsilat ?? "",
                        SabghehJob = userExtraInfo.sabgheh_job ?? "",
                        PhonNumber = userExtraInfo.phon_number ?? "",
                        sokonat = userExtraInfo.sokonat ?? 0,
                        fullnamesabtusr = fullnamesabtusr
                    };

                    return PartialView("~/Areas/Setting/Views/Orders/arzyabilivaluevalue.cshtml", model);
                }
                else
                {
                    var model = new FunctionModel
                    {
                        SoalList = soalList,
                        Job = "",
                        Tahsilat = "",
                        SabghehJob = "",
                        PhonNumber = "",
                        sokonat = 0,

                        fullnamesabtusr = fullnamesabtusr
                    };
                    return PartialView("~/Areas/Setting/Views/Orders/arzyabilivaluevalue.cshtml", model);

                }


            }
            catch (Exception ex)
            {
                return Content("False"+ex.Message);
            }
          

        }
