        public ActionResult EXCEL_GOZARESHONEARZYABI(long NAMDOREH=0)
        {





            //var OutPutFile = SetDataToMachinsOrToolsExcel(Peyman_ID, type, Month, Year);
            var OutPutFile = EXCEL_GOZARESHONEARZYABIupload(NAMDOREH);

            string extension = ".xlsx";

            var stream = new MemoryStream();
            OutPutFile.Save(stream, extension);
            var mimeType = MimeTypes.ByExtension[extension];
            var find = db.arzyzbi5_time.Where(s => s.ID == NAMDOREH).FirstOrDefault();
            string name = "";
            string arzyab = "";
            if (find != null)
            {
                name = find.namedoreh;
                arzyab = find.arzyzbi1.name;
            }
            return File(stream.ToArray(), mimeType,  "نام گزارش: " + arzyab +"_"+"نام دوره: " + name + extension);

        }
        private Workbook EXCEL_GOZARESHONEARZYABIupload(long NAMDOREH = 0)
        {
            List<arzyzbi2_soal> arzyzbi2_soal = new List<arzyzbi2_soal>();
            var findfk = db.arzyzbi5_time.FirstOrDefault(s => s.ID == NAMDOREH);
            if (findfk != null)
            {
                var findsoal = db.arzyzbi2_soal.Where(s => s.FK_arzyzbi1 == findfk.FK_arzyzbi1 && s.Active != false).ToList();
                arzyzbi2_soal.AddRange(findsoal);
            }

            var Moalefeexcelfile = Workbook.Load(Server.MapPath("~/Content/ExcelFiles/EXCELARYABIVERONE.xlsx"));

            // ردیف سوالات - ردیف دوم به بعد
            int questionHeaderRowIndex = 1;
            Row soalHeaderRow = new Row() { Height = 20, Index = questionHeaderRowIndex };
            soalHeaderRow.AddCells(new List<Cell>
    {
        new Cell() { Value = "کد ثبت", Index = 0, FontFamily = "B Nazanin", FontSize = 12 },
        new Cell() { Value = "نام کاربر", Index = 1, FontFamily = "B Nazanin", FontSize = 12 },
        new Cell() { Value = "کد پرسنلی", Index = 2, FontFamily = "B Nazanin", FontSize = 12 },
                new Cell() { Value = "سمت شغل", Index = 3, FontFamily = "B Nazanin", FontSize = 12 },
                                new Cell() { Value = "شهر محل خدمت ", Index = 4, FontFamily = "B Nazanin", FontSize = 12 }
                                ,                                new Cell() { Value = "تایم ارزیابی ", Index = 5, FontFamily = "B Nazanin", FontSize = 12 }


    });

            int columnIndex = 6;
            foreach (var soal in arzyzbi2_soal)
            {
                soalHeaderRow.AddCell(new Cell
                {
                    Value = soal.soal,
                    Index = columnIndex++,
                    FontFamily = "B Nazanin",
                    FontSize = 12
                });
            }
            Moalefeexcelfile.Sheets[0].AddRow(soalHeaderRow);

            // اطلاعات پاسخ‌دهندگان
            var find = db.arzyzbi6_value.Where(s => s.FK_doreh == NAMDOREH).ToList();
            var grouped = find
                .GroupBy(s => new { s.FK_usr, s.FK_usr_sabt, s.FK_doreh })
                .ToList();

            int rowIndex = 2;
