            var stream = new MemoryStream();
            OutPutFile.Save(stream, extension);
            var mimeType = MimeTypes.ByExtension[extension];

            var yy = db.tbPeymanContracts.Where(p => p.pec_ID == peymans3).FirstOrDefault();



            return File(stream.ToArray(), mimeType, "Moalefe"+yy.pec_Title + extension);

        }
