        public ActionResult ExportAddMoalefeExcelforpumnusr()
        {
            int Month = 4;
            int Year = 1403;
            var OutPutFile = SetDataExcel_AddMoalefpymnusr();
            string extension = ".xlsx";
            List<tbMoadelPadashJarimeAyab> List1 = new List<tbMoadelPadashJarimeAyab>();
            tbMoadelPadashJarimeAyab ayab;
            double tty = 0;
            double tty1 = 0;
            var yyy = db.tbMoalefeDastmozdiValueFromExcel
                         .Where(p => p.MoalfeVal_Month == Month && p.MoalfeVal_Year == Year)
                         .ToList();
            var caran = db.tbCaranSettings.ToList();
            var yu = db.tbUsers.Where(p => p.usr_Personal_ID != null).ToList();
            foreach (var it in yu)
            {
                var tt = yyy.Where(p => p.MoalfeVal_FKUser == it.usr_ID
                                        && p.MoalfeVal_Value != 0
                                        && p.MoalfeVal_Month == Month
                                        && p.MoalfeVal_Year == Year
                                        && p.FK_SavedFunctionsID != null).ToList();
                tty = 0;
                tty1 = 0;
                if (tt.Count != 0)
                {
                    foreach (var itwm in tt)
                    {
                        var y = caran
                                  .Where(p => p.FK_Moalefe_ID == itwm.MoalfeVal_FKMoalafeDastmozdi)
                                  .FirstOrDefault();
                        if (y != null) // Added null check for tbCaranSettings
                        {
                            if (y.CaranStandard != 0)
                            {
                                tty += (double)(itwm.MoalfeVal_Value ?? 0) / (double)y.CaranStandard;
                            }
                            if (y.CaranAyabOZahab != 0)
                            {
                                tty1 += (double)(itwm.MoalfeVal_Value ?? 0) * (double)y.CaranAyabOZahab;
                            }
                        }
                    }
                    ayab = new tbMoadelPadashJarimeAyab
                    {
                        Year = Year,
                        Month = Month,
                        Padash = 0,
                        Jarime = 0,
                        AyabOZahab = tty1,
                        Moadel = tty,
                        UserID = it.usr_ID
                    };
                    List1.Add(ayab);
                }
            }
            db.tbMoadelPadashJarimeAyab.AddRange(List1);
            db.SaveChanges();

            var stream = new MemoryStream();
            OutPutFile.Save(stream, extension);
            var mimeType = MimeTypes.ByExtension[extension];
            return File(stream.ToArray(), mimeType, "Cheackestandardmoalfe" + extension);
        }
