        public ActionResult ExportAddMoalevosol(int vaz=0)
        {
            var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie_user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کوکی یافت نشد");

            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return new HttpStatusCodeResult(HttpStatusCode.BadRequest, "کاربر یافت نشد");

            int personal = user.usr_ID;
           
            var OutPutFile = SetDataExcel_Addvosl( personal, vaz);
            //var OutPutFile = SetDataExcel_AddMobemeh();

            string extension = ".xlsx";
            string name = "";

            if (vaz == 1)
            {
                name = "parvande";
            }
            else
            {
                name = "shenaseh";
            }
            var stream = new MemoryStream();
            OutPutFile.Save(stream, extension);
            var mimeType = MimeTypes.ByExtension[extension];
            return File(stream.ToArray(), mimeType, name + extension);
        }

