        public ActionResult PreviewExcelFromServer()
        {
            try
            {
                var path = Server.MapPath("~/Content/ExcelFiles/manathegh.xlsx");

                if (!System.IO.File.Exists(path))
                    return Json(new { success = false, message = "فایل یافت نشد" }, JsonRequestBehavior.AllowGet);

                System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

                using (var stream = System.IO.File.Open(path, FileMode.Open, FileAccess.Read))
                using (var reader = ExcelReaderFactory.CreateReader(stream))
                {
                    var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration()
                    {
                        ConfigureDataTable = _ => new ExcelDataTableConfiguration()
                        {
                            UseHeaderRow = false
                        }
                    });

                    var sheet = dataSet.Tables[0];

                    var result = new List<List<string>>();

                    foreach (DataRow row in sheet.Rows)
                    {
                        var rowData = new List<string>();
                        foreach (var cell in row.ItemArray)
                        {
                            rowData.Add(cell?.ToString());
                        }
                        result.Add(rowData);
                    }

                    return Json(new { success = true, data = result }, JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        public ActionResult CopySheetValues()
        {
            var sourcePath = Server.MapPath("~/Content/ExcelFiles/source.xlsx");
            var destPath = Server.MapPath("~/Content/ExcelFiles/destination.xlsx");

            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

            using (var sourcePkg = new ExcelPackage(new FileInfo(sourcePath)))
            using (var destPkg = new ExcelPackage(new FileInfo(destPath)))
            {
                var sourceSheet = sourcePkg.Workbook.Worksheets[0]; // شیت اول
                var destSheet = destPkg.Workbook.Worksheets[1];

                int rows = sourceSheet.Dimension.End.Row;
                int cols = sourceSheet.Dimension.End.Column;

                for (int r = 1; r <= rows; r++)
                {
                    for (int c = 1; c <= cols; c++)
                    {
                        var val = sourceSheet.Cells[r, c].Value;
                        destSheet.Cells[r, c].Value = val; // paste value
                    }
                }

                destPkg.Save();
            }

            return Content("Done");
        }
