        public ActionResult ExportEydiReport(int year = 1404)
        {
            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

            var yearParam = new SqlParameter("@year", year);

            var data = db.Database.SqlQuery<EydiReportVM>(@"
WITH Base AS (
    SELECT *
    FROM Salary.tbMoalefeValueFish
    WHERE mlfvlfsh_Year = @year
),
Users1979 AS (
    SELECT 
        FK_User,
        MIN(CASE WHEN FK_Moalefe = 1979 AND mlfvlfsh_Value > 0 THEN mlfvlfsh_Month END) AS FirstMonth,
        MAX(CASE WHEN FK_Moalefe = 1979 AND mlfvlfsh_Value > 0 THEN mlfvlfsh_Month END) AS LastMonth,
        COUNT(DISTINCT CASE WHEN FK_Moalefe = 1979 AND mlfvlfsh_Value > 0 THEN mlfvlfsh_Month END) AS ActiveMonthsCount
    FROM Base
    GROUP BY FK_User
    HAVING COUNT(CASE WHEN FK_Moalefe = 1979 AND mlfvlfsh_Value > 0 THEN 1 END) > 0
),
SumCondition AS (
    SELECT  
        FK_User,
        CAST(SUM(
            CASE 
                WHEN FK_Moalefe = 1960 AND FK_EXCel is null THEN mlfvlfsh_Value
                WHEN FK_Moalefe = 1964 AND FK_EXCel is null THEN mlfvlfsh_Value
                ELSE 0
            END
        ) AS DECIMAL(18,2)) AS SumCondition
    FROM Base
    GROUP BY FK_User
)
SELECT  
    u.FK_User,
    us.usr_Personal_ID AS PersonalCode,
    us.usr_Name AS Name,
    us.usr_Family AS Family,
    u.FirstMonth,
    u.LastMonth,
    u.ActiveMonthsCount,
    ISNULL(s.SumCondition,0) AS SumCondition,

    CAST(ISNULL(SUM(CASE WHEN b.FK_Moalefe = 1929 THEN b.mlfvlfsh_Value END),0) AS DECIMAL(18,2)) AS Value1973,
    CAST(ISNULL(SUM(CASE WHEN b.FK_Moalefe = 1930 THEN b.mlfvlfsh_Value END),0) AS DECIMAL(18,2)) AS Value1982,
    CAST(ISNULL(SUM(CASE WHEN b.FK_Moalefe IN (1929,1930) THEN b.mlfvlfsh_Value END),0) AS DECIMAL(18,2)) AS Sum1973_1982,

    CAST((
        ISNULL(SUM(CASE WHEN b.FK_Moalefe IN (1929,1930) THEN b.mlfvlfsh_Value END),0)
        * 60.0 / 365.0
        * ISNULL(s.SumCondition,0)
    ) AS DECIMAL(18,2)) AS Eydi,

    CAST((
        (
            ISNULL(SUM(CASE WHEN b.FK_Moalefe IN (1929,1930) THEN b.mlfvlfsh_Value END),0)
            * 60.0 / 365.0
            * ISNULL(s.SumCondition,0)
        ) / 2.0
    ) AS DECIMAL(18,2)) AS Sanavat

FROM Users1979 u
LEFT JOIN Base b 
    ON u.FK_User = b.FK_User 
    AND b.mlfvlfsh_Month = u.LastMonth
LEFT JOIN SumCondition s 
    ON u.FK_User = s.FK_User
LEFT JOIN Usser.tbUsers us 
    ON u.FK_User = us.usr_ID

GROUP BY 
    u.FK_User,
    us.usr_Personal_ID,
    us.usr_Name,
    us.usr_Family,
    u.FirstMonth,
    u.LastMonth,
    u.ActiveMonthsCount,
    s.SumCondition

ORDER BY us.usr_Family, us.usr_Name
", yearParam).ToList();

            using (var package = new ExcelPackage())
            {
                var ws = package.Workbook.Worksheets.Add("گزارش عیدی");

                ws.Cells[1, 1].Value = $"گزارش عیدی سال {year}";
                ws.Cells[1, 1, 1, 11].Merge = true;
                ws.Cells[1, 1].Style.Font.Bold = true;
                ws.Cells[1, 1].Style.HorizontalAlignment = OfficeOpenXml.Style.ExcelHorizontalAlignment.Center;

                // ستون‌ها
                ws.Cells[2, 1].Value = "نام و نام خانوادگی";
                ws.Cells[2, 2].Value = "کد پرسنلی";
                ws.Cells[2, 3].Value = "اولین ماه";
                ws.Cells[2, 4].Value = "آخرین ماه";
                ws.Cells[2, 5].Value = "ماه فعال";
                ws.Cells[2, 6].Value = "تعداد روزکاری";
                ws.Cells[2, 7].Value = "مزد شغل";     // Value1973
                ws.Cells[2, 8].Value = "مزد سنوات";       // Value1982
                ws.Cells[2, 9].Value = "مزد مبنا";      // Sum1973_1982
                ws.Cells[2, 10].Value = "عیدی";
                ws.Cells[2, 11].Value = "سنوات";

                using (var header = ws.Cells[2, 1, 2, 11])
                {
                    header.Style.Font.Bold = true;
                    header.Style.Fill.PatternType = OfficeOpenXml.Style.ExcelFillStyle.Solid;
                    header.Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.LightGray); // رنگ هدر روشن
                    header.Style.HorizontalAlignment = OfficeOpenXml.Style.ExcelHorizontalAlignment.Center;
                }

                int row = 3;

                foreach (var item in data)
                {
                    ws.Cells[row, 1].Value = item.Family + " " + item.Name;
                    ws.Cells[row, 2].Value = item.PersonalCode?.ToString();
                    ws.Cells[row, 3].Value = item.FirstMonth;
                    ws.Cells[row, 4].Value = item.LastMonth;
                    ws.Cells[row, 5].Value = item.ActiveMonthsCount;

                    // تعداد روزکاری با جداکننده هزارگان
                    ws.Cells[row, 6].Value = item.SumCondition;
                    //ws.Cells[row, 6].Style.Numberformat.Format = "#,##0";

                    ws.Cells[row, 7].Value = item.Value1973;
                    ws.Cells[row, 7].Style.Numberformat.Format = "#,##0";
                    // مزد سنوات
                    ws.Cells[row, 8].Value = item.Value1982;
                    ws.Cells[row, 8].Style.Numberformat.Format = "#,##0";
                    // مزد شغل
                    ws.Cells[row, 9].Value = item.Sum1973_1982;
                    ws.Cells[row, 9].Style.Numberformat.Format = "#,##0";
                    // مزد مبنا
                    ws.Cells[row, 10].Value = item.Eydi;
                    ws.Cells[row, 10].Style.Numberformat.Format = "#,##0";

                    ws.Cells[row, 11].Value = item.Sanavat;
                    ws.Cells[row, 11].Style.Numberformat.Format = "#,##0";


                    row++;
                }

                ws.Cells[ws.Dimension.Address].AutoFitColumns();

                return File(package.GetAsByteArray(),
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    $"EydiReport_{year}.xlsx");
            }
        }
