        public Workbook SetDataExcel_hakemat_new(int month = 4, int year = 1403)
        {
            PersianCalendar persianCalendar = new PersianCalendar();
            DateTime miladiDate = ConvertShamsiToMiladi(year, month);

            var Moalefeexcelfile = Workbook.Load(Server.MapPath("~/Content/ExcelFiles/newkakmeat.xlsx"));
            int dayy = (int)TeadaroozMonth(month, year);
            // گرفتن مقادیر فیش همان ماه
            var moalefeValues = db.tbMoalefeValueFish
                .Where(p => p.mlfvlfsh_Year == year && p.mlfvlfsh_Month == month && p.FK_EXCel == null&&p.mlfvlfsh_Value>0)
                .ToList();

            // کاربران مرتبط
            var users = moalefeValues
                .Where(p => p.tbContractMoalefeDastmozdi.md_Title == "خالص قابل دریافت (ریال)" &&p.mlfvlfsh_Value>0)
                .Select(p => p.tbUsers)
                .Distinct()
                .ToList();

            // Lookup برای دسترسی سریع به مولفه های هر کاربر
            var moalefeLookup = moalefeValues
                .GroupBy(x => x.FK_User)
                .ToDictionary(g => g.Key, g => g.ToList());

            // قراردادها
            var contracts = db.tbUserContracts
                .Where(p => p.usc_TypeOfContract == true && p.FK_UserID != null)
                .ToList()
                .GroupBy(x => x.FK_UserID)
                .ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.usc_ID).ToList());

            // اسناد مالی
            var asnad = db.tbfkfinancial.ToList();

            var asnadFiltered = asnad.Where(it =>
            {
                if (!it.DataDocument.HasValue) return false;
                var d = it.DataDocument.Value;
                return persianCalendar.GetYear(d) == year &&
                       persianCalendar.GetMonth(d) == month;
            }).ToList();

            // اسناد مالی کاربران
            var financialDocs = db.FinancialDocuments
