            int counter = 1;

            foreach (var user in users)
            {
                if (!moalefeLookup.ContainsKey(user.usr_ID))
                    continue;

                var userValues = moalefeLookup[user.usr_ID];

                long val1 = (long)(userValues
                    .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_Title == "خالص قابل دریافت (ریال)")?.mlfvlfsh_Value ?? 0);

                long val2 = (long)(userValues
                    .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_Title == "جمع ناخالص حقوق و مزایا (ریال)")?.mlfvlfsh_Value ?? 0);
