                //var xx2 = userValues.Where(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_ID == 1981).FirstOrDefault();

                long val3 = (long)(userValues
                    .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_ID == 1961)?.mlfvlfsh_Value ?? 0);
                long val4 = (long)(userValues
                .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_ID == 1981)?.mlfvlfsh_Value ?? 0);
                string contractNumber = "";
                long val4day = (long)(userValues
            .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_ID == 1960)?.mlfvlfsh_Value ?? 0);
                long valshogl= (long)(userValues
   .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_Title == "مزد گروه (شغل)")?.mlfvlfsh_Value ?? 0);
                long valsanavat = (long)(userValues
            .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_Title == "مزد سنوات (ریال)")?.mlfvlfsh_Value ?? 0); 
                long valolad = (long)(userValues
            .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_Title == "کمک هزینه اولاد(ریال)")?.mlfvlfsh_Value ?? 0);

                long valmaskan= (long)(userValues
         .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_Title == "کمک هزینه مسکن (ریال)")?.mlfvlfsh_Value ?? 0);
                long valkarbar = (long)(userValues
            .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_Title == "کمک هزینه اقلام مصرفی خانوار(ریال)")?.mlfvlfsh_Value ?? 0);
                long valtahol = (long)(userValues
            .FirstOrDefault(x => x.FK_EXCel == null && x.tbContractMoalefeDastmozdi.md_Title == "حق تاهل")?.mlfvlfsh_Value ?? 0);
                long kolhoghogh = 0;
                long kolhoghoghangizaesh = 0;

                if (val4day != 0 && val4day != dayy)
                {
                    // استفاده از decimal برای جلوگیری از خطای اعشاری
                    valshogl = (long)Math.Ceiling((decimal)valshogl * dayy / val4day);
                    valsanavat = (long)Math.Ceiling((decimal)valsanavat * dayy / val4day);
                    valolad = (long)Math.Ceiling((decimal)valolad * dayy / val4day);
                    valmaskan = (long)Math.Ceiling((decimal)valmaskan * dayy / val4day);
                    valkarbar = (long)Math.Ceiling((decimal)valkarbar * dayy / val4day);
