                //    valmaskan = (long)((valmaskan * dayy) / val4day);
                //    valkarbar = (long)((valkarbar * dayy) / val4day);
                //    valtahol = (long)((valtahol * dayy) / val4day);
                //}
                kolhoghogh = valtahol + valkarbar + valmaskan + valolad + valsanavat + valshogl;
                kolhoghoghangizaesh = valtahol + valkarbar + valmaskan + valolad ;

                if (contracts.ContainsKey(user.usr_ID))
                {
                    var t = contracts[user.usr_ID]
                        .FirstOrDefault(p => miladiDate >= p.usc_StartTime && miladiDate <= p.usc_EndTime);

                    if (t != null)
                        contractNumber = t.usc_ContractNumber;
                }

                Row row = new Row() { Height = 20, Index = counter };

