    new Cell(){Value = GetMonthName(month), FontFamily="B Nazanin", FontSize=12, Index=1},
    new Cell() {
    Value = kolhoghogh, // عدد را بفرستید، نه رشته را
    Format = "#,##0",   // فرمت اکسل برای جداکننده هزارگان
    FontFamily = "B Nazanin",
    FontSize = 12,
    Index = 3
}
,
    // ستون‌های پولی با فرمت سه رقم جداکننده (N0)
    //new Cell(){Value = kolhoghogh.ToString("N0"), FontFamily="B Nazanin", FontSize=12, Index=3},
    new Cell(){Value = val1,Format = "#,##0", FontFamily="B Nazanin", FontSize=12, Index=8},

    new Cell(){Value = user.usr_NationalCode,    
 FontFamily="B Nazanin", FontSize=12, Index=2},
    new Cell(){Value = val3,Format = "#,##0", FontFamily="B Nazanin", FontSize=12, Index=5},
    new Cell(){Value = val4, FontFamily="B Nazanin",Format = "#,##0", FontSize=12, Index=4},
    new Cell(){Value = val2, Format = "#,##0",FontFamily="B Nazanin", FontSize=12, Index=7}
});

                // برای ستون آخر (Index 8)
             


                long financialSum = 0;

                if (financialDocs.ContainsKey(user.usr_ID))
                {
                    foreach (var item in financialDocs[user.usr_ID])
                    {
                        if (!item.DataDocument.HasValue)
                            continue;

                        var d = item.DataDocument.Value;

                        if (persianCalendar.GetYear(d) == year &&
                            persianCalendar.GetMonth(d) == month)
                        {
                            if (item.Debtore != null && item.Creditor != null && item.Debtore != 0 && item.Creditor != 0)
                                financialSum += (long)(item.Creditor - item.Debtore);

                            else if (item.Debtore != null && item.Debtore != 0)
                                financialSum -= (long)item.Debtore;

                            else if (item.Creditor != null && item.Creditor != 0)
                                financialSum += (long)item.Creditor;
                        }
                    }
                }
                row.AddCells(new List<Cell>()
{
    new Cell()
    {
        Value = (financialSum + kolhoghoghangizaesh),
        Format = "#,##0",
        FontFamily = "B Nazanin",
        FontSize = 12,
        Index = 6
    }
});

                Moalefeexcelfile.Sheets[0].AddRow(row);
                counter++;
            }

            return Moalefeexcelfile;
        }
