        public ActionResult Hoshdarattention()
        {
            var cookie = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
            if (cookie == null)
                return Json(new { success = false }, JsonRequestBehavior.AllowGet);

            var nationalcode = Utility.Base64.Base64Decode(cookie.Value);

            var user = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode == nationalcode);
            if (user == null)
                return Json(new { success = false }, JsonRequestBehavior.AllowGet);

            var today = DateTime.Today;
            var now = DateTime.Now;

            var hoshdars = db.tbHoshdar
                .Where(s => s.FK_usr == user.usr_ID && s.Active != false)
                .ToList();

            var hoshdarIds = hoshdars.Select(x => x.ID).ToList();

            var history = db.tbHoshdar1
                .Where(x => x.FK_tbHoshdar.HasValue && hoshdarIds.Contains(x.FK_tbHoshdar.Value))
                .ToList();


            foreach (var it in hoshdars)
            {
                var his = history.Where(h => h.FK_tbHoshdar == it.ID)
                                 .OrderByDescending(h => h.ID)
                                 .FirstOrDefault();

                if (it.datepickerFromEn_usrrepet?.Date == today &&
                    it.datepickerFromEn_usrrepet.Value.TimeOfDay <= now.TimeOfDay)
                {
                    return Json(new
                    {
                        success = true,
                        name = it.NAME,
                        description = it.sharhhoshdar,
                        timetamarkoz = it.Timetamarkoz ?? 10
                    }, JsonRequestBehavior.AllowGet);
                }
            }

            return Json(new { success = false }, JsonRequestBehavior.AllowGet);
        }

        public ActionResult Aghazrinvaziatsorat()
        {
            FunctionModel lstMoalefeexcel2 = new FunctionModel();
            lstMoalefeexcel2.tbdetail = new List<tbdetail>();
            lstMoalefeexcel2.Agarinvaziat = new List<Agarinvaziat>();

            var find = db.tbSoratvaziat.Where(s => s.Finalvaluesorat != null).GroupBy(t=>t.Fk_pymn).ToList();
            foreach(var it in find)
            {
                var countend = db.tbSoratvaziat.Where(s => s.Finalvaluesorat != null && s.Final_accept == true && s.Fk_pymn == it.Key).Count();
                var countdargaryan = db.tbSoratvaziat.Where(s => s.Finalvaluesorat != null && s.Final_accept != true && s.Fk_pymn == it.Key).Count();
                var pmb = db.tbSoratvaziat.Where(s => s.Finalvaluesorat != null && s.Fk_pymn == it.Key).FirstOrDefault();

                var Agarinvaziat1 = new Agarinvaziat
                {
                    IDPymn =(int) it.Key,
                    countend= countend,
                    countdargaryan= countdargaryan,
                    Namepymn= pmb.tbPeymanContracts.pec_Title,

                };
                lstMoalefeexcel2.Agarinvaziat.Add(Agarinvaziat1);
            }
            return View(lstMoalefeexcel2);
        }


