        public string creattad(long valuetaead=0,string Title="",int Fk_Document = 0)
        {
            var fin = db.tbDocuments.Where(p => p.ID == Fk_Document).FirstOrDefault();
            if(fin != null)
            {
                fin.IsAccepted = true;
                db.SaveChanges();
            }
            tbteaddocument taee = new tbteaddocument();
            taee.Fk_Document = Fk_Document;
            taee.valuetaead=valuetaead;
            taee.Title = Title;
            db.tbteaddocument.Add(taee);
            db.SaveChanges();
            return "True";

        }
        public string creatuntad( string Title = "", int Fk_Document = 0)
        {
            var fin = db.tbDocuments.Where(p => p.ID == Fk_Document).FirstOrDefault();
            if (fin != null)
            {
                fin.IsAccepted = false;
                db.SaveChanges();
            }
            tbteaddocument taee = new tbteaddocument();
            taee.Fk_Document = Fk_Document;
            taee.valuetaead = null;
            taee.Title = Title;
            db.tbteaddocument.Add(taee);
            db.SaveChanges();
            return "True";

        }






